// بنك أسئلة محاكي الامتحان الوزاري (السادس العلمي) — مسحوب آلياً من كل أسئلة
// اختبارات الفصول (g6c1-g6c9) المُتحقَّق منها مسبقاً. لا تُعدَّل هذا الملف يدوياً؛
// أي تصحيح يجب أن يصير بالمصدر الأصلي (ملف الدرس نفسه) ثم إعادة توليد هذا الملف.
window.MOCK_EXAM_G6_POOL = [{"ch":"g6c1","q":"موصل كروي نصف قطره r شُحن بشحنة Q. ما العلاقة الصحيحة لجهد سطحه؟","opts":["V = kQ/r","V = kQ/r²","V = kQr","V = kQ²/r"],"a":0,"why":"جهد الموصل الكروي عند سطحه V = kQ/r — طردي مع الشحنة وعكسي مع نصف القطر."},{"ch":"g6c1","q":"علّل: نادراً ما يُستعمل الموصل الكروي المنفرد لتخزين الشحنات الكهربائية.","opts":["لأن جهده يبقى ثابتاً","لأن زيادة شحنته تزيد المجال حتى يحصل انهيار كهربائي للهواء وتفريغ للشحنة","لأنه لا يقبل الشحن أصلاً","لأن سعته كبيرة جداً"],"a":1,"why":"V=kQ/r؛ زيادة الشحنة ترفع الجهد والمجال حتى يبلغ قوة عزل الهواء فتقفز شرارة تفرّغ الشحنة."},{"ch":"g6c1","q":"كرة معدنية جهد سطحها 3000V ونصف قطرها 0.1m. ما مقدار المجال الكهربائي عند سطحها؟","opts":["300 V/m","3×10⁴ V/m","30 V/m","3×10⁶ V/m"],"a":1,"why":"أسرع طريق: E = V/r = 3000/0.1 = 3×10⁴ V/m."},{"ch":"g6c1","q":"كرتان لهما الشحنة نفسها، الأولى نصف قطرها أصغر. أيّهما جهد سطحها أعلى؟","opts":["ذات نصف القطر الأصغر","ذات نصف القطر الأكبر","متساويتان","لا يمكن تحديد ذلك"],"a":0,"why":"V=kQ/r؛ وبنفس Q كلّما صغُر r ارتفع الجهد — لذا الأصغر جهدها أعلى (وهي أسرع في الانهيار)."},{"ch":"g6c1","q":"ما الحلّ العملي الذي نلجأ إليه بدل الموصل المنفرد لخزن شحنة أكبر؟","opts":["نكبّر الموصل فقط","نستعمل موصلَين يفصل بينهما عازل (متسعة)","نبرّد الموصل","نغلّفه بالبلاستيك"],"a":1,"why":"نظام موصلَين متقابلين بينهما عازل — المتسعة — يخزن شحنة أكبر عند جهد أقل بكثير."},{"ch":"g6c1","q":"متسعة سعتها 5μF رُبطت بمصدر جهده 12V. ما مقدار الشحنة المختزنة في أيٍّ من صفيحتيها؟","opts":["60 μC","2.4 μC","17 μC","600 μC"],"a":0,"why":"من تعريف السعة: Q = C×ΔV = 5×12 = 60 μC."},{"ch":"g6c1","q":"ما وحدة قياس السعة الكهربائية؟","opts":["الفولط (V)","الفاراد (F = C/V)","الكولوم (C)","الأوم (Ω)"],"a":1,"why":"السعة C = Q/ΔV، فوحدتها كولوم/فولط وتسمى الفاراد (Farad)."},{"ch":"g6c1","q":"عند مضاعفة فرق الجهد بين صفيحتي متسعة (سعتها ثابتة)، فإن الشحنة المختزنة تصبح:","opts":["Q","½Q","2Q","4Q"],"a":2,"why":"بما أن Q=C×ΔV والسعة ثابتة لا تتأثر بالجهد، فمضاعفة ΔV تضاعف Q."},{"ch":"g6c1","q":"علّل: صافي الشحنة الكلية للمتسعة المشحونة يساوي صفراً.","opts":["لأنها لا تُشحن أصلاً","لأن صفيحة تحمل +Q وأخرى −Q فمجموعهما صفر","لأن الشحنة تتسرّب","لأن العازل يلغيها"],"a":1,"why":"الصفيحتان تحملان شحنتين متساويتين متعاكستين (+Q و−Q)، فمجموعهما الجبري صفر."},{"ch":"g6c1","q":"قياسات على متسعة: عند 10V شحنتها 20μC، وعند 30V شحنتها 60μC. ما مقدار سعتها؟","opts":["2 μF","0.5 μF","6 μF","تتغيّر مع الجهد"],"a":0,"why":"النسبة Q/ΔV ثابتة: 20/10 = 60/30 = 2 μF — وهذا يؤكد أن السعة لا تتغيّر بالجهد."},{"ch":"g6c1","q":"متسعة سعتها والهواء بينها 6μF. أُدخل بينها عازل ثابت عزله k=4. ما سعتها الجديدة؟","opts":["24 μF","1.5 μF","10 μF","6 μF"],"a":0,"why":"C_k = k×C₀ = 4×6 = 24 μF — العازل يضاعف السعة k مرة."},{"ch":"g6c1","q":"علّل: إدخال عازل بدلاً من الهواء بين صفيحتي المتسعة يزيد من فائدتها العملية.","opts":["يزيد سعتها ويرفع جهد انهيارها فتتحمّل جهداً أعلى","يقلّل حجمها فقط","يجعلها موصلاً","يمنع شحنها"],"a":0,"why":"العازل يضاعف السعة (C_k=kC₀) ويرفع جهد الانهيار لأن قوة عزله أكبر من الهواء."},{"ch":"g6c1","q":"متسعة مشحونة ومفصولة عن البطارية أُدخل بين صفيحتيها عازل k=2. ماذا يحصل لفرق الجهد؟","opts":["يتضاعف","يقلّ إلى النصف","يبقى ثابتاً","يصبح صفراً"],"a":1,"why":"مفصولة ⟹ Q ثابتة. العازل يزيد C مرتين، ومن ΔV=Q/C يقلّ الجهد إلى النصف."},{"ch":"g6c1","q":"متسعة أُدخل بينها عازل وهي مفصولة عن البطارية. ماذا يحصل للمجال الكهربائي بين صفيحتيها؟","opts":["يزداد k مرة","يقلّ إلى E/k","يبقى ثابتاً","ينعدم"],"a":1,"why":"الشحنات السطحية للعازل تولّد مجالاً معاكساً، فيقلّ المجال المحصّل إلى E_k = E/k."},{"ch":"g6c1","q":"ماذا يمثّل ثابت العزل الكهربائي k لمادة ما؟","opts":["مقاومتها الكهربائية","نسبة سعة المتسعة بوجود المادة إلى سعتها والفراغ بينها","كثافتها","جهد انهيارها"],"a":1,"why":"k = C_k / C₀، أي كم مرة تزيد المادة سعة المتسعة مقارنة بالفراغ."},{"ch":"g6c1","q":"أيّ العلاقات صحيحة لسعة المتسعة ذات الصفيحتين المتوازيتين؟","opts":["C = kε₀A/d","C = kε₀d/A","C = ε₀Ad","C = A/(kε₀d)"],"a":0,"why":"C = kε₀A/d — طردية مع المساحة A وثابت العزل k، عكسية مع البعد d."},{"ch":"g6c1","q":"متسعة سعتها C قُرّبت صفيحتاها حتى صار البعد بينهما ⅓ ما كان. سعتها الجديدة تساوي:","opts":["C/9","C/3","3C","9C"],"a":2,"why":"C تتناسب عكسياً مع البعد d؛ فإذا صار d ← d/3 تصبح السعة 3C."},{"ch":"g6c1","q":"إذا ضاعفنا المساحة المتقابلة لصفيحتي متسعة وأبقينا كل شيء آخر ثابتاً، فإن السعة:","opts":["تتضاعف","تصبح نصفاً","لا تتغيّر","تصبح ربعاً"],"a":0,"why":"C ∝ A؛ مضاعفة المساحة تضاعف السعة."},{"ch":"g6c1","q":"علّل: يُحدَّد أقصى فرق جهد تعمل عنده المتسعة.","opts":["لأن السعة تتغيّر مع الجهد","لتجنّب الانهيار الكهربائي للعازل وتفريغ المتسعة من شحنتها","لأن البطارية تتلف","لتصغير حجمها"],"a":1,"why":"زيادة الجهد تزيد المجال حتى يخترق شرارةٌ العازلَ فتتفرّغ المتسعة وتتلف."},{"ch":"g6c1","q":"أيّ العوامل التالية لا يؤثّر في سعة متسعة معيّنة؟","opts":["المساحة A","البعد d","نوع العازل k","فرق الجهد المسلَّط ΔV"],"a":3,"why":"السعة صفة هندسية تعتمد على A و d و k فقط؛ ΔV لا يظهر في القانون ولا يغيّر السعة."},{"ch":"g6c1","q":"ثلاث متسعات (2μF, 3μF, 5μF) مربوطة على التوازي مع بطارية 6V. ما مقدار السعة المكافئة؟","opts":["10 μF","1 μF","0.97 μF","30 μF"],"a":0,"why":"في التوازي: C_eq = 2+3+5 = 10 μF."},{"ch":"g6c1","q":"متسعتان 4μF و12μF مربوطتان على التوالي. ما مقدار السعة المكافئة؟","opts":["16 μF","3 μF","8 μF","48 μF"],"a":1,"why":"بصيغة الضرب على الجمع: C_eq = (4×12)/(4+12) = 48/16 = 3 μF."},{"ch":"g6c1","q":"علّل: نقصان السعة المكافئة لمجموعة متسعات مربوطة على التوالي.","opts":["لأنها تكافئ زيادة البعد بين الصفيحتين","لأنها تكافئ زيادة المساحة المتقابلة","لأن الشحنة تقلّ","لأن العازل يضعف"],"a":0,"why":"التوالي يكافئ زيادة البعد الفعلي، وC تتناسب عكسياً مع البعد فتنقص السعة المكافئة."},{"ch":"g6c1","q":"متسعتان متماثلتان سعة كل منهما C. ما نسبة سعة توازيهما إلى سعة تواليهما؟","opts":["1","2","4","½"],"a":2,"why":"توازٍ: C_eq=2C. توالٍ: C_eq=C/2. النسبة = 2C ÷ (C/2) = 4."},{"ch":"g6c1","q":"ما الغرض العملي من ربط مجموعة من المتسعات على التوالي؟","opts":["زيادة السعة المكافئة","تحمّل فرق جهد أكبر لا تتحمّله متسعة منفردة","تقليل المقاومة","زيادة التيار"],"a":1,"why":"التوالي يوزّع فرق الجهد الكلي بين المتسعات فلا تتحمّل الواحدة إلا جزءاً منه."},{"ch":"g6c1","q":"متسعة سعتها 4μF شُحنت إلى 100V. ما مقدار الطاقة المختزنة فيها؟","opts":["0.02 J","0.2 J","400 J","2 J"],"a":0,"why":"PE = ½CV² = ½ × 4×10⁻⁶ × (100)² = 0.02 J."},{"ch":"g6c1","q":"أيّ الصيغ التالية لا تصلح لحساب الطاقة المختزنة في متسعة؟","opts":["½QΔV","½CΔV²","Q²/2C","½QC²"],"a":3,"why":"الصيغ الصحيحة الثلاث: ½QΔV و½CΔV² وQ²/2C. أما ½QC² فليست منها."},{"ch":"g6c1","q":"عند مضاعفة فرق الجهد على متسعة (سعتها ثابتة)، فإن الطاقة المختزنة تصبح:","opts":["مثلين","أربعة أمثال","نصفاً","لا تتغيّر"],"a":1,"why":"PE = ½CΔV²؛ الطاقة تتناسب مع مربّع الجهد، فمضاعفة ΔV تجعلها 4 أمثال."},{"ch":"g6c1","q":"متسعة تختزن طاقة 10J تُفرّغها خلال 2ms. ما مقدار القدرة الناتجة؟","opts":["5000 W","20 W","0.02 W","5 W"],"a":0,"why":"P = PE/t = 10 / (2×10⁻³) = 5000 W."},{"ch":"g6c1","q":"علّل: تجهّز المتسعة قدرة لحظية أكبر بكثير من البطارية التي شحنتها.","opts":["لأنها تختزن شحنة أكبر","لأنها تُفرّغ طاقتها في زمن قصير جداً فترتفع القدرة P=PE/t","لأن جهدها أعلى","لأنها لا تفقد طاقة"],"a":1,"why":"القدرة = الطاقة/الزمن؛ التفريغ في زمن ضئيل جداً يرفع القدرة اللحظية كثيراً."},{"ch":"g6c1","q":"دائرة شحن: بطارية 24V ومقاومة 60Ω ومتسعة. ما مقدار أعظم تيار شحن لحظة غلق المفتاح؟","opts":["0.4 A","1440 A","2.5 A","84 A"],"a":0,"why":"لحظة الغلق المتسعة فارغة فكل الجهد على المقاومة: I = ΔV/R = 24/60 = 0.4 A."},{"ch":"g6c1","q":"بعد اكتمال شحن متسعة في دائرة RC، ما مقدار التيار في الدائرة؟","opts":["أعظم قيمة ΔV/R","صفر","نصف القيمة الأعظم","يتذبذب باستمرار"],"a":1,"why":"عند اكتمال الشحن يتساوى جهد المتسعة مع جهد البطارية فلا يبقى جهد على المقاومة، فيكون التيار صفراً — المتسعة كمفتاح مفتوح."},{"ch":"g6c1","q":"دائرة RC فيها R=2kΩ وC=50μF. ما مقدار الزمن الثابت τ؟","opts":["0.1 s","100 s","0.04 s","40 s"],"a":0,"why":"τ = RC = 2000 × 50×10⁻⁶ = 0.1 s."},{"ch":"g6c1","q":"عند رسم دائرة تفريغ المتسعة، ما الخطأ الأكثر شيوعاً الذي يُصفّر درجة السؤال؟","opts":["نسيان رسم المفتاح","رسم بطارية في دائرة التفريغ","نسيان تسمية المقاومة","رسم المصباح بدل المقاومة"],"a":1,"why":"دائرة التفريغ لا تحتوي بطارية إطلاقاً — مصدر الطاقة هو المتسعة المشحونة نفسها."},{"ch":"g6c1","q":"بعد زمن ثابت واحد τ من بدء الشحن، يبلغ جهد المتسعة نحو:","opts":["100% من أقصاه","63% من أقصاه","37% من أقصاه","صفر"],"a":1,"why":"خاصية المنحنى الأسّي: بعد τ واحد يصل الشحن إلى نحو 63% من قيمته النهائية."},{"ch":"g6c1","q":"أيّ نوع من المتسعات يمتاز بصغر حجمه وكبر مساحة صفائحه بسبب لفّها أسطوانياً؟","opts":["ذات الورق المشمّع","الإلكتروليتية","المتغيّرة الدوّارة","متسعة الفراغ"],"a":0,"why":"المتسعة ذات الورق المشمّع تُلف صفائحها مع الورق العازل أسطوانياً لتوفير مساحة كبيرة في حجم صغير."},{"ch":"g6c1","q":"لماذا يجب ربط المتسعة الإلكتروليتية بالقطبية الصحيحة؟","opts":["لأنها كبيرة الحجم","لأن عازلها يتولّد كيميائياً باتجاه واحد وعكس القطبية يتلفها","لتزيد سعتها","لتقليل تكلفتها"],"a":1,"why":"مادة العزل نتاج تفاعل كيميائي باتجاه محدد؛ عكس القطبية يهدم طبقة العزل."},{"ch":"g6c1","q":"ما العامل الذي يتغيّر في متسعة لوحة المفاتيح أثناء الضغط على المفتاح؟","opts":["المساحة A","البعد d","ثابت العزل k","الشحنة الكلية"],"a":1,"why":"الضغط يقلّل البعد d فتزداد السعة (C∝1/d)، فتتعرّف الدائرة على المفتاح."},{"ch":"g6c1","q":"في المتسعة متغيّرة السعة ذات الصفائح الدوّارة، ما الذي يغيّر السعة عند تدوير المحور؟","opts":["ثابت العزل k","المساحة المتقابلة بين المجموعتين","البعد d فقط","الجهد المسلَّط"],"a":1,"why":"الدوران يغيّر المساحة المتقابلة بين المجموعتين، وC ∝ A فتتغيّر السعة."},{"ch":"g6c1","q":"ما الفائدة العملية للمتسعة في مصباح الكاميرا الومضي؟","opts":["تبريد المصباح","تجهيز طاقة تكفي لومضة قوية مفاجئة عند تفريغها","تكبير الصورة","تخزين البيانات"],"a":1,"why":"تُشحن ببطء ثم تُفرّغ طاقتها دفعة واحدة فتنتج ومضة قوية تعجز البطارية عنها مباشرة."},{"ch":"g6c1","q":"متسعة ذات الصفيحتين المتوازيتين، مشحونة ومفصولة عن البطارية، الهواء يملأ الحيز بين صفيحتيها، أُدخلت مادة عازلة ثابت عزلها (k = 2) ملأت الحيز بين الصفيحتين، فإن مقدار المجال الكهربائي (Ek) بين صفيحتيها بوجود المادة العازلة مقارنة مع مقداره (E) في حالة الهواء، يصير:","opts":["E/4","2E","E","E/2"],"a":3,"why":"المتسعة معزولة (مفصولة عن البطارية) فالشحنة Q ثابتة. E = σ/(ε₀κ) = Q/(ε₀κA). عند k=2 يصبح المجال = Q/(ε₀×2×A) = E/2."},{"ch":"g6c1","q":"وحدة (Farad) تُستعمل لقياس سعة المتسعة وهي لا تكافئ إحدى الوحدات الآتية:","opts":["Coulomb²/J","Coulomb/V","Coulomb × V²","J/V²"],"a":2,"why":"C=Q/V ⇒ Coulomb/V صحيحة. من U=Q²/2C ⇒ C=Q²/2U وحدتها Coulomb²/J صحيحة. من U=½CV² ⇒ C=2U/V² وحدتها J/V² صحيحة. أما Coulomb×V² فليست مكافئة للفاراد (أبعادها C·V² وليست C/V)."},{"ch":"g6c1","q":"متسعة ذات الصفيحتين المتوازيتين، سعتها C، قُرّبت صفيحتاها من بعضهما حتى صار البعد بينهما (⅓) ما كان عليه، فإن مقدار سعتها الجديدة يساوي:","opts":["(1/3)C","(1/9)C","3C","9C"],"a":2,"why":"C = ε₀A/d، فإذا صار d الجديد = d/3 فإن C الجديدة = ε₀A/(d/3) = 3×(ε₀A/d) = 3C."},{"ch":"g6c1","q":"متسعة مقدار سعتها (20μF)، لكي تختزن طاقة في مجالها الكهربائي مقدارها (2.5J) يتطلب ربطها بمصدر فرق جهده مستمر يساوي:","opts":["150 V","350V","500V","250 kV"],"a":2,"why":"U=½CV² ⇒ V=√(2U/C)=√(2×2.5/20×10⁻⁶)=√(250000)=500V."},{"ch":"g6c1","q":"متسعة ذات الصفيحتين المتوازيتين سعتها (50 μF)، الهواء يملأ الحيز بين صفيحتيها، إذا أُدخلت مادة عازلة بين صفيحتيها ازدادت سعتها بمقدار (60 μF)، فإن ثابت عزل تلك المادة يساوي:","opts":["0.45","0.55","1.1","2.2"],"a":3,"why":"السعة الجديدة = 50+60=110μF. k = C_جديدة/C_هواء = 110/50 = 2.2."},{"ch":"g6c1","q":"وأنت في المختبر تحتاج إلى متسعة سعتها (10μF) والمتوافر لديك مجموعة من المتسعات المتماثلة من ذوات السعة (15 μF)، فإن عدد المتسعات التي تحتاجها وطريقة الربط التي تختارها هي:","opts":["العدد 4 تُربط جميعاً على التوالي","العدد 6 تُربط جميعاً على التوازي","العدد 3 اثنان منها تُربط على التوالي ومجموعتهما تُربط مع الثالثة على التوازي","العدد 3 اثنان منها تُربط على التوازي ومجموعتهما تُربط مع الثالثة على التوالي"],"a":3,"why":"اثنتان على التوازي: 15+15=30μF. بالتوالي مع الثالثة (15μF): (30×15)/(30+15)=450/45=10μF ✓ يطابق المطلوب."},{"ch":"g6c1","q":"متسعة ذات الصفيحتين المتوازيتين ربطت صفيحتاها بين قطبي بطارية تجهز فرق جهد ثابت، فإذا أُبعدت الصفيحتان عن بعضهما قليلاً مع بقاء البطارية موصولة بهما فإن مقدار المجال الكهربائي بين الصفيحتين:","opts":["يزداد والشحنة المختزنة في أي من صفيحتيها تزداد","يقل والشحنة المختزنة في أي من صفيحتيها تقل","يبقى ثابتاً والشحنة المختزنة في أي من صفيحتيها تبقى ثابتة","يبقى ثابتاً والشحنة المختزنة في أي من صفيحتيها تزداد"],"a":1,"why":"V ثابت (بطارية موصولة). زيادة d تقلل C=ε₀A/d فتقل Q=CV. والمجال E=V/d يقل أيضاً لأن d ازداد و V ثابت."},{"ch":"g6c1","q":"للحصول على أكبر مقدار سعة مكافئة لمجموعة المتسعات في الشكل (37)، اختر الدائرة المربوطة في الشكل:","opts":["a","b","c","d"],"a":3,"why":"a: (2∥4)=6µF، بالتوالي مع 3 ⇒ (6×3)/9=2µF. b: 2∥1=3µF. c: 12 بالتوالي مع 6 ⇒ (12×6)/18=4µF. d: 4µF بالتوازي مع (2∥2=4µF) ⇒ 4+4=8µF (الأكبر)."},{"ch":"g6c1","q":"متسعتان (C1، C2) رُبطتا مع بعضهما على التوالي، ومجموعتهما رُبطت بين قطبي بطارية، وكان مقدار سعة الأولى أكبر من مقدار سعة الثانية. وعند مقارنة فرق الجهد بين صفيحتي المتسعة الأولى (ΔV1) مع فرق الجهد بين صفيحتي المتسعة الثانية (ΔV2) نجد أن:","opts":["ΔV2 أكبر من ΔV1","ΔV2 أصغر من ΔV1","ΔV2 يساوي ΔV1","كل الاحتمالات السابقة، يعتمد ذلك على شحنة كل منهما"],"a":0,"why":"في التوالي: نفس الشحنة Q على الاثنتين. ΔV=Q/C، وبما أن C1>C2 فإن ΔV1=Q/C1 أصغر من ΔV2=Q/C2. إذن ΔV2 أكبر من ΔV1."},{"ch":"g6c1","q":"ثلاث متسعات (C1، C2، C3) مربوطة مع بعضها على التوازي ومجموعتها رُبطت بين قطبي بطارية، كان مقدار سعاتها (C1>C2>C3). وعند مقارنة مقدار الشحنات (Q1، Q2، Q3) المختزنة في أي من صفيحتي كل متسعة، نجد أن:","opts":["Q3>Q2>Q1","Q1>Q3>Q2","Q1>Q2>Q3","Q3=Q2=Q1"],"a":2,"why":"في التوازي: نفس فرق الجهد V على الجميع. Q=CV، فتتناسب Q طردياً مع C، وبما أن C1>C2>C3 فإن Q1>Q2>Q3."},{"ch":"g6c1","q":"متسعة ذات صفيحتين متوازيتين (الهواء عازل بينهما)، عند زيادة المساحة السطحية المتقابلة للصفيحتين مع بقاء البعد بينهما ونوع العازل ثابتين، فإن سعتها:","opts":["تزداد طردياً مع المساحة، وفق العلاقة C=ε₀κA/d","تقل عكسياً مع المساحة","تبقى ثابتة لا تتأثر بالمساحة","تزداد مع مربع المساحة"],"a":0,"why":"من C=ε₀κA/d: C تتناسب طردياً وخطياً مع A مع بقاء d وκ ثابتين."},{"ch":"g6c1","q":"متسعة ذات صفيحتين متوازيتين، عند زيادة البعد بين الصفيحتين مع بقاء المساحة ونوع العازل ثابتين، فإن سعتها:","opts":["تزداد طردياً مع البعد","تقل عكسياً مع البعد، وفق العلاقة C=ε₀κA/d","تبقى ثابتة لا تتأثر بالبعد","تقل مع مربع البعد"],"a":1,"why":"من C=ε₀κA/d: C تتناسب عكسياً مع d (تناسب خطي عكسي) مع بقاء A وκ ثابتين."},{"ch":"g6c1","q":"متسعة ذات صفيحتين متوازيتين (الهواء عازل بينهما)، عند إدخال مادة عازلة ثابت عزلها κ لتملأ الحيز بين الصفيحتين بدلاً من الهواء، مع بقاء المساحة والبعد ثابتين، فإن سعة المتسعة الجديدة تصبح:","opts":["تساوي سعة الهواء مقسومة على κ","تساوي سعة الهواء مضروبة في κ² ","تساوي سعة الهواء مضروبة في κ، وفق العلاقة C=ε₀κA/d","تساوي سعة الهواء نفسها بلا تغيير"],"a":2,"why":"C_هواء = ε₀A/d (κ=1). بإدخال عازل ثابته κ: C = ε₀κA/d = κ×C_هواء."},{"ch":"g6c1","q":"عند مضاعفة مقدار فرق الجهد الكهربائي بين صفيحتي متسعة ذات سعة ثابتة، فإن:","opts":["تصبح الشحنة أربعة أمثالها والطاقة تتضاعف","تبقى الشحنة ثابتة وتتضاعف الطاقة","تتضاعف الشحنة وتصبح الطاقة أربعة أمثالها","تتضاعف الشحنة وتتضاعف الطاقة"],"a":2,"why":"Q=CV، فمضاعفة V تُضاعف Q. أما U=½CV² فتعتمد على مربع V، فمضاعفة V تجعل U أربعة أمثالها."},{"ch":"g6c1","q":"متسعة مشحونة، فرق الجهد بين صفيحتيها عالٍ جداً وهي مفصولة عن مصدر الفولطية، تبقى لمدة زمنية طويلة خطرة عند لمس صفيحتيها مباشرة. ما تفسير ذلك؟","opts":["لأن التيار المستمر ينساب باستمرار خلال دائرة المتسعة حتى بعد الفصل","لأن المجال المغناطيسي الناتج عن الشحنة يسبب صدمة كهربائية","لأن العزل يمنع تسرّب الشحنة فتبقى المتسعة مشحونة مدة طويلة، واللمس يوفّر مسار تفريغ عبر الجسم","لأن المتسعة تولّد شحنة جديدة ذاتياً طالما بقيت مشحونة"],"a":2,"why":"المتسعة المعزولة تحتفظ بشحنتها Q (وفولطيتها وطاقتها) لأن لا مسار تفريغ إلا عبر عزل جيد بطيء التسرب؛ لمسها مباشرة يوفر مساراً عبر الجسم يُفرِّغ الطاقة المختزنة فجأة.<br><br><b>الصياغة الكاملة للجواب:</b> لأن العزل بين صفيحتيها يمنع تسرّب الشحنة بسرعة، فتبقى الشحنة (وبالتالي فرق الجهد والطاقة المختزنة) محتفَظاً بها لفترة طويلة، ولمس الصفيحتين يوفر مساراً يُفرِّغ هذه الطاقة فجأة خلال الجسم"},{"ch":"g6c1","q":"في دائرة كهربائية لشحن متسعة عبر مقاومة R من بطارية ثم تفريغها، أي وصف للدائرة صحيح؟","opts":["التفريغ يتطلب مصدر جهد أكبر من الشحن","الشحن والتفريغ كلاهما يتطلبان وجود البطارية في الدائرة باستمرار","الشحن: بطارية ومقاومة ومتسعة في حلقة مغلقة؛ والتفريغ: الحلقة نفسها بلا بطارية إطلاقاً","لا يمكن تفريغ المتسعة إلا بعكس قطبية البطارية"],"a":2,"why":"دائرة RC النموذجية: عند الشحن تُغلق الحلقة على البطارية والمقاومة والمتسعة. للتفريغ تُفصل البطارية وتُبقى المتسعة موصولة بالمقاومة في حلقة مغلقة فيتدفق التيار عكسياً حتى تتلاشى الشحنة.<br><br><b>الصياغة الكاملة للجواب:</b> الشحن: بطارية + مقاومة + متسعة في حلقة مغلقة بمفتاح؛ والتفريغ: إزالة البطارية من الحلقة وإبقاء المتسعة والمقاومة في حلقة مغلقة، فتندفع الشحنة عكسياً عبر R حتى تتلاشى"},{"ch":"g6c1","q":"لديك ثلاث متسعات متماثلة سعة كل منها C ومصدر فولطية مستمر فرق جهده ثابت V. أي طريقة ربط تعطي أكبر مقدار من الطاقة الكهربائية المختزنة في المجموعة؟","opts":["ربط اثنتين على التوالي والثالثة على التوازي معهما","ربط الثلاث جميعاً على التوالي (Ceq=C/3)","ربط الثلاث جميعاً على التوازي (Ceq=3C)","طريقة الربط لا تؤثر في الطاقة المختزنة"],"a":2,"why":"U=½CeqV² وV ثابت (مصدر واحد)، فتعظيم U يستلزم تعظيم Ceq. أكبر Ceq لثلاث متماثلات هو ربطها جميعاً على التوازي: Ceq=3C."},{"ch":"g6c1","q":"المتسعات المؤلَّفة من صفائح دوّارة متعددة (متسعة متغيرة السعة تُستعمل في أجهزة الاستقبال) تكون فيها المتسعات الأولية (بين كل صفيحتين متجاورتين) مربوطة مع بعضها:","opts":["بعضها على التوالي وبعضها على التوازي بالتساوي","لا يمكن تحديد ذلك دون معرفة عدد الصفائح","على التوالي، لأن جميع الصفائح الدوّارة مربوطة بقطب واحد وجميع الصفائح الثابتة بالقطب الآخر","على التوازي، لأن جميع الصفائح الدوّارة مربوطة كهربائياً معاً (لوح واحد فعلياً) وكذلك جميع الصفائح الثابتة، فتتشارك كل الأزواج فرق الجهد نفسه"],"a":3,"why":"كل الصفائح الدوّارة متصلة معاً كهربائياً (قطب واحد) وكل الصفائح الثابتة متصلة معاً (القطب الآخر)، فكل زوج متجاور يشكّل متسعة بين نفس العقدتين ⇒ ربط توازي، وCeq=مجموع السعات الأولية."},{"ch":"g6c1","q":"ثلاث متسعات متماثلة سعة كل منها C، رُبطت بأربع طرائق: (a) الثلاث على التوالي، (b) اثنتان على التوازي وناتجهما على التوالي مع الثالثة، (c) اثنتان على التوالي وناتجهما على التوازي مع الثالثة، (d) الثلاث على التوازي. رتّب السعة المكافئة للمجموعة من الأكبر إلى الأصغر:","opts":["a > b > c > d","c > d > a > b","d > b > c > a","d > c > b > a"],"a":3,"why":"a=C/3، b=(2C×C)/(2C+C)=2C/3، c=(C/2)+C=3C/2، d=3C. بالترتيب التنازلي: d(3C) > c(3C/2) > b(2C/3) > a(C/3)."},{"ch":"g6c1","q":"متسعة ذات صفيحتين متوازيتين مشحونة ومفصولة عن البطارية، لو مُلئ الحيز بين صفيحتيها بالماء النقي بدلاً من الهواء، فإن فرق الجهد الكهربائي بين صفيحتيها سينخفض. ما السبب؟","opts":["لأن الماء موصل يسمح بتسرّب الشحنة","لأن الماء عازل يزيد السعة، والشحنة ثابتة (معزولة) فينخفض الجهد","لأن الماء يقلل المساحة الفعالة للصفيحتين","لأن الماء يقلل الشحنة المختزنة على الصفيحتين"],"a":1,"why":"الماء عازل ثابت عزله كبير (κ≈80)، فإدخاله يزيد C = κC_هواء بمقدار كبير. المتسعة معزولة فـ Q ثابتة، وV=Q/C ينخفض بشدة."},{"ch":"g6c1","q":"في بعض لوحات مفاتيح الحاسوب تُستعمل متسعة تحت كل مفتاح لاستشعار الضغط عليه. عند الضغط على المفتاح، ما العامل الفيزيائي الذي يتغيّر في تلك المتسعة مسبباً تغيّر سعتها؟","opts":["فرق الجهد المطبق على المتسعة","المساحة السطحية المتقابلة للّوحين","البعد بين صفيحتيها، إذ يقترب اللوحان عند الضغط فتزداد السعة","نوع المادة العازلة بين صفيحتيها"],"a":2,"why":"الضغط على المفتاح يقرّب صفيحتي المتسعة (يقلل d)، فتزداد C=ε₀κA/d، ويستشعر الدارة الإلكترونية هذا التغير."},{"ch":"g6c1","q":"ما مصدر الطاقة الكهربائية في جهاز الصدمات القلبية (Defibrillator) المستعمل لتوليد الصدمة الكهربائية لغرض تحفيز وإعادة انتظام عمل قلب المريض؟","opts":["مصدر تيار متناوب مباشر من الشبكة الكهربائية","ملف محاثة يولّد تياراً حثياً مستمراً","بطارية عادية تزوّد التيار مباشرة إلى جسم المريض","متسعة تُشحن ببطء لجهد عالٍ ثم تُفرّغ بسرعة عبر جسم المريض"],"a":3,"why":"الجهاز يشحن متسعة كبيرة تدريجياً لفرق جهد عالٍ (طاقة U=½CV² كبيرة)، ثم يُفرّغها فجأة (زمن قصير جداً) عبر جسم المريض فتنتج نبضة تيار عالية القدرة.<br><br><b>الصياغة الكاملة للجواب:</b> متسعة كبيرة تُشحن ببطء إلى فرق جهد عالٍ ثم تُفرّغ شحنتها بسرعة عبر جسم المريض مطلقةً طاقة كبيرة خلال زمن قصير جداً"},{"ch":"g6c1","q":"ما التفسير الفيزيائي الصحيح لازدياد السعة المكافئة عند ربط المتسعات على التوازي، ونقصانها عند ربطها على التوالي؟","opts":["التوازي يزيد البعد الفعال فتقل C، والتوالي يزيد المساحة فتزداد C","الربط لا يغيّر السعة المكافئة أبداً","كلا الحالتين تزيد C لأن عدد المتسعات يزداد","التوازي يزيد المساحة الفعالة فتزداد C، والتوالي يزيد البعد الفعّال فتقل C"],"a":3,"why":"من C=ε₀κA/d: التوازي يُكافئ زيادة المساحة الكلية A فتزداد Ceq، والتوالي يُكافئ زيادة البعد الكلي d فتقل Ceq.<br><br><b>الصياغة الكاملة للجواب:</b> التوازي يزيد المساحة السطحية الفعالة المشتركة (كأنها متسعة واحدة أكبر مساحة) فتزداد C؛ والتوالي يزيد البعد الفعال الكلي بين الصفيحتين الطرفيتين (كأنها متسعة واحدة أكبر بعداً) فتقل C"},{"ch":"g6c1","q":"علّل: المتسعة المشحونة والموضوعة في دائرة التيار المستمر تُعدّ مفتاحاً مفتوحاً؟","opts":["لأن التيار يتسرّب منها بسرعة كبيرة جداً فتصبح كأنها غير موجودة","لأن عزلها الداخلي يمنع مرور التيار المستمر بعد اكتمال الشحن","لأنها تولّد قوة دافعة كهربائية معاكسة تُلغي تأثير البطارية","لأن مقاومتها تساوي صفراً فتقصر الدائرة"],"a":1,"why":"في الحالة المستقرة (بعد اكتمال الشحن) لا ينساب تيار مستمر عبر متسعة لأن بين صفيحتيها عازل يمنع مرور الشحنات، فتتصرف الدائرة كأن ذلك الفرع مفتوح.<br><br><b>الصياغة الكاملة للجواب:</b> لأن عزلها الداخلي بين صفيحتيها يمنع مرور التيار المستمر خلالها في الحالة المستقرة بعد اكتمال الشحن، فلا ينساب تيار في ذلك الفرع كما لو كان مفتاحاً مفتوحاً"},{"ch":"g6c1","q":"علّل: يقل مقدار المجال الكهربائي بين صفيحتي متسعة مشحونة ومفصولة عن البطارية عند إدخال مادة عازلة بين صفيحتيها؟","opts":["لأن سعة المتسعة تقل عند إدخال العازل","لأن المادة العازلة توصّل جزءاً من الشحنة بين الصفيحتين","لأن استقطاب العازل يولّد شحنات سطحية ذات مجال معاكس، فيقل المجال إلى E₀/κ","لأن المادة العازلة تقلل الشحنة الحرة على الصفيحتين"],"a":2,"why":"استقطاب جزيئات العازل يولّد شحنات سطحية مستحثة مجالها معاكس للمجال الأصلي، فيقل المجال المحصّل الصافي داخل العازل إلى E₀/κ.<br><br><b>الصياغة الكاملة للجواب:</b> لأن جزيئات المادة العازلة تستقطب مكوّنةً شحنات سطحية مستحثة تولّد مجالاً معاكساً للمجال الأصلي، فيقل المجال المحصّلة بمقدار κ من قيمته الأصلية (E=E₀/κ)"},{"ch":"g6c1","q":"علّل: يحدَّد مقدار أقصى فرق جهد كهربائي يمكن أن تعمل عنده المتسعة؟","opts":["بمساحة الصفيحتين المتقابلة، فكلّما كبرت تحمّلت جهداً أعلى","بقوة العزل الكهربائي للمادة العازلة، فتجاوزها يُحدث انهياراً","بطول الأسلاك الموصلة للمتسعة بالدائرة ومقدار مقاومتها","بنوع المعدن المصنوعة منه الصفيحتان ودرجة نقاوته"],"a":1,"why":"لكل مادة عازلة حد أقصى للمجال الكهربائي تتحمله (قوة العزل الكهربائي)؛ تجاوزه يسبب انهيار العزل الكهربائي وتفريغاً مفاجئاً، فيحدد ذلك أقصى فرق جهد آمن للمتسعة.<br><br><b>الصياغة الكاملة للجواب:</b> قوة تحمّل المادة العازلة (قوة العزل الكهربائي)؛ فإذا تجاوز المجال الكهربائي بين الصفيحتين الحد الذي تتحمله المادة العازلة، ينهار العزل ويصبح موصلاً فيحدث تفريغ مفاجئ يُتلف المتسعة"},{"ch":"g6c1","q":"متسعة ذات صفيحتين متوازيتين، الهواء عازل بينهما، شُحنت بوساطة بطارية ثم فُصلت عنها. عند إدخال لوح عازل كهربائي ثابت عزله (k=2) بين صفيحتيها، ماذا يحدث لكل من: الشحنة Q، السعة C، فرق الجهد V، المجال الكهربائي E، الطاقة المختزنة U؟","opts":["Q تتضاعف، C ثابتة، V ثابت، E ثابت، U تتضاعف","Q ثابتة، C تنخفض للنصف، V يتضاعف، E يتضاعف، U يتضاعف","جميع الكميات الخمس تبقى ثابتة لأن المتسعة معزولة","Q ثابتة (معزولة)، C تتضاعف (=2C)، V تنخفض للنصف (=V/2)، E ينخفض للنصف (=E/2)، U تنخفض للنصف (=U/2)"],"a":3,"why":"معزولة ⇒ Q ثابتة. C_جديدة=kC=2C. V=Q/C ⇒ V/2. E=V/d ⇒ E/2. U=Q²/2C ⇒ U/2 (أو U=½QV تعطي نفس النتيجة)."},{"ch":"g6c1","q":"متسعة ذات صفيحتين متوازيتين، الهواء عازل بينهما، رُبطت بين قطبي بطارية، وعند إدخال عازل كهربائي ثابت عزله (k=6) بين صفيحتيها والمتسعة ما زالت موصولة بالبطارية، ماذا يحدث لكل من: فرق الجهد V، السعة C، الشحنة Q، المجال الكهربائي E، الطاقة المختزنة U؟","opts":["V يبقى ثابتاً (تفرضه البطارية)، C تصبح 6 أمثالها، Q تصبح 6 أمثالها، E يبقى ثابتاً (=V/d ولم يتغير كل من V وd)، U تصبح 6 أمثالها","V يصبح 6 أمثاله، C ثابتة، Q تصبح 6 أمثالها، E يصبح 6 أمثاله، U تصبح 36 مثلاً","V ثابت، C تصبح 6 أمثالها، Q ثابتة، E ينخفض إلى سدس قيمته، U ثابتة","V ثابت، C تنخفض إلى سدس قيمتها، Q تنخفض إلى سدس قيمتها، E ثابت، U تنخفض إلى سدس قيمتها"],"a":0,"why":"البطارية موصولة ⇒ V ثابت. C_جديدة=kC=6C. Q=CV ⇒ Q تصبح 6 أمثالها. E=V/d ثابت لأن V وd لم يتغيرا. U=½CV² ⇒ U تصبح 6 أمثالها."},{"ch":"g6c1","q":"دائرة RC كما في الشكل (40): بطارية جهدها الطرفي V=12V، متسعة C=100µF، مقاومة R=20Ω مربوطة على التوالي مع مفتاح. ما أعظم مقدار لتيار الشحن لحظة إغلاق المفتاح؟","opts":["I=0.3A","I=0.6A","I=240A","I=1.2A"],"a":1,"why":"لحظة الإغلاق Vc=0 (المتسعة فارغة)، فكل جهد البطارية يقع على R: I_max=V/R=12/20=0.6A. لاحقاً (بعد زمن طويل، اكتمال الشحن): V_C=12V، Q=CV=1200µC=1.2mC، U=½CV²=7.2mJ."},{"ch":"g6c1","q":"متسعة ذات صفيحتين متوازيتين سعتها (C=4µF) رُبطت بين قطبي بطارية فرق الجهد بين قطبيها (20V). ما مقدار الشحنة المختزنة في أي من صفيحتي المتسعة؟","opts":["Q=5µC","Q=0.2µC","Q=80µC","Q=320µC"],"a":2,"why":"Q=CV=4µF×20V=80µC."},{"ch":"g6c1","q":"(تتمة المسألة السابقة) إذا فُصلت المتسعة عن البطارية وأُدخل لوح عازل كهربائي بين صفيحتيها فهبط فرق الجهد بين صفيحتيها إلى (10V)، فإن ثابت عزل ذلك اللوح يساوي:","opts":["k=10","k=4","k=2","k=0.5"],"a":2,"why":"بعد الفصل Q ثابتة (80µC). k=V/V'=20/10=2. (والسعة الجديدة C'=kC=8µF)."},{"ch":"g6c1","q":"متسعتان (C1=9µF، C2=18µF) من ذوات الصفائح المتوازية مربوطتان مع بعضهما على التوالي، وربطت مجموعتهما مع مصدر فرق جهد كهربائي ثابت مقداره (12V) بين قطبيه. ما مقدار فرق الجهد بين صفيحتي المتسعة (C1)؟","opts":["ΔV1=4V","ΔV1=8V","ΔV1=12V","ΔV1=6V"],"a":1,"why":"Ceq=(9×18)/27=6µF. Q=Ceq×V=72µC (نفسها على الاثنتين لأنهما على التوالي). ΔV1=Q/C1=72/9=8V (وΔV2=72/18=4V، والمجموع=12V ✓). U1=Q²/2C1=288µJ، U2=144µJ."},{"ch":"g6c1","q":"إذا أُدخل لوح عازل كهربائي ثابت عزله (k=4) بين صفيحتي المتسعة (C1) فقط من المسألة السابقة، مع بقاء البطارية مربوطة بين طرفي المجموعة، فإن فرق الجهد الجديد بين صفيحتي (C2) يصبح:","opts":["4V","12V","2V","8V"],"a":3,"why":"C1الجديدة=4×9=36µF. Ceqالجديدة=(36×18)/54=12µF. Q'=12×12=144µC. ΔV2'=Q'/C2=144/18=8V (وΔV1'=144/36=4V، المجموع=12V ✓)."},{"ch":"g6c1","q":"متسعتان من ذوات الصفائح المتوازيتين (C1=16µF، C2=24µF) مربوطتان مع بعضهما على التوازي ومجموعتهما مربوطة بين قطبي بطارية فرق الجهد بينهما (48V). إذا أُدخل لوح من مادة عازلة ثابت عزلها (k) بين صفيحتي المتسعة الأولى ومازالت المجموعة موصولة بالبطارية فكانت الشحنة الكلية للمجموعة (3456µC)، فإن ثابت العزل (k) يساوي:","opts":["k=2","k=1.5","k=4","k=3"],"a":3,"why":"V=48V ثابت (توازي، بطارية موصولة). Q_كلية=(k×16+24)×48=3456 ⇒ 16k+24=72 ⇒ k=3. (قبل العزل: Q1=768µC، Q2=1152µC؛ بعده: Q1'=48×48=2304µC، Q2 ثابتة=1152µC؛ المجموع=3456µC ✓)."},{"ch":"g6c1","q":"متسعتان (C1=4µF، C2=8µF) مربوطتان مع بعضهما على التوازي، فإذا شُحنت مجموعتهما بشحنة كلية مقدارها (600µC) بوساطة مصدر فولطية مستمرة ثم فُصلت عنه، فإن فرق الجهد بين طرفي المجموعة (وكل من المتسعتين) يساوي:","opts":["V=75V","V=12.5V","V=50V","V=25V"],"a":2,"why":"Ceq=4+8=12µF. V=Q/Ceq=600/12=50V. Q1=C1V=200µC، Q2=C2V=400µC. U1=½C1V²=5mJ، U2=½C2V²=10mJ."},{"ch":"g6c1","q":"إذا أُدخل لوح عازل كهربائي ثابت عزله (k=2) بين صفيحتي المتسعة الثانية (C2) بعد فصل المجموعة عن المصدر (مع بقاء المتسعتين مربوطتين مع بعضهما)، فإن الشحنة الجديدة على المتسعة (C2) تصبح:","opts":["800µC","400µC","300µC","480µC"],"a":3,"why":"C2الجديدة=2×8=16µF. Ceqالجديدة=4+16=20µF. الشحنة الكلية محفوظة=600µC (متسعتان متصلتان مع بعضهما فقط، منعزلتان عن الخارج). V'=600/20=30V. Q2'=16×30=480µC (وQ1'=4×30=120µC)."},{"ch":"g6c1","q":"لديك ثلاث متسعات سعاتها (C1=6µF، C2=9µF، C3=18µF) ومصدر فرق جهد كهربائي مستمر مقداره (6V). لأكبر مقدار للسعة المكافئة يجب ربط المتسعات الثلاث:","opts":["بربط اثنتين على التوازي والثالثة على التوالي معهما","على التوالي جميعها","بربط اثنتين على التوالي والثالثة على التوازي معهما","على التوازي جميعها"],"a":3,"why":"أكبر Ceq تكون بالتوازي دائماً: Ceq=6+9+18=33µF. الشحنات: Q1=C1V=36µC، Q2=54µC، Q3=108µC، ومجموعها 198µC."},{"ch":"g6c1","q":"أما لأصغر مقدار للسعة المكافئة لنفس المتسعات الثلاث (C1=6µF، C2=9µF، C3=18µF) مع نفس مصدر (6V)، فإن مقدار الشحنة المختزنة على صفيحتي كل متسعة (وهي نفسها على الثلاث لأنها على التوالي) يساوي:","opts":["Q=198µC","Q=36µC","Q=6µC","Q=18µC"],"a":3,"why":"أصغر Ceq تكون بالتوالي: 1/Ceq=1/6+1/9+1/18=6/18 ⇒ Ceq=3µF. الشحنة (نفسها على الثلاث لأنها على التوالي) Q=CeqV=3×6=18µC."},{"ch":"g6c1","q":"أربع متسعات (C1=6µF، C2=3µF، C3=2µF، C4=4µF) رُبطت مع بعضها كما في الشكل (41): (C1) على التوالي مع (C2) وهذه المجموعة على التوازي مع (C3)، والمحصّلة على التوالي مع (C4)، وفرق الجهد الكلي بين طرفي الشبكة (ΔV=40V). ما مقدار السعة المكافئة للمجموعة؟","opts":["Ceq=15µF","Ceq=2µF","Ceq=4µF","Ceq=0.5µF"],"a":1,"why":"C1توالي C2=(6×3)/9=2µF. بالتوازي مع C3(2µF)=4µF. بالتوالي مع C4(4µF)=(4×4)/8=2µF ⇒ Ceq=2µF. Q_كلي=Ceq×ΔV=80µC (على C4). فرق جهد الفرع المتوازي=80/4=20V (وV4=20V أيضاً). Q3=2×20=40µC، وQ1=Q2=2µF×20V=40µC (V1=40/6≈6.7V، V2=40/3≈13.3V). U4=½C4V4²=0.8mJ."},{"ch":"g6c1","q":"متسعتان (C1=6µF، C2=3µF) رُبطتا على التوالي مع بعضهما ثم رُبطت مجموعتهما بين قطبي بطارية فرق الجهد بينهما (90V) كما في الشكل (42-a). بعد اكتمال الشحن، فُصلت المتسعتان عن بعضهما وعن البطارية دون حدوث ضياع للطاقة، ثم أُعيد ربطهما مع بعضهما بحيث تتلامس الصفائح المتشابهة الشحنة (كما في الشكل 42-b). ما مقدار الشحنة المختزنة على المتسعة (C1) بعد إعادة الربط؟","opts":["180µC","120µC","360µC","240µC"],"a":3,"why":"قبل الفصل (على التوالي): Ceq=(6×3)/9=2µF، Q=Ceq×90=180µC (نفس الشحنة على كل من C1،C2). عند إعادة الربط بتماسّ الشحنات المتشابهة: الشحنة الكلية=180+180=360µC تتوزع على Ceq_توازي=6+3=9µF بفرق جهد مشترك V'=360/9=40V. Q1'=C1×V'=6×40=240µC (وQ2'=3×40=120µC)."},{"ch":"g6c1","q":"أما إذا أُعيد ربط المتسعتين من المسألة السابقة (C1=6µF، C2=3µF، كل منهما كانت مشحونة بـ180µC) بحيث تتلامس الصفائح المختلفة الشحنة (كما في الشكل 42-c)، فإن مقدار الشحنة المختزنة على كل من المتسعتين بعد إعادة الربط يصبح:","opts":["180µC لكل منهما كما كانت","240µC و120µC على التوالي كما في الحالة الأولى","60µC لكل منهما","صفراً لكلتا المتسعتين"],"a":3,"why":"كانت شحنتاهما الابتدائيتان متساويتين بالمقدار (180µC لكل منهما، لأنهما كانتا على التوالي)؛ فعند تلامس القطبين المختلفين تُلغي إحداهما الأخرى تماماً (الشحنة الصافية = 180-180=0)، فيصبح فرق الجهد المشترك صفراً وتتفرغ المتسعتان كلياً."},{"ch":"g6c1","q":"خمس متسعات (C2=3µF، C3=6µF، C4=18µF، C5=12µF، C6=9µF) رُبطت على هيئة شبكة جسر بين نقطتين (a) و(b) كما في الشكل (43): تصل (C3) و(C4) من (a) إلى عقدتين وسطيتين، وتصل (C2) و(C6) من العقدتين الوسطيتين إلى (b)، وتصل (C5) بين العقدتين الوسطيتين (ذراع الجسر). ما مقدار السعة المكافئة للمجموعة بين (a) و(b)؟","opts":["Ceq=48µF","Ceq=4.36µF","Ceq=12µF","Ceq=8µF"],"a":3,"why":"نسبة الذراعين: C3/C2=6/3=2 وC4/C6=18/9=2 (متساويتان) ⇒ الجسر متوازن، فلا تنساب شحنة خلال C5 ويمكن إهمالها. تُختزل الشبكة إلى مسارين متوازيين بين a وb: مسار (C3 توالي C2)=(6×3)/9=2µF، ومسار (C4 توالي C6)=(18×9)/27=6µF. مجموعهما بالتوازي: Ceq=2+6=8µF. (لو طُبق فرق جهد 20V بين a وb: Q_كلية=160µC، موزعة 40µC على مسار C3-C2 و120µC على مسار C4-C6، وQ5=0)."},{"ch":"g6c2","q":"ما القانون الصحيح للقوة المغناطيسية المؤثرة في شحنة متحركة داخل مجال مغناطيسي منتظم؟","opts":["F_b = qvB","F_b = qvB sinθ","F_b = qv/B","F_b = qBsinθ"],"a":1,"why":"القانون العام يتضمن الزاوية θ بين السرعة والمجال: F_b = qvB sinθ."},{"ch":"g6c2","q":"علّل: شحنة تتحرك موازية لمجال مغناطيسي منتظم لا تتأثر بأي قوة مغناطيسية.","opts":["لأن الشحنة معدومة","لأن θ=0° وsin0°=0 فتكون F_b=صفر","لأن السرعة معدومة","لأن المجال معدوم"],"a":1,"why":"F_b=qvBsinθ، وعندما تكون v موازية لـB فإن θ=0° وsin0°=0، فلا قوة تؤثر."},{"ch":"g6c2","q":"شحنة q=5×10⁻⁶ C تتحرك بسرعة v=4×10⁴ m/s عمودياً على مجال B=0.2T. ما مقدار القوة المغناطيسية؟","opts":["4×10⁻² N","4×10⁻¹ N","2×10⁻² N","4×10⁻³ N"],"a":0,"why":"بما أن θ=90° فإن sinθ=1، إذن F_b=qvB=5×10⁻⁶×4×10⁴×0.2=0.04N=4×10⁻² N."},{"ch":"g6c2","q":"ما محصّلة القوتين الكهربائية والمغناطيسية المؤثرتين معاً في شحنة متحركة داخل مجالين متزامنين؟","opts":["قانون فاراداي","قوة لورنتز","قانون لينز","القوة الدافعة الحركية"],"a":1,"why":"قوة لورنتز F_Lorentz = F_e + F_b هي محصّلة القوة الكهربائية والمغناطيسية معاً."},{"ch":"g6c2","q":"في مرشّح السرعة، عند توازن القوتين الكهربائية والمغناطيسية، ما السرعة التي تمرّ من الفتحة؟","opts":["v = E×B","v = E/B","v = B/E","v = qE"],"a":1,"why":"عند التوازن qE=qvB ⟹ v=E/B — لا تمرّ إلا الشحنات بهذه السرعة بالضبط."},{"ch":"g6c2","q":"لماذا لا تُغيّر القوة المغناطيسية مقدار سرعة الشحنة المتحركة؟","opts":["لأنها قوة ضعيفة جداً","لأنها عمودية دائماً على السرعة فلا تبذل شغلاً","لأن الشحنة ثابتة","لأن المجال ضعيف"],"a":1,"why":"القوة المغناطيسية عمودية دائماً على v، وأي قوة عمودية على الحركة لا تبذل شغلاً (W=Fdcos90°=0) فلا تُغيّر الطاقة الحركية."},{"ch":"g6c2","q":"ما القانون الذي يفسّر عمل قارئ البطاقة الممغنطة؟","opts":["قانون فاراداي (تغيّر الفيض المخترق للملف يحتثّ تياراً)","قانون كولوم","قانون نيوتن الأول","قانون باسكال"],"a":0,"why":"حركة الشريط الممغنط أمام الملف تُغيّر الفيض بسرعة، فيُحتثّ تيار يحمل البيانات — تطبيق مباشر لقانون فاراداي."},{"ch":"g6c2","q":"لماذا يُصنع وتر القيثار الكهربائي من معدن فيرومغناطيسي تحديداً؟","opts":["ليكون خفيف الوزن فقط","ليتأثر بالمجال المغناطيسي فيُغيّر الفيض عند اهتزازه، فيُحتثّ تيار في الملف تحته","ليكون أرخص من الأوتار العادية","ليمنع انقطاعه أثناء العزف"],"a":1,"why":"الوتر الفيرومغناطيسي يتفاعل مع المجال، فاهتزازه يُغيّر الفيض المخترق للملف تكراراً، فيُحتثّ تيار صوتي."},{"ch":"g6c2","q":"لماذا لا يعمل الطباخ الحثّي بكفاءة مع إناء ألمنيوم عادي (ضعيف المغناطيسية)؟","opts":["لأن الألمنيوم لا يتفاعل مغناطيسياً بقوة، فتضعف التيارات الدوّامة المسخّنة فيه","لأن الألمنيوم يذوب فوراً عند التسخين","لأن الطباخ الحثّي لا يعمل مع أي معدن إطلاقاً","لا علاقة لنوع المعدن بالتسخين الحثّي"],"a":0,"why":"التسخين الحثّي يعتمد على قوة التيارات الدوّامة، وهي أضعف بكثير في المعادن غير المغناطيسية كالألمنيوم."},{"ch":"g6c2","q":"أي ظاهرة فيزيائية مشتركة بين البطاقة الممغنطة والقيثار الكهربائي؟","opts":["كلاهما يعتمد على تغيّر الفيض المغناطيسي المخترق لملف لتوليد قوة دافعة محتثة (قانون فاراداي)","كلاهما لا علاقة له بالحث الكهرومغناطيسي إطلاقاً","كلاهما يستهلك طاقة نووية","كلاهما يعتمد على الحث المتبادل فقط دون فاراداي"],"a":0,"why":"كلاهما يولّد تياراً محتثاً بسبب تغيّر الفيض عبر الزمن — الأول بحركة الشريط، والثاني باهتزاز الوتر."},{"ch":"g6c2","q":"ما الظاهرة الفيزيائية التي تُسخّن قاع الإناء في الطباخ الحثّي تحديداً؟","opts":["التيارات الدوّامة الناتجة عن تغيّر الفيض المغناطيسي داخل قاعدة الإناء المعدنية","احتكاك الإناء بالسطح الزجاجي مباشرة","تفاعل كيميائي بين الإناء والزجاج","أشعة تحت حمراء يُصدرها الملف"],"a":0,"why":"المجال المتناوب يحتثّ تيارات دوّامة داخل قاعدة الإناء نفسها، فتُسخّنها عبر مقاومتها الكهربائية."},{"ch":"g6c2","q":"ما القاسم المشترك بين كل تطبيقات هذا الفصل — من الساق المنزلقة حتى الطباخ الحثّي؟","opts":["تغيّر الفيض المغناطيسي عبر الزمن يولّد قوة دافعة محتثة، بصرف النظر عن سبب هذا التغيّر","كلها تحتاج بطارية داخلية لتعمل","كلها تستعمل بالضبط نفس نوع المعدن","لا قاسم مشترك حقيقي بينها"],"a":0,"why":"هذا هو محور الفصل كله: أي تغيّر في الفيض — بحركة أو دوران أو تيار متغيّر — يولّد قوة دافعة محتثة."},{"ch":"g6c2","q":"ما الذي يولّد التيار المحتث فعلياً؟","opts":["الفيض المغناطيسي نفسه مهما كان ثابتاً","تغيّر الفيض المغناطيسي عبر الزمن فقط","عدد لفّات الملف فقط","نوع المغناطيس المستخدم"],"a":1,"why":"القاعدة الذهبية: مغناطيس أو فيض ساكن لا يولّد شيئاً. لا بدّ من تغيّر الفيض عبر الزمن (ΔΦ_B/Δt) لتوليد تيار محتث."},{"ch":"g6c2","q":"ما قانون القوة الدافعة الكهربائية الحركية الناتجة عن ساق موصلة تتحرك عمودياً على مجال مغناطيسي؟","opts":["ε = vBℓ","ε = vB/ℓ","ε = v/(Bℓ)","ε = vℓ/B"],"a":0,"why":"من اتزان القوة الكهربائية والمغناطيسية على شحنات الساق نصل إلى ε = vBℓ."},{"ch":"g6c2","q":"ساق طولها 0.4m تتحرك بسرعة 10 m/s عمودياً على مجال 0.6T، ومقاومة الدائرة 3Ω. ما مقدار التيار المحتث؟","opts":["0.8 A","2.4 A","0.24 A","8 A"],"a":0,"why":"ε = vBℓ = 10×0.6×0.4 = 2.4V، ثم I = ε/R = 2.4/3 = 0.8A."},{"ch":"g6c2","q":"لماذا تظهر قوة مغناطيسية معرقلة على الساق بعد انسياب التيار المحتث فيها؟","opts":["لأن التيار المحتث نفسه موجود داخل المجال B فتنشأ عليه قوة F=BIℓ تعاكس حركة الساق","لأن مقاومة الساق تزداد فجأة","لأن سرعة الساق تتحول لصفر تلقائياً","لا توجد أي قوة معرقلة في الحقيقة"],"a":0,"why":"الساق تحمل تياراً محتثاً وهي داخل مجال مغناطيسي، فتتأثر بقوة F=BIℓ اتجاهها معاكس لحركتها."},{"ch":"g6c2","q":"أثناء سحب الساق بسرعة ثابتة، كيف تقارَن القدرة الميكانيكية المبذولة بالقدرة الكهربائية المتبدّدة في المقاومة؟","opts":["القدرة الميكانيكية أكبر دائماً","القدرة الكهربائية أكبر دائماً","القدرتان متساويتان تماماً (حفظ الطاقة)","لا توجد علاقة بينهما"],"a":2,"why":"P_ميكانيكية = F×v = v²B²ℓ²/R، وP_كهربائية = I²R = v²B²ℓ²/R — متساويتان بالضبط، وهذا مبدأ عمل كل مولّد."},{"ch":"g6c2","q":"علل: مغناطيس ساكن تماماً بجانب ملف موصل، مهما كان قوياً، لا يولّد فيه أي تيار محتث.","opts":["لأن الملف معزول كهربائياً","لأن الفيض المخترق للملف لا يتغيّر مع الزمن (ΔΦ_B/Δt=0)","لأن المغناطيس ضعيف","لأن الملف يحتاج بطارية ليعمل"],"a":1,"why":"بلا حركة نسبية أو تغيّر، يبقى الفيض ثابتاً، وبلا تغيّر في الفيض لا يتولّد أي تيار محتث."},{"ch":"g6c2","q":"ما الفيض المغناطيسي Φ_B فيزيائياً؟","opts":["قوة المجال المغناطيسي عند نقطة معينة","مقياس لعدد خطوط المجال التي تخترق مساحة معينة عمودياً","سرعة تغيّر المجال المغناطيسي","الشحنة الكلية للمغناطيس"],"a":1,"why":"الفيض Φ_B=BAcosθ يقيس مقدار خطوط المجال المخترقة لمساحة الحلقة عمودياً، لا مجرد وجود المجال."},{"ch":"g6c2","q":"ما وحدة قياس الفيض المغناطيسي في النظام الدولي؟","opts":["تسلا (T)","أمبير (A)","ويبر (Wb)","فاراد (F)"],"a":2,"why":"وحدة الفيض المغناطيسي هي الويبر Wb، بينما التسلا T هي وحدة كثافة الفيض B."},{"ch":"g6c2","q":"حلقة مساحتها 0.1 m² داخل مجال كثافته 0.4T، ومتجه مساحتها يوازي المجال تماماً (θ=0°). ما مقدار الفيض؟","opts":["0.04 Wb","0.4 Wb","4 Wb","صفر"],"a":0,"why":"عند θ=0°: Φ=BA=0.4×0.1=0.04 Wb (لأن cos0°=1)."},{"ch":"g6c2","q":"نفس الحلقة السابقة، لكن أُديرت حتى صار مستواها موازياً لخطوط المجال تماماً. ما مقدار الفيض الآن؟","opts":["0.04 Wb (لم يتغيّر)","0.02 Wb","صفر","0.08 Wb"],"a":2,"why":"مستوى الحلقة موازٍ للمجال يعني متجه مساحتها عمودي عليه، أي θ=90°، وcos90°=0 ⟹ Φ=صفر."},{"ch":"g6c2","q":"أيٌّ من التالي ليس من الطرائق الثلاث لتغيير الفيض المغناطيسي المخترق لحلقة؟","opts":["تغيير زاوية ميل الحلقة داخل المجال","تغيير مساحة الحلقة","تغيير كثافة الفيض المغناطيسي B","تغيير درجة حرارة الحلقة"],"a":3,"why":"الطرائق الثلاث في Φ=BAcosθ هي: تغيير θ أو A أو B فقط. درجة الحرارة ليست عاملاً في القانون."},{"ch":"g6c2","q":"علل: عندما يوازي مستوى حلقة موصلة خطوط مجال مغناطيسي منتظم، يكون الفيض المخترق لها صفراً.","opts":["لأن متجه مساحتها يصبح عمودياً على المجال (θ=90°) وcos90°=0","لأن مساحة الحلقة تصبح صفراً فعلياً","لأن المجال نفسه ينعدم عندها","لأن الحلقة تفقد موصليتها"],"a":0,"why":"متجه المساحة عمودي دائماً على مستوى الحلقة، فإذا وازى المستوى المجالَ صار المتجه عمودياً عليه (θ=90°) فيصبح الفيض صفراً."},{"ch":"g6c2","q":"ماذا ينص قانون فاراداي؟","opts":["القوة الدافعة المحتثة تتناسب طردياً مع الفيض المغناطيسي نفسه","القوة الدافعة المحتثة تتناسب طردياً مع المعدّل الزمني لتغيّر الفيض","التيار المحتث يتناسب عكسياً مع عدد لفّات الملف","الفيض المغناطيسي يساوي صفراً دائماً داخل الملفات"],"a":1,"why":"قانون فاراداي: ε=−NΔΦ_B/Δt — القوة الدافعة تتناسب مع معدّل تغيّر الفيض عبر الزمن، لا مع الفيض نفسه."},{"ch":"g6c2","q":"ما الصيغة الرياضية الصحيحة لقانون فاراداي لملف عدد لفّاته N؟","opts":["ε = N ΔΦ_B × Δt","ε = −N (ΔΦ_B/Δt)","ε = ΔΦ_B/(NΔt)","ε = N/ΔΦ_B"],"a":1,"why":"الصيغة الصحيحة: ε=−N(ΔΦ_B/Δt)، والإشارة السالبة من قانون لنز."},{"ch":"g6c2","q":"علل: يُصنع المولّد الكهربائي من ملف بعدد لفّات كبير جداً، لا من لفة واحدة.","opts":["لأن القوة الدافعة المحتثة تتناسب طردياً مع عدد اللفّات N","لأن اللفة الواحدة لا تولّد أي قوة دافعة إطلاقاً","لأن كثرة اللفّات تُلغي مقاومة الملف","لا فائدة حقيقية من زيادة عدد اللفّات"],"a":0,"why":"كل لفة تضيف قوتها الدافعة الخاصة، وتُجمع اللفات على التوالي، فتتناسب ε طردياً مع N."},{"ch":"g6c2","q":"ملف تغيّر الفيض المخترق له بنفس المقدار مرتين: مرة خلال 2 ثانية، ومرة خلال 0.5 ثانية فقط. متى تكون القوة الدافعة المحتثة أكبر؟","opts":["عندما يحصل التغيّر خلال 0.5 ثانية (تغيّر أسرع)","عندما يحصل التغيّر خلال 2 ثانية (تغيّر أبطأ)","القوة الدافعة نفسها في الحالتين","لا علاقة بين الزمن والقوة الدافعة"],"a":0,"why":"ε تتناسب عكسياً مع Δt لنفس مقدار ΔΦ، فكلما كان التغيّر أسرع (Δt أصغر) كانت ε أكبر."},{"ch":"g6c2","q":"ملف من 50 لفة مساحة اللفة 20cm²، تغيّرت كثافة الفيض من صفر إلى 0.8T خلال 0.4s (متجه المساحة يوازي المجال). ما مقدار القوة الدافعة المحتثة؟","opts":["0.2 V","2 V","0.02 V","20 V"],"a":0,"why":"ε=NA(ΔB/Δt)=50×20×10⁻⁴×(0.8/0.4)=50×0.002×2=0.2V."},{"ch":"g6c2","q":"ماذا تدل الإشارة السالبة في قانون فاراداي ε=−N(ΔΦ_B/Δt)؟","opts":["أن القوة الدافعة المحتثة سالبة دائماً فعلياً كعدد","أن القوة الدافعة المحتثة تعارض دائماً التغيّر الذي ولّدها (قانون لنز)","أن الفيض المغناطيسي سالب دائماً","لا معنى فيزيائي لها، مجرد اصطلاح رياضي"],"a":1,"why":"الإشارة السالبة تعبّر عن قانون لنز: القوة الدافعة المحتثة تعارض التغيّر الذي أنتجها، وليست مجرد اصطلاح شكلي."},{"ch":"g6c2","q":"ماذا ينصّ قانون لنز؟","opts":["التيار المحتث يتجه بحيث يُعارض التغيّر في الفيض الذي ولّده","التيار المحتث يتجه دائماً مع التغيّر في الفيض ليُسرّعه","التيار المحتث ليس له اتجاه محدّد","قانون لنز يحدّد مقدار التيار لا اتجاهه"],"a":0,"why":"نصّ قانون لنز: المجال المحتث يعارض التغيّر الذي ولّده — الطبيعة تقاوم التغيير دائماً."},{"ch":"g6c2","q":"مغناطيس يقترب من ملف موصل بقطبه الشمالي N المواجه له. أي قطب يتولّد في وجه الملف المواجه للمغناطيس؟","opts":["قطب شمالي N (ليتنافر مع المغناطيس ويعارض اقترابه)","قطب جنوبي S (ليتجاذب مع المغناطيس)","لا يتولّد أي قطب","يعتمد على مادة الملف فقط"],"a":0,"why":"عند الاقتراب (الفيض يتزايد)، يولّد الملف قطباً مطابقاً للقطب المواجه فيتنافران، معارضاً استمرار الاقتراب."},{"ch":"g6c2","q":"مغناطيس يبتعد عن ملف بقطبه الجنوبي S المواجه له. ما نوع القوة بين المغناطيس والملف؟","opts":["تنافر","تجاذب (لأن الملف يولّد قطباً شمالياً N ليعارض الابتعاد)","لا توجد أي قوة","تعتمد على سرعة الابتعاد فقط"],"a":1,"why":"عند الابتعاد (الفيض يتناقص)، يولّد الملف القطب المعاكس (N) فيتجاذبان، معارضاً استمرار الابتعاد."},{"ch":"g6c2","q":"علل: يُعدّ قانون لنز تطبيقاً لقانون حفظ الطاقة.","opts":["لأن التيار المحتث يعارض التغيّر الذي ولّده، فيتطلّب شغلاً ميكانيكياً يتحوّل لطاقة كهربائية — لا طاقة من العدم","لأن قانون لنز لا علاقة له بالطاقة إطلاقاً","لأن التيار المحتث يزيد الطاقة الكلية للنظام دون أي شغل خارجي","لأن المغناطيس يفقد طاقته الداخلية تلقائياً"],"a":0,"why":"لو ساعد التيار المحتث التغيير بدل معارضته لحصلنا على طاقة مجانية، وهذا مستحيل — فمقاومته تعني لزوم شغل خارجي يتحول لطاقة كهربائية."},{"ch":"g6c2","q":"ماذا تُسمّى التيارات المحتثة التي تنساب في مسارات دائرية مقفلة داخل صفيحة معدنية كاملة (لا ملف رفيع)؟","opts":["تيارات دوّامة (فوكو)","تيارات مستمرة","تيارات وزارية","تيارات ساكنة"],"a":0,"why":"تُسمّى التيارات الدوّامة (تيارات فوكو)، وتشبه دوّامات الماء في مسارها الدائري المغلق داخل الكتلة الموصلة."},{"ch":"g6c2","q":"ملف من 50 لفة مساحة اللفة 20cm²، تغيّرت كثافة الفيض من صفر إلى 0.8T خلال 0.4s. إذا صنع متجه المجال زاوية 30° مع مستوى اللفة (لا مع متجه مساحتها)، ما مقدار القوة الدافعة المحتثة؟","opts":["0.1 V","0.2 V","0.173 V","0.4 V"],"a":0,"why":"الزاوية مع متجه المساحة = 90°−30°=60°. فـε=NA(ΔB/Δt)×cos60°=0.2×0.5=0.1V."},{"ch":"g6c2","q":"ما تعريف معامل الحث الذاتي L لملف؟","opts":["النسبة بين الفيض المرتبط بالملف (NΦ_B) والتيار المسبّب له: NΦ_B=LI","مقاومة الملف الكهربائية فقط","عدد لفّات الملف فقط","طول السلك المستعمل في لفّ الملف"],"a":0,"why":"المحاثة L ثابت تناسب بين NΦ_B والتيار I، أي NΦ_B=LI — صفة هندسية للملف لا تتغيّر بتغيّر التيار."},{"ch":"g6c2","q":"ما وحدة قياس معامل الحث الذاتي L؟","opts":["الهنري (H)","الفاراد (F)","التسلا (T)","الويبر (Wb)"],"a":0,"why":"وحدة المحاثة هي الهنري H، نسبةً للعالم جوزيف هنري."},{"ch":"g6c2","q":"ماذا يحدث لتيار ملف لحظة غلق دائرته؟","opts":["يقفز فوراً لقيمته العظمى","ينمو تدريجياً من الصفر بسبب معارضة الحث الذاتي لتغيّره","يبقى صفراً دائماً","يتذبذب بشكل عشوائي"],"a":1,"why":"القوة الدافعة الذاتية تعارض نموّ التيار (قانون لنز)، فينمو تدريجياً بدل أن يقفز فجأة."},{"ch":"g6c2","q":"ملف معامل حثه الذاتي 2.5mH، ينساب فيه تيار مستمر 4A. ما مقدار الطاقة المختزنة في مجاله؟","opts":["0.02 J","0.2 J","2 J","10 J"],"a":0,"why":"PE=½LI²=½×2.5×10⁻³×(4)²=½×2.5×10⁻³×16=0.02J."},{"ch":"g6c2","q":"علل: لا يمكن أن يتغيّر التيار في ملف تغيّراً فجائياً (قفزة لحظية).","opts":["لأن القوة الدافعة الذاتية المحتثة تعارض أي تغيّر في التيار وتكبح سرعته","لأن الملف عازل كهربائياً تماماً","لأن التيار يحتاج مصدراً خارجياً جديداً في كل لحظة","لا يوجد سبب فيزيائي، هذا افتراض نظري فقط"],"a":0,"why":"بقانون لنز، القوة الدافعة الذاتية تعاكس دائماً تغيّر التيار الذي ولّدها، فتكبح سرعة أي تغيّر مفاجئ."},{"ch":"g6c2","q":"أيّ العبارتين صحيحة عن المحث المهمَل المقاومة؟","opts":["يستهلك الطاقة ويحوّلها حرارة كالمقاومة","لا يستهلك الطاقة، بل يختزنها في مجاله المغناطيسي ثم يعيدها للدائرة","يمنع مرور أي تيار نهائياً","يزيد الطاقة الكلية للدائرة من العدم"],"a":1,"why":"المحث المهمَل المقاومة لا يبدّد طاقة حرارياً، بل يختزنها مغناطيسياً (PE=½LI²) ويعيدها عند تلاشي التيار."},{"ch":"g6c2","q":"ما المقصود بالحث المتبادل؟","opts":["تولّد قوة دافعة محتثة في ملف بسبب تغيّر التيار في ملف آخر مجاور له، دون اتصال سلكي بينهما","تولّد قوة دافعة محتثة في الملف بسبب تغيّر تياره هو نفسه","مرور تيار مباشر بين ملفين متصلين بسلك واحد","تنافر دائم بين ملفين متجاورين"],"a":0,"why":"الحث المتبادل: تيار متغيّر في ملف يحثّ قوة دافعة في ملف مجاور، دون أي اتصال سلكي بينهما."},{"ch":"g6c2","q":"ما الصيغة الصحيحة للقوة الدافعة المحتثة في الملف الثانوي؟","opts":["ε₂ = −M(ΔI₁/Δt)","ε₂ = −L(ΔI₂/Δt)","ε₂ = M × I₁ × Δt","ε₂ = M/I₁"],"a":0,"why":"ε_ind(2)=−M(ΔI₁/Δt) — القوة الدافعة بالثانوي تعتمد على معدّل تغيّر تيار الابتدائي، لا تياره نفسه."},{"ch":"g6c2","q":"متى يحدث اقتران مغناطيسي تام بين ملفين؟","opts":["عندما يكونان بعيدين جداً عن بعضهما","عندما يُلفّان حول حلقة مغلقة واحدة من الحديد المطاوع فيمرّ كل الفيض عبر كليهما","عندما يكون تيار كل منهما ثابتاً بلا تغيّر","لا يحدث اقتران تام أبداً في الواقع العملي"],"a":1,"why":"الاقتران التام يحدث عندما يُلفّ الملفان حول قلب حديدي مغلق واحد يوجّه كل الفيض عبرهما معاً، كما في المحوّلة."},{"ch":"g6c2","q":"ما الصيغة الصحيحة لمعامل الحث المتبادل M عند الاقتران المغناطيسي التام؟","opts":["M = L₁ + L₂","M = √(L₁ × L₂)","M = L₁ × L₂","M = L₁ / L₂"],"a":1,"why":"عند الاقتران التام: M=√(L₁×L₂)."},{"ch":"g6c2","q":"ملفان اقترانهما تام، محاثتاهما 2H و8H. ما مقدار معامل الحث المتبادل بينهما؟","opts":["4 H","16 H","10 H","1.6 H"],"a":0,"why":"M=√(L₁×L₂)=√(2×8)=√16=4H."},{"ch":"g6c2","q":"أيّ الأجهزة التالية يعتمد مبدأ عمله على الحث المتبادل؟","opts":["المحوّلة الكهربائية (Transformer) وأجهزة الشحن اللاسلكي","المقاومة الكهربائية العادية","البطارية الجافة","المتسعة الكهربائية"],"a":0,"why":"المحوّلات والشحن اللاسلكي يعتمدان على نقل طاقة بين ملفين عبر الحث المتبادل، دون اتصال سلكي مباشر."},{"ch":"g6c2","q":"ما القوة التي تدفع الشحنات لتتحرك في حلقة موصلة ساكنة تماماً موضوعة في مجال مغناطيسي متغيّر؟","opts":["قوة لورنتز الحركية (F=qvB) فقط","مجال كهربائي محتث ينشأ بسبب تغيّر المجال المغناطيسي","لا توجد أي قوة، ولن يمرّ أي تيار في الحلقة","قوة الجاذبية الأرضية"],"a":1,"why":"بما أن الحلقة ساكنة (v=0) فلا قوة لورنتز حركية. التغيّر في B نفسه يولّد مجالاً كهربائياً محتثاً يدفع الشحنات."},{"ch":"g6c2","q":"ما الفرق الجوهري بين خطوط المجال الكهربائي المستقر وخطوط المجال الكهربائي المحتث؟","opts":["لا فرق بينهما إطلاقاً","خطوط المستقر تبدأ من شحنة موجبة وتنتهي بسالبة، بينما خطوط المحتث مغلقة بلا بداية أو نهاية","خطوط المحتث تبدأ من شحنة موجبة فقط","خطوط المستقر مغلقة دائماً على نفسها"],"a":1,"why":"المستقر ينشأ من شحنات (خطوط مفتوحة، +⟶−)، بينما المحتث ينشأ من تغيّر الفيض (خطوط مغلقة بلا شحنة)."},{"ch":"g6c2","q":"ما الذي يُنشئ المجال الكهربائي غير المستقر (المحتث)؟","opts":["شحنات ساكنة فقط","التغيّر في المجال المغناطيسي عبر الزمن","التيار الكهربائي الثابت فقط","درجة حرارة الموصل"],"a":1,"why":"المجال المحتث مصدره تغيّر B عبر الزمن، لا أي شحنة كهربائية."},{"ch":"g6c2","q":"اتجاه المجال الكهربائي المحتث (وبالتالي التيار الناتج عنه) يُحدَّد بأي قانون؟","opts":["قانون كولوم","قانون لنز","قانون أوم","قانون نيوتن الثاني للحركة"],"a":1,"why":"قانون لنز هو ما يحدّد اتجاه المجال المحتث والتيار الناتج عنه، بحيث يعارضان التغيّر المسبِّب لهما."},{"ch":"g6c2","q":"علل: خطوط المجال الكهربائي المحتث مغلقة دائماً، بعكس خطوط المجال الكهربائي المستقر.","opts":["لأن المجال المحتث لا ينشأ من شحنات (لا نقطة بداية أو نهاية)، بل من تغيّر الفيض المغناطيسي المستمر","لأن الشحنات في المجال المحتث سالبة دائماً","لأنه خطأ مطبعي في الكتب المدرسية، ولا فرق حقيقي","لأن المجال المحتث أضعف من المستقر دائماً"],"a":0,"why":"بلا شحنات تُنشئ المجال، لا توجد نقطة بداية أو نهاية تُلزم الخطوط بالتوقف، فتنغلق على نفسها."},{"ch":"g6c2","q":"لو وضعتَ حلقة موصلة ساكنة داخل مجال مغناطيسي متغيّر، ثم أزلتَ الحلقة نفسها، هل يبقى المجال الكهربائي المحتث موجوداً في تلك المنطقة من الفضاء؟","opts":["لا، يختفي المجال المحتث فوراً بغياب الموصل","نعم، لأن المجال المحتث ينشأ من تغيّر B نفسه بغضّ النظر عن وجود موصل — الموصل يكشفه فقط بمرور تيار فيه","يعتمد على نوع المعدن المستعمل في الحلقة","لا معنى للسؤال فيزيائياً"],"a":1,"why":"المجال المحتث خاصية للفضاء نفسه حيث يتغيّر B، لا خاصية للموصل — الموصل وسيلة كشف فقط، لا مصدر."},{"ch":"g6c2","q":"ما قانون القوة الدافعة اللحظية لمولّد التيار المتناوب؟","opts":["ε = NBAω sin(ωt)","ε = NBA cos(ωt)","ε = NBAω","ε = NBω/A"],"a":0,"why":"بتطبيق قانون فاراداي على فيض جيبي Φ=BAcos(ωt)، نحصل على ε=NBAω sin(ωt)."},{"ch":"g6c2","q":"متى تبلغ القوة الدافعة المحتثة بالمولّد ذروتها ε_max؟","opts":["عند ωt=90° (بعد ربع دورة)","عند ωt=0° (بداية الدوران)","عند ωt=180° (نصف دورة)","لا تبلغ ذروة أبداً"],"a":0,"why":"sin(ωt) يبلغ أعظم قيمة له (=1) عند ωt=90°، فتبلغ ε ذروتها ε_max حينها."},{"ch":"g6c2","q":"(سؤال وزاري، الدور الثالث 2019) في مولّد يعطي ذروة ε_max، إذا زيد عدد اللفّات لثلاثة أمثالها، وقُلّل قطر الملف للثلث، وضُوعف التردد الدوراني، فإن الذروة الجديدة تساوي:","opts":["⅔ ε_max","¼ ε_max","3/2 ε_max","3 ε_max"],"a":0,"why":"ε_max=NBAω=NB(πr²)(2πf). التغييرات: N→3N، r→r/3 فـA→A/9، وf→2f فـω→2ω. الجديدة = 3×(1/9)×2 × القديمة = 6/9 = ⅔ ε_max."},{"ch":"g6c2","q":"ما وظيفة حلقة المبادل بمولّد التيار المستمر؟","opts":["عكس التوصيل كلما همّت القطبية بالانعكاس، فيبقى اتجاه التيار الخارج ثابتاً","زيادة سرعة دوران الملف","تحويل التيار المستمر إلى متناوب","منع أي تيار من الخروج من المولّد"],"a":0,"why":"المبادل (نصفا حلقة معزولان) يعكس التوصيل بالخارجي في كل نصف دورة، فيبقى اتجاه التيار الخارج ثابتاً (تيار نبضي أحادي الاتجاه)."},{"ch":"g6c2","q":"لماذا يسحب المحرّك الكهربائي تياراً عالياً لحظة بدء تشغيله، ثم يقلّ التيار تدريجياً؟","opts":["لأن القوة الدافعة المضادّة ε_back تساوي صفراً عند السكون وتكبر مع تسارع الملف، فيقلّ الفرق (V−ε_back) المحدِّد للتيار","لأن مقاومة الملف تزداد فجأة عند البدء","لأن الفولطية المسلّطة تتناقص تدريجياً بعد التشغيل","لا علاقة فيزيائية حقيقية بهذه الظاهرة"],"a":0,"why":"عند السكون ε_back=0 فيكون التيار I=V/R في أعظمه؛ وكلما تسارع الملف كبرت ε_back فقلّ الفرق (V−ε_back) وبالتالي التيار."},{"ch":"g6c2","q":"ما الفائدة العملية للمولّد ثلاثي الطور مقارنة بمولّد الطور الواحد؟","opts":["يجهّز تياراً أكبر مقداراً، مناسباً لنقل الكهرباء وتشغيل المحرّكات الصناعية الكبيرة","أصغر حجماً من مولّد الطور الواحد دائماً","لا يحتاج مغناطيساً إطلاقاً","يعمل فقط بالتيار المستمر لا المتناوب"],"a":0,"why":"ثلاثة ملفات متباعدة 120° تجهّز تياراً أكبر مقداراً بثلاثة خطوط نقل، ولهذا يُستعمل بشبكات نقل الكهرباء والمحرّكات الصناعية الكبيرة."},{"ch":"g6c2","q":"أي من الأشكال الآتية (لاحظ الشكل 57) يبيّن الاتجاه الصحيح للتيار الكهربائي المحتث في الحلقة الموصلة (الملف) بسبب حركة المغناطيس؟","opts":["a","b","c","d"],"a":0,"why":"القطب المواجه للملف هو القطب السفلي من المغناطيس (الأقرب للملف). في (a): القطب المواجه N يقترب (v↓) فيزداد الفيض النازل داخل الملف، فيعاكسه تيار محتث يصنع فيضاً صاعداً؛ بقاعدة اليد اليمنى هذا يعني تياراً عكس عقارب الساعة كما يُرى من فوق (من جهة المغناطيس) — يطابق الرسم ✓. في (b): السرعة صفر فلا قوة دافعة كهربائية محتثة إطلاقاً بصرف النظر عمّا هو مرسوم، فهو خطأ حتماً. في (c): نفس القطب المواجه N يبتعد الآن (v↑) فيتناقص الفيض النازل، فيحاول التيار المحتث الحفاظ عليه بصنع فيض نازل أيضاً = تيار مع عقارب الساعة من فوق؛ لكن الرسم في (c) مطابق لـ(a) (عكس عقارب الساعة) وهو خطأ لهذه الحالة. في (d): القطب المواجه S يبتعد (v↑) فيتناقص الفيض الصاعد، فيحاول التيار الحفاظ عليه = عكس عقارب الساعة من فوق؛ لكن الرسم يُظهره مع عقارب الساعة، فهو خطأ أيضاً. النتيجة: (a) فقط هو الصحيح فيزيائياً."},{"ch":"g6c2","q":"في الشكل (58) حلقة مصنوعة من النحاس، وضعت في مستوي الورقة وموصولة مع المقاومة R، سُلط عليها مجال مغناطيسي باتجاه عمودي على مستوي الورقة خارجاً منه نحو الناظر. في أي حالة من الحالات التالية ينساب تيار محتث في المقاومة R اتجاهه من اليسار نحو اليمين؟","opts":["عند تزايد الفيض المغناطيسي الذي يخترق الحلقة","عند تناقص الفيض المغناطيسي الذي يخترق الحلقة","عند ثبوت الفيض المغناطيسي الذي يخترق الحلقة","جميع الاحتمالات المذكورة آنفاً"],"a":1,"why":"المجال خارج من مستوي الورقة نحو الناظر. لكي ينساب التيار في R من اليسار إلى اليمين، يجب أن يهبط عبر الساق اليسرى للحلقة ثم يمر بـR يساراً-يميناً ثم يصعد عبر الساق اليمنى، أي أن التيار في الحلقة نفسها يدور عكس عقارب الساعة كما يراه الناظر (من الأعلى للأسفل ثم يمين للأعلى). بقاعدة اليد اليمنى، تيار عكس عقارب الساعة (والمجال قادم نحو الناظر) ينتج مجالاً محتثاً خارجاً من الصفحة أيضاً — أي بنفس اتجاه المجال الأصلي. وبقانون لنز، التيار المحتث يحاول تعويض/الحفاظ على الفيض حين يكون في طريقه للتناقص (لا التزايد)، لذا يجب أن يكون الفيض الأصلي في حالة تناقص. إذن الإجابة: عند تناقص الفيض المغناطيسي."},{"ch":"g6c2","q":"عند سقوط الساق المغناطيسية خلال حلقة واسعة من الألمنيوم موضوعة أفقياً بوساطة حامل تحت الساق (لاحظ الشكل 59)، إذا نظرت إلى الحلقة من موقع فوقها وباتجاه السهم لتحديد اتجاه التيار المحتث فيها، فإن اتجاه التيار المحتث في الحلقة يكون:","opts":["دائماً باتجاه دوران عقارب الساعة","دائماً باتجاه معاكس لدوران عقارب الساعة","باتجاه دوران عقارب الساعة، ثم يكون صفراً للحظة، ثم يكون باتجاه معاكس لدوران عقارب الساعة","باتجاه معاكس لدوران عقارب الساعة، ثم يكون صفراً للحظة، ثم يكون باتجاه دوران عقارب الساعة"],"a":3,"why":"انتبه أولاً: الفيض المخترق للحلقة يبقى <b>نازلاً</b> في الحالتين — فخطوط المجال تخرج من القطب N (السفلي) نازلةً قبل الوصول، وتعود لتدخل القطب S (العلوي) نازلةً أيضاً بعد الاجتياز. الذي يتغيّر هو مقداره لا اتجاهه.<br>① الاقتراب: القطب N يقترب فيتزايد الفيض النازل، فيعاكس التيار المحتث هذا التزايد بصنع فيض صاعد داخل الحلقة = تيار عكس عقارب الساعة (من فوق).<br>② لحظة مرور مركز المغناطيس بمستوي الحلقة: الفيض أعظمي لكن معدل تغيّره لحظياً صفر، فالتيار صفر للحظة.<br>③ الابتعاد: المغناطيس صار تحت الحلقة وقطبه S هو الأقرب لها، فيتناقص الفيض النازل، فيحاول التيار المحتث الحفاظ عليه بصنع فيض نازل أيضاً = تيار مع عقارب الساعة (من فوق).<br>النمط الكامل إذن: عكس عقارب الساعة ← صفر ← مع عقارب الساعة."},{"ch":"g6c2","q":"عند سقوط الساق المغناطيسية خلال حلقة من الألمنيوم غير مقفلة (بها فتحة/قطع) موضوعة أفقياً تحت الساق، لاحظ الشكل (60):","opts":["تتأثر الساق بقوة تنافر في أثناء اقترابها من الحلقة، ثم تتأثر بقوة تجاذب في أثناء ابتعادها عن الحلقة","تتأثر الساق بقوة تجاذب في أثناء اقترابها من الحلقة، ثم تتأثر بقوة تنافر في أثناء ابتعادها عن الحلقة","لا تتأثر الساق بأية قوة في أثناء اقترابها من الحلقة، أو في أثناء ابتعادها عن الحلقة","تتأثر الساق بقوة تنافر في أثناء اقترابها من الحلقة، وكذلك تتأثر بقوة تنافر في أثناء ابتعادها عن الحلقة"],"a":2,"why":"الحلقة هنا غير مقفلة (بها فتحة/قطع)، أي أن الدائرة الكهربائية مفتوحة، فلا يمكن أن ينساب فيها أي تيار محتث مهما تغيّر الفيض خلالها (لا يوجد مسار مغلق للشحنات). وبما أن قوى التنافر/التجاذب المغناطيسية بين الساق والحلقة في مثل هذه التجارب ناتجة أصلاً عن تفاعل المجال مع التيار المحتث (F=BIℓ)، فبانعدام التيار تنعدم القوة، فلا تتأثر الساق بأي قوة إطلاقاً في أي من الحالتين (الاقتراب أو الابتعاد)."},{"ch":"g6c2","q":"في الشكل (61) ملف محزون مجوف مربوط على التوالي مع مصباح كهربائي ومقاومة وبطارية ومفتاح. عندما كان المفتاح مغلقاً في الدائرة كانت شدة توهج المصباح ثابتة. إذا أُدخلت ساق من الحديد المطاوع في جوف الملف، فإن توهج المصباح في أثناء دخول الساق (اللحظة الانتقالية فقط):","opts":["يزداد","يقل","يبقى ثابتاً","يزداد ثم يقل"],"a":1,"why":"إدخال الساق الحديدية (المطاوعة) في جوف الملف يزيد معامل حثه الذاتي L تدريجياً أثناء الإدخال. وبما أن الملف يحمل تياراً بالفعل، فإن ازدياد L أثناء استمرار سريان التيار يولّد قوة دافعة كهربائية محتثة ذاتياً معاكسة (تعاكس الزيادة في الفيض)، فتقاوم هذه القوة المضادة ازدياد/استمرار التيار مؤقتاً فيقل التيار قليلاً أثناء لحظة الإدخال نفسها، فيخفت توهج المصباح خلال تلك الفترة الانتقالية فقط. (بعد استقرار الساق داخل الملف يعود التيار المستمر إلى قيمته الأصلية V/R لأن الملف في الحالة المستقرة لا يُسقط جهداً، فيعود توهج المصباح لحالته الأصلية)."},{"ch":"g6c2","q":"عندما يدور ملف دائري حول محور شاقولي موازٍ لوجهه ويمر من مركزه والمحور عمودي على فيض مغناطيسي كثافته B أفقية ومنتظمة (لاحظ الشكل 62)، تولد أعظم مقدار للقوة الدافعة الكهربائية المحتثة εmax. وعند زيادة عدد لفات الملف إلى ثلاثة أمثال ما كانت عليه، وتقليل قطر الملف إلى نصف ما كان عليه، ومضاعفة التردد الدوراني للملف، فإن المقدار الأعظم الجديد للقوة الدافعة الكهربائية المحتثة يكون:","opts":["(3/2) εmax","(1/4) εmax","(1/2) εmax","3 εmax"],"a":0,"why":"εmax = NBAω، والمساحة A تتناسب مع مربع القطر فتصبح A/4 عند تنصيف القطر. εmax الجديدة = (3N)×B×(A/4)×(2ω) = (3×1×2/4)×NBAω = (6/4)NBAω = (3/2)εmax."},{"ch":"g6c2","q":"تتحقق ظاهرة الحث الذاتي في ملف معين عندما:","opts":["تُسحب ساق مغناطيسية بعيداً عن وجه الملف","يوضع هذا الملف بجوار ملف آخر ينساب فيه تيار كهربائي متغير المقدار لوحدة الزمن","ينساب في هذا الملف تيار كهربائي متغير المقدار لوحدة الزمن","يُدوَّر هذا الملف داخل مجال مغناطيسي منتظم"],"a":2,"why":"الحث الذاتي (Self-Induction) يعني أن يُحدث الملف قوة دافعة كهربائية محتثة في نفسه بسبب تغيّر تياره الخاص هو (لا تياراً في ملف مجاور، ولا حركة مغناطيس خارجي، ولا دوران في مجال). الخيار (b) يصف الحث المتبادل بين ملفين، و(a) و(d) يصفان حثاً ناتجاً عن حركة نسبية/مصدر خارجي. الوصف الدقيق للحث الذاتي هو الخيار (c): تغيّر التيار المنساب في الملف نفسه."},{"ch":"g6c2","q":"مقدار القوة الدافعة الكهربائية المحتثة على طرفي ساق موصلة تتحرك نسبة إلى مجال مغناطيسي (في حالة لا سكون) لا يعتمد على:","opts":["طول الساق","قطر الساق","وضعية الساق نسبة للفيض المغناطيسي","كثافة الفيض المغناطيسي"],"a":1,"why":"صيغة القوة الدافعة الكهربائية الحركية: ε = Bℓv sinθ، وهي تعتمد على كثافة الفيض B، وطول الساق ℓ، وسرعتها v، وزاوية وضعيتها θ نسبة إلى المجال؛ لكنها لا تعتمد إطلاقاً على قُطر (سُمك) الساق."},{"ch":"g6c2","q":"عندما تقل السرعة الزاوية لدوران ملف نواة المحرك الكهربائي نتيجة لازدياد الحمل الموصول مع ملفه، فإن ذلك يتسبب في هبوط مقدار:","opts":["القوة الدافعة الكهربائية المحتثة المضادة","الفولطية الموضوعة على طرفي ملف النواة","التيار المنساب في دائرة المحرك","فرق الجهد الضائع (IR) بين طرفي ملف النواة"],"a":0,"why":"القوة الدافعة الكهربائية المحتثة المضادة (Back-EMF) في المحرك تتناسب طردياً مع سرعته الزاوية (ε_back = k·ω تقريباً). فعند زيادة الحمل تقل السرعة الزاوية فتقل هذه القوة المضادة مباشرة. أما الفولطية المطبقة من المصدر فتبقى ثابتة، والتيار في الواقع يزداد (لا يقل) لأن I=(V-ε_back)/R وقد قلّت ε_back."},{"ch":"g6c2","q":"يمكن أن يُستحث تيار كهربائي في حلقة موصلة ومقفلة في العمليات التالية جميعها ما عدا واحدة منها. فالعملية التي لا يُستحث فيها التيار هي:","opts":["حلقة موصلة ومقفلة تدور حول محور موازٍ لمستواها وعمودي على فيض مغناطيسي منتظم","وضع حلقة موصلة ومقفلة ومتجه مساحتها موازٍ لفيض مغناطيسي متغير لوحدة الزمن","وضع حلقة موصلة ومقفلة ومتجه مساحتها عمودياً على فيض مغناطيسي متغير لوحدة الزمن","حلقة موصلة ومقفلة، متجه مساحتها موازٍ لفيض مغناطيسي منتظم، كُبست من جانبيها المتقابلين"],"a":2,"why":"الفيض المخترق للحلقة Φ=B·A·cosθ حيث θ الزاوية بين متجه المساحة (العمودي على مستوي الحلقة) والمجال B. إذا كان متجه المساحة عمودياً على B (θ=90°) فإن Φ=BAcos90°=0 دائماً وباستمرار، بصرف النظر عن كيفية تغيّر B مع الزمن (لأن B يبقى واقعاً في مستوي الحلقة نفسه ولا يخترقها إطلاقاً)، فمشتقته الزمنية أيضاً صفر دائماً، ولا تُستحث أي قوة دافعة كهربائية. أما بقية الحالات (أ: تدوير يغيّر الزاوية، b: متجه موازٍ فالفيض أعظمي ويتغير مع B، d: كبس الحلقة يغيّر المساحة) فكلها تؤدي إلى تغيّر الفيض وتُحدث تياراً محتثاً."},{"ch":"g6c2","q":"وحدة قياس كثافة الفيض المغناطيسي هي:","opts":["weber","weber/s","weber/m²","weber.s"],"a":2,"why":"كثافة الفيض المغناطيسي B (التسلا) = ويبر/م² (Wb/m²)، لأن الفيض Φ=B×A ⇒ B=Φ/A، ووحدة Φ هي الويبر ووحدة A هي م²."},{"ch":"g6c2","q":"في الشكل (63)، عندما تدور حلقة موصلة حول محور شاقولي موازٍ لوجهها ومار من مركزها، والمحور عمودي على فيض مغناطيسي أفقي ومنتظم، فإن قطبية القوة الدافعة الكهربائية المحتثة تكون دالة جيبية تتغير مع الزمن وتنعكس خلال كل:","opts":["دورة واحدة","ربع دورة","نصف دورة","دورتين"],"a":2,"why":"القوة الدافعة الكهربائية المحتثة تُعطى بدالة جيبية ε=εmax sin(ωt)، وهذه الدالة تقطع الصفر وتنعكس إشارتها (قطبيتها) عند ωt=0,π,2π,... أي كل نصف دورة (π radian)، وليس كل دورة كاملة (التي يكتمل بعدها دورة جيبية كاملة لكن القطبية تكون قد انعكست مرتين خلالها)."},{"ch":"g6c2","q":"معامل الحث الذاتي لملف لا يعتمد على:","opts":["عدد لفات الملف","الشكل الهندسي للملف","المعدل الزمني للتغير في التيار المنساب في الملف","النفوذية المغناطيسية للوسط في جوف الملف"],"a":2,"why":"معامل الحث الذاتي L خاصية هندسية-مادية بحتة للملف (تعتمد على N² وأبعاده وشكله الهندسي ونفوذية قلبه μ)، ولا يعتمد إطلاقاً على مقدار التيار أو معدل تغيره الزمني (رغم أن القوة الدافعة الكهربائية المحتثة ε=-L(dI/dt) نفسها تعتمد على dI/dt، فإن L ذاته ثابت لا يتغير بتغير التيار)."},{"ch":"g6c2","q":"علّل: يتوهج مصباح النيون المربوط بالتوازي مع ملف بضوء ساطع لبرهة قصيرة من الزمن لحظة فتح المفتاح، على الرغم من فصل البطارية عن الدائرة عندئذٍ، ولا يتوهج عند إغلاق المفتاح.","opts":["لأن البطارية تولّد نبضة جهد عكسية قوية عند فصلها عن الدائرة","لأن مقاومة الملف الداخلية تتغير فجأة عند فتح المفتاح فيرتفع الجهد","لأن الملف يعارض هبوط تياره المفاجئ عند الفتح بقوة دافعة ذاتية عالية جداً","لأن التيار يزداد فجأة عند فتح المفتاح بسبب انعدام المقاومة الكلية للدائرة"],"a":2,"why":"الملف يقاوم أي تغيّر مفاجئ في تياره (قصور ذاتي كهرومغناطيسي). عند فتح المفتاح يهبط التيار من قيمته المستقرة إلى الصفر خلال زمن قصير جداً، فيكون |dI/dt| ضخماً، ومنه تنتج قوة دافعة كهربائية ذاتية عالية جداً (ε=-L dI/dt) كافية لتأيين غاز النيون وإصدار ومضة ضوئية قصيرة، رغم فصل البطارية. أما عند الإغلاق فالتيار يتصاعد بمعدل محدود بثابت الزمن (L/R) فتبقى ε صغيرة نسبياً ولا تصل لجهد التأيين.<br><br><b>الصياغة الكاملة للجواب:</b> لأن الملف يعاكس الانخفاض المفاجئ للتيار عند الفتح بقوة دافعة كهربائية ذاتية كبيرة جداً (ε=-L·dI/dt، وdI/dt كبير جداً لأن التيار يهبط لشبه الصفر خلال زمن قصير جداً)، فينتج فرق جهد عالٍ يكفي لتأيين غاز النيون؛ أما عند الإغلاق فالتيار يتصاعد تدريجياً (يحدّه ثابت الزمن L/R) فتبقى القوة الدافعة الذاتية صغيرة ولا تكفي لإضاءة المصباح"},{"ch":"g6c2","q":"علّل: يغلي الماء داخل الإناء المعدني الموضوع على السطح العلوي لطباخ حثّي فيغلي بسرعة، ولا يغلي الماء الذي يوضع إناؤه الزجاجي على السطح العلوي لنفس الطباخ.","opts":["لأن الزجاج يعكس المجال المغناطيسي المتردد بعيداً عن الماء","لأن تيارات دوامة تُستحث في المعدن فتسخّنه، ولا تُستحث في الزجاج العازل","لأن الزجاج يمتص المجال المغناطيسي بدلاً من توصيله للماء","لأن الإناء المعدني أثقل وزناً فيحتفظ بحرارة أكبر لفترة أطول"],"a":1,"why":"الطباخ الحثّي يولّد مجالاً مغناطيسياً متردداً أسفل سطحه. إذا كانت قاعدة الإناء من مادة موصلة (معدن)، تُستحث فيها تيارات دوامة كبيرة تبدد طاقة حرارية مباشرة داخل المعدن نفسه (I²R) فيسخن ويُغلي الماء فوقه. أما الزجاج فعازل كهربائياً، فلا تُستحث فيه أي تيارات دوامة مهما تردد المجال، فلا يتولد فيه تسخين حثّي إطلاقاً.<br><br><b>الصياغة الكاملة للجواب:</b> لأن المجال المغناطيسي المتردد أسفل السطح يستحث تيارات دوامة (Eddy Currents) في قاع الإناء المعدني الموصل فتولّد حرارة مباشرة فيه (فقد I²R) تنتقل للماء؛ أما الزجاج فمادة عازلة غير موصلة كهربائياً فلا تُستحث فيه تيارات دوامة، فلا يتولد فيه فقد حراري مباشر ولا يسخن الماء"},{"ch":"g6c2","q":"علّل: إذا تغيّر تيار كهربائي منساب في أحد ملفين متجاورين، يتولد تيار محتث في الملف الآخر.","opts":["لأن الملفين متصلان بسلك كهربائي مباشر بينهما","لأن تغيّر التيار يرفع درجة حرارة الملف الأول فينتقل الحث حرارياً للثاني","لأن الملف الثاني يمتلك بطارية داخلية صغيرة تتفعل عند اقتراب مجال متغير","لأن فيض الملف الأول المتغيّر يخترق الثاني فتُحتثّ فيه قوة دافعة"],"a":3,"why":"هذا وصف مباشر لظاهرة الحث المتبادل (Mutual Induction): تغيّر تيار الملف الابتدائي I₁ يُغيّر فيضه المغناطيسي المحيط، وجزء من هذا الفيض المتغير يخترق لفات الملف الثانوي المجاور، فيُستحث فيه بقانون فاراداي قوة دافعة كهربائية ε₂=-M(dI₁/dt) حيث M معامل الحث المتبادل بين الملفين، دون أي اتصال سلكي مباشر بينهما.<br><br><b>الصياغة الكاملة للجواب:</b> لأن تغيّر تيار الملف الأول يُغيّر فيضه المغناطيسي الخاص، وجزء من هذا الفيض يرتبط (يخترق) الملف الثاني المجاور؛ وبما أن هذا الفيض المرتبط بالملف الثاني يتغير مع الزمن، فبقانون فاراداي تُستحث فيه قوة دافعة كهربائية (ε₂=-M·dI₁/dt)، وينساب تيار محتث إن كانت دائرته مقفلة — وهذا جوهر الحث المتبادل"},{"ch":"g6c2","q":"وضّح كيف يمكنك عملياً معرفة فيما إذا كان مجالاً مغناطيسياً أم مجالاً كهربائياً موجوداً في حيّز معين؟","opts":["بشحنة اختبار: إن تأثرت وهي ساكنة فالمجال كهربائي، وإن لم تتأثر إلا متحركةً فهو مغناطيسي","استعمل مقياس حرارة: ارتفاع الحرارة يدل على مجال كهربائي وثبوتها يدل على مجال مغناطيسي","ضع بوصلة فقط: انحرافها يدل على مجال كهربائي دوماً","لا توجد طريقة عملية للتفريق بينهما إطلاقاً"],"a":0,"why":"الفارق الجوهري: القوة الكهربائية F=qE تؤثر في الشحنة سواء كانت ساكنة أم متحركة، بينما القوة المغناطيسية F=qv×B لا تؤثر إطلاقاً في شحنة ساكنة (v=0 ⇒ F=0)، ولا تؤثر إلا في الشحنة المتحركة، وتكون القوة الناتجة عمودية دوماً على اتجاه حركتها. فبوضع شحنة اختبار ومراقبة تأثرها وهي ساكنة ثم وهي متحركة، يمكن التمييز عملياً بين وجود مجال كهربائي و/أو مغناطيسي.<br><br><b>الصياغة الكاملة للجواب:</b> ضع شحنة اختبار صغيرة موجبة: إذا أثّرت فيها قوة وهي ساكنة تماماً فهناك مجال كهربائي (لأن E يؤثر في الشحنات الساكنة والمتحركة معاً)؛ أما إذا لم تتأثر الشحنة إلا عند تحريكها (وكانت القوة الناتجة عمودية دوماً على اتجاه سرعتها، F=qv×B) فهناك مجال مغناطيسي فقط (B لا يؤثر في الشحنة الساكنة)"},{"ch":"g6c2","q":"عند دوران ملف مساحة اللفة الواحدة فيه (A) بسرعة زاوية (ω) داخل مجال مغناطيسي كثافة فيضه (B) منتظمة، فإن الفيض المغناطيسي الذي يخترق اللفة الواحدة يُعطى بشكل دالة جيب تمام [Φ_B=BAcos(ωt)]. ما ناتج تطبيق قانون فاراداي (ε=-N·dΦ_B/dt) على هذه العلاقة؟","opts":["ε = -NBAω·cos(ωt)","ε = NBAω²·sin(ωt)","ε = NBAω·sin(ωt)","ε = -NBA·sin(ωt)"],"a":2,"why":"باشتقاق Φ_B=BAcos(ωt) بالنسبة للزمن: dΦ_B/dt = BA×d/dt[cos(ωt)] = BA×(-ω sin(ωt)) = -BAω sin(ωt). وبتطبيق قانون فاراداي: ε=-N(dΦ_B/dt) = -N×(-BAω sin ωt) = NBAω sin(ωt). أي أن القوة الدافعة الكهربائية المحتثة دالة جيبية (sin) عظماها εmax=NBAω، بينما الفيض نفسه دالة جيب تمام (cos) — أي أن ε وΦ خارج الطور بمقدار 90°.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>ε = -NBAω·cos(ωt)</b> ← بإبقاء الدالة جيب تمام كما هي<br><b>ε = NBAω²·sin(ωt)</b> ← بإضافة ω إضافية سهواً<br><b>ε = -NBA·sin(ωt)</b> ← بإسقاط عامل ω من الناتج"},{"ch":"g6c2","q":"ما المقصود بالمجالات الكهربائية غير المستقرة (Non-static Electric Fields)؟","opts":["مجالات كهربائية تنشأ فقط من شحنات نقطية متحركة بسرعة عالية جداً","مجالات محتثة من تغيّر المجال المغناطيسي، خطوطها حلقات مغلقة لا شحنات لها","مجالات كهربائية توجد فقط داخل المتسعات المشحونة","مجالات كهربائية تتناقص أسّياً مع الزمن دوماً بصرف النظر عن مصدرها"],"a":1,"why":"المجالات الكهربائية غير المستقرة (المحتثة) هي مجالات تنشأ عن تغيّر الفيض المغناطيسي مع الزمن (تعميم فاراداي)، وتختلف جوهرياً عن المجالات الكهروستاتيكية: خطوطها تشكّل حلقات مغلقة على نفسها (لا تصدر من شحنات موجبة ولا تنتهي عند سالبة)، وهي غير محافظة (لا مصونة) — أي يمكن أن تبذل شغلاً صافياً على شحنة تتحرك في مسار مغلق كامل، بخلاف المجال الكهروستاتيكي المحافظ.<br><br><b>الصياغة الكاملة للجواب:</b> هي مجالات كهربائية محتثة تنشأ نتيجة تغيّر مجال مغناطيسي مع الزمن (لا من شحنات ساكنة)، وخطوط مجالها حلقات مغلقة (لا تبدأ ولا تنتهي عند شحنات)، وهي مجالات لا محافظة (غير مصونة) بخلاف المجالات الكهروستاتيكية الناتجة عن شحنات ساكنة"},{"ch":"g6c2","q":"اذكر بعض المجالات (التطبيقات) التي تُستثمر فيها التيارات الدوامة (Eddy Currents)، ووضّح كل منها.","opts":["تحويل الجهد في المحولات الكهربائية فقط (Transformers)","توليد التيار المتناوب في المولدات الكهربائية فقط","قياس التيار المستمر بدقة عالية في الأميتر الرقمي فقط","الكبح المغناطيسي، والتسخين الحثّي، وكاشفات المعادن، وتخميد إبر الموازين"],"a":3,"why":"التيارات الدوامة (التيارات المستحثة داخل جسم موصل صلب نتيجة تغيّر الفيض خلاله) تُستثمر عملياً في: الكبح الكهرومغناطيسي (قطارات، ملاهٍ) حيث تعاكس القوة الناتجة عنها حركة الجسم فتبطئه دون تلامس ميكانيكي؛ والتسخين الحثّي (مواقد الحث، أفران صهر المعادن) حيث تولّد حرارة I²R مباشرة داخل المعدن؛ وكاشفات المعادن التي تحسّ بتشوّه المجال الناتج عن التيارات الدوامة المستحثة في معدن مخفي؛ وتخميد اهتزاز إبر الموازين الحساسة وعدادات القياس القديمة لإيقافها بسرعة عند التوازن.<br><br><b>الصياغة الكاملة للجواب:</b> الكبح الكهرومغناطيسي (مكابح تيارات دوامة في القطارات وألعاب الملاهي)، وأفران/مواقد التسخين الحثّي لصهر أو طبخ المعادن، وكاشفات المعادن، وتخميد اهتزاز إبرة الموازين والأجهزة الحساسة"},{"ch":"g6c2","q":"إذا تحركت الساق الموصلة (ab) في الشكل (64) في مستوى الورقة أفقياً نحو اليسار، داخل مجال مغناطيسي منتظم مسلط عمودياً على الورقة متجهاً نحو الناظر، يتولد مجال كهربائي داخل الساق يتجه نحو الطرف (b). أما إذا تحركت هذه الساق نحو اليمين (وداخل المجال المغناطيسي نفسه) فإن اتجاه المجال الكهربائي داخلها ينعكس ليتجه نحو الطرف (a). ما تفسير ذلك؟","opts":["لأن اتجاه المجال المغناطيسي نفسه ينعكس تلقائياً عند تغيّر اتجاه حركة الساق","لأن F=qv×B، وعكس اتجاه v يعكس اتجاه القوة فتنعكس جهة تجمّع الشحنات","لأن مقاومة الساق الكهربائية تتغير حسب اتجاه الحركة","اتجاه المجال الكهربائي لا يعتمد على اتجاه السرعة إطلاقاً، والملاحظة خاطئة"],"a":1,"why":"القوة المؤثرة في شحنة موجبة داخل الساق المتحركة هي F=qv×B. عكس اتجاه v (من اليسار لليمين) يعكس تماماً اتجاه الجداء الاتجاهي v×B (لأن الجداء الاتجاهي خطي في كل من عامليه)، فتنعكس جهة اندفاع الشحنات الموجبة داخل الساق، وبالتبعية ينعكس اتجاه المجال الكهربائي الاستقطابي (الداخلي) الذي يتشكل في حالة الاتزان ليوازن هذه القوة المغناطيسية (qE=qv×B).<br><br><b>الصياغة الكاملة للجواب:</b> لأن القوة المغناطيسية المؤثرة في حاملات الشحنة داخل الساق تُعطى بـF=qv×B، وعكس اتجاه السرعة v يعكس اتجاه الجداء الاتجاهي v×B تماماً (بمقدار 180°)، فتنعكس تبعاً لذلك جهة تجمّع الشحنات (وبالتالي اتجاه المجال الكهربائي الداخلي الناتج عن الاستقطاب) من الاتجاه نحو b إلى الاتجاه نحو a"},{"ch":"g6c2","q":"في الشكل (65) ملف سلكي محزون بقلب حديدي، مربوط على التوالي مع بطارية ومفتاح، ووُضعت أمام أحد طرفيه حلقة نحاسية مقفلة (غير ملامسة له). ما الذي يحدث لحلقة النحاس لحظة إغلاق المفتاح، وما الذي يحدث لها لحظة فتحه (بعد أن كان مغلقاً لفترة)؟","opts":["تنافر في الحالتين معاً (عند الإغلاق وعند الفتح على السواء)","لا تتأثر الحلقة بأي قوة في أي من الحالتين لأنها غير ملامسة للملف","لحظة الإغلاق: تنافر فتُدفع الحلقة بعيداً؛ ولحظة الفتح: تجاذب فتُجذب نحو الملف","تجاذب في الحالتين معاً (عند الإغلاق وعند الفتح على السواء)"],"a":2,"why":"لحظة إغلاق المفتاح يتصاعد تيار الملف من صفر فيتزايد الفيض المخترق للحلقة المجاورة؛ بقانون لنز يعاكس التيار المحتث في الحلقة هذا التزايد بجعل وجهها المقابل للملف بنفس قطبية الملف (تنافر)، فتُدفع الحلقة بعيداً (كما في تجربة الحلقة القافزة الشهيرة). أما لحظة فتح المفتاح (بعد استقرار التيار) فيهبط تيار الملف فجأة نحو الصفر فيتناقص الفيض؛ فيتولد تيار محتث معاكس الاتجاه يحاول الحفاظ على الفيض المتناقص بجعل وجه الحلقة بقطبية معاكسة لقطبية الملف (تجاذب)، فتُجذب الحلقة نحو الملف للحظة.<br><br><b>الصياغة الكاملة للجواب:</b> لحظة الإغلاق: يتزايد الفيض المخترق للحلقة فيتولد فيها تيار محتث يعاكس هذا التزايد (بقانون لنز) فتصبح قوة التفاعل بين الحلقة والملف تنافرية فتُدفع الحلقة بعيداً؛ ولحظة الفتح: يتناقص الفيض فيتولد تيار محتث يحاول الحفاظ عليه فتصبح القوة تجاذبية فتُجذب الحلقة نحو الملف"},{"ch":"g6c2","q":"افترض أن الملف والمغناطيس الموضح في الشكل (66)، كل منهما يتحرك بالسرعة نفسها نسبةً إلى الأرض (يحملهما نفس الشخص بيده أثناء المشي)، هل يشير الميلي أميتر الرقمي (أو الكلفانوميتر) المربوط مع الملف إلى انسياب تيار في الدائرة؟ وضّح ذلك.","opts":["نعم، لأن كليهما يتحركان بالنسبة للأرض فيتولد تيار كبير","لا، لأن السرعة النسبية بينهما صفر فلا يتغيّر الفيض المخترق للملف (ΔΦ/Δt=0)","نعم، لكن بمقدار ضئيل جداً يتناسب مع سرعة حركة اليد نسبة للأرض","يعتمد الجواب على مقدار سرعة حركة اليد: كلما زادت زاد التيار المقروء"],"a":1,"why":"الحث الكهرومغناطيسي (وفق قانون فاراداي) يعتمد على معدل تغيّر الفيض المخترق للملف مع الزمن، وهذا التغيّر ناتج فقط عن الحركة النسبية بين المصدر (المغناطيس) والملف. بما أن الملف والمغناطيس يتحركان معاً بنفس السرعة والاتجاه بالضبط، فإن سرعتهما النسبية صفر، ووضع المغناطيس بالنسبة للملف يبقى ثابتاً تماماً طوال الحركة، فلا يتغير الفيض إطلاقاً (بصرف النظر عن مدى سرعة حركتهما معاً نسبة للأرض)، ولا يُستحث أي تيار.<br><br><b>الصياغة الكاملة للجواب:</b> لا، لأن السرعة النسبية بين الملف والمغناطيس تساوي صفراً (يتحركان معاً بنفس السرعة والاتجاه)، فلا يتغير موضع المغناطيس بالنسبة للملف مطلقاً، وبالتالي لا يتغير الفيض المغناطيسي المخترق للملف مع الزمن (dΦ/dt=0)، فلا تُستحث أي قوة دافعة كهربائية ولا ينساب أي تيار، ويقرأ الجهاز صفراً"},{"ch":"g6c2","q":"ما الكمية الفيزيائية التي تُقاس بوحدة (Weber)؟","opts":["كثافة الفيض المغناطيسي B","القوة الدافعة الكهربائية المحتثة ε","معامل الحث L أو M","الفيض المغناطيسي Φ"],"a":3,"why":"الويبر (Weber, Wb) هو وحدة قياس الفيض المغناطيسي Φ في النظام الدولي، حيث Φ=B×A، فوحدته = تسلا×م² = ويبر."},{"ch":"g6c2","q":"ما الكمية الفيزيائية التي تُقاس بوحدة (Weber/s)؟","opts":["القوة الدافعة الكهربائية المحتثة ε","كثافة الفيض المغناطيسي B","معامل الحث الذاتي L","الشحنة الكهربائية Q"],"a":0,"why":"بقانون فاراداي ε=-N(dΦ/dt)، فوحدة القوة الدافعة الكهربائية المحتثة هي وحدة الفيض مقسومة على وحدة الزمن، أي ويبر/ثانية (Wb/s)، وهذه الوحدة تكافئ الفولط (V) تماماً.<br><br><b>الصياغة الكاملة للجواب:</b> القوة الدافعة الكهربائية المحتثة ε (لأن ε=dΦ/dt، ووحدتها ويبر/ثانية = فولط)"},{"ch":"g6c2","q":"ما الكمية الفيزيائية المشتركة التي تُقاس بكل من وحدتي (Tesla) و(Weber/m²)؟","opts":["الفيض المغناطيسي Φ","القوة الدافعة الكهربائية المحتثة ε","كثافة الفيض المغناطيسي B","معامل الحث المتبادل M"],"a":2,"why":"كثافة الفيض المغناطيسي B تُقاس بوحدة التسلا (Tesla)، وهي مكافئة تماماً لوحدة ويبر/م² (Wb/m²)، لأن B=Φ/A."},{"ch":"g6c2","q":"ما الكمية الفيزيائية التي تُقاس بوحدة (Henry)؟","opts":["الفيض المغناطيسي Φ","معامل الحث (الذاتي L أو المتبادل M)","كثافة الفيض المغناطيسي B","الطاقة المغناطيسية المختزنة U"],"a":1,"why":"الهنري (Henry, H) هو وحدة قياس معامل الحث في النظام الدولي، سواء كان معامل حث ذاتي L (في ε=-L·dI/dt) أو معامل حث متبادل M (في ε₂=-M·dI₁/dt)."},{"ch":"g6c2","q":"كيف تعمل التيارات الدوامة على كبح اهتزاز الصفيحة المعدنية المهتزة عمودياً على مجال مغناطيسي منتظم؟","opts":["باستهلاك الصفيحة نفسها فيزيائياً بمرور الوقت","برفع درجة حرارة المجال المغناطيسي المحيط فيضعفه تدريجياً","بتوليد مجال مغناطيسي إضافي يجذب الصفيحة نحو مصدر المجال دائماً","تيارات دوامة تُحدث قوى تعاكس حركة الصفيحة فتُبدّد طاقة اهتزازها حرارياً"],"a":3,"why":"أثناء اهتزاز الصفيحة المعدنية داخل المجال، يتغيّر الفيض المخترق لعناصرها الداخلية باستمرار فتُستحث فيها تيارات دوامة دائرية. بقانون لنز، تتفاعل هذه التيارات مع المجال الخارجي B لتولّد قوى (F=IL×B) تُعارض دوماً سبب نشوئها، أي حركة الصفيحة ذاتها، فتُبدد الطاقة الحركية للاهتزاز على هيئة حرارة (فقد I²R) حتى يخمد الاهتزاز تماماً — وهذا أساس آلية \"الكبح المغناطيسي\".<br><br><b>الصياغة الكاملة للجواب:</b> حركة الصفيحة (اهتزازها) ضمن المجال تُغيّر الفيض المخترق لأجزائها محلياً فتُستحث فيها تيارات دوامة؛ وبقانون لنز تتفاعل هذه التيارات مع المجال لتولّد قوى تُعاكس دوماً حركة الصفيحة نفسها (سبب الاهتزاز)، فتُبدد طاقة الاهتزاز حرارياً (I²R) داخل الصفيحة تدريجياً، فيخمد الاهتزاز ويتوقف"},{"ch":"g6c2","q":"شريحة من النحاس وُضعت بين قطبي مغناطيس كهربائي منتظم كثافة فيضه كبيرة وبمستوٍ شاقولي، وكان مستوى الصفيحة عمودياً على الفيض المغناطيسي. وعندما سُحبت الصفيحة أفقياً بسرعة معينة لإخراجها من المجال، وُجد أن عملية السحب تتطلب تسليط قوة معينة، ويزداد مقدار القوة الساحبة بازدياد مقدار تلك السرعة. ما تفسير الحالتين؟","opts":["لأن التيارات الدوامة تولّد قوة كابحة تعاكس السحب، وتزداد بازدياد السرعة","لأن كتلة الصفيحة تزداد فعلياً أثناء الحركة السريعة","لأن الاحتكاك مع الهواء هو السبب الوحيد لازدياد القوة المطلوبة","القوة المطلوبة للسحب لا علاقة لها بالمجال المغناطيسي إطلاقاً بل بوزن الصفيحة فقط"],"a":0,"why":"أثناء خروج الصفيحة من بين القطبين تتغيّر مساحة تقاطعها مع المجال فيتغيّر الفيض المخترق لها مع الزمن، فتُستحث فيها تيارات دوامة. بقانون لنز، تتفاعل هذه التيارات مع B لتولّد قوة معاكسة لحركة السحب (قوة كبح مغناطيسي)، فيجب تسليط قوة سحب مساوية لها للتغلب عليها والحفاظ على السرعة. وبما أن القوة الدافعة الكهربائية المحتثة تتناسب طردياً مع سرعة السحب (ε∝v)، فإن التيار والقوة الكابحة يزدادان معها، فتزداد القوة الساحبة اللازمة تبعاً لذلك.<br><br><b>الصياغة الكاملة للجواب:</b> أثناء سحب الشريحة يتناقص الفيض المخترق لأجزائها الخارجة من بين القطبين فتُستحث فيها تيارات دوامة تعاكس (بقانون لنز) حركة السحب نفسها، فتنشأ قوة معاكسة (كابحة) يجب التغلب عليها بالقوة المُسلَّطة؛ وبما أن القوة الدافعة الكهربائية المحتثة (وبالتالي التيار والقوة المعاكسة) تتناسب طردياً مع سرعة السحب، فإن ازدياد السرعة يستلزم قوة ساحبة أكبر للتغلب على القوة الكابحة المتزايدة"},{"ch":"g6c2","q":"في كل من الشكلين (67) و(68) سلك نحاسي مستقيم يحمل تياراً متغيراً، وحلقة من النحاس مقفلة بالقرب منه بوضعية مختلفة في كل شكل. في أي وضعية ينساب تيار محتث في الحلقة عندما يتزايد التيار الكهربائي المنساب في السلك؟","opts":["في الشكل (67) فقط، لأن السلك يمر عبر محور الحلقة تماماً","في الشكل (68) فقط، لأن مجال السلك يخترق مساحة الحلقة هناك فعلاً","في كلا الشكلين بمقدار متساوٍ تماماً","لا ينساب أي تيار محتث في أي من الشكلين لأن السلك مستقيم وليس ملفاً"],"a":1,"why":"في الشكل (67) تحيط الحلقة بالسلك بحيث يكون محورها منطبقاً على السلك (السلك يمر من مركزها عمودياً على مستواها). خطوط مجال السلك المستقيم دوائر متمركزة حوله وتقع كلياً في مستوٍ عمودي على السلك — وهو نفس مستوى الحلقة هنا — أي أن المجال عند موضع الحلقة مماسٍ لمستواها دوماً (لا مركبة له عمودية على مستوى الحلقة)، فالفيض المخترق لمساحتها صفر دائماً بصرف النظر عن مقدار أو تغيّر التيار، فلا يُستحث فيها تيار أبداً. أما في الشكل (68) فالحلقة موضوعة بجانب السلك (مستواها يحوي السلك أو موازٍ لجزء منه بشكل مختلف)، فتخترق خطوطُ مجال السلك مساحةَ الحلقة فعلياً، وعند تغيّر التيار يتغيّر هذا الفيض المخترق، فيُستحث تيار في الحلقة وفق قانون فاراداي.<br><br><b>الصياغة الكاملة للجواب:</b> في الشكل (68) فقط؛ ففي هذه الوضعية يخترق مجال السلك مساحة الحلقة فعلاً (له مركبة عمودية على مستواها)، بينما في الشكل (67) تكون الحلقة محيطة بالسلك بحيث يكون مجال السلك مماساً لمستوى الحلقة في كل نقطة منه (خطوط المجال الدائرية حول السلك تقع بأكملها ضمن مستوي الحلقة نفسه)، فلا يخترق مساحتها إطلاقاً (الفيض صفر دائماً) مهما تغيّر التيار، فلا يُستحث فيها أي تيار"},{"ch":"g6c2","q":"يتوافر لك سلك ذو طول ثابت، وترغب في الحصول على مولد بسيط يجهزك بأعظم مقدار للقوة الدافعة الكهربائية. أيتطلب منك أن تجعل السلك بشكل ملف ذي لفة واحدة دائرية الشكل، أم ملف ذي لفتين دائريتي الشكل، أم ملف ذي ثلاث لفات دائرية الشكل، عند تدوير الملف الذي تحصل عليه بسرعة زاوية معينة داخل مجال مغناطيسي منتظم؟ وضّح إجابتك.","opts":["ملف ذو ثلاث لفات، لأن εmax يتناسب طردياً مع عدد اللفات N فقط بصرف النظر عن أي عامل آخر","ملف ذو لفتين، لأنه يمثّل حالة وسطى متوازنة بين المساحة وعدد اللفات","ملف ذو لفة واحدة، لأن εmax تتناسب عكسياً مع N عند ثبوت طول السلك","لا فرق إطلاقاً بين الحالات الثلاث لأن الطول الكلي للسلك واحد في جميعها"],"a":2,"why":"بما أن طول السلك L محدد وثابت ويُوزَّع على عدد اللفات N، فمحيط كل لفة (دائرية) = L/N، ونصف قطرها r=L/(2πN)، فمساحتها A=πr²=L²/(4πN²) — تتناقص بشكل تربيعي مع N. بالتعويض في εmax=NBAω نحصل على εmax=BL²ω/(4πN)، وهذه دالة تتناقص عكسياً مع N. إذن زيادة عدد اللفات (مع ثبوت طول السلك الكلي) تُقلل القوة الدافعة الكهربائية العظمى بدلاً من زيادتها؛ وأعظم قيمة تتحقق مع لفة واحدة فقط (N=1) التي تحصل فيها اللفة على أكبر مساحة ممكنة من طول السلك المتاح.<br><br><b>الصياغة الكاملة للجواب:</b> ملف ذو لفة واحدة؛ فبما أن طول السلك L ثابت وموزَّع بالتساوي على عدد اللفات N (محيط اللفة الواحدة=L/N)، فإن مساحة اللفة الواحدة (للشكل الدائري) A=π(L/2πN)²=L²/(4πN²) تتناقص مع مربع N؛ وحيث إن εmax=NBAω=N×B×[L²/(4πN²)]×ω = BL²ω/(4πN)، فإن εmax يتناسب عكسياً مع N، أي أن أكبر قيمة له تتحقق عند N=1 (لفة واحدة فقط)"},{"ch":"g6c2","q":"في معظم الملفات يُصنع القلب بشكل سيقان متوازية من الحديد المطاوع، معزولة عن بعضها البعض عزلاً كهربائياً، ومكبوسة كبساً شديداً، بدلاً من قلب من الحديد مصنوع كقطعة واحدة (لاحظ الشكل 69). ما الفائدة العملية من ذلك؟","opts":["تقليل التيارات الدوامة في القلب وما تسببه من فقد حراري، بحصرها في سيقان رفيعة معزولة","تقليل وزن الملف الكلي فقط لأغراض النقل","زيادة مقاومة القلب الكهربائية إلى ما لا نهاية فيمنع أي مجال مغناطيسي فيه بتاتاً","جعل الملف أرخص تكلفة في التصنيع فقط دون أي فائدة كهربائية"],"a":0,"why":"قلب الملف نفسه مادة موصلة (حديد) موجودة داخل مجال مغناطيسي متغير (بسبب تيار الملف المتردد)، فتُستحث فيه هو أيضاً تيارات دوامة داخلية. لو كان القلب قطعة معدنية واحدة مصمتة لانسابت هذه التيارات الدوامة بحرية وبمقادير كبيرة مسبّبة فقداً حرارياً كبيراً (I²R) يقلل كفاءة الجهاز (ملف/محول/محرك) ويُسخّنه دون فائدة. بتقطيع القلب (لتصفيح Laminating) إلى سيقان رفيعة معزولة كهربائياً عن بعضها، تنحصر مسارات التيارات الدوامة الممكنة ضمن كل سيقة رفيعة على حدة فقط، فيقل مقدارها بشدة (يتناسب تقريباً مع مربع سُمك الشريحة الموصلة)، فيقل الفقد الحراري وتزداد كفاءة الجهاز.<br><br><b>الصياغة الكاملة للجواب:</b> تقليل التيارات الدوامة (Eddy Currents) التي كانت ستُستحث بمقادير كبيرة داخل قلب حديدي مصمت واحد (كونه موصلاً موضوعاً في مجال متغير)، وتُسبب فقداً حرارياً كبيراً (I²R) يقلل كفاءة الملف ويُسخّنه؛ فتقطيع القلب إلى سيقان رفيعة معزولة عن بعضها يحصر التيارات الدوامة المحتملة ضمن مقاطع صغيرة جداً فقط، فيقل مقدارها (وبالتالي فقدها الحراري) بشدة"},{"ch":"g6c2","q":"ملف سلكي دائري الشكل، عدد لفاته (40) لفة ونصف قطره (15 cm)، وُضع بين قطبي مغناطيس كهربائي (الشكل 70). إذا تغيّرت كثافة الفيض المغناطيسي المارة خلال الملف من (0.0T) إلى (0.5T) خلال فترة زمنية قدرها (4s)، فما مقدار القوة الدافعة الكهربائية المحتثة في الملف عندما يكون متجه مساحة اللفة الواحدة موازياً لمتجه كثافة الفيض المغناطيسي؟","opts":["≈0.177 V","≈1.41 V","≈0.353 V","≈0.0088 V"],"a":2,"why":"A=πr²=π(0.15)²≈0.0707 m². معدل تغير الفيض = ΔB/Δt=(0.5-0)/4=0.125 T/s. عند التوازي (θ=0° بين B والمتجه العمودي على مستوي اللفة): ε=N·A·(ΔB/Δt)·cos0° = 40×0.0707×0.125×1 ≈ 0.353 V.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>≈0.177 V</b> ← استُعمل cos60° سهواً بدل الحالة الموازية<br><b>≈1.41 V</b> ← استُعمل القطر 30cm كنصف قطر سهواً<br><b>≈0.0088 V</b> ← نُسي ضرب العدد N=40"},{"ch":"g6c2","q":"(تتمة المسألة السابقة) ما مقدار القوة الدافعة الكهربائية المحتثة في الملف نفسه، عندما يصنع متجه كثافة الفيض المغناطيسي زاوية قياسها (30°) مع مستوي الملف؟","opts":["≈0.353 V (لم تُطبَّق زاوية الميل إطلاقاً)","≈0.177 V","≈0.306 V (استُعمل cos30° بدل cos60° سهواً)","صفر V"],"a":1,"why":"الزاوية المعطاة (30°) بين B ومستوي الملف، فالزاوية بينه وبين المتجه العمودي على مستوي اللفة (المطلوبة في قانون فاراداي) = 90°-30°=60°. ε = N·A·(ΔB/Δt)·cos60° = 0.353×0.5 ≈ 0.177 V (نصف قيمة الحالة الموازية تماماً، لأن cos60°=0.5)."},{"ch":"g6c2","q":"ملف لمولد دراجة هوائية قطره (4 cm) وعدد لفاته (50) لفة، يدور داخل مجال مغناطيسي منتظم كثافة فيضه (1/π) T. كان أعظم مقدار للفولطية المحتثة على طرفي الملف (16V). ما مقدار السرعة الزاوية التي تدور بها نواة المولد؟","opts":["400 rad/s","200 rad/s (استُعمل القطر بدل نصف القطر سهواً)","800 rad/s","1600 rad/s"],"a":2,"why":"نصف القطر r=0.02m، A=πr²=π(0.0004)=0.0004π m². N·B·A = 50×(1/π)×0.0004π = 50×0.0004 = 0.02 (يُلاحظ إلغاء π تماماً، وهو دليل على صحة اختيار B=1/π). من εmax=NBAω: ω=16/0.02=800 rad/s."},{"ch":"g6c2","q":"(تتمة مسألة مولد الدراجة) كانت القدرة العظمى المجهزة للحمل المربوط مع المولد (12W)، وأعظم فولطية على طرفي الملف (16V). ما المقدار الأعظم للتيار المنساب في الحمل؟","opts":["1.5 A (قُسمت الفولطية على 2R تخميناً)","1.33 A (قُلبت النسبة: V/P بدل P/V)","6 A","0.75 A"],"a":3,"why":"بافتراض أن الفولطية العظمى على طرفي الملف تساوي الفولطية على طرفي الحمل (نفس الدائرة)، فإن القدرة اللحظية العظمى المجهزة للحمل P=V×I، ومنه Imax=P/V=12/16=0.75 A."},{"ch":"g6c2","q":"ملف سلكي مستطيل الشكل، عدد لفاته (50) لفة وأبعاده (10cm × 4cm)، يدور بسرعة زاوية منتظمة مقدارها (15π rad/s) داخل مجال مغناطيسي منتظم كثافة فيضه (0.8 Wb/m²). احسب المقدار الأعظم للقوة الدافعة الكهربائية المحتثة في الملف.","opts":["≈15.08 V","2.4 V","≈7.54 V","≈0.75 V"],"a":2,"why":"A=0.10×0.04=0.004 m². εmax=N·B·A·ω = 50×0.8×0.004×15π = 0.16×15π = 2.4π ≈ 7.54 V.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>≈15.08 V</b> ← خطأ مضاعفة<br><b>2.4 V</b> ← نُسي عامل π في ω، إذ عومل ω=15 بدل 15π<br><b>≈0.75 V</b> ← خطأ في تحويل وحدات المساحة"},{"ch":"g6c2","q":"(تتمة المسألة السابقة) ما القوة الدافعة الكهربائية الآنية المحتثة في الملف بعد مرور s(1/90) من الوضع الذي كان مقدارها فيه يساوي صفراً؟","opts":["≈7.54 V","≈6.53 V","≈1.25 V","≈3.77 V"],"a":3,"why":"بما أن ε بدأت من الصفر فإن ε(t)=εmax·sin(ωt). ωt = 15π×(1/90) = π/6 = 30°. sin30°=0.5. ε = 2.4π×0.5 = 1.2π ≈ 3.77 V.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>≈7.54 V</b> ← كامل القيمة العظمى، بافتراض خاطئ أنها بلغت القيمة القصوى فوراً<br><b>≈6.53 V</b> ← استُعمل cos بدل sin سهواً<br><b>≈1.25 V</b> ← نُسي عامل π الموجود في ω"},{"ch":"g6c2","q":"حلقة موصلة دائرية مساحتها (626 cm²) ومقاومتها (9Ω)، موضوعة في مستوي الورقة، سُلط عليها مجال مغناطيسي منتظم كثافة فيضه (0.15T) باتجاه عمودي على مستوي الحلقة (الشكل 71). سُحبت الحلقة من جانبيها بقوتي شدّ متساويتين فبلغت مساحتها (26 cm²) خلال فترة زمنية (0.2s). احسب مقدار التيار المحتث في الحلقة.","opts":["10 A","5.22 mA","5 mA","45 mA"],"a":2,"why":"ΔA=(626-26)cm²=600cm²=0.06 m². ΔΦ=B·ΔA=0.15×0.06=0.009 Wb. ε=ΔΦ/Δt=0.009/0.2=0.045 V. I=ε/R=0.045/9=0.005 A = 5 mA.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>10 A</b> ← خطأ في تحويل الوحدات من cm² إلى m²<br><b>5.22 mA</b> ← استُعملت المساحة الأصلية كاملة 626cm² بدل الفرق 600cm²<br><b>45 mA</b> ← نُسيت القسمة على المقاومة R"},{"ch":"g6c2","q":"ساق موصلة طولها (0.1m) تتحرك على سكتين متوازيتين (الشكل 72) بسرعة مقدارها (2.5 m/s)، والمقاومة الكلية للدائرة (الساق والسكة) (0.03 Ω)، وكثافة الفيض المغناطيسي العمودي على مستوى الدائرة (0.6T). احسب مقدار القوة الدافعة الكهربائية المحتثة على طرفي الساق.","opts":["0.375 V","0.025 V","1.5 V","0.15 V"],"a":3,"why":"القوة الدافعة الكهربائية الحركية: ε=Bℓv = 0.6×0.1×2.5 = 0.15 V.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>0.375 V</b> ← استُعمل v² بدل v سهواً<br><b>0.025 V</b> ← خُلطت القيم سهواً<br><b>1.5 V</b> ← نُسي ضرب طول الساق ℓ"},{"ch":"g6c2","q":"(تتمة المسألة السابقة) احسب مقدار التيار المحتث في الحلقة (الدائرة المكوّنة من الساق والسكتين).","opts":["0.0045 A","0.5 A","5 A","0.15 A"],"a":2,"why":"I = ε/R = 0.15/0.03 = 5 A.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>0.0045 A</b> ← ضُرب بدل القسمة سهواً<br><b>0.5 A</b> ← استُعملت مقاومة خاطئة 0.3Ω بدل 0.03Ω<br><b>0.15 A</b> ← نُسيت القسمة على المقاومة الكلية"},{"ch":"g6c2","q":"(تتمة المسألة السابقة) احسب مقدار القوة الساحبة (المؤثرة لتحريك الساق بسرعة ثابتة، وتساوي بمقدارها القوة المغناطيسية المعاكسة).","opts":["0.75 N","0.3 N","3 N","0.03 N"],"a":1,"why":"F = B·I·ℓ = 0.6×5×0.1 = 0.3 N (وهذه القوة المسحوبة تساوي بالمقدار القوة المغناطيسية المعاكسة للحركة عند السرعة الثابتة).<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>0.75 N</b> ← خُلط الحساب مع صيغة القدرة εI سهواً<br><b>3 N</b> ← نُسي ضرب طول الساق ℓ<br><b>0.03 N</b> ← استُعمل تيار خاطئ 0.5A"},{"ch":"g6c2","q":"(تتمة المسألة السابقة) احسب مقدار القدرة المتبددة في المقاومة الكلية للدائرة.","opts":["0.15 W","1.5 W","0.0045 W","0.75 W"],"a":3,"why":"P = I²R = (5)²×0.03 = 25×0.03 = 0.75 W. (يمكن التحقق أيضاً بـP=F×v = 0.3×2.5 = 0.75 W، وتطابق النتيجتين دليل على صحة الحل).<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>0.15 W</b> ← نُسي تربيع التيار في I²R<br><b>1.5 W</b> ← خُلط الحساب مع F×I سهواً<br><b>0.0045 W</b> ← استُعملت الصيغة الخاطئة ε×R"},{"ch":"g6c2","q":"كانت الطاقة المغناطيسية المختزنة في ملف تساوي (360 J) عندما كان مقدار التيار المنساب فيه (20A). احسب مقدار معامل الحث الذاتي للملف.","opts":["0.56 H","1.8 H","36 H","0.9 H"],"a":1,"why":"من U=½LI²: L = 2U/I² = (2×360)/(20)² = 720/400 = 1.8 H.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>0.56 H</b> ← قُلبت العلاقة خطأً<br><b>36 H</b> ← نُسي تربيع التيار<br><b>0.9 H</b> ← نُسي المعامل 2 في U=½LI²"},{"ch":"g6c2","q":"(تتمة المسألة السابقة) احسب معدل القوة الدافعة الكهربائية المحتثة في الملف إذا انعكس اتجاه التيار (من 20A+ إلى 20A- أي بتغيّر مقداره 40A) خلال فترة زمنية (0.1s).","opts":["0.0045 V","72 V","360 V","720 V"],"a":3,"why":"انعكاس التيار من +20A إلى -20A يعني أن مقدار التغيّر الكلي ΔI=20-(-20)=40A. ε = L×(ΔI/Δt) = 1.8×(40/0.1) = 1.8×400 = 720 V.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>0.0045 V</b> ← قُلبت العلاقة خطأً<br><b>72 V</b> ← استُعمل زمن خاطئ 1s بدل 0.1s<br><b>360 V</b> ← اعتُبر ΔI=20A فقط متناسياً أن الانعكاس يعني تغيّراً مقداره 40A"},{"ch":"g6c2","q":"ملفان متجاوران بينهما ترابط مغناطيسي تام، معامل الحث الذاتي للملف الابتدائي (0.4H) ومقاومته (16Ω)، ومعامل الحث الذاتي للملف الثانوي (0.9H). الفولطية الموضوعة في دائرة الملف الابتدائي (200V). احسب مقدار التيار الآني في دائرة الملف الابتدائي لحظة ازدياد التيار فيها إلى (80%) من مقداره الثابت النهائي.","opts":["160 A","10 A","12.5 A","12.8 A"],"a":1,"why":"في الحالة المستقرة النهائية (بعد زمن طويل) يسلك الملف سلوك سلك عادي (لا يُسقط جهداً)، فالتيار الثابت النهائي Imax=V/R=200/16=12.5A. عند لحظة بلوغ التيار (80%) من هذه القيمة: I=0.8×12.5=10 A.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>160 A</b> ← طُبقت نسبة 80% على الجهد V بدل التيار<br><b>12.5 A</b> ← هذه قيمة التيار الثابت النهائي كاملاً، دون تطبيق نسبة 80%<br><b>12.8 A</b> ← خُلطت نسبة 80% مع قيمة R سهواً"},{"ch":"g6c2","q":"(تتمة المسألة السابقة) احسب المعدل الزمني لتغيّر التيار (dI/dt) في دائرة الملف الابتدائي في تلك اللحظة نفسها (عندما بلغ التيار 80% من قيمته الثابتة).","opts":["2.5 A/s","500 A/s","0 A/s","100 A/s"],"a":3,"why":"بتطبيق قانون كيرخوف للجهد على الدائرة عند تلك اللحظة: V = I·R + L·(dI/dt). بالتعويض بالتيار الآني I=10A: 200 = (10×16) + 0.4×(dI/dt) ⇒ 200 = 160 + 0.4(dI/dt) ⇒ dI/dt = 40/0.4 = 100 A/s.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>2.5 A/s</b> ← قُسم الفرق على R بدل L خطأً<br><b>500 A/s</b> ← نُسي طرح الهبوط IR على المقاومة قبل القسمة على L<br><b>0 A/s</b> ← استُعملت قيمة التيار الثابت النهائي 12.5A بدل قيمته الآنية 10A في تلك اللحظة"},{"ch":"g6c2","q":"(تتمة المسألة السابقة) احسب مقدار القوة الدافعة الكهربائية المحتثة على طرفي الملف الثانوي في تلك اللحظة نفسها (الترابط المغناطيسي بين الملفين تام).","opts":["36 V","90 V","300 V","60 V"],"a":3,"why":"للترابط المغناطيسي التام: M=√(L1×L2)=√(0.4×0.9)=√0.36=0.6 H. القوة الدافعة الكهربائية المحتثة في الملف الثانوي: ε₂ = M×(dI1/dt) = 0.6×100 = 60 V.<br><br><b>⚠️ الأخطاء الشائعة في هذه المسألة:</b><br><b>36 V</b> ← نُسي الجذر التربيعي في M=√(L1L2) واستُعمل الضرب المباشر L1×L2<br><b>90 V</b> ← استُعمل L2 مباشرة بدل M<br><b>300 V</b> ← استُعمل معدل التغير الخاطئ 500 A/s"},{"ch":"g6c3","q":"ما العلاقة الصحيحة اللي تمثّل تياراً متناوباً أعظمه I_m وتردده الزاوي ω؟","opts":["I = I_m sin(ωt)","I = I_m cos(ω/t)","I = I_m / sin(ωt)","I = I_m × ωt"],"a":0,"why":"التيار المتناوب دالة جيبية بالزمن: I = I_m sin(ωt)، حيث ω = 2πf."},{"ch":"g6c3","q":"كم مرة ينعكس اتجاه التيار المتناوب بالعراق (f=50Hz) خلال ثانية واحدة؟","opts":["50 مرة","100 مرة","25 مرة","314 مرة"],"a":1,"why":"ينعكس اتجاه التيار مرتين كل دورة (عند القمة الموجبة والسالبة)، فيكون العدد 2×50=100 مرة بالثانية."},{"ch":"g6c3","q":"ماذا يمثّل مسقط متجه الطور الدوّار على المحور الشاقولي بأي لحظة؟","opts":["التردد f","زاوية الطور فقط","القيمة الآنية للفولطية أو التيار","المقاومة R"],"a":2,"why":"مسقط متجه الطور (طوله V_m أو I_m) على المحور الشاقولي يعطي بالضبط القيمة الآنية بتلك اللحظة."},{"ch":"g6c3","q":"تيار متناوب أعظمه I_m=8A. ما مقداره المؤثر؟","opts":["4 A","8 A","11.3 A","5.66 A"],"a":3,"why":"I_eff = I_m/√2 = 8/1.414 ≈ 5.66 A."},{"ch":"g6c3","q":"فولطية مؤثرة قراءتها على الفولتميتر 220V. ما القيمة العظمى الحقيقية لهذه الفولطية؟","opts":["311 V","155.6 V","220 V","440 V"],"a":0,"why":"V_m = √2 × V_eff = 1.414 × 220 ≈ 311 V."},{"ch":"g6c3","q":"مصدر فولطية متناوبة معطى بالعلاقة V = 311 sin(314t). ما مقدارها المؤثر؟","opts":["311 V","220 V","155.5 V","440 V"],"a":1,"why":"V_eff = V_m/√2 = 311/1.414 ≈ 220 V — نفس فولطية البيت المعروفة."},{"ch":"g6c3","q":"بدائرة تحتوي مقاومة صرفة R فقط، ما فرق الطور Φ بين الفولطية والتيار؟","opts":["180°","90°","0°","45°"],"a":2,"why":"بمقاومة صرفة، الفولطية والتيار يبلغان الذروة معاً ويصفران معاً — أي بطور واحد، Φ=0."},{"ch":"g6c3","q":"لماذا لا تنخفض القدرة اللحظية بمقاومة صرفة تحت الصفر أبداً؟","opts":["لأن V وI موجبتان دائماً بحكم تعريفهما","القدرة فعلاً تنخفض تحت الصفر أحياناً بمقاومة صرفة","لأن المقاومة تمنع القدرة السالبة بقانون خاص بها","لأن P=V×I، وV وI متطابقتان بالإشارة كل لحظة (بطور واحد)، فحاصل ضربهما موجب دائماً"],"a":3,"why":"بما أن V وI بطور واحد، فهما يتشاركان نفس الإشارة بكل لحظة (موجبتين معاً أو سالبتين معاً)، وحاصل ضرب عددين بنفس الإشارة نتيجته موجبة دائماً."},{"ch":"g6c3","q":"دائرة مقاومة صرفة R=50Ω مربوطة بمصدر V_m=100V. ما مقدار التيار الأعظم I_m؟","opts":["2 A","0.5 A","5 A","50 A"],"a":0,"why":"I_m = V_m/R = 100/50 = 2 A."},{"ch":"g6c3","q":"بنفس الدائرة أعلاه (R=50Ω, V_m=100V, I_m=2A)، ما القدرة المتوسطة P_av؟","opts":["200 W","100 W","50 W","141 W"],"a":1,"why":"P_av = I_m×V_m/2 = 2×100/2 = 100 W."},{"ch":"g6c3","q":"كم مرة تبلغ القدرة اللحظية ذروتها خلال دورة واحدة كاملة للفولطية؟","opts":["مرة واحدة","أربع مرات","مرتان","لا تبلغ ذروة أبداً"],"a":2,"why":"القدرة تتناسب مع sin²(ωt) اللي ترددها ضعف تردد V وI، فتبلغ ذروتها مرتين كل دورة — ولهذا يومض المصباح المتصل بالمتناوب 100 مرة بالثانية عند f=50Hz."},{"ch":"g6c3","q":"يقول زميلك: بما أن متوسط التيار المتناوب الجيبي صفر، فهو لا يعطي أي قدرة. أين الخطأ؟","opts":["كلامه صحيح تماماً، لا توجد قدرة","القدرة تساوي التيار مباشرة بلا أي تربيع","التيار المتناوب لا يسخّن أي شيء فعلاً","خلط بين متوسط التيار ومتوسط القدرة؛ القدرة تتناسب مع I² فهي موجبة دائماً ومتوسطها ½I_m²R لا صفر"],"a":3,"why":"متوسط التيار فعلاً صفر، لكن القدرة P=I²R تعتمد على مربع التيار، ومربع أي عدد موجب دائماً — فمتوسط القدرة ½I_m²R وليس صفراً."},{"ch":"g6c3","q":"بدائرة تحتوي محث صرف L فقط، أيّهما يتقدّم على الآخر؟","opts":["الفولطية تتقدّم التيار بزاوية 90°","التيار يتقدّم الفولطية بزاوية 90°","كلاهما بطور واحد","الفرق بينهما 45° فقط"],"a":0,"why":"بمحث صرف: V_L = V_m sin(ωt+90°)، أي الفولطية تسبق التيار بربع دورة (90°)."},{"ch":"g6c3","q":"ما قانون رادة الحث X_L؟","opts":["X_L = 1/(2πfL)","X_L = 2πfL","X_L = 2πf/L","X_L = L/f"],"a":1,"why":"رادة الحث X_L = ωL = 2πfL — تتناسب طردياً مع التردد ومعامل الحث."},{"ch":"g6c3","q":"محث معامل حثه L=0.2H بدائرة ترددها 50Hz. جد رادة الحث (خذ π≈3.14).","opts":["125.6 Ω","31.4 Ω","62.8 Ω","6.28 Ω"],"a":2,"why":"X_L = 2πfL = 2×3.14×50×0.2 = 62.8 Ω."},{"ch":"g6c3","q":"ماذا يحدث لرادة الحث X_L عند تردد مرتفع جداً؟","opts":["تصبح سالبة","تصبح صفراً","تبقى ثابتة بغضّ النظر عن التردد","تصبح كبيرة جداً وتكاد تخنق التيار (تصرّف الخانق)"],"a":3,"why":"بما أن X_L=2πfL تتناسب طردياً مع f، فارتفاع التردد كثيراً يرفع X_L كثيراً فيكاد يمنع مرور التيار."},{"ch":"g6c3","q":"عند تيار مستمر (f=0)، ما مقدار رادة الحث X_L؟","opts":["صفر — يعمل المحث كسلك عادي (قصر)","لانهاية — يمنع أي تيار كلياً","تساوي L نفسها بالأوم","غير معرّفة رياضياً"],"a":0,"why":"X_L=2πfL، وعند f=0 تصبح X_L=0 مهما كانت قيمة L — أي معارضة معدومة للتيار المستمر."},{"ch":"g6c3","q":"لماذا يستعمل مهندسو الإنارة محثاً (خانقاً) لا مقاومة عادية للحدّ من تيار مصباح الفلورسنت؟","opts":["لأن المحث أرخص ثمناً فقط","لأن رادة المحث تحدّ التيار دون أي تبديد للطاقة حرارةً (قدرته المتوسطة=صفر)، بعكس المقاومة التي تبدّد حرارة وتهدر طاقة","لأن المحث يعمل فقط مع التيار المستمر","لا يوجد فرق حقيقي بين الاثنين"],"a":1,"why":"المقاومة تحدّ التيار لكنها تبدّد جزءاً كبيراً من الطاقة حرارةً (هدر)، بينما المحث يحدّ التيار بلا أي تبديد للطاقة (P_av=0) — كفاءة أعلى بكثير."},{"ch":"g6c3","q":"بدائرة تحتوي متسعة ذات سعة صرفة C فقط، أيّهما يتقدّم على الآخر؟","opts":["كلاهما بطور واحد","الفولطية تتقدّم التيار بزاوية 90°","التيار يتقدّم الفولطية بزاوية 90°","الفرق بينهما 45° فقط"],"a":2,"why":"بمتسعة صرفة: I_C = I_m sin(ωt+90°)، أي التيار يسبق الفولطية بربع دورة (90°) — عكس المحث تماماً."},{"ch":"g6c3","q":"ما قانون رادة السعة X_C؟","opts":["X_C = C/f","X_C = 2πfC","X_C = 2πf/C","X_C = 1/(2πfC)"],"a":3,"why":"رادة السعة X_C = 1/(ωC) = 1/(2πfC) — تتناسب عكسياً مع التردد والسعة."},{"ch":"g6c3","q":"عند تيار مستمر (f=0)، ما مقدار رادة السعة X_C؟","opts":["لانهاية — تعمل المتسعة كمفتاح مفتوح وتحجب المرور","صفر — تعمل المتسعة كسلك عادي","تساوي C نفسها بالأوم","غير معرّفة رياضياً"],"a":0,"why":"X_C=1/(2πfC)، وعند f=0 يصبح المقام صفراً فتؤول X_C إلى لانهاية — أي معارضة كاملة (مفتاح مفتوح) للتيار المستمر."},{"ch":"g6c3","q":"ماذا يحدث لرادة السعة X_C عند تردد مرتفع جداً؟","opts":["تصبح كبيرة جداً وتخنق التيار","تصبح صغيرة جداً وتمرّر التيار بسهولة تامة","تبقى ثابتة بغضّ النظر عن التردد","تصبح سالبة"],"a":1,"why":"بما أن X_C تتناسب عكسياً مع f، فارتفاع التردد كثيراً يخفّض X_C كثيراً فيمرّ التيار بسهولة أكبر."},{"ch":"g6c3","q":"متسعة سعتها C=100μF بمصدر تردده 50Hz. ما مقدار رادة السعة تقريباً؟ (خذ π≈3.14)","opts":["≈ 3.18 Ω","≈ 318 Ω","≈ 31.8 Ω","≈ 0.318 Ω"],"a":2,"why":"X_C = 1/(2π×50×100×10⁻⁶) = 1/(0.0314) ≈ 31.8 Ω."},{"ch":"g6c3","q":"لماذا تُستعمل متسعة (مكثّف ربط) قبل مكبّر الصوت لتمرير إشارة الصوت المتناوبة وحجب فولطية التغذية المستمرة؟","opts":["لأن المتسعة تحجب أي تيار متناوب أياً كان","لا علاقة للتردد بعمل هذه الدائرة","لأن المتسعة تكبّر الصوت بنفسها","لأن رادة المتسعة X_C=1/(2πfC) كبيرة جداً (~لانهاية) مع الفولطية المستمرة (f=0) فتحجبها، بينما محدودة مع إشارة الصوت المتناوبة فتمرّرها"],"a":3,"why":"المتسعة تحجب المركّبة المستمرة (f=0 ⟹ X_C=∞) وتمرّر المركّبة المتناوبة (f>0 ⟹ X_C محدودة) — هذا بالضبط مبدأ مكثّف الربط."},{"ch":"g6c3","q":"لماذا لا نجمع V_R وV_L وV_C جبرياً (بجمع عادي) لإيجاد V_T؟","opts":["لأنها لا تبلغ ذروتها بنفس اللحظة (بينها فروق طور)، فيجب جمعها متجهياً","لأن الجمع الجبري ممنوع رياضياً بالفيزياء","لأنها بوحدات مختلفة","لا سبب حقيقي، الجمع الجبري صحيح أيضاً"],"a":0,"why":"V_R بطور I، وV_L متقدّمة 90°، وV_C متأخرة 90° — فروق طور بينها تمنع جمعها كأعداد عادية، ويجب جمعها متجهياً."},{"ch":"g6c3","q":"دائرة متوالية R-L-C فيها R=6Ω، X_L=12Ω، X_C=4Ω. ما مقدار الممانعة Z؟","opts":["14 Ω","10 Ω","8 Ω","20 Ω"],"a":1,"why":"Z = √(R² + (X_L−X_C)²) = √(6² + 8²) = √(36+64) = √100 = 10 Ω."},{"ch":"g6c3","q":"بنفس الدائرة أعلاه (R=6Ω, X_L−X_C=8Ω)، الدائرة:","opts":["أومية صرفة","سعوية، لأن X_C>X_L","حثّية، لأن X_L>X_C","لا يمكن تحديد نوعها"],"a":2,"why":"بما أن X_L=12Ω أكبر من X_C=4Ω، فالدائرة حثّية وزاوية Φ موجبة."},{"ch":"g6c3","q":"ما شرط اعتبار الدائرة المتوالية R-L-C 'سعوية'؟","opts":["C أكبر من L بالقيمة العددية","X_L > X_C دائماً","R أكبر من Z","X_C > X_L (فتكون Φ سالبة، والفولطية الكلية تتأخر عن التيار)"],"a":3,"why":"الدائرة سعوية إذا كانت رادة السعة أكبر من رادة الحث (X_C>X_L)، فتصبح Φ سالبة وتتأخر الفولطية الكلية عن التيار."},{"ch":"g6c3","q":"دائرة متوالية Z=25Ω وR=20Ω. ما مقدار (X_L−X_C) بهذه الدائرة؟","opts":["15 Ω","5 Ω","45 Ω","invalid"],"a":0,"why":"من Z²=R²+(X_L−X_C)²: 625=400+(X_L−X_C)² ⟹ (X_L−X_C)²=225 ⟹ (X_L−X_C)=15Ω."},{"ch":"g6c3","q":"دائرة متوالية بفولطية كلية V_T=240V وتيار I=4.8A. ما مقدار الممانعة الكلية Z؟","opts":["45.7 Ω","50 Ω","1152 Ω","0.02 Ω"],"a":1,"why":"Z = V_T/I = 240/4.8 = 50 Ω."},{"ch":"g6c3","q":"ما الفرق بين القدرة الحقيقية P_real والقدرة الظاهرية P_app؟","opts":["P_app أكبر من P_real دائماً بمقدار ثابت 90 واط","لا فرق، متساويتان دائماً بكل دائرة","P_real هي المستهلكة فعلاً بالمقاومة (P_real=I V_T cosΦ)، وP_app=I V_T بلا اعتبار لفرق الطور","P_real تقاس بـV·A وP_app تقاس بـW"],"a":2,"why":"القدرة الحقيقية تراعي زاوية الطور (تُضرب بـcosΦ) لأنها المستهلكة فعلاً بالمقاومة، بينما الظاهرية هي حاصل ضرب I×V_T مباشرة بلا اعتبار للطور."},{"ch":"g6c3","q":"ما قانون عامل القدرة pf؟","opts":["pf = tan Φ","pf = sin Φ = X/Z","pf = Z/R","pf = cos Φ = R/Z"],"a":3,"why":"عامل القدرة هو نسبة القدرة الحقيقية للظاهرية، ويساوي cosΦ = R/Z."},{"ch":"g6c3","q":"دائرة مقاومتها R=30Ω وممانعتها Z=50Ω. ما عامل القدرة؟","opts":["0.6","0.3","1.67","50"],"a":0,"why":"pf = R/Z = 30/50 = 0.6."},{"ch":"g6c3","q":"بمقاومة صرفة (R فقط، بلا محث أو متسعة)، ما مقدار عامل القدرة؟","opts":["0","1 (كل القدرة الظاهرية تُستهلك فعلاً)","0.5","يعتمد على قيمة R"],"a":1,"why":"بمقاومة صرفة Φ=0°، وpf=cos0°=1 — أعلى عامل قدرة ممكن."},{"ch":"g6c3","q":"بمحث صرف أو متسعة صرفة (بلا مقاومة)، ما مقدار عامل القدرة ولماذا؟","opts":["0.5 دائماً بكل الحالات","1، تماماً مثل المقاومة","0، لأن Φ=90° وcos90°=0","يعتمد على قيمة L أو C فقط"],"a":2,"why":"بمحث أو متسعة صرفة Φ=90°، وcos90°=0، أي لا استهلاك حقيقي للقدرة إطلاقاً رغم مرور تيار."},{"ch":"g6c3","q":"ملف رُبط بمصدر V_T=100V فمرّ به تيار I=5A بزاوية طور Φ=37° (cos37°=0.8). ما مقاومة الملف R؟","opts":["80 Ω","20 Ω","12.5 Ω","16 Ω"],"a":3,"why":"Z=V_T/I=100/5=20Ω، ثم من pf=cosΦ=R/Z: R=Z×cosΦ=20×0.8=16Ω."},{"ch":"g6c3","q":"ما شرط حدوث الرنين بدائرة RLC متوالية؟","opts":["X_L = X_C","R = Z","X_L = R","X_C = 0 دائماً"],"a":0,"why":"الرنين يحدث عندما تتساوى الرادتان X_L و X_C فتلغي إحداهما الأخرى."},{"ch":"g6c3","q":"عند الرنين، ما مقدار الممانعة الكلية Z؟","opts":["Z = 0","Z = R (أصغر ما يمكن)","Z = X_L + X_C","Z تساوي لانهاية"],"a":1,"why":"عند الرنين X_L=X_C فتلغي إحداهما الأخرى في Z²=R²+(X_L−X_C)²، فتصبح Z=R بالضبط — أصغر قيمة ممكنة للممانعة."},{"ch":"g6c3","q":"ما قانون التردد الرنيني f_r؟","opts":["f_r = 1/(2πLC)","f_r = 2π√(LC)","f_r = 1/(2π√(LC))","f_r = √(L/C)"],"a":2,"why":"من شرط الرنين ωL=1/ωC نستخرج ω_r=1/√(LC)، وf_r=ω_r/2π=1/(2π√(LC))."},{"ch":"g6c3","q":"دائرة رنين محثها L=2H ومتسعتها C=0.5μF. جد التردد الزاوي الرنيني ω_r.","opts":["0.001 rad/s","500 rad/s","2000 rad/s","1000 rad/s"],"a":3,"why":"ω_r = 1/√(LC) = 1/√(2×0.5×10⁻⁶) = 1/√(10⁻⁶) = 1000 rad/s."},{"ch":"g6c3","q":"ماذا يعني عامل نوعية Q_f مرتفع؟","opts":["قمة رنين حادة وضيقة (انتقائية عالية لتردد واحد)، غالباً بمقاومة R صغيرة","قمة رنين عريضة وغير دقيقة","لا علاقة له بحدّة القمة إطلاقاً","يعني تيار الرنين صغير جداً"],"a":0,"why":"Q_f=(1/R)√(L/C) — كلما صغرت R كبر Q_f وصارت قمة الرنين أحدّ (نطاق Δf أضيق)، وهذا ما يمنح الراديو انتقائية عالية لمحطة واحدة."},{"ch":"g6c3","q":"علّل: يمكن أن تكون زاوية فرق الطور Φ=0 بدائرة RLC متوالية الربط.","opts":["لأن R تساوي دائماً صفراً بكل الدوائر","عند حالة الرنين (X_L=X_C) تُلغي الرادتان بعضهما فتصبح Z=R فقط، وtanΦ=(X_L−X_C)/R=0","لأن المصدر بالضرورة تيار مستمر","هذا لا يحدث أبداً بدائرة RLC متوالية"],"a":1,"why":"بحالة الرنين تتساوى X_L وX_C فيصبح البسط بقانون الزاوية صفراً، وبالتالي Φ=0 وعامل القدرة=1."},{"ch":"g6c3","q":"بربط التوازي RLC، أي كمية تكون نفسها عبر كل العناصر؟","opts":["المقاومة R فقط","التيار الكلي I_T","الفولطية V","لا شيء مشترك بينها"],"a":2,"why":"بالتوازي، الفولطية نفسها عبر كل الفروع V_R=V_L=V_C=V، بعكس التوالي حيث التيار هو المشترك."},{"ch":"g6c3","q":"ما قانون التيار الرئيس I_T بربط التوازي؟","opts":["I_T = I_R × I_L × I_C","I_T = I_R + I_L + I_C","I_T² = I_R² + I_L² + I_C²","I_T² = I_R² + (I_C−I_L)²"],"a":3,"why":"نجمع تيارات الفروع متجهياً: I_R مرجع، و(I_C−I_L) هو المحصّلة الشاقولية، فـI_T هو وتر المثلث الناتج."},{"ch":"g6c3","q":"دائرة توازي: I_R=3A، I_C=8A، I_L=12A. جد I_T.","opts":["5 A","23 A","17 A","1 A"],"a":0,"why":"I_T = √(I_R² + (I_C−I_L)²) = √(3² + (8−12)²) = √(9+16) = √25 = 5 A."},{"ch":"g6c3","q":"بنفس الدائرة أعلاه (I_L=12A أكبر من I_C=8A)، ما خواص الدائرة؟","opts":["سعوية، لأن I_L أكبر","حثّية، لأن تيار فرع المحث أكبر من تيار فرع المتسعة","أومية صرفة","لا يمكن تحديد ذلك من التيارات"],"a":1,"why":"بالتوازي: I_L>I_C ⟹ الدائرة حثّية الخواص (عكس اتجاه المقارنة بالتوالي تماماً)."},{"ch":"g6c3","q":"بدائرة توالية، الحكم على نوع الدائرة يعتمد على مقارنة X_L بـX_C مباشرة. بدائرة توازي، على أي كمية تعتمد المقارنة بدلاً من ذلك؟","opts":["مقارنة R بـZ فقط","نفس مقارنة X_L وX_C بالضبط وبنفس الاتجاه","مقارنة تيار فرع المحث I_L بتيار فرع المتسعة I_C (باتجاه معاكس تماماً لقاعدة التوالي)","لا توجد أي طريقة للتفريق بينهما بالتوازي"],"a":2,"why":"بالتوازي، I=V/X علاقة عكسية، فالفرع ذو الرادة الأصغر يسحب التيار الأكبر — لذا ينعكس اتجاه المقارنة عن التوالي."},{"ch":"g6c3","q":"دائرة توازي فرق جهدها 240V، وتياراتها I_R=3A، I_C=8A، I_L=12A (فـI_T=5A). ما الممانعة الكلية Z؟","opts":["1200 Ω","80 Ω","28.8 Ω","48 Ω"],"a":3,"why":"Z = V/I_T = 240/5 = 48 Ω."},{"ch":"g6c3","q":"تيار متناوب معطى بالعلاقة I=6 sin(100πt). ما مقدار تردده f؟","opts":["50 Hz","100 Hz","25 Hz","314 Hz"],"a":0,"why":"ω=100π=2πf ⟹ f=50Hz."},{"ch":"g6c3","q":"فولطية متناوبة أعظمها V_m=150V. ما مقدارها المؤثر تقريباً؟","opts":["150 V","≈106.1 V","212 V","75 V"],"a":1,"why":"V_eff = V_m/√2 = 150/1.414 ≈ 106.1 V."},{"ch":"g6c3","q":"تيار متناوب مقداره المؤثر I_eff=4A. ما مقداره الأعظم I_m؟","opts":["2.83 A","4 A","≈5.66 A","8 A"],"a":2,"why":"I_m = I_eff × √2 = 4×1.414 ≈ 5.66 A."},{"ch":"g6c3","q":"متجه الطور بتيار متناوب يدور بسرعة زاوية ω. ما الذي يمثله مسقطه على المحور الشاقولي بأي لحظة؟","opts":["لا يمثّل شيئاً فيزيائياً","تردد التيار f","المقاومة R للدائرة","القيمة الآنية (اللحظية) للتيار"],"a":3,"why":"مسقط متجه الطور (طوله I_m) على المحور الشاقولي يعطي القيمة الآنية بالضبط i(t)=I_m sinθ."},{"ch":"g6c3","q":"لماذا نستعمل المقدار المؤثر لا الذروة عند وصف تيار أو فولطية متناوبة عملياً؟","opts":["لأنه يكافئ تياراً/فولطية مستمرة بنفس التأثير الحراري، وهو ما تقرؤه الأجهزة (الأميتر والفولتميتر) فعلياً","لأنه أكبر رقمياً من الذروة دائماً","لأن الذروة لا يمكن حسابها رياضياً","لا يوجد سبب فيزيائي حقيقي لذلك"],"a":0,"why":"المقدار المؤثر (RMS) هو ما تقيسه الأجهزة فعلياً، ويكافئ تياراً/فولطية مستمرة بنفس مقدار التأثير الحراري."},{"ch":"g6c3","q":"دائرة تحتوي مقاومة صرفة R=25Ω مربوطة بمصدر V_m=50V. جد التيار الأعظم I_m.","opts":["0.5 A","2 A","25 A","75 A"],"a":1,"why":"I_m = V_m/R = 50/25 = 2 A."},{"ch":"g6c3","q":"بنفس الدائرة أعلاه (R=25Ω, I_m=2A, V_m=50V)، جد القدرة المتوسطة P_av.","opts":["25 W","100 W","50 W","12.5 W"],"a":2,"why":"P_av = I_m V_m/2 = 2×50/2 = 50 W."},{"ch":"g6c3","q":"ما فرق الطور Φ بين الفولطية والتيار بدائرة مقاومة صرفة؟","opts":["يعتمد على قيمة R","90°","180°","0°"],"a":3,"why":"بمقاومة صرفة، V وI يبلغان الذروة ويصفران بنفس اللحظة تماماً، أي Φ=0."},{"ch":"g6c3","q":"لماذا تتحول كل القدرة بمقاومة صرفة إلى حرارة، بعكس المحث أو المتسعة؟","opts":["لأن V وI بطور واحد فحاصل ضربهما (القدرة) موجب دائماً بلا أي جزء يُختزن ويُعاد","لأن المقاومة تخزّن الطاقة أكثر من المحث","لا فرق حقيقي بين المقاومة والمحث","لأن التيار بالمقاومة أكبر دائماً من غيرها"],"a":0,"why":"بما أن الإشارة متطابقة دائماً (Φ=0)، فحاصل الضرب p=vi موجب بكل لحظة، فكل الطاقة تُستهلك حرارة."},{"ch":"g6c3","q":"القدرة اللحظية بمقاومة صرفة تتذبذب بضعف تردد الفولطية نفسها. إذا كان تردد الشبكة 50Hz، فبأي تردد تتذبذب القدرة؟","opts":["50 Hz","100 Hz","25 Hz","200 Hz"],"a":1,"why":"لأن p(t)∝sin²(ωt) وترددها ضعف تردد v وi، فتكون 2×50=100Hz."},{"ch":"g6c3","q":"محث صرف L=0.5H بدائرة ترددها f=100Hz. جد رادة الحث X_L (خذ π≈3.14).","opts":["50 Ω","157 Ω","314 Ω","628 Ω"],"a":2,"why":"X_L = 2πfL = 2×3.14×100×0.5 = 314 Ω."},{"ch":"g6c3","q":"بدائرة محث صرف، الفولطية V_L بالنسبة للتيار I_L:","opts":["تتقدّم عليه بزاوية 180°","تتأخر عنه بزاوية 90°","بطور واحد معه","تتقدّم عليه بزاوية 90°"],"a":3,"why":"V_L = V_m sin(ωt+90°)، أي الفولطية تسبق التيار بربع دورة."},{"ch":"g6c3","q":"محث رادته X_L=40Ω مربوط بمصدر فولطيته المؤثرة 20V. جد التيار المؤثر.","opts":["0.5 A","2 A","20 A","800 A"],"a":0,"why":"I_eff = V_eff/X_L = 20/40 = 0.5 A."},{"ch":"g6c3","q":"عند مضاعفة تردد مصدر مربوط بمحث صرف (مع بقاء L ثابتاً)، ماذا يحدث لرادة الحث X_L؟","opts":["تنخفض للنصف","تتضاعف","تبقى ثابتة","تصبح صفراً"],"a":1,"why":"X_L=2πfL تتناسب طردياً مع f، فمضاعفة f تضاعف X_L."},{"ch":"g6c3","q":"لماذا يُستعمل المحث (لا المقاومة) لتحديد تيار أنبوب الفلورسنت؟","opts":["لأنه يعمل فقط مع مصدر تيار مستمر","لأنه أرخص ثمناً من المقاومة فقط","لأنه يحدّ التيار دون تبديد أي طاقة حرارية (قدرته المتوسطة تساوي صفراً)","لا يوجد سبب هندسي حقيقي لذلك"],"a":2,"why":"المحث الصرف يحدّ التيار بلا تبديد أي طاقة حرارية (Φ=90°⟹P_av=0)، بعكس المقاومة التي تهدر جزءاً كبيراً حرارة."},{"ch":"g6c3","q":"متسعة C=20μF بدائرة ترددها f=1000Hz. جد رادة السعة X_C تقريباً.","opts":["≈800 Ω","≈80 Ω","≈0.8 Ω","≈8 Ω"],"a":3,"why":"X_C = 1/(2πfC) = 1/(2π×1000×20×10⁻⁶) ≈ 8 Ω."},{"ch":"g6c3","q":"بدائرة متسعة صرفة، التيار I_C بالنسبة للفولطية V_C:","opts":["يتقدّم عليها بزاوية 90°","يتأخر عنها بزاوية 90°","بطور واحد معها","يتقدّم عليها بزاوية 180°"],"a":0,"why":"I_C = I_m sin(ωt+90°)، أي التيار يسبق الفولطية بربع دورة — عكس المحث."},{"ch":"g6c3","q":"عند تيار مستمر تماماً (f=0)، كيف تتصرف المتسعة بالدائرة؟","opts":["كسلك عادي — تمرر بلا أي معارضة","كمفتاح مفتوح — تحجب المرور تماماً","تنفجر دائماً بهذه الحالة","لا فرق عن حالة التيار المتناوب"],"a":1,"why":"X_C=1/(2πfC)→∞ عند f=0، أي معارضة كاملة (مفتاح مفتوح) للتيار المستمر."},{"ch":"g6c3","q":"عند مضاعفة تردد مصدر مربوط بمتسعة صرفة (مع بقاء C ثابتة)، ماذا يحدث لرادة السعة X_C؟","opts":["تبقى ثابتة","تتضاعف","تنخفض للنصف","تصبح لانهاية"],"a":2,"why":"X_C=1/(2πfC) تتناسب عكسياً مع f، فمضاعفة f تخفّض X_C للنصف."},{"ch":"g6c3","q":"متسعة C=50μF بدائرة ترددها f=200Hz (فتكون X_C≈15.9Ω) وفولطيتها المؤثرة V_eff≈15.9V. جد التيار المؤثر تقريباً.","opts":["≈100 A","≈10 A","≈0.1 A","≈1 A"],"a":3,"why":"I_eff = V_eff/X_C ≈ 15.9/15.9 ≈ 1 A."},{"ch":"g6c3","q":"دائرة توالية R=9Ω، X_L=25Ω، X_C=13Ω. جد الممانعة الكلية Z.","opts":["15 Ω","37 Ω","22 Ω","9.6 Ω"],"a":0,"why":"Z = √(R²+(X_L−X_C)²) = √(9²+12²) = √(81+144) = √225 = 15 Ω."},{"ch":"g6c3","q":"بنفس الدائرة أعلاه (X_L=25Ω > X_C=13Ω)، نوع الدائرة:","opts":["سعوية","حثّية","أومية صرفة","لا يمكن تحديد نوعها"],"a":1,"why":"بما أن X_L أكبر من X_C، فالدائرة حثّية الخواص وΦ موجبة."},{"ch":"g6c3","q":"دائرة توالية RLC ممانعتها Z=13Ω ومقاومتها R=5Ω. جد مقدار |X_L−X_C|.","opts":["18 Ω","8 Ω","12 Ω","65 Ω"],"a":2,"why":"13² = 5² + d² ⟹ d² = 169−25 = 144 ⟹ d = 12 Ω."},{"ch":"g6c3","q":"متى تكون الدائرة المتوالية RLC 'أومية الخواص' تماماً (Φ=0)؟","opts":["لا تحدث هذه الحالة أبداً","عندما R=0","عندما L=C عددياً بأي وحدات","عندما X_L = X_C (حالة الرنين)"],"a":3,"why":"عند X_L=X_C تُلغي الرادتان بعضهما فتصبح Z=R وΦ=0 — هذه بالضبط حالة الرنين."},{"ch":"g6c3","q":"دائرة توالية R=8Ω وZ=17Ω. جد زاوية فرق الطور Φ تقريباً.","opts":["≈62°","≈28°","≈45°","≈90°"],"a":0,"why":"cos Φ = R/Z = 8/17 ≈ 0.47 ⟹ Φ ≈ 62°."},{"ch":"g6c3","q":"دائرة توالية RLC مقاومتها R=12Ω وممانعتها Z=20Ω. جد عامل القدرة pf.","opts":["0.4","0.6","1.67","12"],"a":1,"why":"pf = R/Z = 12/20 = 0.6."},{"ch":"g6c3","q":"دائرة تيارها المؤثر I=3A وفولطيتها الكلية V_T=50V وعامل قدرتها 0.8. جد القدرة الحقيقية P_real.","opts":["37.5 W","150 W","120 W","187.5 W"],"a":2,"why":"P_real = I V_T cosΦ = 3×50×0.8 = 120 W."},{"ch":"g6c3","q":"بنفس الدائرة أعلاه (I=3A، V_T=50V)، جد القدرة الظاهرية P_app.","opts":["187.5 V·A","120 V·A","96 V·A","150 V·A"],"a":3,"why":"P_app = I × V_T = 3×50 = 150 V·A (بلا اعتبار لعامل القدرة)."},{"ch":"g6c3","q":"لماذا تُقاس القدرة الظاهرية بوحدة فولت-أمبير (V·A) لا واط (W)؟","opts":["لتمييزها عن القدرة الحقيقية المستهلكة فعلاً، فهي لا تمثّل استهلاكاً فعلياً كاملاً للطاقة","لأنها دائماً أكبر رقمياً من ألف واط","خطأ تاريخي بالتسمية بلا سبب فيزيائي","لأن التيار والفولطية بوحدات غير متوافقة"],"a":0,"why":"القدرة الظاهرية I×V لا تراعي فرق الطور، فقد يكون جزء كبير منها متردداً بلا استهلاك فعلي — لذا تُميَّز بوحدة مختلفة."},{"ch":"g6c3","q":"أي دائرة تملك أعلى عامل قدرة ممكن (pf=1)؟","opts":["دائرة محث صرف فقط","دائرة مقاومة صرفة (R فقط)","دائرة متسعة صرفة فقط","أي دائرة RLC عامة بغضّ النظر عن قيمها"],"a":1,"why":"بمقاومة صرفة Φ=0 وpf=cos0°=1 — أعلى عامل قدرة ممكن فيزيائياً."},{"ch":"g6c3","q":"دائرة رنين محثها L=0.5H ومتسعتها C=2μF. جد التردد الرنيني f_r تقريباً.","opts":["≈1000 Hz","≈318 Hz","≈159 Hz","≈50 Hz"],"a":2,"why":"f_r = 1/(2π√(LC)) = 1/(2π√(0.5×2×10⁻⁶)) = 1/(2π×0.001) ≈ 159 Hz."},{"ch":"g6c3","q":"عند الرنين بدائرة RLC متوالية، ما مقدار عامل القدرة؟","opts":["يعتمد على قيمة R","0","0.5","1"],"a":3,"why":"عند الرنين Z=R وΦ=0، فpf=cos0°=1 بغض النظر عن قيمة R نفسها."},{"ch":"g6c3","q":"دائرة رنين R=5Ω، L=0.1H، C=40μF. جد عامل النوعية Q_f.","opts":["10","50","5","0.02"],"a":0,"why":"Q_f = (1/R)√(L/C) = (1/5)√(0.1/40×10⁻⁶) = (1/5)×50 = 10."},{"ch":"g6c3","q":"ماذا يحدث لعرض قمة الرنين (نطاق التردد Δf) عند زيادة المقاومة R؟","opts":["ينخفض دائماً مع زيادة R","يزداد (تصبح القمة أعرض وأقل حدّة، وQ_f ينخفض)","يبقى ثابتاً بغض النظر عن R","يصبح صفراً حتماً"],"a":1,"why":"Δω=R/L يزداد طردياً مع R، فتتّسع قمة الرنين ويقلّ عامل النوعية Q_f=ω_r/Δω."},{"ch":"g6c3","q":"دائرة رنين مقاومتها R صغيرة جداً تقترب من الصفر. ماذا يحدث لتيار الرنين تحديداً (I_max=V/R)؟","opts":["لا يتأثر بقيمة R إطلاقاً","يصبح صفراً","يصبح كبيراً جداً","يصبح سالباً"],"a":2,"why":"عند الرنين I_max=V/R، فكلما صغرت R اقترب المقام من الصفر فكبر التيار جداً."},{"ch":"g6c3","q":"دائرة توازي: I_R=6A، I_L=8A، I_C=8A. جد التيار الرئيس I_T.","opts":["2 A","22 A","10 A","6 A"],"a":3,"why":"I_T = √(I_R²+(I_C−I_L)²) = √(6²+0²) = 6 A (لأن I_C=I_L فيلغي أحدهما الآخر)."},{"ch":"g6c3","q":"بنفس الدائرة أعلاه (I_L=I_C بالضبط)، ما خواص الدائرة؟","opts":["أومية صرفة تقريباً (حالة قريبة من الرنين)","حثّية بشدة","سعوية بشدة","غير معرّفة رياضياً"],"a":0,"why":"عندما يتساوى I_L مع I_C يُلغي أحدهما الآخر تماماً، فتتصرف الدائرة كأنها مقاومة صرفة — أقرب حالة للرنين بالتوازي."},{"ch":"g6c3","q":"دائرة توازي V=100V، I_R=5A، I_L=15A، I_C=3A. جد التيار الرئيس I_T.","opts":["23 A","13 A","7 A","≈15.8 A"],"a":1,"why":"I_T = √(5²+(3−15)²) = √(25+144) = √169 = 13 A."},{"ch":"g6c3","q":"بنفس الدائرة أعلاه، جد الممانعة الكلية Z.","opts":["13 Ω","100 Ω","≈7.7 Ω","5 Ω"],"a":2,"why":"Z = V/I_T = 100/13 ≈ 7.7 Ω."},{"ch":"g6c3","q":"بدائرة توازي RLC، إذا كان I_C أكبر من I_L، فالدائرة:","opts":["لا يمكن تحديد ذلك من التيارات فقط","حثّية الخواص","أومية صرفة دائماً بهذه الحالة","سعوية الخواص"],"a":3,"why":"بالتوازي: I_C>I_L ⟹ الدائرة سعوية (عكس اتجاه المقارنة بالتوالي حيث تُقارن X_L بـX_C مباشرة)."},{"ch":"g6c3","q":"أي من العناصر الثلاثة (R، L، C) هو الوحيد الذي يستهلك طاقة فعلياً وبشكل دائم بدائرة تيار متناوب؟","opts":["R (المقاومة) فقط","L (المحث) فقط","C (المتسعة) فقط","الثلاثة بالتساوي"],"a":0,"why":"المحث والمتسعة يختزنان الطاقة ويعيدانها (P_av=0)، بينما المقاومة وحدها تحوّلها حرارة بشكل دائم."},{"ch":"g6c3","q":"بدائرة RLC متوالية عند تردد أقل من التردد الرنيني (f<f_r)، أيّهما أكبر: X_L أم X_C؟","opts":["X_L أكبر دائماً بغضّ النظر عن f","X_C أكبر (الدائرة سعوية تحت الرنين)","متساويتان دائماً مهما كان f","لا علاقة للتردد بهذه المقارنة"],"a":1,"why":"X_L=2πfL يصغر مع صغر f، وX_C=1/(2πfC) يكبر مع صغر f، فتحت الرنين تكون X_C>X_L حتماً — دائرة سعوية."},{"ch":"g6c3","q":"ما وحدة قياس الرادة (X_L أو X_C) والممانعة Z؟","opts":["أمبير (A)","فولت (V)","أوم (Ω) — نفس وحدة المقاومة تماماً","واط (W)"],"a":2,"why":"الرادة والممانعة كلاهما نوع من المعارضة الكهربائية، ويُقاسان بالأوم كالمقاومة تماماً رغم اختلاف طبيعتهما الفيزيائية."},{"ch":"g6c3","q":"بالمخطط المرفق (الضلع الشاقولي متّجه لأسفل، أي X_C أكبر من X_L)، ما مقدار الممانعة Z؟","opts":["60 Ω","17 Ω","7 Ω","13 Ω"],"a":3,"why":"Z = √(R²+(X_C−X_L)²) = √(5²+12²) = √(25+144) = √169 = 13 Ω."},{"ch":"g6c3","q":"(سؤال وزاري، تمهيدي 2020) مصدر فولطية متناوبة رُبط بينه وبين مقاومة صرفة R=100Ω، والفولطية V_R=424.2 sin(200πt). ما المقدار المؤثر للتيار؟","opts":["3 A","4.242 A","300 A","1.5 A"],"a":0,"why":"V_eff=V_m/√2=424.2/1.414≈300V، ثم I_eff=V_eff/R=300/100=3A."},{"ch":"g6c3","q":"(سؤال وزاري، الدور الثالث 2019) علّل: القدرة المتبدّدة بتيار متناوب أعظمه I_m لا تساوي قدرة تيار مستمر بنفس المقدار I_m.","opts":["لأن التيار المتناوب لا يسخّن شيئاً إطلاقاً","لأن المتناوب لا يبقى عند I_m إلا لحظة واحدة كل ربع دورة، فمتوسط قدرته ½I_m²R أصغر من قدرة المستمر I_m²R","لأن المقاومة تتغيّر قيمتها مع نوع التيار","لا فرق حقيقي بين النوعين"],"a":1,"why":"متوسط قدرة المتناوب ½I_m²R يكافئ مستمراً بمقدار I_eff=I_m/√2 فقط، وهو أصغر من I_m."},{"ch":"g6c3","q":"(سؤال وزاري، الدور الثاني 2020) ما مميزات منحني القدرة المتوسطة بدائرة تحتوي محث صرف فقط؟","opts":["سالب دائماً بلا استثناء","موجب دائماً كما بالمقاومة الصرفة","أجزاء موجبة وسالبة متساوية المساحة، فمجموعها صفر (لا تبديد طاقة)","يساوي القدرة الظاهرية دائماً"],"a":2,"why":"بمحث أو متسعة صرفة (Φ=90°) تتساوى مساحتا الجزء الموجب والسالب من منحني القدرة، فمتوسطها صفر تماماً."},{"ch":"g6c3","q":"(سؤال وزاري، الدور الثالث 2022) دائرة توالية R=40Ω، X_L=120Ω، X_C=90Ω، فولطيتها V_T=240V. جد تيار الدائرة I.","opts":["48 A","6 A","2.67 A","4.8 A"],"a":3,"why":"Z=√(40²+30²)=√2500=50Ω، ثم I=V_T/Z=240/50=4.8A."},{"ch":"g6c3","q":"(سؤال وزاري، الدور الثاني 2021) ملف رُبط بمصدر V_T=100V فمرّ به تيار I=5A بزاوية طور Φ=37° (cos37°=0.8). جد مقاومة الملف R.","opts":["16 Ω","20 Ω","12.5 Ω","80 Ω"],"a":0,"why":"Z=V_T/I=100/5=20Ω، ثم R=Z×cosΦ=20×0.8=16Ω."},{"ch":"g6c3","q":"(سؤال وزاري، الدور الثالث 2019) دائرة رنين متوالية R=3Ω، L=0.04H، C=25μF، فولطيتها 75V. جد التيار عند الرنين.","opts":["3 A","25 A","75 A","225 A"],"a":1,"why":"عند الرنين Z=R=3Ω، فالتيار I=V/Z=75/3=25A."},{"ch":"g6c3","q":"(سؤال وزاري، تمهيدي 2017) دائرة توازي فرق جهدها 240V، وتياراتها I_C=8A، I_L=12A، I_R=3A. جد التيار الرئيس I_T.","opts":["17 A","23 A","5 A","1 A"],"a":2,"why":"I_T=√(I_R²+(I_C−I_L)²)=√(3²+(8−12)²)=√(9+16)=√25=5A."},{"ch":"g6c3","q":"(سؤال وزاري، الدور الثاني 2020) أيّ الحالات التالية تجعل زاوية فرق الطور Φ تساوي صفراً بدائرة RLC متوالية الربط؟","opts":["لا تحدث هذه الحالة أبداً بوجود L وC معاً","عندما تكون R=0","عندما يكون التردد f=0 دائماً","حالة الرنين، حيث X_L=X_C فتُلغي إحداهما الأخرى"],"a":3,"why":"عند الرنين X_L=X_C فتصبح Z=R وtanΦ=(X_L−X_C)/R=0 ⟹ Φ=0."},{"ch":"g6c4","q":"لماذا يصلنا ضوء الشمس عبر الفراغ بينما لا يصلنا أي صوت من الفضاء؟","opts":["لأن الضوء موجة كهرومغناطيسية لا تحتاج وسطاً ماديّاً، بينما الصوت موجة ميكانيكية تحتاج جزيئات مادة تهتزّ","لأن الصوت أبطأ من الضوء فقط ولم يصل بعد","لأن الفضاء يمتص الصوت بالكامل رغم قدرته على الانتقال به","لا فرق حقيقي، والصوت يصل لكن بشدة ضعيفة جداً"],"a":0,"why":"الموجة الكهرومغناطيسية تحمل مجاليها الكهربائي والمغناطيسي معها فلا تحتاج وسطاً، بعكس الصوت (موجة ميكانيكية) الذي يحتاج جزيئات مادة يهتزّ بها."},{"ch":"g6c4","q":"ما الذي يجمع بين الضوء المرئي وموجة الراديو وأشعة گاما رغم اختلاف استعمالاتها كلياً؟","opts":["لا يجمعها شيء إطلاقاً، فكل منها نوع فيزيائي مختلف كلياً","كلها موجات كهرومغناطيسية من الطبيعة نفسها، لا تختلف إلا بالتردد وطول الموجة","كلها موجات ميكانيكية تحتاج وسطاً مادياً للانتقال","كلها تنتقل بنفس السرعة تماماً في كل الأوساط المادية"],"a":1,"why":"كل موجات الطيف الكهرومغناطيسي (راديو، مرئي، گاما...) نوع فيزيائي واحد، تختلف فيما بينها بالتردد وطول الموجة فقط، وتنتقل جميعها بسرعة الضوء بالفراغ."},{"ch":"g6c4","q":"ما حجم الضوء المرئي مقارنة بالطيف الكهرومغناطيسي الكامل؟","opts":["الطيف الكهرومغناطيسي كله تقريباً","نصف الطيف الكهرومغناطيسي تقريباً","شريحة ضيقة جداً فقط من طيف واسع جداً","لا علاقة للضوء المرئي بالطيف الكهرومغناطيسي إطلاقاً"],"a":2,"why":"عين الإنسان تكشف فقط شريحة ضيقة جداً من الطيف الكهرومغناطيسي الواسع (٤٠٠-٧٠٠ نانومتر تقريباً)، بينما يمتد الطيف من موجات الراديو حتى أشعة گاما."},{"ch":"g6c4","q":"أي المناطق التالية بالطيف الكهرومغناطيسي أعلى تردداً؟","opts":["الأشعة تحت الحمراء","موجات الراديو","المايكروويف","أشعة گاما"],"a":3,"why":"ترتيب الطيف من أوطأ تردد لأعلاه تقريباً: راديو ← مايكروويف ← تحت الحمراء ← مرئي ← فوق البنفسجية ← سينية ← گاما (الأعلى تردداً والأقصر طول موجة)."},{"ch":"g6c4","q":"ماذا يعني اختصار RADAR؟","opts":["Radio Detection And Ranging — الكشف وتحديد البُعد بوساطة الموجات الراديوية","Rapid Data Transfer — نقل بيانات سريع","Radio Amplitude Distance Reading","لا يحمل الاختصار أي معنى فيزيائي محدد"],"a":0,"why":"RADAR اختصار Radio Detection And Ranging: الكشف وتحديد البُعد بوساطة الموجات الراديوية."},{"ch":"g6c4","q":"كيف يحدّد الرادار بُعد الهدف عملياً؟","opts":["من لون الموجة المرتدّة فقط","من الزمن الذي تستغرقه الموجة ذهاباً وإياباً بين الرادار والهدف (d=ct/2)","من درجة حرارة الهدف المرصود","من وزن الهدف المقاس مباشرة"],"a":1,"why":"يرسل الرادار موجة فترتدّ عن الهدف، والزمن الكلي للرحلة ذهاباً وإياباً يحدد البُعد بالعلاقة d=ct/2."},{"ch":"g6c4","q":"رادار أرسل نبضة استغرقت 400 μs لترتدّ عن سفينة وتعود. جد بُعد السفينة (c=3×10⁸ m/s).","opts":["30 km","120 km","60 km","240 km"],"a":2,"why":"d = ct/2 = (3×10⁸ × 400×10⁻⁶)/2 = 120000/2 = 60000 m = 60 km."},{"ch":"g6c4","q":"ما الفرق بين الصور النشطة وغير النشطة بالاستشعار عن بُعد؟","opts":["النشطة تحتاج طائرة، وغير النشطة تحتاج قمراً صناعياً حصراً","لا فرق حقيقي بين النوعين إطلاقاً","النشطة تُستعمل بالليل فقط، وغير النشطة بالنهار فقط","النشطة: القمر نفسه مصدر الإشعاع (يرسل الموجة ويحلّل ارتدادها)؛ غير النشطة: تعتمد على إشعاع صادر أو منعكس من الهدف نفسه دون أن يُصدر القمر شيئاً"],"a":3,"why":"بالصور النشطة يُصدر القمر موجته الخاصة ويحلّل الارتداد (كالرادار)؛ بغير النشطة يعتمد فقط على إشعاع الهدف نفسه (كضوء الشمس المنعكس)."},{"ch":"g6c4","q":"لماذا كان الرادار حاسماً بالإنذار المبكر عن الطائرات المعادية بالحرب العالمية الثانية؟","opts":["لأنه يكشف بُعد واتجاه الطائرات القادمة بموجات راديوية قبل أن تُرى بالعين المجرّدة","لأنه كان يُسقط الطائرات مباشرة بالموجات الراديوية","لأنه يصنع سحابة تُخفي القوات الصديقة عن العدو","لا علاقة حقيقية للرادار بهذا الحدث التاريخي"],"a":0,"why":"يكشف الرادار بُعد الهدف واتجاهه من زمن ارتداد الموجة، فيُنذر بقدوم الطائرات المعادية قبل رؤيتها بالعين — وهذا بالضبط ما منح بريطانيا وقتاً حاسماً للاستعداد."},{"ch":"g6c4","q":"أي المجالات التالية تستفيد عملياً من الاستشعار عن بُعد؟","opts":["الطب النفسي فقط دون غيره","المساحة، الجيولوجيا، الزراعة (رصد صحة المحاصيل)، الأرصاد الجوية، والتطبيقات العسكرية","صناعة النسيج المحلية فقط","لا يوجد له أي استعمال عملي حقيقي حتى الآن"],"a":1,"why":"الاستشعار عن بُعد يُستعمل بالمساحة والجيولوجيا والزراعة (رصد صحة المحاصيل عبر الأشعة تحت الحمراء) والأرصاد الجوية والتطبيقات العسكرية."},{"ch":"g6c4","q":"كم عدد الحقائق التي استند إليها ماكسويل لبناء نظريته الكهرومغناطيسية؟","opts":["ست حقائق","حقيقتان فقط","أربع حقائق","حقيقة واحدة"],"a":2,"why":"استند ماكسويل لأربع حقائق: مجال الشحنة الساكنة، عدم وجود قطب مغناطيسي منفرد، وتوليد كل من المجالين المتغيّرين للآخر."},{"ch":"g6c4","q":"ماذا يمثّل \"تيار الإزاحة\" I_d الذي قدّمه ماكسويل؟","opts":["قوة دافعة كهربائية محتثة بملف فقط","تياراً حقيقياً ينساب بسلك التوصيل الاعتيادي فقط","فقداً حرارياً بالدائرة الكهربائية","كمية تكافئ أثر المجال الكهربائي المتغيّر مع الزمن، وتتناسب مع معدّل تغيّره (وليست تياراً حقيقياً بشحنات متحركة)"],"a":3,"why":"تيار الإزاحة ليس تياراً حقيقياً (لا شحنات فعلية تتحرك)، بل يكافئ أثر المجال الكهربائي المتغيّر I_d∝ΔE/Δt، وبيّن ماكسويل أنه يولّد مجالاً مغناطيسياً تماماً كتيار التوصيل."},{"ch":"g6c4","q":"لماذا تُوصف الموجة الكهرومغناطيسية بأنها \"مستعرضة\"؟","opts":["لأن مجاليها E وB يتذبذبان عموديين على اتجاه انتشار الموجة (وعموديين على بعضهما أيضاً)","لأنها تنتقل بخط متعرّج لا مستقيم","لأنها أعرض من الموجات الصوتية فيزيائياً","لأن سرعتها تتغيّر باستمرار أثناء انتشارها"],"a":0,"why":"الموجة المستعرضة تتذبذب عمودياً على اتجاه انتشارها، وهذا بالضبط حال E وB بالموجة الكهرومغناطيسية — كلاهما عمودي على اتجاه الانتشار وعلى بعضهما."},{"ch":"g6c4","q":"بأي علاقة يرتبط المجالان الكهربائي والمغناطيسي بالموجة الكهرومغناطيسية من حيث الطور؟","opts":["يتأخر المغناطيسي عن الكهربائي بزاوية 90°","يتذبذبان بالطور نفسه (يبلغان الذروة ويصفران معاً بنفس اللحظة)","يتقدّم المغناطيسي على الكهربائي بزاوية 90°","لا علاقة طورية ثابتة بينهما إطلاقاً"],"a":1,"why":"بحقيقتَي ماكسويل الثالثة والرابعة، يتذبذب كل من E وB بالطور نفسه — يبلغان الذروة معاً ويصفران معاً بنفس اللحظة."},{"ch":"g6c4","q":"أي خاصية من خصائص الموجة الكهرومغناطيسية الخمس تصف توزيع طاقتها؟","opts":["تحمل كل طاقتها بالمجال المغناطيسي فقط","تحمل كل طاقتها بالمجال الكهربائي فقط","تحمل طاقة موزّعة بالتساوي بين مجاليها الكهربائي والمغناطيسي","لا تحمل أي طاقة إطلاقاً، بل تنقل معلومات فقط"],"a":2,"why":"الخاصية الخامسة: تحمل الموجة الكهرومغناطيسية طاقة موزَّعة بالتساوي بين مجاليها الكهربائي والمغناطيسي."},{"ch":"g6c4","q":"أي نوع من الشحنات يُشِعّ موجات كهرومغناطيسية؟","opts":["لا تُشِعّ أي شحنة موجات كهرومغناطيسية إطلاقاً","الشحنة الساكنة فقط","أي شحنة متحركة بسرعة ثابتة، معجَّلة كانت أم لا","الشحنة المعجَّلة (المتذبذبة) فقط"],"a":3,"why":"الشحنة الساكنة تولّد مجالاً كهربائياً ثابتاً فقط، والمتحركة بسرعة ثابتة تولّد مجالين ثابتين؛ أمّا المعجَّلة (المتذبذبة) فتولّد مجالين متغيّرين ينتشران كموجة."},{"ch":"g6c4","q":"بماذا نولّد عملياً الشحنات المتذبذبة اللازمة لإشعاع الموجات الكهرومغناطيسية؟","opts":["مولّد الذبذبات (oscillator) موصولاً بساقين معدنيين (ثنائي قطب كهربائي)","بطارية اعتيادية موصولة بسلك مستقيم بلا حركة","مغناطيس دائم ساكن دون أي دائرة كهربائية","مقاومة كهربائية ثابتة القيمة فقط"],"a":0,"why":"يُوصَل مولّد الذبذبات بساقين معدنيين (ثنائي قطب كهربائي)، فتتذبذب الشحنات صعوداً ونزولاً بتردد المولّد، فتُشِعّ موجات كهرومغناطيسية بالتردد نفسه."},{"ch":"g6c4","q":"ماذا يحدث لتردد الموجة الكهرومغناطيسية المُشعَّة إذا زاد تردد تذبذب الشحنة بمولّد الذبذبات؟","opts":["يبقى تردد الموجة المُشعَّة ثابتاً مهما تغيّر تردد الشحنة","يزداد تردد الموجة المُشعَّة بنفس مقدار زيادة تردد تذبذب الشحنة","يقلّ تردد الموجة المُشعَّة كلما زاد تردد الشحنة","لا علاقة إطلاقاً بين تردد تذبذب الشحنة وتردد الموجة المُشعَّة"],"a":1,"why":"تُشِعّ الشحنة المتذبذبة موجة كهرومغناطيسية بالتردد نفسه لتذبذبها بالضبط — فزيادة تردد التذبذب تعني زيادة مساوية بتردد الموجة المُشعَّة."},{"ch":"g6c4","q":"لماذا لا يُشِعّ سلكٌ يمرّ به تيار كهربائي ثابت المقدار والاتجاه أي موجة كهرومغناطيسية؟","opts":["لأن السلك المستقيم لا يوصل الكهرباء أصلاً","لأن التيار الكهربائي لا يولّد أي مجال مغناطيسي إطلاقاً","لأن الشحنات به تتحرك بسرعة ثابتة (غير معجَّلة)، فتولّد مجالين ثابتين لا متغيّرين","لأن الإشعاع يحتاج فرق جهد أكبر من أي بطارية عادية"],"a":2,"why":"التيار الثابت يعني شحنات تتحرك بسرعة منتظمة غير متسارعة (لا تعجيل)، فتولّد مجالين كهربائياً ومغناطيسياً ثابتين لا يتغيّران بالزمن — ولا إشعاع دون تغيّر."},{"ch":"g6c4","q":"من ماذا تتكوّن دائرة الإرسال أساساً؟","opts":["مكبّر صوت فقط لا علاقة له بالموجات الكهرومغناطيسية","بطارية ومقاومة فقط دون أي هوائي","هوائي فقط دون أي دائرة اهتزاز","دائرة اهتزاز (ملف + متسعة متغيرة) تولّد الموجات، وهوائي يشعّها إلى الفضاء"],"a":3,"why":"دائرة الإرسال تتكوّن من دائرة اهتزاز (ملف ومتسعة متغيرة) تولّد الموجة بالتردد المطلوب، وهوائي يُشِعّها إلى الفضاء."},{"ch":"g6c4","q":"من ماذا تتكوّن دائرة التسلم أساساً؟","opts":["هوائي يلتقط الموجات فيتولّد فيه تيار محتث، ودائرة اهتزاز تُوالَف على تردد المحطة المطلوبة","دائرة اهتزاز فقط دون أي هوائي استقبال","مصباح كهربائي يضيء عند وصول الموجة فقط","لا تحتاج أي مكوّنات، فالموجة تُستقبل تلقائياً"],"a":0,"why":"دائرة التسلم تتكوّن من هوائي يلتقط الموجة الواردة (فيتولّد فيه تيار محتث)، ودائرة اهتزاز تُوالَف بالرنين على تردد المحطة المطلوبة لاختيارها من بين كل الموجات."},{"ch":"g6c4","q":"ما الفرق الجوهري بين دائرتَي الإرسال والتسلم من حيث المكوّنات؟","opts":["دائرة الإرسال لا تحتاج هوائياً إطلاقاً","كلتاهما تحتويان دائرة اهتزاز (L وC) وهوائياً، لكن الإرسال يولّد الموجة ويشعّها، بينما التسلم يلتقطها ويُوالِف عليها","دائرة التسلم لا تحتاج دائرة اهتزاز إطلاقاً","لا فرق حقيقي بينهما بتاتاً"],"a":1,"why":"كلتا الدائرتين تحتويان دائرة اهتزاز وهوائياً؛ لكن الإرسال يُنشئ الموجة بدائرة الاهتزاز ويشعّها بالهوائي، بينما التسلم يلتقط الموجة بالهوائي ويُوالِف دائرة اهتزازه على ترددها بالرنين."},{"ch":"g6c4","q":"أي عبارة تصف دور الهوائي بشكل صحيح بكلا الجهازين (الإرسال والتسلم)؟","opts":["يلتقط الموجة بكلا الجهازين دون أي إشعاع إطلاقاً","يشعّ الموجة بكلا الجهازين دون أي التقاط إطلاقاً","يشعّ الموجة إلى الفضاء بجهاز الإرسال، ويلتقطها من الفضاء بجهاز التسلم","لا دور فيزيائياً حقيقياً للهوائي بأي من الجهازين"],"a":2,"why":"الهوائي عنصر مشترك بكلا الجهازين لكن بدور معاكس: يُشِعّ الموجة للفضاء بالإرسال، ويلتقطها من الفضاء بالتسلم."},{"ch":"g6c4","q":"بأي علاقة يُحسب التردد الرنيني لدائرة الاهتزاز (L وC)؟","opts":["f_r = 1/(LC)","f_r = 2π√(LC)","f_r = LC","f_r = 1/(2π√(LC))"],"a":3,"why":"نفس علاقة الرنين بدائرة RLC المتوالية من فصل التيار المتناوب: f_r=1/(2π√(LC))."},{"ch":"g6c4","q":"كيف نختار التردد المطلوب إرساله أو استقباله عملياً بدائرة الاهتزاز؟","opts":["بتغيير سعة المتسعة المتغيرة C (تدوير قرص الدوزان)","بتغيير طول الهوائي فقط كل مرة","لا يمكن اختيار تردد معيّن إطلاقاً","بتغيير لون السلك الموصل"],"a":0,"why":"تغيير C يغيّر التردد الرنيني f_r=1/(2π√LC))، فنُوالف الدائرة على تردد المحطة المطلوبة."},{"ch":"g6c4","q":"ما أفضل طول لهوائي غير مؤرَّض بالنسبة لطول الموجة λ المرسلة أو المستقبَلة؟","opts":["طول الموجة كاملاً (ℓ=λ)","نصف طول الموجة (ℓ=λ/2)","ضعف طول الموجة (ℓ=2λ)","عُشر طول الموجة (ℓ=λ/10)"],"a":1,"why":"أفضل طول لهوائي غير مؤرَّض يساوي نصف طول الموجة ℓ=λ/2؛ ولو أُرِّض لكفى ربعها ℓ=λ/4."},{"ch":"g6c4","q":"دائرة موالفة محاثتها 2mH وسعتها 8pF. ما تردّدها الرنيني تقريباً؟","opts":["≈0.5×10⁶ Hz","≈2.5×10⁶ Hz","≈1.26×10⁶ Hz","≈16×10⁶ Hz"],"a":2,"why":"f_r=1/(2π√(2×10⁻³×8×10⁻¹²))=1/(2π√(1.6×10⁻¹⁴))≈1.26×10⁶ Hz."},{"ch":"g6c4","q":"لماذا يُفضَّل عملياً تأريض الهوائي (ℓ=λ/4) على تركه غير مؤرَّض (ℓ=λ/2)؟","opts":["لا فرق عملي إطلاقاً بين الحالتين","لأن الهوائي المؤرَّض لا يعمل إطلاقاً بدون بطارية إضافية","لأنه يُضاعف تردد الموجة المستقبَلة تلقائياً","لأن طوله يصير أقصر بمقدار النصف لنفس التردد، إذ تُكمِّل الأرض النصف الناقص كهربائياً"],"a":3,"why":"تأريض الهوائي (وصل طرفه بالأرض) يجعل الأرض تُكمِّل كهربائياً نصف الطول الناقص، فيكفي ربع طول الموجة فقط (ℓ=λ/4) بدل نصفها — هوائي أقصر وأنسب عملياً."},{"ch":"g6c4","q":"كيف يعمل الهوائي المستقيم (ثنائي القطب) على كشف الموجة الواردة؟","opts":["المجال الكهربائي E للموجة يكون موازياً لطول السلك، فيدفع الإلكترونات الحرة للتذبذب بتردد الموجة، فيتولّد فرق جهد متردد","يعتمد فقط على المجال المغناطيسي المخترق لمساحته","يسخن السلك بحرارة الموجة فيتمدد وينقبض متردداً","لا علاقة له بأي من مجالَي الموجة إطلاقاً"],"a":0,"why":"بالهوائي المستقيم، المجال الكهربائي E يوازي طول السلك فيدفع إلكتروناته الحرة للتذبذب بتردد الموجة نفسه، منتجاً فرق جهد متردد."},{"ch":"g6c4","q":"كيف يكتشف الهوائي الحلقي المعلومة المحمولة على موجة كهرومغناطيسية واردة؟","opts":["بجذب الشحنات الساكنة بالهواء المحيط فقط","بقانون فاراداي: المجال المغناطيسي المتغيّر للموجة يخترق مساحة الحلقة فيُحتث فيها تيار متردد","لا علاقة له بأي قانون فيزيائي معروف","بتسخين الحلقة مباشرة بالموجة الواردة"],"a":1,"why":"المجال المغناطيسي المتغيّر B للموجة يخترق مساحة الحلقة، فبقانون فاراداي (ε=−NΔΦ/Δt) يُحتث تيار متردد يحمل المعلومة."},{"ch":"g6c4","q":"ما الفرق الجوهري بين طريقتَي الكشف بالمجال الكهربائي والمجال المغناطيسي؟","opts":["الأولى تحتاج مصدر طاقة خارجي، والثانية لا تحتاجه إطلاقاً","لا فرق حقيقي بينهما، فكلتاهما تعتمدان على المجال نفسه","الأولى تستغل تذبذب الإلكترونات بسلك موازٍ لـE، والثانية تستغل تيار الحث الناتج عن B المخترق لمساحة حلقة","الثانية تعمل فقط بالنهار والأولى فقط بالليل"],"a":2,"why":"الكشف بالمجال الكهربائي يستغل قوة E الدافعة للإلكترونات بسلك موازٍ له؛ أما الكشف بالمجال المغناطيسي فيستغل الحث الكهرومغناطيسي (فاراداي) الناتج عن تغيّر الفيض المغناطيسي المخترق لحلقة."},{"ch":"g6c4","q":"لماذا يُفضَّل الهوائي المستقيم أن يكون موازياً لاتجاه المجال الكهربائي E للموجة القادمة تحديداً؟","opts":["لأن ذلك يمنع أي تشويش خارجي كلياً بكل الحالات","لأن ذلك يزيد سرعة الموجة نفسها أثناء انتشارها بالفضاء","لا علاقة لاتجاه السلك بكفاءة الاستقبال إطلاقاً","لأن القوة الدافعة للإلكترونات بطول السلك تكون أعظمية عندما يوازي السلك اتجاه E نفسه"],"a":3,"why":"القوة المؤثرة على إلكترونات السلك تعتمد على مركبة E الموازية له؛ فإذا كان السلك موازياً لـE تماماً، تكون هذه القوة (وبالتالي الإشارة المتولّدة) أعظمية."},{"ch":"g6c4","q":"لماذا لا نُرسل إشارة الصوت مباشرة كما هي عبر الهواء بدل تضمينها على موجة حاملة؟","opts":["لأن ترددها منخفض جداً، فتحتاج هوائياً طويلاً جداً (كيلومترات) وتنتشر بضعف شديد","لأن الصوت لا يمكن تحويله لإشارة كهربائية إطلاقاً","لأن الأذن البشرية لا تسمع الترددات العالية فقط","لا يوجد سبب فيزيائي حقيقي لذلك"],"a":0,"why":"تردد الصوت منخفض جداً (مئات الهرتز)، فيحتاج هوائياً بطول غير عملي (كيلومترات) وينتشر بكفاءة ضعيفة جداً — لذا نُحمِّله على موجة حاملة عالية التردد."},{"ch":"g6c4","q":"ما الذي يتغيّر بالتضمين السعوي AM، وماذا يبقى ثابتاً؟","opts":["يتغيّر تردد الموجة الحاملة، وتبقى سعتها ثابتة","تتغيّر سعة الموجة الحاملة وفق إشارة المعلومة، ويبقى ترددها ثابتاً","يتغيّران معاً بنفس الوقت دائماً","لا يتغيّر أي منهما، بل يتغيّر الطور فقط"],"a":1,"why":"AM = Amplitude Modulation: نغيّر سعة (مقدار) الموجة الحاملة كدالة خطية وفق تردد إشارة المعلومة، مع ثبوت تردّدها."},{"ch":"g6c4","q":"ما الذي يتغيّر بالتضمين الترددي FM؟","opts":["طور الموجة الحاملة فقط","سعة الموجة الحاملة فقط، مع ثبوت ترددها","تردد الموجة الحاملة يتغيّر وفق سعة إشارة المعلومة، مع ثبوت سعة الحاملة","لا شيء يتغيّر إطلاقاً بـFM"],"a":2,"why":"FM = Frequency Modulation: نغيّر تردد الموجة الحاملة وفق سعة إشارة المعلومة، مع ثبوت سعتها."},{"ch":"g6c4","q":"لماذا يكون صوت راديو FM عادة أنقى وأقل تشويشاً من AM (خصوصاً أثناء العواصف الرعدية)؟","opts":["لا فرق حقيقي بين نقاوة الاثنين إطلاقاً","لأن محطات FM أقوى إرسالاً من AM دائماً بلا استثناء","لأن الأذن البشرية تفضّل الترددات المستعملة بـFM فقط","لأن المعلومة بـFM محمولة بالتردد، والتشويش الجوي (كالبرق) يغيّر السعة أساساً لا التردد"],"a":3,"why":"تشويش كالبرق يؤثر أساساً بسعة الموجة الملتقطة؛ بما أن معلومة AM محمولة بالسعة فتتأثر بوضوح، بينما معلومة FM محمولة بالتردد فلا يكاد التشويش يؤثر بها."},{"ch":"g6c4","q":"ما التضمين الطوري PM؟","opts":["تغيير طور الموجة الحاملة وفق سعة إشارة المعلومة","تغيير سعة الموجة الحاملة فقط","تغيير تردد الموجة الحاملة فقط","إلغاء الموجة الحاملة كلياً واستبدالها بالإشارة مباشرة"],"a":0,"why":"PM = Phase Modulation: نغيّر طور الموجة الحاملة وفق سعة إشارة المعلومة."},{"ch":"g6c4","q":"ما ميزة التضمين الرقمي (Digital) مقارنة بالتضمين التماثلي (Analog)؟","opts":["لا يحتاج أي موجة حاملة إطلاقاً","يحوّل المعلومة إلى نبضات، فيقلّل تأثير التشويش الخارجي ويرفع دقّة الإرسال والتسلم","أبطأ دائماً من التضمين التماثلي","يعمل فقط مع الصوت لا الصورة أو البيانات"],"a":1,"why":"التضمين الرقمي يحوّل المعلومة لنبضات منفصلة، وهذا يقلّل تأثير التشويش الخارجي مقارنة بالإشارة التماثلية المستمرة، فترتفع دقّة الإرسال والتسلم."},{"ch":"g6c4","q":"أي منطقة ترددية (رمزها) تُستعمل للبث الإذاعي المتوسط AM؟","opts":["VHF (عالية جداً)","VLF (منخفضة جداً)","MF (متوسطة، 300kHz–3MHz)","HF فقط دون غيرها"],"a":2,"why":"منطقة MF (300kHz–3MHz) هي المخصصة للبث الإذاعي المتوسط (AM) حسب الجدول."},{"ch":"g6c4","q":"أي منطقة ترددية تُستعمل بشكل أساسي للملاحة البحرية؟","opts":["MF (متوسطة)","VHF (عالية جداً)","HF (عالية)","VLF (منخفضة جداً، 3–30 kHz)"],"a":3,"why":"منطقة VLF (3–30 kHz) هي الأدنى تردداً وتُستعمل أساساً بالملاحة البحرية."},{"ch":"g6c4","q":"أي منطقة ترددية تُستعمل للتلفاز والإرسال FM وأنظمة الشرطة؟","opts":["VHF (عالية جداً، 30–300 MHz)","VLF (منخفضة جداً)","MF (متوسطة)","LF (منخفضة)"],"a":0,"why":"منطقة VHF (30–300 MHz) هي الأعلى تردداً بين المناطق الخمس، وتُستعمل للتلفاز وإرسال FM وأنظمة الشرطة."},{"ch":"g6c4","q":"موجة ترددها 15 MHz. إلى أي منطقة ترددية تنتمي؟","opts":["VLF (منخفضة جداً)","HF (عالية، 3–30 MHz)","MF (متوسطة)","VHF (عالية جداً)"],"a":1,"why":"15 MHz تقع ضمن مدى 3–30 MHz، أي منطقة HF."},{"ch":"g6c4","q":"رتّب المناطق الترددية الخمس من الأوطأ تردداً إلى الأعلى.","opts":["MF ← VLF ← HF ← LF ← VHF","VHF ← HF ← MF ← LF ← VLF","VLF ← LF ← MF ← HF ← VHF","LF ← VLF ← VHF ← HF ← MF"],"a":2,"why":"الترتيب الصحيح تصاعدياً بالتردد: VLF (3–30kHz) ← LF (30–300kHz) ← MF (300kHz–3MHz) ← HF (3–30MHz) ← VHF (30–300MHz)."},{"ch":"g6c4","q":"علامَ تعتمد سرعة انتشار الموجة الكهرومغناطيسية بوسط مادي معيّن؟","opts":["السرعة ثابتة دائماً وواحدة بكل الأوساط","على لون الوسط المادي فقط","على درجة حرارة الوسط فقط بصرف النظر عن خواصه الكهرومغناطيسية","على السماحية الكهربائية ε والنفاذية المغناطيسية μ للوسط (v=1/√(εμ))"],"a":3,"why":"v=1/√(εμ) — كلما كبرت εμ للوسط قلّت سرعة الموجة فيه، وتبلغ أعظمها (c) بالفراغ حيث ε₀ وμ₀ أصغر ما يمكن."},{"ch":"g6c4","q":"لماذا يتّسع مدى استقبال الموجات السماوية ليلاً مقارنة بالنهار؟","opts":["لأن الطبقة الواطئة الماصّة (D) من الأيونوسفير تختفي ليلاً، فتنعكس الموجات عن الطبقة العليا (F) وتصل مسافات أبعد","لأن الشمس تقوّي إشارة الموجات ليلاً فقط","لأن كل محطات الراديو تزيد قدرة إرسالها ليلاً فقط","لا فرق حقيقي بين الليل والنهار بمدى الاستقبال"],"a":0,"why":"نهاراً تمتصّ طبقة D الواطئة جزءاً من الموجات السماوية فيقلّ مداها؛ ليلاً تختفي هذه الطبقة فتنعكس الموجات عن طبقة F الأعلى وترتدّ لمسافات أبعد بكثير."},{"ch":"g6c4","q":"ما الذي يميّز الموجات الفضائية عن الأرضية والسماوية؟","opts":["لا تحتاج أي هوائي إرسال إطلاقاً","ترددها أكبر من 30MHz، تنتشر بخطوط مستقيمة وتخترق الأيونوسفير فتحتاج أقماراً صناعية لنقلها لمسافات بعيدة","تنحني مع سطح الأرض تماماً كالموجة الأرضية","تنعكس عن الأيونوسفير تماماً كالموجة السماوية"],"a":1,"why":"الموجات الفضائية (VHF فأعلى) تخترق الأيونوسفير بدل الانعكاس عنه، وتنتشر بخط مستقيم (بصري)، فتحتاج أقماراً صناعية كمعيدات للاتصال بين القارّات."},{"ch":"g6c4","q":"لماذا يكون مدى الموجة الأرضية محدوداً نسبياً؟","opts":["لأن ترددها عالٍ جداً فتنعكس عن الأيونوسفير بدل السطح","لأنها تُمتص بالكامل فور خروجها من الهوائي مباشرة","لأنها تنتقل قريباً من سطح الأرض وتنحني مع انحنائه، فيحجبها انحناء الأرض بعد مسافة معيّنة","لا سبب فيزيائي محدد لذلك"],"a":2,"why":"الموجة الأرضية تتبع انحناء سطح الأرض، لكن هذا الانحناء نفسه يحجبها تدريجياً بعد مسافة معيّنة، فمداها العملي محدود."},{"ch":"g6c4","q":"موجة راديو ترددها 15 MHz. إلى أي منطقة تنتمي وبأي طريقة تنتشر أغلب الظن؟","opts":["منطقة MF، وتنتشر بالبث الإذاعي المتوسط فقط","منطقة VLF، وتنتشر كموجة أرضية فقط","منطقة VHF، وتنتشر كموجة فضائية تحتاج قمراً صناعياً","منطقة HF، وتنتشر كموجة سماوية تنعكس عن الأيونوسفير"],"a":3,"why":"15 MHz تقع ضمن 3–30 MHz، أي منطقة HF، وهذا المدى بالضبط هو مدى الموجات السماوية المنعكسة عن الأيونوسفير."},{"ch":"g6c4","q":"أي مما يلي يمثّل ترتيباً صحيحاً للطيف الكهرومغناطيسي من أطول طول موجي إلى أقصره؟","opts":["راديو ← مايكروويف ← مرئي ← فوق بنفسجية ← سينية","سينية ← فوق بنفسجية ← مرئي ← مايكروويف ← راديو","مرئي ← راديو ← سينية ← مايكروويف ← فوق بنفسجية","لا يوجد ترتيب ثابت للطيف الكهرومغناطيسي"],"a":0,"why":"الطيف الكهرومغناطيسي مرتّب من أطول طول موجي (وأخفض تردد) إلى أقصره: راديو، مايكروويف، تحت الحمراء، مرئي، فوق بنفسجية، سينية/غاما."},{"ch":"g6c4","q":"كم عدد الحقائق التي بنى عليها ماكسويل نظريته الكهرومغناطيسية؟","opts":["اثنتان","أربع","ست","ثمانٍ"],"a":1,"why":"بنى ماكسويل نظريته على أربع حقائق تربط المجالين الكهربائي والمغناطيسي."},{"ch":"g6c4","q":"وفق حقيقتَي ماكسويل الثالثة والرابعة، ما العلاقة الطورية بين المجال المتغيّر (سبب) والمجال الناتج عنه؟","opts":["يتعاكسان تماماً بالطور (فرق طور 180°)","يتعامدان بالطور (فرق طور 90°)","يتّفقان بالطور (يبلغان الذروة ويصفران معاً)","لا علاقة طورية ثابتة بينهما"],"a":2,"why":"تنصّ حقيقتا ماكسويل الثالثة والرابعة على أن المجال الناتج يكون متّفقاً بالطور مع المجال المتغيّر المسبِّب له."},{"ch":"g6c4","q":"تيار الإزاحة I_d الذي قدّمه ماكسويل يتناسب طردياً مع:","opts":["المسافة بين لوحَي المتسعة فقط","مقدار المقاومة الكهربائية بالدائرة","درجة حرارة الوسط المحيط","معدّل تغيّر المجال الكهربائي مع الزمن (ΔE/Δt)"],"a":3,"why":"I_d ∝ ΔE/Δt — تيار الإزاحة يتناسب مع معدّل التغيّر الزمني للمجال الكهربائي، لا مع مقداره المطلق."},{"ch":"g6c4","q":"أي مما يلي ليس من خصائص الموجة الكهرومغناطيسية الخمس؟","opts":["تحتاج وسطاً مادياً لتنتقل خلاله","تنتشر بالفراغ بخطوط مستقيمة، وتنعكس وتنكسر وتتداخل وتحيد وتستقطب","هي موجة مستعرضة","تحمل طاقة موزّعة بالتساوي بين مجاليها"],"a":0,"why":"على العكس تماماً — من أهم خصائصها أنها لا تحتاج وسطاً مادياً إطلاقاً، وتنتقل بالفراغ التام بسرعة الضوء."},{"ch":"g6c4","q":"لماذا تُوصف الموجة الكهرومغناطيسية بأنها مستعرضة لا طولية؟","opts":["لأن سرعتها متغيّرة باستمرار أثناء الانتشار","لأن مجالَيها E وB يتذبذبان عموديين على اتجاه انتشار الموجة","لأنها أعرض فيزيائياً من الموجة الصوتية","لأنها تحمل طاقة أكبر من الموجة الطولية دائماً"],"a":1,"why":"الموجة المستعرضة تتذبذب عمودياً على اتجاه انتشارها، وهذا حال E وB بالضبط بالموجة الكهرومغناطيسية."},{"ch":"g6c4","q":"أي شحنة تُشِعّ موجة كهرومغناطيسية؟","opts":["الشحنة المتحركة بسرعة ثابتة فقط","أي شحنة ساكنة بصرف النظر عن مقدارها","الشحنة المعجَّلة (المتذبذبة) فقط","لا تُشِعّ أي شحنة موجة كهرومغناطيسية مهما كانت حركتها"],"a":2,"why":"الشحنة المعجَّلة (المتذبذبة) وحدها تولّد مجالين متغيّرين مع الزمن يولّد كل منهما الآخر، فتنطلق موجة."},{"ch":"g6c4","q":"بأي جهاز عملي نولّد الموجات الكهرومغناطيسية من شحنات معجَّلة؟","opts":["متسعة مشحونة بشكل دائم دون أي دائرة أخرى","بطارية جافة عادية موصولة بسلك مستقيم فقط","مقاومة كهربائية ثابتة القيمة","مولّد ذبذبات موصول بساقين معدنيتين (ثنائي قطب كهربائي)"],"a":3,"why":"مولّد الذبذبات الموصول بثنائي قطب كهربائي (ساقين معدنيتين) يجعل الشحنات تتذبذب صعوداً ونزولاً بتردده، فتُشِعّ موجات."},{"ch":"g6c4","q":"بأي قانون يُحسب التردد الرنيني لدائرة اهتزاز (L وC) بجهاز الإرسال أو الاستقبال؟","opts":["f_r = 1/(2π√(LC))","f_r = 2π√(LC)","f_r = 1/(2πLC)","f_r = √(L/C)"],"a":0,"why":"نفس علاقة الرنين المتوالي من فصل التيار المتناوب: f_r=1/(2π√(LC))."},{"ch":"g6c4","q":"دائرة موالفة محاثتها L=4μH وسعتها C=9pF. جد تردّدها الرنيني تقريباً.","opts":["≈13.3 MHz","≈26.5 MHz","≈53 MHz","≈2.65 MHz"],"a":1,"why":"LC=4×10⁻⁶×9×10⁻¹²=3.6×10⁻¹⁷، و√(LC)=6×10⁻⁹ s. f_r=1/(2π×6×10⁻⁹)≈2.65×10⁷ Hz=26.5 MHz."},{"ch":"g6c4","q":"إذا ضُوعفت سعة C لدائرة الاهتزاز (وبقيت L ثابتة)، ماذا يحدث للتردد الرنيني f_r؟","opts":["يبقى ثابتاً دون تغيّر","يتضاعف تماماً","يقلّ بمعامل 1/√2","يقلّ للربع"],"a":2,"why":"f_r=1/(2π√(LC))، فمضاعفة C تضاعف الجذر √(LC) بمعامل √2، فيقلّ f_r بمعامل 1/√2 ≈ 0.707 من قيمته الأصلية."},{"ch":"g6c4","q":"محطة إذاعية تبثّ بتردد 150 MHz. ما طول موجتها؟","opts":["0.5 m","4.5 m","1 m","2 m"],"a":3,"why":"λ=c/f=(3×10⁸)/(150×10⁶)=2 m."},{"ch":"g6c4","q":"ما أفضل طول لهوائي غير مؤرَّض يبثّ إشارة طول موجتها 4 m؟","opts":["2 m","4 m","1 m","8 m"],"a":0,"why":"ℓ=λ/2=4/2=2 m."},{"ch":"g6c4","q":"لماذا يُفضَّل تأريض الهوائي عملياً (وصل طرفه بالأرض)؟","opts":["لأن التأريض يزيد قدرة الإرسال عشرة أضعاف","لأن الأرض تُكمِّل كهربائياً نصف الطول الناقص، فيكفي هوائي بطول ربع الموجة فقط بدل نصفها (أقصر وأعملي)","لأن الهوائي المؤرَّض لا يحتاج دائرة اهتزاز إطلاقاً","لا فائدة حقيقية للتأريض، وهو إجراء تجميلي فقط"],"a":1,"why":"الهوائي المؤرَّض يكفيه طول ربع الموجة ℓ=λ/4 (الأرض تُكمِّل النصف الآخر كهربائياً)، فيكون أقصر وأنسب عملياً من الهوائي غير المؤرَّض (ℓ=λ/2)."},{"ch":"g6c4","q":"ما مكوّنا دائرة الإرسال الأساسيان؟","opts":["مضخّم صوت ومكبّر فقط","بطارية ومقاومة ثابتة فقط دون أي شيء آخر","دائرة اهتزاز كهرومغناطيسي (ملف ومتسعة متغيرة) تولّد الموجة، وهوائي يشعّها للفضاء","مصباح كهربائي وسلك توصيل بسيط"],"a":2,"why":"دائرة الإرسال: دائرة اهتزاز (L وC متغيرة) تولّد الموجة بالتردد المطلوب، وهوائي يشعّها للفضاء."},{"ch":"g6c4","q":"كيف يكتشف الهوائي المستقيم (ثنائي القطب) المعلومة من موجة واردة؟","opts":["لا علاقة للمجال الكهربائي بعمل الهوائي المستقيم إطلاقاً","بجذب الموجة مغناطيسياً نحو مركز الهوائي فقط","بتسخين السلك مباشرة حتى ينصهر جزئياً","المجال الكهربائي E للموجة (الموازي لطول الهوائي) يدفع إلكترونات المعدن للتذبذب بتردد الموجة، فيتولّد فرق جهد متردد"],"a":3,"why":"المجال الكهربائي الموازي لطول الهوائي المستقيم يدفع الإلكترونات الحرة للتذبذب بتردد الموجة، فيتولّد فرق جهد متردد يحمل المعلومة."},{"ch":"g6c4","q":"ما المقصود بالتضمين بشكل عام؟","opts":["تحميل إشارة المعلومة (منخفضة التردد) على موجة حاملة عالية التردد","تحويل الموجة الحاملة إلى موجة صوتية مباشرة","حذف الموجة الحاملة كلياً واستبدالها بالمعلومة الخام","تضخيم شدّة الموجة الحاملة فقط دون أي تغيير آخر"],"a":0,"why":"التضمين هو تحميل إشارة المعلومة ذات التردد الواطئ على الموجة الحاملة ذات التردد العالي لتُبثّ بكفاءة."},{"ch":"g6c4","q":"في التضمين السعوي AM، ماذا يبقى ثابتاً؟","opts":["سعة الموجة الحاملة","تردد الموجة الحاملة","كلاهما يتغيّر معاً","لا شيء يبقى ثابتاً بـAM"],"a":1,"why":"بـAM تتغيّر السعة وفق إشارة المعلومة، بينما يبقى تردد الموجة الحاملة ثابتاً بلا تغيير."},{"ch":"g6c4","q":"في التضمين الترددي FM، ماذا يبقى ثابتاً؟","opts":["كلاهما يتغيّر معاً","تردد الموجة الحاملة","سعة الموجة الحاملة","لا شيء يبقى ثابتاً بـFM"],"a":2,"why":"بـFM يتغيّر التردد وفق سعة إشارة المعلومة، بينما تبقى سعة الموجة الحاملة ثابتة."},{"ch":"g6c4","q":"ما الذي يتغيّر بالتضمين الطوري PM؟","opts":["لا يتغيّر أي شيء بـPM، وهذا سبب تسميته","تردد الموجة الحاملة فقط","سعة الموجة الحاملة فقط","طور الموجة الحاملة، وفق سعة إشارة المعلومة"],"a":3,"why":"PM = Phase Modulation: يتغيّر طور الموجة الحاملة وفق سعة إشارة المعلومة."},{"ch":"g6c4","q":"لماذا يكون بث الراديو FM عادة أقل تأثراً بالتشويش الجوي (كالبرق) من AM؟","opts":["لأن معلومة FM محمولة بالتردد لا بالسعة، والتشويش الجوي يغيّر السعة أساساً","لأن محطات FM دائماً أقوى إرسالاً بلا استثناء","لأن أجهزة استقبال FM أغلى ثمناً فقط","لا فرق حقيقي في مقاومة التشويش بين النوعين"],"a":0,"why":"التشويش كالبرق يؤثر أساساً بسعة الإشارة الملتقطة. بما أن معلومة FM محمولة بالتردد لا بالسعة، فلا يكاد التشويش يؤثر بها، بعكس AM."},{"ch":"g6c4","q":"ما ميزة التضمين الرقمي على التماثلي؟","opts":["لا يحتاج أي موجة حاملة على الإطلاق","يحوّل المعلومة إلى نبضات فيقلّل تأثير التشويش الخارجي ويرفع دقّة الإرسال والتسلم","يعمل فقط بترددات منخفضة جداً دون العالية","أبطأ بشكل ثابت من التضمين التماثلي بكل الحالات"],"a":1,"why":"التضمين الرقمي يحوّل المعلومة لنبضات منفصلة، فيقلّل تأثير التشويش الخارجي مقارنة بالإشارة التماثلية المستمرة."},{"ch":"g6c4","q":"أي منطقة ترددية (رمزها) تُستعمل بالبث الإذاعي المتوسط AM؟","opts":["VHF (30–300MHz)","VLF (3–30kHz)","MF (300kHz–3MHz)","HF فقط (3–30MHz)"],"a":2,"why":"منطقة MF (300kHz–3MHz) هي المخصصة للبث الإذاعي المتوسط AM."},{"ch":"g6c4","q":"أي منطقة ترددية تُستعمل بإرسال FM والتلفاز وأنظمة الشرطة؟","opts":["LF (30–300kHz)","VLF (3–30kHz)","MF (300kHz–3MHz)","VHF (30–300MHz)"],"a":3,"why":"منطقة VHF (30–300MHz) هي المخصصة للتلفاز وإرسال FM وأنظمة الشرطة."},{"ch":"g6c4","q":"علامَ يعتمد مقدار سرعة انتشار الموجة الكهرومغناطيسية بوسط مادي؟","opts":["على السماحية الكهربائية ε والنفاذية المغناطيسية μ للوسط (v=1/√(εμ))","على كثافة الوسط فقط بصرف النظر عن خواصه الكهربائية والمغناطيسية","على درجة حرارة الوسط فقط","السرعة ثابتة بكل الأوساط ولا تعتمد على شيء"],"a":0,"why":"v=1/√(εμ). كلما كبرت εμ للوسط قلّت سرعة الموجة فيه، وتبلغ أعظمها c بالفراغ."},{"ch":"g6c4","q":"ما قيمة سرعة الضوء بالفراغ التي ينتج عنها التعويض c=1/√(μ₀ε₀)؟","opts":["3×10⁶ m/s","3×10⁸ m/s","3×10¹⁰ m/s","3×10⁵ m/s"],"a":1,"why":"بالتعويض بثوابت الفراغ ε₀ وμ₀ بالعلاقة c=1/√(μ₀ε₀) ينتج c=3×10⁸ m/s بالضبط."},{"ch":"g6c4","q":"ما الذي يميّز الموجة الأرضية عن غيرها من طرائق الانتشار؟","opts":["تخترق الأيونوسفير وتحتاج قمراً صناعياً","تنعكس عن الأيونوسفير لتصل مسافات بعيدة جداً","تنتقل قريباً من سطح الأرض وتنحني مع انحنائه، فمداها محدود نسبياً","لا تحتاج هوائياً إطلاقاً لإرسالها"],"a":2,"why":"الموجة الأرضية (530kHz–2MHz) تتبع انحناء سطح الأرض، لكن هذا الانحناء نفسه يحدّ من مداها بعد مسافة معيّنة."},{"ch":"g6c4","q":"ما الذي يميّز الموجة السماوية؟","opts":["أقصر مدى من الموجة الأرضية دائماً","تنتشر بخط مستقيم فقط دون أي انعكاس","لا تتأثر إطلاقاً بالفرق بين الليل والنهار","تنعكس عن طبقات الأيونوسفير فتصل مسافات بعيدة، وترددها 3–30MHz"],"a":3,"why":"الموجة السماوية (3–30MHz) تنعكس عن طبقات الأيونوسفير، فتصل مسافات بعيدة جداً، ويتّسع مداها ليلاً بغياب الطبقة الماصّة D."},{"ch":"g6c4","q":"ما الذي يميّز الموجة الفضائية، ولماذا تحتاج أقماراً صناعية؟","opts":["ترددها أكبر من 30MHz، تنتشر بخط مستقيم وتخترق الأيونوسفير بدل الانعكاس عنه، فتحتاج أقماراً كمعيدات للاتصال بمسافات بعيدة","لأنها لا تنتشر أصلاً إلا داخل الأقمار الصناعية نفسها","لأن ترددها أقل من الموجة الأرضية بكثير","لأنها الوحيدة التي تحتاج هوائي إرسال من بين الطرائق الثلاث"],"a":0,"why":"الموجة الفضائية (>30MHz) تخترق الأيونوسفير بدل الانعكاس عنه وتنتشر بخط بصري مستقيم، فتحتاج أقماراً صناعية تُعيد بثّها لمسافات بعيدة (بين القارّات مثلاً)."},{"ch":"g6c4","q":"لماذا يتّسع مدى استقبال محطات AM البعيدة ليلاً مقارنة بالنهار؟","opts":["لأن قدرة الإرسال تتضاعف تلقائياً ليلاً بكل المحطات","لأن الطبقة الواطئة الماصّة (D) بالأيونوسفير تختفي ليلاً، فتنعكس الموجات عن الطبقة العليا (F) وتصل مسافات أبعد","لأن الهواء يصبح أكثر برودة فتزيد سرعة الموجة فقط","لا علاقة فيزيائية حقيقية بين الوقت من اليوم ومدى الاستقبال"],"a":1,"why":"نهاراً تمتصّ طبقة D الموجات السماوية فيقلّ مداها؛ ليلاً تختفي هذه الطبقة فتنعكس الموجات عن طبقة F الأعلى وترتدّ لمسافات أبعد بكثير — أحياناً عبر قارّات."},{"ch":"g6c4","q":"ماذا يعني اختصار RADAR؟","opts":["Radio Antenna Direction And Reception","Rapid Automatic Data Analysis Radio","Radio Detection And Ranging — الكشف وتحديد البُعد بوساطة الموجات الراديوية","لا يحمل الاختصار معنى فيزيائياً محدداً"],"a":2,"why":"RADAR اختصار Radio Detection And Ranging: الكشف وتحديد البُعد بوساطة الموجات الراديوية."},{"ch":"g6c4","q":"رادار أرسل نبضة استغرقت 600 μs لترتدّ عن هدف وتعود. جد بُعد الهدف (c=3×10⁸ m/s).","opts":["360 km","180 km","45 km","90 km"],"a":3,"why":"d = c×t/2 = (3×10⁸ × 600×10⁻⁶)/2 = 180000/2 = 90000 m = 90 km."},{"ch":"g6c4","q":"هدفٌ يبعد 45 km عن رادار. كم يستغرق الزمن الكلي (ذهاباً وإياباً) لنبضة الرادار لترتدّ عنه وتعود؟","opts":["300 μs","150 μs","600 μs","45 μs"],"a":0,"why":"t = 2d/c = (2×45000)/(3×10⁸) = 90000/(3×10⁸) = 3×10⁻⁴ s = 300 μs."},{"ch":"g6c4","q":"ما الفرق الجوهري بين الصور النشطة وغير النشطة بالاستشعار عن بُعد؟","opts":["لا فرق حقيقي بين النوعين إطلاقاً","النشطة: القمر مصدر الإشعاع نفسه (يرسل الموجة ويحلّل ارتدادها)؛ غير النشطة: تعتمد على إشعاع صادر أو منعكس من الهدف نفسه فقط","النشطة تعمل بالليل فقط، وغير النشطة بالنهار فقط حصراً","غير النشطة تحتاج طاقة أكبر من النشطة دائماً"],"a":1,"why":"بالصور النشطة يُصدر القمر موجته الخاصة ويحلّل ارتدادها (كالرادار)؛ بغير النشطة يعتمد على إشعاع الهدف نفسه (كضوء الشمس المنعكس) دون أن يُصدر القمر شيئاً."},{"ch":"g6c4","q":"أي المجالات التالية تستفيد من الاستشعار عن بُعد؟","opts":["الطب النفسي حصراً","صناعة النسيج المحلية فقط دون غيرها","المساحة، الجيولوجيا، الزراعة، الأرصاد الجوية، والتطبيقات العسكرية","لا يوجد له أي تطبيق عملي فعلي حتى الآن"],"a":2,"why":"يُستعمل الاستشعار عن بُعد بالمساحة والجيولوجيا والزراعة (رصد صحة المحاصيل) والأرصاد الجوية والتطبيقات العسكرية."},{"ch":"g6c4","q":"لماذا يكفي قياس زمن قصير جداً (بالميكروثانية) ليحسب الرادار مسافات كبيرة (بالكيلومترات)؟","opts":["لا علاقة لسرعة الضوء بدقة قياس الرادار للمسافة","لأن الرادار يستعمل ساعة ذرية فائقة الدقة تلغي أي خطأ","لأن المسافات الفعلية المقاسة صغيرة جداً بالحقيقة","لأن سرعة الضوء c هائلة (3×10⁸ m/s)، فمسافات كبيرة جداً تقابلها أزمنة قصيرة جداً فقط"],"a":3,"why":"بما أن d=ct/2 وc كبيرة جداً (3×10⁸ m/s)، فحتى أزمنة قصيرة جداً (ميكروثانية) تقابل مسافات كبيرة بالكيلومترات — هذا سرّ دقة الرادار العملية."},{"ch":"g6c5","q":"متى يجب التعامل مع الضوء كموجة (بصريات فيزيائية) بدل أشعة مستقيمة (بصريات هندسية)؟","opts":["عندما تكون أبعاد الفتحة/العائق كبيرة جداً مقارنة بـλ","عندما تكون أبعاد الفتحة/العائق مقارنة أو أصغر من الطول الموجي λ","دائماً بلا أي شرط","فقط عند استعمال الليزر حصراً"],"a":1,"why":"كلما اقتربت أبعاد الفتحات/العوائق من الطول الموجي أو صغرت عنه، ظهرت ظواهر موجية (تداخل وحيود) لا تفسّرها الأشعة المستقيمة."},{"ch":"g6c5","q":"أي ظاهرة من ظواهر هذا الفصل تثبت أن الضوء موجة مستعرضة تحديداً، لا طولية؟","opts":["الاستقطاب","التداخل","الحيود","الاستطارة"],"a":0,"why":"الاستقطاب ممكن فقط للموجات المستعرضة (يمكن حجب اتجاه اهتزاز واحد وإنفاذ آخر) — الموجات الطولية لا يمكن استقطابها إطلاقاً."},{"ch":"g6c5","q":"أي ظاهرتين تعتمدان أساساً على تراكب (جمع) موجتين ضوئيتين متشاكهتين؟","opts":["الاستقطاب والاستطارة","التداخل والحيود","الحيود والاستطارة فقط","الاستقطاب فقط"],"a":1,"why":"التداخل (يونك، الأغشية الرقيقة) والحيود (الشق المفرد، المحزز) كلاهما نتيجة تراكب موجات ضوئية وفق مبدأ التراكب."},{"ch":"g6c5","q":"ما المقصود بتداخل الضوء؟","opts":["امتصاص الضوء كلياً عند سطح عاكس","إعادة توزيع الطاقة الضوئية من تراكب موجات متشاكهة","انحراف الضوء عن مساره المستقيم عند حافة حاجز","تحلّل الضوء الأبيض إلى ألوانه عبر منشور"],"a":1,"why":"تداخل الضوء: إعادة توزيع الطاقة الضوئية الناشئة عن تراكب موجات ضوئية متشاكهة. (تمهيدي 2019 · تمهيدي 2021)"},{"ch":"g6c5","q":"في تجربة تداخل، فرق المسار البصري بين موجتين متشاكهتين متراكبتين يساوي أعداداً فردية من أنصاف الأطوال الموجية — أي نوع تداخل يحصل؟","opts":["تداخل بناء","استطارة","تداخل إتلاف","استقطاب"],"a":2,"why":"Δℓ = (m+½)λ هو شرط التداخل الإتلافي بالضبط. (اختيار وزاري: 2020د1 · 2021ت)"},{"ch":"g6c5","q":"لحصول التداخل المستديم في موجات الضوء يجب أن يكون مصدراهما:","opts":["غير متشاكهين","مصدرين ليزريين حصراً","على بعد كيلومتر واحد بالضبط","متشاكهين"],"a":3,"why":"التشاكه شرط أساسي: تساوي التردد، وتساوي أو تقارب السعة، وثبوت فرق الطور. (اختيار وزاري: 2023ت)"},{"ch":"g6c5","q":"مصدران ضوئيان غير متشاكهين يُسقطان ضوءهما على شاشة. لماذا لا يظهر نمط تداخل مستقر؟","opts":["فرق الطور بينهما يتغيّر عشوائياً بسرعة فائقة فلا يثبت","لأن شدة الضوء منهما صفر","لأن الشاشة تمتصّ كل الضوء","لأن أطوالهما الموجية متساوية دوماً"],"a":0,"why":"المصدران غير المتشاكهين يبعثان أطواراً عشوائية متغيّرة بسرعة، فلا يتحقق شرط ثبات فرق الطور. (تمهيدي 2017 · د1 2020 وغيرها)"},{"ch":"g6c5","q":"في تجربة شقي يونك، يحصل الهدب المضيء الأول على جانبي الهدب المركزي عندما يكون فرق المسار البصري مساوياً:","opts":["2λ","λ","3λ","½λ"],"a":1,"why":"شرط الهدب المضيء d sinθ=mλ، وللأول (م=1) فرق المسار = λ بالضبط. (اختيار وزاري: 2019د1)"},{"ch":"g6c5","q":"نمط التداخل بتجربة شقي يونك يتولّد بسبب:","opts":["الانعكاس فقط","الانكسار فقط","حيود وتداخل موجات الضوء معاً","الاستقطاب فقط"],"a":2,"why":"تحيد الموجات بالشقين الضيقين فتصير مصدرين متشاكهين، ثم تتداخل: بناءً وإتلافاً بالتعاقب فيظهر الهدب. (اختيار وزاري: 2021د1)"},{"ch":"g6c5","q":"أُجريت تجربة يونك تحت سطح الماء بدل الهواء. ماذا يحصل لفاصلة الهدب؟","opts":["تزداد وتتباعد الهدب","تقلّ وتتقارب الهدب من بعضها","تبقى ثابتة تماماً","يختفي نمط التداخل كلياً"],"a":1,"why":"الطول الموجي يقلّ داخل الماء (λ_n=λ/n)، وبما أن Δy=λL/d تتناسب طردياً مع λ، تقلّ فاصلة الهدب. (وزاري الأكثر تكراراً: 2017د1 وغيرها)"},{"ch":"g6c5","q":"عند إضاءة شقي يونك بضوء أخضر طوله الموجي 5×10⁻⁷ m، والبعد بين الشقين 1 mm، وبعد الشاشة 2 m، فإن فاصلة الهدب تساوي:","opts":["0.4 mm","0.25 mm","0.1 mm","1 mm"],"a":3,"why":"Δy = λL/d = (5×10⁻⁷×2)/(1×10⁻³) = 10⁻³ m = 1 mm. (تمهيدي 2022 — سؤال الكتاب س١/١٥)"},{"ch":"g6c5","q":"وُضعت شاشة على بُعد 4.5 m من حاجز ذي شقين وأُضيء الشقان بضوء λ=490nm، فكانت فاصلة الهدب الأول (m=1) عن المركزي 4.5 cm. ما البعد بين الشقين؟","opts":["≈0.49 mm","≈4.9 mm","≈0.049 mm","≈49 mm"],"a":2,"why":"d = λL/y₁ = (490×10⁻⁹×4.5)/(4.5×10⁻²) = 4.9×10⁻⁵ m = 0.049 mm. (مسألة الكتاب س١)"},{"ch":"g6c5","q":"لماذا يحصل انقلاب طور مقداره π rad للموجة المنعكسة عن السطح الأمامي لغشاء رقيق؟","opts":["لأنها تنعكس عن وسط أقل كثافة بصرية","لأنها تنعكس عن وسط معامل انكساره أكبر من الوسط القادمة منه","لأن الغشاء يمتصّ نصف طاقتها","لا يحصل أي انقلاب طور إطلاقاً"],"a":1,"why":"الانعكاس عن وسط أعلى معامل انكسار يسبّب دوماً انقلاب طور 180°. (د1 2018 · د1 2024 · تمهيدي 2024)"},{"ch":"g6c5","q":"للحصول على تداخل بناء (غشاء مضيء) بغشاء رقيق سمكه البصري nt، يجب أن يكون nt مساوياً:","opts":["أعداداً زوجية من λ/4","صفراً دوماً","أعداداً فردية من λ/4","λ كاملة دوماً"],"a":2,"why":"nt=1×λ/4, 3×λ/4, 5×λ/4… (أرباع فردية) يعطي تداخلاً بناءً. (تمهيدي 2018 · د1 2019 · د1 2020)"},{"ch":"g6c5","q":"ألوان فقاعات الصابون وأغشية الزيت الرقيقة تُعزى إلى ظاهرة:","opts":["الحيود","الاستقطاب","التداخل","الاستطارة"],"a":2,"why":"تداخل موجات الضوء المنعكسة عن السطحين الأمامي والخلفي للغشاء، ويختلف السمك من موضع لآخر فتظهر ألوان مختلفة. (د1 2017 · تمهيدي 2020 · د2 2019)"},{"ch":"g6c5","q":"غشاء صابون سمكه البصري nt = 3λ/4 لضوء ساقط. هل يظهر الغشاء مضيئاً أم مظلماً؟","opts":["مظلماً — تداخل إتلاف","مضيئاً — 3λ/4 عدد فردي من أرباع λ فيحصل تداخل بناء","لا يظهر أي لون","يظهر أسود دائماً بغض النظر عن السمك"],"a":1,"why":"3λ/4 = 1×(3λ/4) عدد فردي من أرباع الطول الموجي ⟸ تداخل بناء ⟸ الغشاء يظهر مضيئاً بلون الضوء الساقط."},{"ch":"g6c5","q":"الحيود هو:","opts":["انحراف الضوء عن مساره المستقيم عند حافة حاجز أو شق ضيق","تراكب موجتين ضوئيتين متشاكهتين","تقييد اهتزاز المجال الكهربائي باتجاه واحد","إعادة بث الضوء من دقائق صغيرة بكل الاتجاهات"],"a":0,"why":"الحيود: انحراف الضوء عن مساره المستقيم عند مروره بحافة حاجز أو شق ضيق."},{"ch":"g6c5","q":"في حيود الضوء من شق واحد، شرط الهُدب المعتمة هو:","opts":["ℓ sinθ = (m+½)λ","ℓ sinθ = mλ","d sinθ = mλ","ℓ sinθ = λ/2 دوماً"],"a":1,"why":"لاحظ الانعكاس عن يونك: بالشق الواحد mλ يعطي معتماً لا مضيئاً، بعكس يونك حيث mλ يعطي مضيئاً."},{"ch":"g6c5","q":"ماذا يحدث لعرض المنطقة المركزية المضيئة بنمط حيود شق واحد عندما يضيق الشق أكثر؟","opts":["يقلّ عرضها","يزداد عرضها","يبقى ثابتاً","تختفي المنطقة المركزية"],"a":1,"why":"من ℓsinθ=λ: كلما ضاق ℓ كبرت θ التي يقع عندها أول معتم، فيتوسّع النمط. (د1 2017 · تمهيدي 2019)"},{"ch":"g6c5","q":"شرط تكوّن الهدب المضيء الأول (غير المركزي) بحيود شق واحد هو أن يساوي عرض الشق:","opts":["λ/(2sinθ)","λ","3λ/(2sinθ)","λ/2"],"a":2,"why":"ℓsinθ=(m+½)λ وللأول m=1: ℓsinθ=(3/2)λ ⟹ ℓ=3λ/(2sinθ). (د2 2017 — سؤال الكتاب س١/١)"},{"ch":"g6c5","q":"ثابت المحزز d يُحسب من العلاقة:","opts":["d = N/W","d = W×N","d = λ/N","d = W/N (عرض المحزز÷عدد الحزوز)"],"a":3,"why":"ثابت المحزز = عرض المحزز الكلي مقسوماً على عدد حزوزه."},{"ch":"g6c5","q":"محزز حيود عرضه 2 cm وعدد حزوزه 8000. ما ثابت المحزز d؟","opts":["4×10³ cm","2.5×10⁴ cm","1.6×10⁴ cm","2.5×10⁻⁴ cm"],"a":3,"why":"d = W/N = 2/8000 = 2.5×10⁻⁴ cm."},{"ch":"g6c5","q":"الخاصية المميزة لطيف المتولد بوساطة محزز الحيود:","opts":["انتشار الخطوط المضيئة وضبابيتها","انعدام الخطوط المضيئة كلياً","الخطوط المضيئة واضحة المعالم (حادة ودقيقة)","انعدام الخطوط المظلمة كلياً"],"a":2,"why":"كثرة شقوق المحزز تجعل هدبه حادة ودقيقة المعالم — وهذا سرّ دقته كأداة قياس. (سؤال الكتاب س١/١١)"},{"ch":"g6c5","q":"ضوء أبيض على محزز 2000 line/cm. زاوية حيود المرتبة الأولى للأحمر (λ=640nm) إذا كان sin7.5°=0.128؟","opts":["15°","7.5°","3.75°","21.3°"],"a":1,"why":"d=1/2000=5×10⁻⁴cm. sinθ=mλ/d=(640×10⁻⁷)/(5×10⁻⁴)=0.128 ⟹ θ=7.5°. (د2 2018 — مسألة الكتاب س٢)"},{"ch":"g6c5","q":"محزز 5000 line/cm، وزاوية حيود المرتبة الثانية للأحمر 30°. جد λ.","opts":["250 nm","1000 nm","125 nm","500 nm"],"a":3,"why":"d=1/5000=2×10⁻⁴cm. λ=d sinθ/m=(2×10⁻⁴×0.5)/2=5×10⁻⁵cm=500nm. (تمهيدي 2019؛ ونظيره د1 2019 بمحزز 10000 line وزاوية مرتبة أولى 30° يعطي نفس الجواب 500nm)"},{"ch":"g6c5","q":"ليزر هيليوم-نيون تردده 6×10¹³ Hz يسقط على محزز 1000 line/cm. جد زاوية حيود المرتبة الأولى.","opts":["45°","60°","30°","15°"],"a":2,"why":"λ=c/f=3×10⁸/6×10¹³=5×10⁻⁶m. d=1cm/1000=10⁻⁵m. sinθ=λ/d=0.5 ⟹ θ=30°. (د1 2024 ومثله د3 2020)"},{"ch":"g6c5","q":"ليزر هيليوم-نيون على محزز حيود، وزاوية المرتبة الثانية المضيئة 30°. جد زاوية المرتبة الرابعة.","opts":["60°","90°","45°","لا توجد مرتبة رابعة"],"a":1,"why":"d sin30°=2λ ⟹ λ/d=0.25. للمرتبة الرابعة: sinθ₄=4×0.25=1 ⟹ θ₄=90° (تقع عند حافة النمط تماماً). (د1 2020)"},{"ch":"g6c5","q":"حزمة الضوء غير المستقطبة هي التي تكون تذبذبات مجالها الكهربائي:","opts":["مقتصرة على مستوٍ واحد","لا يمكنها المرور خلال أي لوح قطبي","تحصل بالاتجاهات جميعها","تحصل باتجاهات محددة فقط"],"a":2,"why":"الضوء غير المستقطب يهتزّ مجاله الكهربائي عشوائياً بكل الاتجاهات الممكنة العمودية على الانتشار. (سؤال الكتاب س١/١٢)"},{"ch":"g6c5","q":"قانون بروستر لزاوية الاستقطاب الكلي بالانعكاس هو:","opts":["sin θp = n","cos θp = n","tan θp = n","θp = n"],"a":2,"why":"عند زاوية بروستر يتعامد المنعكس والمنكسر، وينتج عن ذلك tanθp=n."},{"ch":"g6c5","q":"زاوية سقوط جعلت الشعاع المنعكس عن سطح مستقطباً كلياً كانت 48° (tan48°=1.110). جد معامل انكسار الوسط.","opts":["1.110","0.667","48","1.482"],"a":0,"why":"n = tanθp = tan48° = 1.110. (مسألة الكتاب س٣)"},{"ch":"g6c5","q":"الزاوية الحرجة لمادة عقيق أزرق محاط بالهواء 34.4° (sin34.4°=0.565). جد زاوية الاستقطاب (بروستر) لهذه المادة (tan60.5°=1.77).","opts":["34.4°","45°","29.5°","60.5°"],"a":3,"why":"من الزاوية الحرجة: n=1/sinθc=1/0.565=1.77. ومن بروستر: tanθp=n=1.77 ⟹ θp=60.5°."},{"ch":"g6c5","q":"ماذا يحدث لضوء أبيض ساقط على شريحتي تورمالين متعامدتي المحاور؟","opts":["يمرّ الضوء كاملاً بلا أي نقصان","يتحوّل لونه إلى أحمر فقط","ينعدم الضوء النافذ تقريباً","يتضاعف مقدار الضوء النافذ"],"a":2,"why":"عند تعامد محوري الشريحتين تنعدم شدة الضوء النافذ تقريباً — وهذا ما يثبت الاستقطاب واستعراضية الموجة الضوئية."},{"ch":"g6c5","q":"تكون السماء زرقاء لأن:","opts":["جزيئات الهواء زرقاء اللون أصلاً","استطارة الضوء تكون أكثر مثالية للموجات القصيرة الطول الموجي","عدسة العين تكون زرقاء","استطارة الضوء تكون أكثر مثالية للموجات الطويلة"],"a":1,"why":"الشدة ∝ 1/λ⁴ فتُستطار الأطوال القصيرة (الأزرق) أكثر بكثير من الطويلة. (سؤال الكتاب س١/١٤)"},{"ch":"g6c5","q":"علّل: يظهر قرص الشمس أحمر عند الشروق والغروب.","opts":["الشمس تُصدر ضوءاً أحمر فقط بهذين الوقتين","الأطوال القصيرة تُستطار بعيداً عن خط النظر بعد مسار طويل بالغلاف الجوي، فيصل الأحمر (الأقل استطارة) مباشرة","الغلاف الجوي يلوّن كل الضوء أحمر دوماً","العين البشرية لا ترى الأزرق صباحاً ومساءً"],"a":1,"why":"الشدة∝1/λ⁴؛ فالأزرق والبنفسجي (أقصر طولاً) يُستطاران بنسبة أكبر بكثير على المسار الطويل عند الشروق/الغروب. (تمهيدي 2017 · د3 2017)"},{"ch":"g6c5","q":"لماذا تبدو سماء القمر سوداء نهاراً بينما سماء الأرض زرقاء؟","opts":["القمر أبعد عن الشمس بكثير من الأرض","لون تربة القمر أسود أصلاً","القمر بلا غلاف جوي فلا استطارة، بينما غلاف الأرض يستطير الأزرق بكل الاتجاهات","الأرض فيها ماء والقمر لا يحتوي ماءً"],"a":2,"why":"بلا جزيئات هواء لا تحدث استطارة، فلا ضوء مستطار يصل عين الراصد على القمر — بعكس الأرض حيث الاستطارة الجوية تصبغ السماء زرقاء وتحجب ضوء النجوم الخافت. (د1 2018 · د3 2023 · د2 2018)"},{"ch":"g6c5","q":"أي أطوال الضوء الأبيض يُستطار بأكبر نسبة؟","opts":["البنفسجي (أقصر الأطوال)","الأحمر (أطول الأطوال)","الأخضر فقط","كل الأطوال تُستطار بنسبة متساوية"],"a":0,"why":"الشدة∝1/λ⁴، وλ البنفسجي أصغر أطوال الضوء المرئي فيُستطار أكثرها. (د2 2020 · د2 2023 · د2 2022)"},{"ch":"g6c5","q":"ما تعريف تداخل الضوء؟","opts":["امتصاص كامل الضوء الساقط على سطح","إعادة توزيع الطاقة الضوئية الناشئة عن تراكب موجات ضوئية متشاكهة","انحناء الضوء عند حافة حاجز","تحوّل الضوء من موجة إلى جسيم"],"a":1,"why":"تداخل الضوء: إعادة توزيع الطاقة الضوئية الناشئة عن تراكب سلسلتين أو أكثر من الموجات الضوئية المتشاكهة. (تمهيدي 2019 · تمهيدي 2021)"},{"ch":"g6c5","q":"(سؤال وزاري، الأكثر تكراراً) لو أُجريت تجربة يونك تحت سطح الماء بدل الهواء، ماذا يحدث لفاصلة الهدب؟","opts":["تزداد فتتباعد الهدب","تبقى ثابتة تماماً","تقلّ فتتقارب الهدب من بعضها","يختفي نمط التداخل كلياً"],"a":2,"why":"λ_n=λ/n أصغر داخل الماء، وΔy=λ_nL/d تتناسب طردياً مع λ، فتقلّ فاصلة الهدب. (2017د1 · 2018ت · 2019د3 · 2021ت وغيرها)"},{"ch":"g6c5","q":"مصدران ضوئيان غير متشاكهين يُسقطان موجاتهما على شاشة. لماذا لا يظهر نمط تداخل مستقر؟","opts":["فرق الطور بينهما يتغيّر عشوائياً بسرعة فائقة فلا يثبت","لأن شدة الضوء منهما صفر","لأن الشاشة تمتصّ كل الضوء","لأن أطوالهما الموجية متساوية دوماً"],"a":0,"why":"المصدران غير المتشاكهين يبعثان أطواراً عشوائية متغيّرة بسرعة، فلا يتحقق شرط ثبات فرق الطور اللازم لتداخل مستديم. (تمهيدي 2017 · د1 2020 وغيرها)"},{"ch":"g6c5","q":"(اختيار وزاري) فرق المسار البصري بين موجتين متشاكهتين متراكبتين يساوي أعداداً فردية من أنصاف الأطوال الموجية. أي تداخل يحصل؟","opts":["تداخل بناء","استطارة","استقطاب","تداخل إتلاف"],"a":3,"why":"Δℓ=(m+½)λ شرط التداخل الإتلافي. (2020د1 · 2021ت)"},{"ch":"g6c5","q":"سبب ظهور هدب مضيئة ومظلمة بتجربة شقي يونك هو:","opts":["الحيود فقط","حيود وتداخل موجات الضوء معاً","التداخل فقط","الانعكاس عن الشقين"],"a":1,"why":"تحيد الموجات بالشقين فتصير مصدرين متشاكهين، ثم تتداخل بناءً وإتلافاً. عبارة «الحيود فقط» وردت بصح/خطأ (2020د2) وهي خاطئة."},{"ch":"g6c5","q":"أثبت أن فاصلة الهدب في تجربة يونك تُعطى بالعلاقة Δy=λL/d — ما الخطوة الأخيرة بهذا الإثبات؟","opts":["Δy = y_m فقط بلا طرح","Δy = λ/d بلا L إطلاقاً","Δy = y_(m+1) − y_m = (λL/d)(m+1) − (λL/d)m = λL/d","Δy = mλ مباشرة"],"a":2,"why":"طرح موقعي هدبين متتاليين ذوي مرتبتين m وm+1 يحذف m ويبقي λL/d. (د1 2022)"},{"ch":"g6c5","q":"بتجربة يونك، البعد بين الشقين 0.2mm وبعد الشاشة 1m، وبعد الهدب الثالث المضيء عن المركزي 9.49mm. جد λ.","opts":["≈633 nm","≈490 nm","≈500 nm","≈700 nm"],"a":0,"why":"λ=y₃d/(3L)=(9.49×10⁻³×0.2×10⁻³)/3=633×10⁻⁹m. (تمهيدي 2020 — ورد وزارياً حرفياً)"},{"ch":"g6c5","q":"بضوء أخضر λ=5×10⁻⁷m، وتباعد شقين 1mm، وبعد شاشة 2m، فإن فاصلة الهدب:","opts":["0.5 mm","2 mm","0.25 mm","1 mm"],"a":3,"why":"Δy=λL/d=(5×10⁻⁷×2)/(10⁻³)=10⁻³m=1mm. (تمهيدي 2022 — سؤال الكتاب س١/١٥)"},{"ch":"g6c5","q":"كيف تتغيّر فاصلة الهدب بازدياد بعد الشاشة L مع ثبوت d وλ؟","opts":["تقلّ عكسياً","تزداد طردياً","تبقى ثابتة","تنعدم كلياً"],"a":1,"why":"Δy=λL/d تتناسب طردياً مع L. (د2 2018 · تمهيدي 2020 · د1 2021 · تمهيدي 2022)"},{"ch":"g6c5","q":"لماذا يحصل انقلاب طور مقداره π rad للموجة المنعكسة عن السطح الأمامي لغشاء رقيق؟","opts":["لأنها تنعكس عن وسط أقل كثافة بصرية","لأن الغشاء يمتصّ نصف طاقتها","لأنها تنعكس عن وسط معامل انكساره أكبر من الوسط القادمة منه","لا يحصل أي انقلاب طور إطلاقاً"],"a":2,"why":"الانعكاس عن وسط أعلى معامل انكسار يسبّب دوماً انقلاب طور 180°. (د1 2018 · د1 2024 · تمهيدي 2024)"},{"ch":"g6c5","q":"للحصول على تداخل بناء (غشاء مضيء) بغشاء رقيق سمكه البصري nt، يجب أن يكون nt مساوياً:","opts":["أعداداً فردية من λ/4","أعداداً زوجية من λ/4","صفراً دوماً","λ كاملة دوماً"],"a":0,"why":"nt=1×λ/4, 3×λ/4, 5×λ/4… (أرباع فردية) يعطي تداخلاً بناءً. (تمهيدي 2018 · د1 2019 · د1 2020)"},{"ch":"g6c5","q":"ألوان فقاعات الصابون وأغشية الزيت الرقيقة تُعزى إلى ظاهرة:","opts":["الحيود","الاستقطاب","الاستطارة","التداخل"],"a":3,"why":"تداخل موجات الضوء المنعكسة عن السطحين الأمامي والخلفي للغشاء، ويختلف السمك من موضع لآخر فتظهر ألوان مختلفة. (د1 2017 · تمهيدي 2020 · د2 2019)"},{"ch":"g6c5","q":"ماذا يحدث لعرض المنطقة المركزية المضيئة بنمط حيود شق واحد عندما يضيق الشق أكثر؟","opts":["يقلّ عرضها","يزداد عرضها","يبقى ثابتاً","تختفي المنطقة المركزية"],"a":1,"why":"من ℓsinθ=λ: كلما ضاق ℓ كبرت θ التي يقع عندها أول معتم، فيتوسّع النمط. (د1 2017 · تمهيدي 2019)"},{"ch":"g6c5","q":"شرط تكوّن الهدب المضيء الأول (غير المركزي) بحيود شق واحد هو أن يساوي عرض الشق:","opts":["λ/(2sinθ)","λ","3λ/(2sinθ)","λ/2"],"a":2,"why":"ℓsinθ=(m+½)λ وللأول m=1: ℓsinθ=(3/2)λ ⟹ ℓ=3λ/(2sinθ). (د2 2017 — سؤال الكتاب س١/١)"},{"ch":"g6c5","q":"في حيود الضوء من شق واحد، شرط الهُدب المعتمة هو:","opts":["ℓ sinθ = mλ","ℓ sinθ = (m+½)λ","ℓ sinθ = λ/2 دوماً","d sinθ = mλ"],"a":0,"why":"لاحظ الانعكاس عن يونك: بالشق الواحد mλ يعطي معتماً لا مضيئاً."},{"ch":"g6c5","q":"ثابت المحزز d يُحسب من العلاقة:","opts":["d = N/W","d = W×N","d = λ/N","d = W/N (عرض المحزز÷عدد الحزوز)"],"a":3,"why":"ثابت المحزز = عرض المحزز الكلي مقسوماً على عدد حزوزه."},{"ch":"g6c5","q":"ليزر هيليوم-نيون λ=632.8nm على محزز 6000 خط/سم. جد زاوية حيود المرتبة الأولى (sin21.3°=0.3796).","opts":["≈49°","≈21.3°","≈10.6°","≈42.6°"],"a":1,"why":"d=1/6000cm=1.667×10⁻⁴cm. sinθ₁=λ/d=0.3796 ⟹ θ₁=21.3°. (مثال الكتاب)"},{"ch":"g6c5","q":"محزز 2000 line/cm، جد زاوية حيود المرتبة الأولى للأحمر λ=640nm (sin7.5°=0.128).","opts":["15°","3.75°","7.5°","60°"],"a":2,"why":"d=5×10⁻⁴cm. sinθ=λ/d=0.128 ⟹ θ=7.5°. (د2 2018 — مسألة الكتاب س٢)"},{"ch":"g6c5","q":"الهدب المركزي بمحزز الحيود عند إضاءته بضوء أبيض يكون:","opts":["أبيض","طيفاً مستمراً","أسود تماماً","أزرق فقط"],"a":0,"why":"كل الألوان تصل الهدب المركزي بفرق مسار صفر فيظهر أبيض؛ الأطياف المستمرة تظهر بالمراتب الجانبية فقط. (د2 2020 · تمهيدي 2020)"},{"ch":"g6c5","q":"اشرح نشاطاً يوضّح استقطاب الضوء بشريحتي تورمالين — ماذا يحدث عند تعامد محوريهما؟","opts":["تتضاعف شدة الضوء النافذ","لا يتغيّر شيء إطلاقاً","يتحوّل الضوء إلى اللون الأحمر","تنعدم شدة الضوء النافذ تقريباً"],"a":3,"why":"عند تعامد المحورين تمتصّ الشريحة الثانية كل الضوء النافذ من الأولى تقريباً، فتنعدم الشدة. (د1 2018 · د1 2024)"},{"ch":"g6c5","q":"الموجات الطولية (كالصوت) لا يمكنها إظهار خاصية:","opts":["الانعكاس","الاستقطاب","الانكسار","الحيود"],"a":1,"why":"اهتزاز الموجة الطولية باتجاه انتشارها نفسه فلا مستويات اهتزاز متعددة تُحجب أو تُنفذ انتقائياً. (تمهيدي 2017 — سؤال الكتاب س١/١٣)"},{"ch":"g6c5","q":"قانون بروستر لزاوية الاستقطاب الكلي بالانعكاس هو:","opts":["sin θp = n","cos θp = n","tan θp = n","θp = n"],"a":2,"why":"عند زاوية بروستر يتعامد المنعكس والمنكسر، وينتج عن ذلك tanθp=n."},{"ch":"g6c5","q":"زاوية سقوط جعلت الشعاع المنعكس عن سطح مستقطباً كلياً كانت 48° (tan48°=1.110). جد معامل انكسار الوسط.","opts":["1.110","0.667","48","1.482"],"a":0,"why":"n = tanθp = tan48° = 1.110. (مسألة الكتاب س٣)"},{"ch":"g6c5","q":"زاوية الدوران البصري لمادة نشطة بصرياً (كمحلول السكر) تعتمد على:","opts":["درجة حرارة الغرفة فقط","لون إناء المحلول فقط","شدة الضوء الساقط فقط بلا أي عامل آخر","نوع المادة وسمكها وتركيزها وطول موجة الضوء"],"a":3,"why":"أربعة عوامل معاً: نوع المادة، سمكها، تركيز المحلول، وطول موجة الضوء المارّ خلالها. (تمهيدي 2020 · د3 2020)"},{"ch":"g6c5","q":"علّل: يظهر قرص الشمس أحمر عند الشروق والغروب.","opts":["الشمس تُصدر ضوءاً أحمر فقط بهذين الوقتين","الأطوال القصيرة تُستطار بعيداً عن خط النظر بعد مسار طويل بالغلاف الجوي، فيصل الأحمر (الأقل استطارة) مباشرة","الغلاف الجوي يلوّن كل الضوء أحمر دوماً","العين البشرية لا ترى الأزرق صباحاً ومساءً"],"a":1,"why":"الشدة∝1/λ⁴؛ فالأزرق والبنفسجي (أقصر طولاً) يُستطاران بنسبة أكبر بكثير على المسار الطويل عند الشروق/الغروب. (تمهيدي 2017 · د3 2017)"},{"ch":"g6c5","q":"لماذا تبدو سماء القمر سوداء نهاراً بينما سماء الأرض زرقاء؟","opts":["القمر أبعد عن الشمس بكثير من الأرض","لون تربة القمر أسود أصلاً","القمر بلا غلاف جوي فلا استطارة، بينما غلاف الأرض يستطير الأزرق بكل الاتجاهات","الأرض فيها ماء والقمر لا يحتوي ماءً"],"a":2,"why":"بلا جزيئات هواء لا تحدث استطارة، فلا ضوء مستطار يصل عين الراصد على القمر — بعكس الأرض حيث الاستطارة الجوية تصبغ السماء زرقاء وتحجب ضوء النجوم الخافت. (د1 2018 · د3 2023 · د2 2018)"},{"ch":"g6c5","q":"أي أطوال الضوء الأبيض يُستطار بأكبر نسبة؟","opts":["البنفسجي (أقصر الأطوال)","الأحمر (أطول الأطوال)","الأخضر فقط","كل الأطوال تُستطار بنسبة متساوية"],"a":0,"why":"الشدة∝1/λ⁴، وλ البنفسجي أصغر أطوال الضوء المرئي فيُستطار أكثرها. (د2 2020 · د2 2023 · د2 2022)"},{"ch":"g6c5","q":"الزاوية الحرجة لمادة معينة 34.4° (sin34.4°=0.565). جد زاوية بروستر لهذه المادة (tan60.5°=1.77).","opts":["34.4°","29.5°","90°","60.5°"],"a":3,"why":"n=1/sinθc=1/0.565=1.77، ثم tanθp=n=1.77 ⟹ θp=60.5°."},{"ch":"g6c6","q":"لماذا اعتُبرت الفيزياء الكلاسيكية شبه مكتملة قبيل عام ١٩٠٠؟","opts":["لأن قوانين نيوتن وماكسويل فسّرت حركة الكواكب والضوء والكهرباء والمغناطيسية بدقة مذهلة","لأن كل التجارب الفيزيائية توقفت تماماً بذلك الوقت","لأن العلماء لم يجدوا أي أسئلة جديدة يطرحونها","لأن الفيزياء الحديثة كانت قد اكتُشفت بالفعل قبل ١٩٠٠"],"a":0,"why":"قوانين نيوتن للحركة ومعادلات ماكسويل الكهرومغناطيسية بدت وكأنها تفسّر كل الظواهر الفيزيائية المعروفة وقتها بدقة عالية جداً."},{"ch":"g6c6","q":"من صاحب فرضية الكمّ التي بدأت ثورة الفيزياء الحديثة عام ١٩٠٠؟","opts":["ألبرت آينشتاين","ماكس بلانك","لويس دي برولي","فيرنر هايزنبرغ"],"a":1,"why":"طرح ماكس بلانك عام ١٩٠٠ فرضية أن الطاقة الإشعاعية تُصدر وتُمتص بحزم منفصلة (كمّات) لا بشكل متصل."},{"ch":"g6c6","q":"لماذا يُلقَّب عام ١٩٠٥ بـ\"عام آينشتاين المعجزة\"؟","opts":["لأنه اكتشف الإلكترون لأول مرة بذلك العام","لأنه فاز بجائزة نوبل بذلك العام بالضبط","لأنه نشر بنفس العام تفسيره الكمّي للظاهرة الكهروضوئية والنظرية النسبية الخاصة — ثورتان منفصلتان بعام واحد","لأنه أثبت فرضية دي برولي تجريبياً بذلك العام"],"a":2,"why":"نشر آينشتاين عام ١٩٠٥ بحثين ثوريين منفصلين كلياً: تفسيره الكمّي للظاهرة الكهروضوئية، والنظرية النسبية الخاصة."},{"ch":"g6c6","q":"أي مجالين فيزيائيين رئيسيين يغطيهما هذا الفصل معاً؟","opts":["الفيزياء النووية وحدها دون أي مجال آخر","الكهرباء الساكنة والمغناطيسية فقط","البصريات الفيزيائية والتيار المتناوب فقط","ميكانيك الكم (عالم الذرات والجسيمات دون الذرية) والنظرية النسبية الخاصة (السرعات القريبة من الضوء)"],"a":3,"why":"يتتبّع الفصل خيطين متوازيين: ميكانيك الكم (بلانك، الكهروضوئية، دي برولي، هايزنبرغ) والنظرية النسبية الخاصة (آينشتاين)."},{"ch":"g6c6","q":"(سؤال وزاري — التمهيدي 2022) ما المقصود بتحويلات لورنتز؟","opts":["معادلات تربط إحداثيات الحدث (الموقع والزمن) بين إطارين عطاليين يتحرك أحدهما بالنسبة للآخر","معادلات تحسب سرعة الضوء فقط بإطار واحد ساكن","قانون يربط بين الشحنة والتيار الكهربائي","معادلات تصف حركة الكواكب حول الشمس فقط"],"a":0,"why":"تحويلات لورنتز تربط إحداثيات الحدث (x,y,z,t) كما يقيسها مراقب بإطار عطالي، بإحداثياته نفسها كما يقيسها مراقب آخر بإطار عطالي متحرك بالنسبة للأول — وتحلّ محلّ تحويلات غاليليو الكلاسيكية."},{"ch":"g6c6","q":"ما الصيغة الرياضية الصحيحة لعامل لورنتز γ؟","opts":["γ = √(1 − v²/c²)","γ = 1/√(1 − v²/c²)","γ = v²/c²","γ = 1 − v/c"],"a":1,"why":"γ = 1/√(1−v²/c²) — يساوي 1 عند السكون، ويؤول إلى ما لا نهاية كلما اقتربت v من c."},{"ch":"g6c6","q":"(سؤال وزاري — 2016/2017 خارج القطر · التطبيقي 2019) ما الفرق الأساسي بين تحويلات غاليليو والتحويلات النسبية (لورنتز)؟","opts":["لا فرق حقيقي بينهما بأي سرعة كانت","غاليليو تخص المادة فقط ولورنتز تخص الضوء فقط","المقدار γ (عامل لورنتز) الذي يؤثر بالزخم والطول والكتلة والزمن المقاس عند السرعات القريبة من c","لورنتز أقدم زمنياً من غاليليو بقرون"],"a":2,"why":"تحويلات غاليليو لا تتضمّن γ إطلاقاً (تفترض زمناً وطولاً وكتلة مطلقة)، بينما تحويلات لورنتز تُدخله فيؤثر على هذه المقادير عند السرعات القريبة من سرعة الضوء."},{"ch":"g6c6","q":"عند أي سرعة يكون عامل لورنتز γ مساوياً تقريباً للواحد (١) بلا أي تأثيرات نسبية محسوسة؟","opts":["γ لا يساوي الواحد أبداً بأي سرعة كانت","فقط عند v=c بالضبط","فقط عند v=0.9c فأكثر","عند السرعات الصغيرة جداً مقارنة بسرعة الضوء (v≪c) — عالمنا اليومي بأكمله"],"a":3,"why":"عند v≪c يكون v²/c² مهملاً جداً، فيؤول γ إلى 1 تقريباً — ولهذا لا نلاحظ أي تأثيرات نسبية بحياتنا اليومية."},{"ch":"g6c6","q":"قضيب طوله بالسكون L₀=10m يتحرك بسرعة v=0.6c. ما طوله كما يقيسه مراقب ساكن؟","opts":["8 m","6 m","10 m","4 m"],"a":0,"why":"L = L₀√(1−v²/c²) = 10×√(1−0.36) = 10×√0.64 = 10×0.8 = 8 m."},{"ch":"g6c6","q":"(سؤال وزاري — اختيار من متعدد) سفينة فضائية طولها بالسكون 40m تتحرك بسرعة 0.8c. كم يصبح طولها كما يقيسه مراقب ساكن على الأرض؟","opts":["18 m","24 m","20 m","40 m"],"a":1,"why":"L = L₀√(1−v²/c²) = 40×√(1−0.64) = 40×0.6 = 24 m."},{"ch":"g6c6","q":"جسيم كتلته بالسكون m₀=2kg يتحرك بسرعة v=0.6c. جد كتلته النسبية كما يقيسها مراقب ساكن.","opts":["2 kg","1.6 kg","2.5 kg","3.33 kg"],"a":2,"why":"γ=1/√(1−0.36)=1/0.8=1.25. m=m₀γ=2×1.25=2.5 kg."},{"ch":"g6c6","q":"لماذا يستحيل عملياً أن يبلغ جسمٌ له كتلة سكون سرعة الضوء؟","opts":["لأن قوانين نيوتن تمنع ذلك بشكل مباشر عند أي سرعة","لأن الجاذبية الأرضية تمنع أي جسم من التسارع فوق سرعة الصوت","لأن الضوء نفسه لا يتحرك بسرعة ثابتة أصلاً","لأن عامل لورنتز γ يؤول إلى ما لا نهاية عند v→c، فتزداد كتلته النسبية بلا حدود وتحتاج طاقة غير منتهية لتسريعه أكثر"],"a":3,"why":"بما أن m=m₀γ، وγ يكبر بلا حدود كلما اقتربت v من c، فإن كتلة الجسم النسبية تزداد بلا حدود أيضاً — ما يحتاج طاقة غير منتهية لتسريعه أكثر، وهذا مستحيل عملياً بأي مصدر طاقة محدود."},{"ch":"g6c6","q":"ما القاسم المشترك بين نتائج النسبية الخاصة الثلاث (تمدد الزمن، تقلص الطول، ازدياد الكتلة)؟","opts":["كلها تتضمّن عامل لورنتز γ — الزمن والكتلة يُضربان به، والطول يُقسَم عليه","لا قاسم مشترك حقيقي بينها إطلاقاً","كلها تعتمد على كتلة الجسم فقط بصرف النظر عن سرعته","كلها نتائج تظهر فقط بالسرعات المنخفضة جداً"],"a":0,"why":"الزمن والكتلة يُضربان بعامل لورنتز γ (يكبران بالحركة)، بينما الطول يُقسَم على γ (يصغر) — وعند γ≈1 (السرعات اليومية) تختفي كل الفروق."},{"ch":"g6c6","q":"ما الصيغة الصحيحة لمعادلة آينشتاين لتكافؤ الكتلة والطاقة؟","opts":["E = mc","E = mc²","E = m/c²","E = m²c"],"a":1,"why":"E=mc² — الطاقة المكافئة لكتلة m تساوي حاصل ضربها بمربّع سرعة الضوء."},{"ch":"g6c6","q":"لماذا تكافئ كمّية صغيرة جداً من الكتلة طاقة ضخمة وفق E=mc²؟","opts":["المعادلة تنطبق فقط على كتل كبيرة جداً لا الصغيرة","لأن الكتلة نفسها تتضاعف تلقائياً قبل التحويل","لأن c² مقدار هائل (9×10¹⁶ m²/s²)، فيضخّم أي كتلة مهما صغرت إلى طاقة كبيرة جداً","لا علاقة حقيقية بين حجم c وحجم الطاقة الناتجة"],"a":2,"why":"بما أن c²=9×10¹⁶ m²/s² مقدار هائل جداً، فضربه حتى بكتلة صغيرة جداً (كغرام واحد) ينتج طاقة ضخمة جداً."},{"ch":"g6c6","q":"إذا تحوّلت كتلة مقدارها 1 gram بالكامل إلى طاقة وفق E=mc²، فما مقدار هذه الطاقة تقريباً؟","opts":["≈9×10¹⁶ J","≈3×10⁸ J","≈1×10⁻³ J","≈9×10¹³ J"],"a":3,"why":"E=mc²=1×10⁻³×(3×10⁸)²=1×10⁻³×9×10¹⁶=9×10¹³ J — طاقة تكفي بيتاً عراقياً نحو ألفي سنة!"},{"ch":"g6c6","q":"ما المصدر الفيزيائي لطاقة الشمس المستمرة منذ مليارات السنين، وفق تكافؤ الكتلة والطاقة؟","opts":["تحوّل جزء ضئيل من كتلة الشمس إلى طاقة هائلة عبر الاندماج النووي (E=mc²)","احتراق غازات كيميائية عادية بالشمس فقط","الشمس لا تفقد أي كتلة إطلاقاً رغم إشعاعها المستمر","طاقة الشمس مصدرها الجاذبية فقط بلا أي علاقة بالكتلة"],"a":0,"why":"تفقد الشمس نحو 4 ملايين طنّ من كتلتها كل ثانية عبر الاندماج النووي، يتحوّل خلاله جزء ضئيل من الكتلة إلى طاقة هائلة وفق E=mc²."},{"ch":"g6c6","q":"إذا تحوّلت كتلة مقدارها 2mg بالكامل إلى طاقة، فكم تساوي هذه الطاقة تقريباً؟","opts":["≈9×10¹⁶ J","≈1.8×10¹¹ J","≈2×10⁻⁶ J","≈3×10⁸ J"],"a":1,"why":"E=mc²=2×10⁻⁶×(3×10⁸)²=2×10⁻⁶×9×10¹⁶=1.8×10¹¹ J."},{"ch":"g6c6","q":"ما تعريف الجسم الأسود المثالي؟","opts":["جسم يعكس كل الإشعاع الساقط عليه","جسم لونه أسود دائماً حتى وهو ساخن","جسم يمتص كل الإشعاع الساقط عليه بجميع الأطوال الموجية دون عكس أو نفاذ","جسم لا يتأثر بالحرارة إطلاقاً"],"a":2,"why":"الجسم الأسود المثالي يمتص الإشعاع الساقط عليه بالكامل، بجميع الأطوال الموجية، بلا أي عكس أو نفاذ."},{"ch":"g6c6","q":"وفق قانون ستيفان-بولتزمان، شدة إشعاع الجسم الأسود I تتناسب طردياً مع:","opts":["نوع مادة الجسم فقط","درجة الحرارة المطلقة T مباشرة","مقلوب درجة الحرارة 1/T","الأس الرابع لدرجة الحرارة المطلقة T⁴"],"a":3,"why":"I = σT⁴ — شدة الإشعاع تتناسب طردياً مع الأس الرابع لدرجة الحرارة المطلقة، بغض النظر عن نوع المادة."},{"ch":"g6c6","q":"جسم أسود درجة حرارته 400K. جد الطول الموجي المقابل لذروة إشعاعه تقريباً (قانون فِن: λ_mT=2.898×10⁻³).","opts":["≈7.25×10⁻⁶ m","≈2.898×10⁻³ m","≈1.159 m","≈4×10⁻⁶ m"],"a":0,"why":"λ_m = 2.898×10⁻³/400 ≈ 7.25×10⁻⁶ m."},{"ch":"g6c6","q":"ماذا حدث لمنحني إشعاع الجسم الأسود عند الأطوال الموجية القصيرة جداً حسب تنبؤ الفيزياء الكلاسيكية (قبل بلانك)؟","opts":["بقيت الشدة صفراً دائماً","تصاعدت شدة الإشعاع إلى ما لا نهاية (الكارثة فوق البنفسجية)","طابق التنبؤ التجربة تماماً","هبطت الشدة تدريجياً كما يحدث فعلاً"],"a":1,"why":"النموذج الكلاسيكي تنبأ بازدياد الشدة إلى ما لا نهاية عند الأطوال الموجية القصيرة، بعكس المشاهدة التجريبية — سُمي هذا الفشل الكارثة فوق البنفسجية."},{"ch":"g6c6","q":"ما نص فرضية بلانك الأساسية لحل مشكلة إشعاع الجسم الأسود؟","opts":["الضوء موجة كهرومغناطيسية متصلة فقط بلا أي طبيعة أخرى","الطاقة الإشعاعية ثابتة مهما تغيّر ترددها","الطاقة الإشعاعية تُصدر وتُمتص على شكل حزم منفصلة (كمّات) لا بشكل متصل","درجة حرارة الجسم لا تؤثر على طيف إشعاعه"],"a":2,"why":"فرضية بلانك: الطاقة تُصدر أو تُمتص بحزم منفصلة (كمّات) طاقة كل منها E=hf، لا بشكل متصل كما افترضت الفيزياء الكلاسيكية."},{"ch":"g6c6","q":"كمّ إشعاعي (فوتون) تردده f=6×10¹⁴ Hz. جد طاقته تقريباً (h=6.63×10⁻³⁴J.s).","opts":["≈3.98×10⁻¹⁵ J","≈6.63×10⁻³⁴ J","≈1.1×10⁻⁴⁸ J","≈3.98×10⁻¹⁹ J"],"a":3,"why":"E = hf = 6.63×10⁻³⁴ × 6×10¹⁴ ≈ 3.98×10⁻¹⁹ J."},{"ch":"g6c6","q":"ضوء شدته عالية جداً لكن تردده أقل من التردد الحرج لفلز معيّن سقط عليه. ماذا يحدث؟","opts":["لا ينبعث أي إلكترون مهما زادت الشدة أو طال زمن السقوط","تنبعث إلكترونات ببطء بعد فترة انتظار طويلة","تنبعث إلكترونات فوراً بطاقة حركية كبيرة","ينبعث عدد كبير جداً من الإلكترونات فوراً"],"a":0,"why":"إن كان f&lt;f₀ فإن طاقة الفوتون الواحد hf أقل من دالة الشغل W₀، فلا يتحرر أي إلكترون بغض النظر عن الشدة (عدد الفوتونات) أو زمن الانتظار."},{"ch":"g6c6","q":"عند مضاعفة شدة الضوء الساقط (بتردد ثابت أعلى من f₀)، أي مقدار يتضاعف؟","opts":["الطاقة الحركية العظمى KE_max","تيار الإشباع (عدد الإلكترونات المنبعثة بالثانية) فقط","جهد الإيقاف V_s","دالة الشغل W₀"],"a":1,"why":"مضاعفة الشدة تضاعف عدد الفوتونات الساقطة، فيتضاعف تيار الإشباع، لكن طاقة كل فوتون (وبالتالي KE_max وV_s) تبقى ثابتة لأنها تعتمد على التردد فقط."},{"ch":"g6c6","q":"يتوقف تحرير الإلكترونات الضوئية من سطح معدن عندما يزيد طول موجة الضوء الساقط عن 600nm. إذا أُضيء المعدن نفسه بضوء طول موجته 300nm، جد الطاقة الحركية العظمى للإلكترونات المنبعثة (h=6.63×10⁻³⁴J.s، c=3×10⁸m/s).","opts":["≈1.99×10⁻¹⁸ J","≈6.63×10⁻¹⁹ J","≈3.315×10⁻¹⁹ J (≈2.07 eV)","صفر — لا ينبعث شيء"],"a":2,"why":"W₀=hc/600nm=3.315×10⁻¹⁹J. عند 300nm: hf=hc/300nm=6.63×10⁻¹⁹J. KE_max=6.63×10⁻¹⁹−3.315×10⁻¹⁹=3.315×10⁻¹⁹J≈2.07eV."},{"ch":"g6c6","q":"برسم بياني للطاقة الحركية العظمى KE_max مقابل تردد الضوء الساقط f، ماذا يمثّل ميل الخط المستقيم الناتج؟","opts":["التردد الحرج f₀","دالة الشغل W₀ للفلز","شدة الضوء الساقط","ثابت بلانك h (نفسه بغض النظر عن نوع الفلز)"],"a":3,"why":"من KE_max=hf−W₀ (بصورة y=mx+c)، الميل m=h ثابت بلانك، وهو نفسه مهما اختلف الفلز — لهذا خطوط الفلزات المختلفة متوازية دائماً."},{"ch":"g6c6","q":"ما العلاقة الصحيحة بين طول موجة العتبة λ₀ ودالة الشغل W₀؟","opts":["λ₀ = hc/W₀","λ₀ = W₀/hc","λ₀ = hW₀/c","λ₀ = c/(hW₀)"],"a":0,"why":"من W₀=hf₀ وf₀=c/λ₀، نستنتج W₀=hc/λ₀ ⟹ λ₀=hc/W₀."},{"ch":"g6c6","q":"أي مما يلي تطبيق عملي شائع للظاهرة الكهروضوئية؟","opts":["تسخين الطعام بفرن المايكرويف","الألواح الشمسية والكاميرات الرقمية","توليد المجال المغناطيسي بالمحول الكهربائي","شحن المتسعة بدائرة RC"],"a":1,"why":"الألواح الشمسية والكاميرات الرقمية (CCD) تعتمدان مباشرة على تحويل الفوتونات الساقطة إلى إلكترونات حرة."},{"ch":"g6c6","q":"ما زخم الفوتون الذي طوله الموجي λ؟","opts":["p = λ/h","p = hλ","p = h/λ","p = h²/λ"],"a":2,"why":"زخم الفوتون p=mc=hf/c=h/λ — يربط الصفة الجسيمية (الزخم) بالصفة الموجية (الطول الموجي)."},{"ch":"g6c6","q":"لماذا يملك الفوتون زخماً محسوباً رغم أنه عديم كتلة السكون؟","opts":["لأن الفوتون يكتسب كتلة من الإلكترون الذي يصطدم به فقط","لأن كل الفوتونات تملك كتلة سكون صغيرة جداً لكنها غير معدومة فعلياً","الزخم مفهوم لا ينطبق على الفوتون إطلاقاً وما يُحسب هو تقدير تقريبي فقط","لأنه يحمل طاقة E=hf ويتحرك بسرعة الضوء c، فتُعرَّف له كتلة حركية m=hf/c² يُحسب منها زخمه p=mc"],"a":3,"why":"الفوتون يحمل طاقة E=hf رغم عدم امتلاكه كتلة سكون؛ بمعادلة آينشتاين E=mc² تُعرَّف كتلته الحركية m=hf/c²، ومنها زخمه p=mc=hf/c=h/λ."},{"ch":"g6c6","q":"فوتون طاقته E. ما زخمه بدلالة E وسرعة الضوء c؟","opts":["p = E/c","p = Ec","p = E×c²","p = c/E"],"a":0,"why":"من p=h/λ وE=hc/λ، نستنتج مباشرة p=E/c."},{"ch":"g6c6","q":"فوتون طوله الموجي λ=2nm. جد زخمه تقريباً (h=6.63×10⁻³⁴J.s).","opts":["≈1.33×10⁻²⁴ kg·m/s","≈3.32×10⁻²⁵ kg·m/s","≈6.63×10⁻³⁴ kg·m/s","≈2×10⁻⁹ kg·m/s"],"a":1,"why":"p = h/λ = (6.63×10⁻³⁴)/(2×10⁻⁹) ≈ 3.32×10⁻²⁵ kg·m/s."},{"ch":"g6c6","q":"من صاحب فرضية الموجات المادية (الطبيعة الموجية للجسيمات كالإلكترون)؟","opts":["ألبرت أينشتاين","ماكس بلانك","لويس دي برولي","فيرنر هايزنبرغ"],"a":2,"why":"طرح الفيزيائي الفرنسي لويس دي برولي هذه الفرضية عام 1923-1924 برسالته الجامعية."},{"ch":"g6c6","q":"ما قانون طول موجة دي برولي المرافقة لجسيم كتلته m وسرعته v؟","opts":["λ = mv/h","λ = h×mv","λ = hf","λ = h/(mv)"],"a":3,"why":"λ = h/p = h/(mv) — يتناسب طول الموجة عكسياً مع زخم الجسيم mv."},{"ch":"g6c6","q":"أي تجربة أكدت عملياً الطبيعة الموجية للإلكترون؟","opts":["تجربة ديفيسون وجيرمر (حيود الإلكترونات عبر بلورة نيكل)","تجربة ميليكان لقطرة الزيت","تجربة يانگ لشقّين بالضوء فقط","تجربة رذرفورد لتشتت جسيمات ألفا"],"a":0,"why":"عام 1927 رصد ديفيسون وجيرمر نمط حيود للإلكترونات المرتدة عن بلورة نيكل، مماثلاً لحيود الأشعة السينية، مؤكدين فرضية دي برولي."},{"ch":"g6c6","q":"إلكترون كتلته 9.11×10⁻³¹kg يتحرك بسرعة 2×10⁶ m/s. جد طول موجة دي برولي المرافقة له تقريباً.","opts":["≈1.82×10⁻²⁴ m","≈3.64×10⁻¹⁰ m","≈6.63×10⁻³⁴ m","≈3.64×10⁻⁷ m"],"a":1,"why":"λ = h/(mv) = (6.63×10⁻³⁴)/(9.11×10⁻³¹ × 2×10⁶) ≈ 3.64×10⁻¹⁰ m."},{"ch":"g6c6","q":"لماذا لا نلاحظ أي سلوك موجي محسوس لكرة متحركة رغم انطباق فرضية دي برولي عليها نظرياً؟","opts":["لأن فرضية دي برولي تخص الفوتونات فقط لا الأجسام المادية","لأن الكرة لا تملك زخماً خطياً إطلاقاً","كتلتها كبيرة جداً مقارنة بثابت بلانك، فيكون طول موجتها المرافق ضئيلاً جداً يستحيل رصده","لأن سرعة الكرة كبيرة جداً مقارنة بسرعة الضوء"],"a":2,"why":"λ=h/(mv) يتناسب عكسياً مع الكتلة؛ كتلة الكرة الكبيرة تجعل λ أصغر من نواة الذرة بمراحل، أي مهمل عملياً ولا يمكن رصده."},{"ch":"g6c6","q":"بماذا يصف ميكانيك الكم حالة الجسيم المجهري (كالإلكترون)؟","opts":["لا يوجد أي وصف رياضي ممكن لحالة الجسيم المجهري","بموضع وسرعة محددين تماماً بأي لحظة كما بميكانيك نيوتن","بشحنته الكهربائية فقط دون أي وصف آخر","بدالة الموجة ψ، وهي دالة رياضية تصف حالته احتمالياً لا حتمياً"],"a":3,"why":"بما أن الجسيمات المجهرية موجية الطبيعة، تُوصف حالتها بدالة الموجة ψ وصفاً احتمالياً، لا حتمياً دقيقاً كالميكانيك الكلاسيكي."},{"ch":"g6c6","q":"دالة الموجة ψ لجسيم، ماذا يمثّل مربّع مقدارها |ψ|² عند نقطة وزمان معيّنين (تفسير بورن)؟","opts":["كثافة احتمال العثور على الجسيم في تلك المنطقة وتلك اللحظة","الطاقة الحركية للجسيم مباشرة","زخم الجسيم مباشرة","شحنة الجسيم الكهربائية"],"a":0,"why":"وفق تفسير بورن، |ψ|² يمثّل كثافة الاحتمال: كلما كبرت قيمتها بمنطقة ما، كبر احتمال العثور على الجسيم هناك."},{"ch":"g6c6","q":"بالوصف الكمّي الحديث لذرة الهيدروجين (بعكس نموذج بور الكلاسيكي)، كيف يوصف موضع الإلكترون؟","opts":["بمدار دائري ثابت نصف قطره محدد بدقة تامة دائماً","بسحابة احتمال |ψ|² حول النواة، لا بمدار دائري محدد الشكل","بنقطة ساكنة تماماً داخل النواة","لا يوجد أي وصف علمي لموضعه إطلاقاً"],"a":1,"why":"الوصف الكمي يستبدل مدار بور الحاد بسحابة احتمال ضبابية |ψ|²، أعلى كثافة قرب نصف قطر بور لكن مع احتمال (ضئيل) بمناطق أخرى."},{"ch":"g6c6","q":"ما الفرق الجوهري بين الوصف الكلاسيكي (نيوتن) والوصف الكمّي لحركة جسيم؟","opts":["الكمّي حتمي والكلاسيكي احتمالي — عكس الترتيب المعروف","لا فرق جوهري بينهما، فكلاهما حتمي تماماً بنفس الدرجة","الكلاسيكي حتمي (موضع وسرعة محددان تماماً)، بينما الكمّي احتمالي (يصف فقط احتمالية وجود الجسيم بمنطقة ما)","الفرق يقتصر على وحدات القياس المستعملة فقط لا أكثر"],"a":2,"why":"الميكانيك الكلاسيكي يصف الحركة وصفاً حتمياً دقيقاً؛ بينما ميكانيك الكم يصفها احتمالياً عبر دالة الموجة ψ وكثافة الاحتمال |ψ|²، انعكاساً للطبيعة الموجية للجسيمات المجهرية."},{"ch":"g6c6","q":"من صاحب مبدأ اللادقة (اللاتحديد) في ميكانيكا الكم؟","opts":["ألبرت أينشتاين","لويس دي برولي","ماكس بلانك","فيرنر هايزنبرغ"],"a":3,"why":"صاغ الفيزيائي الألماني فيرنر هايزنبرغ هذا المبدأ عام 1927."},{"ch":"g6c6","q":"ما الصيغة الرياضية الصحيحة لمبدأ هايزنبرغ للادقة؟","opts":["Δx · Δp ≥ h/4π","Δx + Δp ≥ h","Δx / Δp ≥ 4π/h","Δx · Δp = h بالضبط دائماً"],"a":0,"why":"حاصل ضرب اللادقة بالموضع Δx واللادقة بالزخم Δp لا يقل أبداً عن h/4π."},{"ch":"g6c6","q":"(سؤال وزاري — التمهيدي 2019) افترض أنه قيس موضع جسيم بدقة تامة، أي أن Δx=0. فإن أقل دقة لزخم هذا الجسيم بهذا الاتجاه تساوي:","opts":["صفر","ما لا نهاية","h/4π","h/2π"],"a":1,"why":"من Δx·Δp≥h/4π، إذا كان Δx=0 فلا بد أن يكون Δp غير منتهٍ ليبقى حاصل الضرب محقّقاً للمتراجحة — أي انعدام الدقة كلياً بمعرفة الزخم."},{"ch":"g6c6","q":"مبدأ اللادقة نتيجة حتمية مباشرة لأي فكرة فيزيائية سابقة بهذا الفصل؟","opts":["قانون حفظ الطاقة العام","فرضية بلانك عن إشعاع الجسم الأسود فقط","الطبيعة الموجية للجسيمات (فرضية دي برولي)","الظاهرة الكهروضوئية فقط"],"a":2,"why":"بما أن كل جسيم له طبيعة موجية (دي برولي)، والموجة ممتدة بالفضاء لا نقطة محددة، يستحيل حصر موضعها وزخمها بدقة تامة معاً — هذا أصل مبدأ اللادقة."},{"ch":"g6c6","q":"إلكترون محصور بمنطقة عرضها Δx=2×10⁻¹⁰m. جد أدنى لادقة ممكنة بزخمه Δp تقريباً.","opts":["≈5.28×10⁻³⁵ kg·m/s","≈6.63×10⁻³⁴ kg·m/s","≈1.33×10⁻²⁴ kg·m/s","≈2.64×10⁻²⁵ kg·m/s"],"a":3,"why":"Δp_min = h/(4πΔx) = (6.63×10⁻³⁴)/(4π×2×10⁻¹⁰) ≈ 2.64×10⁻²⁵ kg·m/s."},{"ch":"g6c6","q":"لماذا لا نلاحظ تأثير مبدأ اللادقة أثناء مراقبتنا حركة كرة قدم؟","opts":["كتلتها كبيرة جداً، فتكون اللادقة الدنيا بسرعتها Δv مهملة تماماً وغير محسوسة","لأن الكرة لا تملك زخماً خطياً إطلاقاً","لأن مبدأ اللادقة يخص الفوتونات فقط لا الأجسام المادية","لأن الكرة ساكنة دائماً أثناء المراقبة"],"a":0,"why":"بما أن Δp=mΔv، فكلما كبرت الكتلة m صغرت اللادقة الناتجة بالسرعة Δv بشدة لنفس اللادقة بالزخم، فتصبح مهملة عملياً."},{"ch":"g6c6","q":"مبدأ اللادقة لهايزنبرغ يعني استحالة معرفة أي زوج من الكميات التاليتين بدقة تامة في آنٍ واحد؟","opts":["الكتلة والشحنة معاً","الموضع والزخم معاً","التردد واللون معاً","درجة الحرارة والزمن معاً"],"a":1,"why":"مبدأ اللادقة يربط تحديداً بين اللادقة بالموضع (Δx) واللادقة بالزخم (Δp) — لا يمكن معرفة كليهما بدقة تامة بنفس اللحظة."},{"ch":"g6c6","q":"ما تعريف الإطار المرجعي العطالي (القصوري)؟","opts":["إطار مرتبط بسطح الأرض فقط دون أي إطار آخر","إطار يتسارع أو يدور، وتحتاج فيه قوانين نيوتن تعديلات إضافية","إطار يتحرك بسرعة ثابتة (أو ساكن)، تنطبق فيه قوانين نيوتن مباشرة بلا أي تعديل","إطار لا وجود له فعلياً إلا نظرياً"],"a":2,"why":"الإطار العطالي (القصوري) يتحرك بسرعة ثابتة أو يكون ساكناً، وتنطبق فيه قوانين نيوتن للحركة مباشرة بلا تعديل."},{"ch":"g6c6","q":"بالوصف الكلاسيكي (قبل النسبية)، كيف يُنظر إلى الزمن؟","opts":["كمّية تعتمد فقط على درجة الحرارة","بُعد رابع متشابك مع المكان يعتمد على حركة المراقب","كمّية غير موجودة أصلاً بالفيزياء الكلاسيكية","كمّية مطلقة منفصلة عن المكان، تتدفق بالمعدّل نفسه لكل المراقبين"],"a":3,"why":"بالفيزياء الكلاسيكية، الزمن كمّية مطلقة منفصلة عن الإحداثيات المكانية الثلاث، تتدفق بالمعدّل نفسه بصرف النظر عن حركة المراقب."},{"ch":"g6c6","q":"ما مفهوم \"الزمكان\" (spacetime) الذي أدخلته النظرية النسبية؟","opts":["وصف الحدث بأربعة إحداثيات متشابكة: ثلاثة مكانية والزمن رابعها، بحيث يعتمد الزمن على حركة المراقب","مفهوم يخص فقط حركة الكواكب حول الشمس","اسم آخر للمكان الفارغ (الفراغ) فقط دون الزمن","وحدة قياس جديدة للسرعة فقط"],"a":0,"why":"الزمكان يصف كل حدث بأربعة إحداثيات متشابكة (x,y,z,t)، حيث الزمن ليس مطلقاً بل بُعد رابع يعتمد على حركة المراقب."},{"ch":"g6c6","q":"ماذا كانت النتيجة المفاجئة لتجربة مايكلسون-مورلي عام ١٨٨٧؟","opts":["وُجد فرق كبير جداً بسرعة الضوء أكّد وجود الأثير","لم يوجد أي فرق بسرعة الضوء بين الاتجاهين المتعامدين، رغم توقّع فرق بسبب حركة الأرض","لم تنجح التجربة بقياس أي شيء إطلاقاً","أثبتت التجربة أن سرعة الضوء تتغيّر بتغيّر الفصول فقط"],"a":1,"why":"توقّع العالمان فرقاً بسرعة الضوء بسبب حركة الأرض خلال الأثير المفترض، لكن النتيجة جاءت صفراً تماماً — دحضت فكرة الأثير ومهّدت لفرضية آينشتاين بثبات سرعة الضوء."},{"ch":"g6c6","q":"(سؤال وزاري — التمهيدي 2022–2023 · الدور الأول 2020) ما هما فرضيتا آينشتاين في النظرية النسبية الخاصة؟","opts":["قانون حفظ الطاقة وقانون حفظ الزخم فقط","ثبات الزمن المطلق وثبات الكتلة المطلقة لكل المراقبين","مبدأ النسبية (قوانين الفيزياء واحدة بكل الأطر العطالية) وثبات سرعة الضوء لكل المراقبين","فرضية بلانك وفرضية دي برولي"],"a":2,"why":"الفرضية الأولى: قوانين الفيزياء واحدة بجميع الأطر العطالية. الفرضية الثانية: سرعة الضوء بالفراغ ثابتة لجميع المراقبين مهما تحرّك المصدر أو المراقب."},{"ch":"g6c6","q":"وفق مبدأ النسبية (الفرضية الأولى)، ما صحة وجود إطار مرجعي \"مميّز\" بحالة سكون مطلق؟","opts":["كل مراقب يملك قوانين فيزياء مختلفة عن غيره","يوجد إطار واحد مميّز هو الأرض نفسها","يوجد إطار واحد مميّز هو الشمس","لا يوجد أي إطار مميّز — قوانين الفيزياء نفسها تنطبق بجميع الأطر العطالية"],"a":3,"why":"مبدأ النسبية ينصّ على أن قوانين الفيزياء نفسها تنطبق بجميع الأطر المرجعية العطالية، فلا يوجد إطار مطلق مميّز بحالة سكون حقيقي."},{"ch":"g6c6","q":"مركبة فضائية تتحرك بسرعة 0.5c نحوك وتُطلق شعاع ليزر باتجاهك. بأي سرعة يصلك هذا الضوء وفق الفرضية الثانية؟","opts":["بالضبط c=3×10⁸ m/s، بصرف النظر عن حركة المركبة","بسرعة c+0.5c، كما يتوقع جمع السرعات الكلاسيكي","بسرعة c−0.5c فقط","بسرعة تعتمد على لون الليزر المستعمل"],"a":0,"why":"وفق ثبات سرعة الضوء، يصل الضوء لأي مراقب بالسرعة c نفسها دائماً، بصرف النظر عن حركة مصدره — بعكس جمع السرعات الكلاسيكي المعتاد."},{"ch":"g6c6","q":"ما الدليل التجريبي الذي استند إليه آينشتاين لصياغة فرضية ثبات سرعة الضوء؟","opts":["تجربة ديفيسون-جيرمر لحيود الإلكترونات","نتيجة تجربة مايكلسون-مورلي: عدم وجود أي فرق بسرعة الضوء بأي اتجاه قياس","تجربة ميليكان لقطرة الزيت","الظاهرة الكهروضوئية نفسها فقط"],"a":1,"why":"أثبتت تجربة مايكلسون-مورلي (1887) أن سرعة الضوء لا تتغيّر بتغيّر اتجاه القياس، رغم توقّع فرق بسبب حركة الأرض — هذا الدليل التجريبي دحض الأثير ومهّد لفرضية آينشتاين."},{"ch":"g6c6","q":"ما تعريف الجسم الأسود المثالي؟","opts":["جسم يعكس كل الإشعاع الساقط عليه بالكامل","جسم لونه أسود دائماً حتى وهو ساخن جداً","جسم يمتص كل الإشعاع الساقط عليه بجميع الأطوال الموجية دون عكس أو نفاذ","جسم لا يُصدر أي إشعاع مهما سخُن"],"a":2,"why":"الجسم الأسود المثالي يمتص الإشعاع الساقط عليه بالكامل بجميع الأطوال الموجية، دون أي عكس أو نفاذ."},{"ch":"g6c6","q":"(سؤال وزاري، الدور الثالث 2019 · الدور الثالث 2023) على ماذا ينصّ قانون ستيفان-بولتزمان؟","opts":["شدة الإشعاع ثابتة لكل الأجسام السوداء بغض النظر عن حرارتها","شدة الإشعاع لا تعتمد على درجة الحرارة إطلاقاً","شدة الإشعاع تتناسب عكسياً مع درجة الحرارة","شدة إشعاع الجسم الأسود I تتناسب طردياً مع الأس الرابع لدرجة حرارته المطلقة (I=σT⁴)"],"a":3,"why":"I=σT⁴ — شدة إشعاع الجسم الأسود تتناسب طردياً مع الأس الرابع لدرجة حرارته المطلقة، وتعتمد على درجة الحرارة فقط لا نوع المادة."},{"ch":"g6c6","q":"جسم أسود درجة حرارته 500K. جد الطول الموجي المقابل لذروة إشعاعه (قانون فِن: λ_mT=2.898×10⁻³m·K).","opts":["≈5.8×10⁻⁶ m","≈2.898×10⁻³ m","≈1.449 m","≈5.8×10⁻³ m"],"a":0,"why":"λ_m = 2.898×10⁻³/500 ≈ 5.8×10⁻⁶ m."},{"ch":"g6c6","q":"(سؤال وزاري، الدور الثاني 2023) لماذا فشلت المحاولات العديدة لتفسير طيف الجسم الأسود وفق قوانين الفيزياء الكلاسيكية؟","opts":["لأن الجسم الأسود لا يوجد فعلياً بالطبيعة","لأنها افترضت أن الطاقة تُصدر وتُمتص بكميات مستمرة، فتنبأت بطاقة لا نهائية عند الأطوال الموجية القصيرة","لأن درجة الحرارة لا تؤثر على الإشعاع أصلاً","لأن الفيزياء الكلاسيكية لم تدرس الإشعاع الحراري إطلاقاً"],"a":1,"why":"الفيزياء الكلاسيكية افترضت طاقة إشعاعية مستمرة (بلا تكميم)، فتنبأت بطاقة لا نهائية عند الأطوال الموجية القصيرة (الكارثة فوق البنفسجية) — يخالف التجربة تماماً."},{"ch":"g6c6","q":"ما نص فرضية بلانك الأساسية؟","opts":["الضوء موجة كهرومغناطيسية متصلة فقط بلا أي طبيعة أخرى","الطاقة الإشعاعية ثابتة مهما تغيّر ترددها","الطاقة الإشعاعية تُصدر وتُمتص على شكل حزم منفصلة (كمّات) طاقة كل منها E=hf","درجة حرارة الجسم لا علاقة لها بطيف إشعاعه"],"a":2,"why":"فرضية بلانك: الطاقة تُصدر أو تُمتص بحزم منفصلة (كمّات) طاقة كل منها E=hf."},{"ch":"g6c6","q":"كمّ إشعاعي (فوتون) تردده f=5×10¹⁴ Hz. جد طاقته تقريباً (h=6.63×10⁻³⁴J.s).","opts":["≈3.32×10⁻¹⁵ J","≈6.63×10⁻³⁴ J","≈1.33×10⁻⁴⁸ J","≈3.32×10⁻¹⁹ J"],"a":3,"why":"E = hf = 6.63×10⁻³⁴ × 5×10¹⁴ ≈ 3.32×10⁻¹⁹ J."},{"ch":"g6c6","q":"كلما ارتفعت درجة حرارة الجسم الأسود، ماذا يحدث لموقع قمة منحني إشعاعه ولشدته الكلية؟","opts":["تنزاح القمة نحو أطوال موجية أقصر، وتزداد الشدة الكلية بقوة","تنزاح القمة نحو أطوال موجية أطول، وتقلّ الشدة الكلية","تبقى القمة والشدة ثابتتين تماماً","تختفي القمة والشدة معاً"],"a":0,"why":"قانون فِن: القمة تنزاح لأطوال موجية أقصر مع ارتفاع T. قانون ستيفان-بولتزمان: الشدة الكلية تزداد بقوة (∝T⁴)."},{"ch":"g6c6","q":"ما ملاحظتان تجريبيتان من ملاحظات الظاهرة الكهروضوئية الأربع تناقضان توقعات النظرية الموجية الكلاسيكية؟","opts":["زيادة عدد الإلكترونات مع شدة الضوء فقط","الانبعاث الفوري بلا تأخير، ووجود تردد عتبة أدنى لا ينبعث دونه أي إلكترون","أن التيار الضوئي يساوي صفراً دائماً","أن الظاهرة لا تحدث إلا بالضوء الأحمر فقط"],"a":1,"why":"النموذج الكلاسيكي يتوقع تأخيراً زمنياً لتجميع الطاقة، وعدم وجود تردد عتبة (أي تردد يحرر إلكتروناً لو انتظرنا كفاية) — كلا الأمرين يخالف التجربة."},{"ch":"g6c6","q":"(اختيار وزاري متكرر، الدور الأول 2024 · 2022 · 2019) عند مضاعفة شدة الضوء الساقط بتردد ثابت أعلى من f₀، أي مقدار يتضاعف؟","opts":["جهد الإيقاف V_s","الطاقة الحركية العظمى KE_max","تيار الإشباع (عدد الإلكترونات المنبعثة بالثانية)","دالة الشغل W₀"],"a":2,"why":"مضاعفة الشدة تضاعف عدد الفوتونات فقط، فيتضاعف تيار الإشباع، بينما KE_max وV_s ثابتتان لاعتمادهما على التردد فقط."},{"ch":"g6c6","q":"(سؤال وزاري، الدور الثالث 2017 · الدور الثاني 2019 وغيرها — الأكثر تكراراً) يتوقّف تحرير الإلكترونات من سطح معدن عند λ₀=600nm. أُضيء المعدن نفسه بضوء λ=300nm. جد KE_max.","opts":["صفر","≈6.63×10⁻¹⁹ J","≈1.99×10⁻¹⁸ J","≈3.315×10⁻¹⁹ J (≈2.07eV)"],"a":3,"why":"W₀=hc/600nm=3.315×10⁻¹⁹J. عند 300nm: hf=hc/300nm=6.63×10⁻¹⁹J. KE_max=6.63×10⁻¹⁹−3.315×10⁻¹⁹=3.315×10⁻¹⁹J≈2.07eV."},{"ch":"g6c6","q":"(سؤال وزاري، الدور الثاني 2023) سقط ضوء λ=3×10⁻⁷m على معدن، وكان جهد القطع اللازم لإيقاف الإلكترونات 1.658V. جد طول موجة العتبة لهذا المعدن.","opts":["≈500 nm","≈300 nm","≈600 nm","≈150 nm"],"a":0,"why":"KE_max=eV_s=1.6×10⁻¹⁹×1.658=2.653×10⁻¹⁹J. W₀=hc/λ−KE_max=6.63×10⁻¹⁹−2.653×10⁻¹⁹=3.977×10⁻¹⁹J. λ₀=hc/W₀≈5×10⁻⁷m=500nm."},{"ch":"g6c6","q":"(سؤال وزاري، التمهيدي 2022–2023 · 2023–2024) سقط ضوء λ=300nm على معدن دالة شغله 3.978×10⁻¹⁹J. جد KE_max بوحدة الجول.","opts":["≈6.63×10⁻¹⁹ J","≈2.652×10⁻¹⁹ J","≈3.978×10⁻¹⁹ J","≈1.326×10⁻¹⁸ J"],"a":1,"why":"hf=hc/λ=6.63×10⁻¹⁹J. KE_max=6.63×10⁻¹⁹−3.978×10⁻¹⁹=2.652×10⁻¹⁹J."},{"ch":"g6c6","q":"(سؤال وزاري، الدور الأول 2021) سقط ضوء λ=400nm على الصوديوم، فانبعثت إلكترونات طاقتها الحركية العظمى 0.8eV. جد دالة الشغل للصوديوم بوحدة eV.","opts":["≈0.8 eV","≈3.11 eV","≈2.31 eV","≈1.5 eV"],"a":2,"why":"hf=hc/λ=4.9725×10⁻¹⁹J≈3.108eV. W₀=hf−KE_max=3.108−0.8≈2.31eV."},{"ch":"g6c6","q":"(سؤال وزاري، التمهيدي 2021) سقط ضوء λ=100nm على معدن دالة شغله 1.67×10⁻¹⁹J. جد الانطلاق الأعظم للإلكترونات المنبعثة تقريباً.","opts":["≈2×10¹⁰ m/s","≈2×10⁸ m/s","≈2×10⁴ m/s","≈2×10⁶ m/s"],"a":3,"why":"KE_max=hc/λ−W₀=1.989×10⁻¹⁸−0.167×10⁻¹⁸=1.822×10⁻¹⁸J. من KE_max=½mv²: v=√(2×KE_max/m)≈2×10⁶m/s."},{"ch":"g6c6","q":"(سؤال وزاري، التمهيدي 2019 — نمط بالتردد) سقط ضوء تردده 0.75×10¹⁵Hz على معدن، وجهد القطع اللازم 0.3V. جد التردد الحرج لهذا المعدن.","opts":["≈0.678×10¹⁵ Hz","≈0.75×10¹⁵ Hz","≈0.072×10¹⁵ Hz","≈1.428×10¹⁵ Hz"],"a":0,"why":"KE_max=eV_s=4.8×10⁻²⁰J. f₀=f−KE_max/h=0.75×10¹⁵−0.0724×10¹⁵≈0.678×10¹⁵Hz."},{"ch":"g6c6","q":"برسم بياني، يمر خط KE_max−f لفلز بنقطتين: (f=5×10¹⁴Hz, KE_max=0) و(f=10×10¹⁴Hz, KE_max≈2.07eV). جد ثابت بلانك h التقريبي (بوحدة eV.s).","opts":["≈2.07×10⁻¹⁴ eV.s","≈4.14×10⁻¹⁵ eV.s","≈6.63×10⁻³⁴ eV.s","≈5×10¹⁴ eV.s"],"a":1,"why":"h = ΔKE_max/Δf = 2.07/(5×10¹⁴) ≈ 4.14×10⁻¹⁵ eV.s — القيمة المعروفة لثابت بلانك بوحدة eV.s."},{"ch":"g6c6","q":"أي مما يلي تطبيق عملي شائع للظاهرة الكهروضوئية؟","opts":["توليد المجال المغناطيسي بالمحول الكهربائي","تسخين الطعام بفرن المايكرويف","الألواح الشمسية وأجهزة الإنذار الضوئية والكاميرات الرقمية (CCD)","شحن المتسعة بدائرة RC"],"a":2,"why":"هذه التطبيقات الثلاثة كلها تعتمد على تحويل الفوتونات الساقطة إلى تيار كهربائي عبر الظاهرة الكهروضوئية."},{"ch":"g6c6","q":"(سؤال وزاري متكرر جداً، الدور الثالث 2023 · الدور الثاني 2018 وغيرها) ما النظرة الحديثة لطبيعة الضوء؟","opts":["لا علاقة للضوء بالموجات أو الجسيمات","موجة خالصة بلا أي طبيعة جسيمية إطلاقاً","جسيم خالص بلا أي طبيعة موجية إطلاقاً","طبيعة مزدوجة: موجة بالتداخل والحيود، وجسيم (فوتون) بالظاهرة الكهروضوئية"],"a":3,"why":"الضوء له طبيعة مزدوجة (ثنائية): يسلك سلوك الموجات بالتداخل والحيود والاستقطاب، وسلوك الجسيمات (الفوتونات) بالظاهرة الكهروضوئية."},{"ch":"g6c6","q":"ما زخم فوتون طاقته E؟","opts":["p = E/c","p = Ec","p = E×c²","p = c/E"],"a":0,"why":"من p=h/λ وE=hc/λ، نستنتج p=E/c مباشرة."},{"ch":"g6c6","q":"فوتون طوله الموجي λ=2nm. جد زخمه تقريباً (h=6.63×10⁻³⁴J.s).","opts":["≈1.33×10⁻²⁴ kg·m/s","≈3.32×10⁻²⁵ kg·m/s","≈6.63×10⁻³⁴ kg·m/s","≈2×10⁻⁹ kg·m/s"],"a":1,"why":"p = h/λ = (6.63×10⁻³⁴)/(2×10⁻⁹) ≈ 3.32×10⁻²⁵ kg·m/s."},{"ch":"g6c6","q":"(سؤال وزاري مركّب — زخم الفوتون + الكهروضوئية) سقط ضوء زخم فوتونه 3.32×10⁻²⁷kg·m/s على الصوديوم، فكانت KE_max=2.75×10⁻¹⁹J. جد دالة الشغل للصوديوم.","opts":["≈2.75×10⁻¹⁹ J","≈9.96×10⁻¹⁹ J","≈7.21×10⁻¹⁹ J","≈1.66×10⁻¹⁸ J"],"a":2,"why":"E=pc=3.32×10⁻²⁷×3×10⁸=9.96×10⁻¹⁹J. W₀=E−KE_max=9.96×10⁻¹⁹−2.75×10⁻¹⁹=7.21×10⁻¹⁹J."},{"ch":"g6c6","q":"(سؤال وزاري، التمهيدي 2018) ما المقصود بـ: فرضية دي برولي؟","opts":["الطاقة تُشعّ بشكل متصل لا كمّات منفصلة","الضوء موجة خالصة بلا أي طبيعة جسيمية","لا يمكن لأي جسيم مادي أن يتصرف كموجة إطلاقاً","لكل جسيم مادي متحرك سلوك موجي مرافق، طوله الموجي λ=h/mv"],"a":3,"why":"فرضية دي برولي: لكل جسيم مادي متحرك (كتلته m وسرعته v) سلوك موجي مرافق طوله λ=h/mv=h/p."},{"ch":"g6c6","q":"(سؤال وزاري، التمهيدي 2017) إلكترون يتحرك بانطلاق 6×10⁶m/s. جد طول موجة دي برولي المرافقة له تقريباً.","opts":["≈1.21×10⁻¹⁰ m","≈6.63×10⁻³⁴ m","≈5.47×10⁻²⁴ m","≈1.21×10⁻⁷ m"],"a":0,"why":"λ=h/mv=(6.63×10⁻³⁴)/(9.11×10⁻³¹×6×10⁶)≈1.21×10⁻¹⁰m — نحو نصف قطر ذرة الهيدروجين تقريباً."},{"ch":"g6c6","q":"إلكترون عُجِّل من السكون بفرق جهد V=100V. جد طول موجة دي برولي المرافقة له تقريباً.","opts":["≈1.23 nm","≈0.123 nm","≈0.0123 nm","≈123 nm"],"a":1,"why":"v=√(2eV/m)≈5.93×10⁶m/s، ثم λ=h/(mv)≈1.23×10⁻¹⁰m=0.123nm."},{"ch":"g6c6","q":"لماذا لا نلاحظ أي سلوك موجي محسوس لكرة متحركة رغم انطباق فرضية دي برولي عليها نظرياً؟","opts":["لأن فرضية دي برولي تخص الفوتونات فقط","لأن الكرة لا تملك زخماً خطياً","كتلتها كبيرة جداً مقارنة بثابت بلانك، فطول موجتها المرافق ضئيل جداً يستحيل رصده","لأن سرعة الكرة أكبر من سرعة الضوء"],"a":2,"why":"λ=h/mv يتناسب عكسياً مع الكتلة؛ كتلة الكرة الكبيرة تجعل λ أصغر من نواة الذرة بمراحل، فلا يمكن رصده."},{"ch":"g6c6","q":"(سؤال وزاري، الدور الأول 2019) علامَ تدل قيمة كبيرة لـ|ψ|² لجسيم بمكان وزمان معيّنين؟","opts":["على أن الجسيم يتحرك بسرعة الضوء بالضبط","على أن الجسيم غير موجود إطلاقاً هناك","على أن طاقة الجسيم تساوي صفراً","على احتمالية كبيرة للعثور على الجسيم في ذلك المكان وتلك اللحظة"],"a":3,"why":"تفسير بورن الاحتمالي: كثافة الاحتمال |ψ|² تتناسب طردياً مع احتمالية العثور على الجسيم في تلك المنطقة وتلك اللحظة."},{"ch":"g6c6","q":"بالوصف الكمّي الحديث لذرة الهيدروجين (بعكس نموذج بور)، كيف يوصف موضع الإلكترون؟","opts":["بسحابة احتمال |ψ|² حول النواة، لا بمدار دائري محدد الشكل بدقة تامة","بمدار دائري ثابت نصف قطره محدد بدقة تامة دائماً كما بنموذج بور","بنقطة ساكنة تماماً داخل النواة نفسها","لا يوجد له أي وصف علمي ممكن"],"a":0,"why":"الوصف الكمي يستبدل مدار بور الحاد بسحابة احتمال ضبابية |ψ|²، أعلى كثافة قرب نصف قطر بور الكلاسيكي لكن مع احتمال ضئيل بمناطق أخرى."},{"ch":"g6c6","q":"ما الصيغة الرياضية الصحيحة لمبدأ هايزنبرغ للادقة؟","opts":["Δx + Δp ≥ h","Δx · Δp ≥ h/4π","Δx · Δp = 0 دائماً","Δx − Δp ≥ h/4π"],"a":1,"why":"حاصل ضرب اللادقة بالموضع Δx واللادقة بالزخم Δp لا يقل أبداً عن h/4π."},{"ch":"g6c6","q":"(سؤال وزاري، التمهيدي 2018 · الدور الثالث 2019) ما المقصود بـ: مبدأ اللادقة لهايزنبرك؟","opts":["استحالة قياس أي كمية فيزيائية بأي دقة إطلاقاً","إمكانية تحديد موضع الجسيم وزخمه بدقة تامة معاً دائماً","استحالة تحديد موضع الجسيم وزخمه بدقة تامة في الوقت نفسه","مبدأ يخص فقط الأجسام الكبيرة لا الجسيمات دون الذرية"],"a":2,"why":"مبدأ اللادقة: يستحيل تحديد موضع الجسيم وزخمه بدقة تامة بآنٍ واحد؛ حاصل ضرب اللادقتين لا يقل عن h/4π."},{"ch":"g6c6","q":"(اختيار وزاري، التمهيدي 2019) إذا قيس موضع جسيم بدقة تامة (Δx=0)، فإن أقل دقة لزخمه تساوي:","opts":["h/2π","صفر","h/4π","ما لا نهاية"],"a":3,"why":"من Δx·Δp≥h/4π، إذا Δx=0 فلا بد أن يؤول Δp إلى ما لا نهاية — أي انعدام الدقة كلياً بمعرفة الزخم."},{"ch":"g6c6","q":"بروتون محصور بمنطقة عرضها Δx=5×10⁻¹⁵m (بحجم النواة). جد أدنى لادقة ممكنة بزخمه Δp تقريباً.","opts":["≈1.05×10⁻²⁰ kg·m/s","≈6.63×10⁻³⁴ kg·m/s","≈5×10⁻¹⁵ kg·m/s","≈2.1×10⁻²⁰ kg·m/s"],"a":0,"why":"Δp_min = h/(4πΔx) = (6.63×10⁻³⁴)/(4π×5×10⁻¹⁵) ≈ 1.05×10⁻²⁰ kg·m/s."},{"ch":"g6c6","q":"بنفس المسألة أعلاه (Δp_min≈1.05×10⁻²⁰kg·m/s) وكتلة البروتون 1.67×10⁻²⁷kg، جد أدنى لادقة ممكنة بسرعته.","opts":["≈1.05×10⁻²⁰ m/s","≈6.3×10⁶ m/s","≈1.67×10⁻²⁷ m/s","≈6.3×10⁻⁴⁷ m/s"],"a":1,"why":"Δv_min = Δp_min/m = (1.05×10⁻²⁰)/(1.67×10⁻²⁷) ≈ 6.3×10⁶ m/s — كبيرة رغم أن البروتون أثقل من الإلكترون بـ1836 مرة، لأن الحصر هنا بمقياس نووي دقيق جداً."},{"ch":"g6c6","q":"ماذا تعني الصيغة المرافقة لمبدأ اللادقة: ΔE·Δt≥h/4π؟","opts":["لا يمكن قياس الزمن بدقة تامة أبداً بأي حال","الطاقة والزمن لا علاقة بينهما إطلاقاً بميكانيكا الكم","كلما قصرت مدة قياس طاقة نظام ما، كبرت اللادقة بقيمة تلك الطاقة بالضرورة","الطاقة ثابتة دائماً بغض النظر عن زمن القياس"],"a":2,"why":"علاقة اللادقة بين الطاقة والزمن: قياس طاقة نظام خلال فترة قصيرة جداً يترافق حتماً بلادقة كبيرة بقيمة تلك الطاقة."},{"ch":"g6c6","q":"لماذا لا يُعدّ مبدأ اللادقة لهايزنبرغ قصوراً تقنياً يمكن حله بجهاز قياس أدق مستقبلاً؟","opts":["لأن العلماء لم يحاولوا بعد تطوير أجهزة أدق","لأن كل الأجهزة الحالية دقيقة تماماً بلا أي خطأ","لأنه ينطبق فقط على الأجسام الكبيرة لا الجسيمات الصغيرة","لأنه نتيجة حتمية للطبيعة الموجية الأساسية للجسيمات نفسها، لا لعيب بأي جهاز قياس"],"a":3,"why":"اللادقة نابعة من كون الجسيم موجة ممتدة بالفضاء أصلاً (فرضية دي برولي)، فلا يمكن لأي جهاز — مهما تطوّر — أن يتجاوز هذا القيد الطبيعي الأساسي."},{"ch":"g6c6","q":"رتّب هذه الاكتشافات حسب تسلسلها الزمني الصحيح: فرضية بلانك، تفسير أينشتاين الكهروضوئي، فرضية دي برولي، مبدأ هايزنبرغ.","opts":["بلانك (1900) ← أينشتاين (1905) ← دي برولي (1923) ← هايزنبرغ (1927)","هايزنبرغ ← دي برولي ← أينشتاين ← بلانك","أينشتاين ← بلانك ← هايزنبرغ ← دي برولي","دي برولي ← بلانك ← هايزنبرغ ← أينشتاين"],"a":0,"why":"التسلسل التاريخي الصحيح: بلانك 1900 (فرضية الكم) ← أينشتاين 1905 (الظاهرة الكهروضوئية) ← دي برولي 1923 (الموجات المادية) ← هايزنبرغ 1927 (مبدأ اللادقة)."},{"ch":"g6c6","q":"ما القاسم المشترك بين القوانين الرئيسية بهذا الفصل: E=hf، hf=W₀+KE_max، p=h/λ، λ=h/mv، وΔx·Δp≥h/4π؟","opts":["لا علاقة بين هذه القوانين إطلاقاً","تحتوي جميعها على ثابت بلانك h، مؤكدة أنه المفتاح الأساسي للفيزياء الحديثة","جميعها تخص الجسيمات المشحونة كهربائياً فقط","جميعها لا تنطبق إلا على الإلكترون تحديداً"],"a":1,"why":"ثابت بلانك h يظهر بكل قوانين هذا الفصل — من تكميم الطاقة، إلى الظاهرة الكهروضوئية، إلى زخم الفوتون والموجات المادية، إلى مبدأ اللادقة."},{"ch":"g6c6","q":"الفوتون والإلكترون كلاهما يُظهران ثنائية موجة-جسيم. ما وجه الشبه المفاهيمي الدقيق بينهما بهذا الفصل؟","opts":["كلاهما لا يتفاعل مع المادة إطلاقاً","كلاهما عديم الكتلة تماماً بكل الحالات","كل منهما يملك خاصية جسيمية (طاقة أو زخم) مرتبطة بخاصية موجية (تردد أو طول موجي) عبر ثابت بلانك h نفسه","كلاهما يتحرك دائماً بسرعة الضوء بالضبط"],"a":2,"why":"للفوتون: E=hf وp=h/λ. للإلكترون (وأي جسيم مادي): λ=h/p. نفس ثابت بلانك h يربط الصفتين الجسيمية والموجية بكلا الحالتين."},{"ch":"g6c6","q":"(سؤال وزاري، الدور الأول 2021 · التمهيدي 2018) ما الذي أضافته النظرية النسبية للمفاهيم الكلاسيكية؟","opts":["مبدأ حفظ الطاقة نفسه لأول مرة","المكان كبُعد خامس منفصل عن الزمن كلياً","فكرة أن الطاقة تُمتص وتُصدر بكمّات منفصلة","الزمن كبُعدٍ رابع يتشابك مع الأبعاد المكانية الثلاثة، بدلاً من كونه كمّية مطلقة منفصلة"],"a":3,"why":"أضافت النظرية النسبية الزمن كبُعد رابع (x,y,z,t) متشابك مع المكان — لا كمّية مطلقة منفصلة كما بالفيزياء الكلاسيكية."},{"ch":"g6c6","q":"(سؤال وزاري، التمهيدي 2022–2023 · الدور الأول 2020 · الدور الثاني التكميلي 2021) ما هما فرضيتا آينشتاين في النظرية النسبية الخاصة؟","opts":["مبدأ النسبية (قوانين الفيزياء واحدة بكل الأطر العطالية) وثبات سرعة الضوء لكل المراقبين","ثبات الزمن المطلق وثبات المكان المطلق لكل المراقبين","قانون حفظ الطاقة وقانون حفظ الزخم فقط","فرضية بلانك وفرضية دي برولي"],"a":0,"why":"الفرضية الأولى: قوانين الفيزياء واحدة بجميع الأطر العطالية. الفرضية الثانية: سرعة الضوء بالفراغ (3×10⁸m/s) ثابتة لجميع المراقبين."},{"ch":"g6c6","q":"(سؤال وزاري، التمهيدي 2022) ما المقصود بتحويلات لورنتز؟","opts":["معادلات تصف فقط حركة الأقمار الصناعية حول الأرض","معادلات تربط إحداثيات الحدث (الموقع والزمن) بين إطارين عطاليين يتحرك أحدهما بالنسبة للآخر بسرعة v","قانون يربط بين شدة الضوء وتردده فقط","معادلات تحويل الوحدات بين النظامين المتري والإنكليزي"],"a":1,"why":"تحويلات لورنتز تربط إحداثيات الحدث كما يقيسها مراقبان بإطارين عطاليين مختلفين، وتحلّ محلّ تحويلات غاليليو الكلاسيكية."},{"ch":"g6c6","q":"ما الصيغة الرياضية الصحيحة لعامل لورنتز γ؟","opts":["γ = v/c","γ = 1 − v²/c²","γ = 1/√(1 − v²/c²)","γ = c/v"],"a":2,"why":"γ = 1/√(1−v²/c²) — يساوي 1 عند السكون تقريباً، ويكبر بلا حدود كلما اقتربت v من c."},{"ch":"g6c6","q":"(سؤال وزاري، 2013 · 2016 و2017 خارج القطر · التطبيقي 2019) ما الفرق الأساسي بين تحويلات غاليليو والتحويلات النسبية (لورنتز)؟","opts":["لورنتز أقدم زمنياً من غاليليو بقرون","غاليليو تخص المادة فقط ولورنتز تخص الضوء فقط","لا فرق عملي بينهما بأي سرعة كانت","المقدار γ (عامل لورنتز)، الذي يؤثر بزخم الجسم وطوله وكتلته والزمن المقاس له"],"a":3,"why":"تحويلات غاليليو لا تتضمّن γ إطلاقاً (تفترض زمناً وطولاً وكتلة مطلقة)، بينما تحويلات لورنتز تُدخله فيؤثر على هذه المقادير عند السرعات القريبة من سرعة الضوء."},{"ch":"g6c6","q":"(سؤال وزاري — اختيار من متعدد) سفينة فضائية طولها بالسكون 40m تتحرك بسرعة 0.8c. كم يصبح طولها كما يقيسه مراقب ساكن على الأرض؟","opts":["24 m","18 m","20 m","40 m"],"a":0,"why":"L=L₀√(1−v²/c²)=40×√(1−0.64)=40×0.6=24 m."},{"ch":"g6c6","q":"جسيم كتلته بالسكون m₀=2kg يتحرك بسرعة v=0.6c. جد كتلته النسبية كما يقيسها مراقب ساكن.","opts":["1.6 kg","2.5 kg","2 kg","3.33 kg"],"a":1,"why":"γ=1/√(1−0.36)=1/0.8=1.25. m=m₀γ=2×1.25=2.5 kg."},{"ch":"g6c6","q":"إذا تحوّلت كتلة مقدارها 1 gram بالكامل إلى طاقة وفق E=mc²، فما مقدار هذه الطاقة تقريباً؟","opts":["≈1×10⁻³ J","≈3×10⁸ J","≈9×10¹³ J","≈9×10¹⁶ J"],"a":2,"why":"E=mc²=1×10⁻³×(3×10⁸)²=1×10⁻³×9×10¹⁶=9×10¹³ J — طاقة تكفي بيتاً عراقياً نحو ألفي سنة!"},{"ch":"g6c6","q":"لماذا يستحيل عملياً أن يبلغ جسمٌ له كتلة سكون سرعة الضوء؟","opts":["لأن الجاذبية الأرضية وحدها تمنع هذا الأمر","لأن سرعة الضوء نفسها ليست ثابتة فعلياً","لأن قوانين نيوتن الثلاث تمنع ذلك صراحة","لأن عامل لورنتز γ يؤول إلى ما لا نهاية عند v→c، فتزداد كتلته النسبية بلا حدود وتحتاج طاقة غير منتهية لتسريعه أكثر"],"a":3,"why":"بما أن m=m₀γ وγ يكبر بلا حدود عند v→c، تحتاج زيادة سرعة الجسم أكثر إلى طاقة غير منتهية — مستحيل عملياً بأي مصدر طاقة محدود."},{"ch":"g6c7","q":"من اخترع أول ترانزستور عام 1947، وأين؟","opts":["توماس إديسون، بمختبره الخاص","ماكس بلانك، بجامعة برلين","باردين وبراتين وشوكلي، بمختبرات Bell","ألبرت أينشتاين، بجامعة برينستون"],"a":2,"why":"اخترع العلماء باردين وبراتين وشوكلي أول ترانزستور بمختبرات Bell عام 1947، بديلاً عن الصمام المفرغ."},{"ch":"g6c7","q":"ما أبرز عيوب الصمام المفرغ (Vacuum Tube) مقارنة بالترانزستور؟","opts":["حجم كبير، استهلاك طاقة عالٍ لتسخين الفتيل، وعمر قصير","حجم أصغر من الترانزستور بكثير","لا يحتاج أي طاقة كهربائية للعمل","لا يُستخدم إطلاقاً بأي جهاز إلكتروني قديم"],"a":0,"why":"الصمام المفرغ كبير الحجم، يحتاج فتيلاً ساخناً يستهلك طاقة عالية، ويحترق ويتعطّل بسرعة نسبياً — عكس الترانزستور الصلب المدمج."},{"ch":"g6c7","q":"ماذا يعني وصف إلكترونيات اليوم بـ«إلكترونيات الحالة الصلبة»؟","opts":["أنها إلكترونيات لا تعمل إلا بدرجات حرارة متجمدة","أنها إلكترونيات مصنوعة بالكامل من المعادن الصلبة فقط","أنها إلكترونيات لا تحتوي أي إلكترونات متحركة إطلاقاً","أنها تُبنى من نبائط مصنوعة من مواد صلبة بلورية (كأشباه الموصلات)، لا من صمامات مفرغة من الهواء"],"a":3,"why":"«الحالة الصلبة» تعني أن التحكم بالتيار يتم داخل بلورة مادة صلبة (شبه موصل) بدل أنبوب مفرغ من الهواء يحوي فتيلاً ساخناً."},{"ch":"g6c7","q":"وفق النموذج الذري، متى يمكن لإلكترون أن ينتقل من مستوى طاقة إلى آخر أعلى؟","opts":["في أي وقت وبأي مقدار طاقة يكتسبه","فقط إذا اكتسب طاقة تساوي بالضبط الفرق بين المستويين","لا يمكن للإلكترون الانتقال بين المستويات إطلاقاً","فقط إذا فقد طاقة، لا إذا اكتسبها"],"a":1,"why":"مستويات الطاقة مكمّمة ومنفصلة؛ لا ينتقل الإلكترون إلا إذا اكتسب طاقة تساوي بالضبط فرق الطاقة بين المستويين، لا أقل ولا أكثر."},{"ch":"g6c7","q":"لماذا ينشطر مستوى الطاقة الواحد إلى عدة مستويات متقاربة جداً عندما تتقارب N ذرة في بلورة؟","opts":["بسبب مبدأ باولي للاستبعاد: لا يمكن لإلكترونين متطابقين بالبلورة أن يشغلا نفس مستوى الطاقة بالضبط","لأن الذرات تفقد إلكتروناتها كلياً عند التقارب","لأن درجة حرارة البلورة تنخفض دائماً عند تقارب الذرات","لا علاقة لعدد الذرات بعدد مستويات الطاقة إطلاقاً"],"a":0,"why":"مبدأ باولي يمنع تطابق الحالات الكمية لإلكترونين بنفس النظام، فيضطر كل مستوى مشترك أصلاً بين N ذرة للانشطار إلى N مستوى متمايز طفيفاً عن بعضه."},{"ch":"g6c7","q":"طاقة الإلكترون بمستواه الأرضي في ذرة الهيدروجين تساوي −13.6eV. كم مقدار الطاقة اللازمة لتحريره تماماً من الذرة (نقله إلى المستوى الصفري E=0)؟","opts":["−13.6 eV","0 eV","+13.6 eV","+27.2 eV"],"a":2,"why":"الانتقال من −13.6eV إلى المستوى الصفري E=0 يتطلب اكتساب فرق الطاقة نفسه بالضبط: 0−(−13.6)=+13.6eV."},{"ch":"g6c7","q":"فوتون طاقته 4×10⁻¹⁹J يمكن أن ينقل إلكتروناً بين مستويين طاقتهما تفصل بينهما بالضبط بنفس المقدار. ماذا يحدث لو كانت طاقة الفوتون الساقط أكبر أو أصغر من هذا الفرق؟","opts":["يُمتص الفوتون دائماً بغض النظر عن طاقته","ينتقل الإلكترون دائماً مهما كانت طاقة الفوتون","لا يُمتص الفوتون ولا ينتقل الإلكترون بينهما","تنبعث طاقة إضافية من الذرة تلقائياً لتعويض الفرق"],"a":2,"why":"الانتقال بين مستويين مكمّمين يتطلب طاقة تساوي الفرق بالضبط؛ أي طاقة أخرى (أكبر أو أصغر) لا تُمتص لإحداث هذا الانتقال المحدد."},{"ch":"g6c7","q":"ما تعريف «حزمة التوصيل»؟","opts":["حزمة الطاقة التي تحتوي إلكترونات مرتبطة بالروابط بين الذرات فقط","حزمة الطاقة التي يصبح فيها الإلكترون حراً تماماً ويساهم في التيار الكهربائي","المدى الممنوع كلياً على أي إلكترون أن يشغله","حزمة موجودة فقط بالعوازل دون غيرها"],"a":1,"why":"حزمة التوصيل هي الحزمة التي يتحرر فيها الإلكترون من قيد ذرته ويصبح قادراً على التحرك بحرية عبر البلورة، مساهماً بالتيار."},{"ch":"g6c7","q":"ما الذي يحدد ما إذا كانت المادة موصلاً أم عازلاً أم شبه موصل؟","opts":["عدد بروتونات نواة الذرة فقط","لون المادة الظاهري للعين المجردة","درجة انصهار المادة فقط","حجم الفجوة الطاقية المحرمة Eg بين حزمتي التكافؤ والتوصيل"],"a":3,"why":"حجم الفجوة الطاقية Eg هو الفيصل: صفر تقريباً (موصل)، صغيرة (شبه موصل)، كبيرة (عازل)."},{"ch":"g6c7","q":"فجوة الطاقة للجرمانيوم Eg≈0.72eV، بينما فجوة الماس Eg≈5.5eV. ماذا يعني هذا الفرق عملياً؟","opts":["الجرمانيوم شبه موصل يوصل التيار بسهولة نسبية أكبر بكثير من الماس العازل التام تقريباً","كلاهما موصل ممتاز بنفس الكفاءة تماماً","كلاهما عازل تام بنفس الدرجة","لا علاقة بين قيمة Eg وسلوك المادة الكهربائي إطلاقاً"],"a":0,"why":"فجوة الجرمانيوم صغيرة (سلوك شبه موصل)، بينما فجوة الماس كبيرة جداً (سلوك عازل) — فرق يعكس مباشرة سهولة أو صعوبة قفز الإلكترونات لحزمة التوصيل."},{"ch":"g6c7","q":"فجوة طاقية Eg=2eV. جد أطول طول موجي لفوتون قادر على نقل إلكترون عبر هذه الفجوة تقريباً.","opts":["≈1130 nm","≈300 nm","≈622 nm","≈2000 nm"],"a":2,"why":"λ_max=hc/Eg=(6.63×10⁻³⁴×3×10⁸)/(2×1.6×10⁻¹⁹)≈6.22×10⁻⁷m=622nm."},{"ch":"g6c7","q":"لماذا تُعد أشباه الموصلات (كالسيليكون) أساس صناعة الإلكترونيات الحديثة، لا الموصلات ولا العوازل؟","opts":["لأنها أرخص عنصر متوفر على وجه الأرض فقط","لأنها توصل الكهرباء أفضل من كل الفلزّات المعروفة","لأنها لا تتأثر بالحرارة أو الضوء إطلاقاً","لأن توصيليتها بين الحالتين، ويمكن التحكم بها بدقة (بالحرارة أو التطعيم أو الضوء)، بعكس الموصل الثابت التوصيل دوماً أو العازل عديم التوصيل دوماً"],"a":3,"why":"المرونة في التحكم بتوصيلية أشباه الموصلات (تحكماً دقيقاً غير ممكن بالموصل الدائم التوصيل ولا بالعازل الدائم العزل) هي ما يجعلها أساس بناء نبائط إلكترونية قابلة للتحكم كالثنائي والترانزستور."},{"ch":"g6c7","q":"لماذا تمتلك الفلزّات الموصلة أعداداً هائلة من الإلكترونات الحرة المتاحة للتوصيل دوماً؟","opts":["لأن كل ذرة منها تملك إلكترون تكافؤ واحداً فقط، ضعيف الارتباط بالنواة فيتحرر بسهولة فائقة","لأن ذرات الفلز لا تملك أي إلكترونات تكافؤ إطلاقاً","لأن الفلزّات لا تحتوي أي بروتونات بنواتها","لأن حزمة التكافؤ في الفلز فارغة تماماً دوماً"],"a":0,"why":"ذرّة الفلز الموصل تمتلك إلكترون تكافؤ واحداً يرتبط ارتباطاً ضعيفاً جداً بالنواة، فيتحرر بسهولة ويصير حرّ الحركة."},{"ch":"g6c7","q":"كم إلكترون تكافؤ تملكه ذرة السيليكون الواحدة، وكم رابطة تساهمية تكوّنها مع جاراتها بالبلورة؟","opts":["إلكترون تكافؤ واحد، ورابطة واحدة فقط","٤ إلكترونات تكافؤ، و٤ روابط تساهمية","٨ إلكترونات تكافؤ، و٨ روابط","٢ إلكترون تكافؤ، ولا روابط تساهمية إطلاقاً"],"a":1,"why":"السيليكون من المجموعة الرابعة، فله ٤ إلكترونات تكافؤ، يكوّن بها ٤ روابط تساهمية مع ٤ ذرات مجاورة."},{"ch":"g6c7","q":"ما الذي يبقيه انكسار رابطة تساهمية واحدة في بلورة سيليكون نقي عند تسخينها؟","opts":["إلكترونين حرّين بلا أي فجوة","فجوتين بلا أي إلكترون حر","لا شيء؛ تختفي الطاقة تماماً","إلكتروناً حراً واحداً وفجوة واحدة معاً"],"a":3,"why":"انكسار الرابطة يحرر إلكتروناً واحداً (يصبح حراً) ويترك مكانه فارغاً (فجوة) — زوج واحد من كل نوع."},{"ch":"g6c7","q":"لماذا تتصرف «الفجوة» عملياً وكأنها جسيم موجب الشحنة يتحرك بالبلورة؟","opts":["لأن إلكترونات الروابط المجاورة السليمة تقفز تباعاً لملء الفجوة، تاركة فجوات جديدة خلفها — فتبدو الفجوة وكأنها تنتقل بعكس اتجاه حركة الإلكترونات","لأن الفجوة فعلياً جسيم موجب الشحنة الحقيقية مثل البروتون تماماً","لأن الفجوة أثقل من الإلكترون بآلاف المرات","لأن الفجوة لا تتحرك إطلاقاً داخل البلورة"],"a":0,"why":"الفجوة ليست جسيماً حقيقياً، بل مكان شاغر ينتقل ظاهرياً عبر «تتابع قفزات» إلكترونات الروابط المجاورة، بحركة معاكسة لحركة الإلكترونات — فتُسهم بالتيار كأنها شحنة موجبة متحركة."},{"ch":"g6c7","q":"قيس تركيز الفجوات في بلورة جرمانيوم نقي فوُجد 2.4×10¹⁹ فجوة/m³. ما تركيز الإلكترونات الحرة في نفس البلورة؟","opts":["صفر","أكبر من تركيز الفجوات بكثير","2.4×10¹⁹ إلكترون/m³ (مساوٍ تماماً)","أصغر من تركيز الفجوات بكثير"],"a":2,"why":"في شبه الموصل النقي (الذاتي) n=p دوماً، لأن كل رابطة منكسرة تنتج زوجاً واحداً بالتساوي."},{"ch":"g6c7","q":"لماذا تتصرف بلورة سيليكون نقي عند درجة حرارة الصفر المطلق (0K) كعازل تقريباً تام؟","opts":["لأن ذرات السيليكون تتفكك تماماً عند هذه الدرجة","لأن كل الإلكترونات مقيّدة تماماً داخل روابطها التساهمية، ولا توجد طاقة حرارية كافية لكسر أي رابطة وتحرير حاملات شحنة","لأن السيليكون يتحول لفلز موصل عند هذه الدرجة تحديداً","لأن الفجوات تختفي كلياً عند التبريد الشديد فقط"],"a":1,"why":"بلا طاقة حرارية كافية، تبقى كل الروابط التساهمية سليمة وكل الإلكترونات مقيّدة بها — أي لا حاملات شحنة حرة، فتنعدم التوصيلية تقريباً."},{"ch":"g6c7","q":"أين يقع مستوى فيرمي في شبه الموصل النقي (الذاتي)؟","opts":["فوق حزمة التوصيل مباشرة","أسفل حزمة التكافؤ مباشرة","خارج البلورة كلياً","في منتصف ثغرة الطاقة المحظورة، بين حزمتي التوصيل والتكافؤ بالضبط"],"a":3,"why":"في شبه الموصل النقي، يقع مستوى فيرمي في منتصف الفجوة الطاقية بالضبط — بعكس الموصل حيث يقع ضمن حزمة التوصيل نفسها."},{"ch":"g6c7","q":"فجوة الجرمانيوم عند 300K تساوي 0.72eV مقابل 1.1eV للسيليكون. ماذا يعني هذا؟","opts":["الجرمانيوم يحتاج طاقة أقل لتوليد زوج (إلكترون-فجوة) من السيليكون","السيليكون يحتاج طاقة أقل من الجرمانيوم","كلاهما يحتاجان الطاقة نفسها بالضبط","لا علاقة بين قيمة الفجوة وسهولة توليد الأزواج"],"a":0,"why":"الجرمانيوم فجوته الطاقية أصغر (0.72eV<1.1eV)، فيحتاج طاقة أقل لكسر رابطة وتوليد زوج (إلكترون-فجوة)."},{"ch":"g6c7","q":"ماذا نسمي عملية إضافة كمية صغيرة ومضبوطة من عنصر شائبة إلى بلورة شبه موصل نقي؟","opts":["التبريد","التطعيم (Doping)","التبخير","الانصهار"],"a":1,"why":"التطعيم هو الاسم العلمي لإضافة شوائب متحكَّم بها لتغيير توصيلية شبه الموصل ونوع حامل الشحنة الغالب فيه."},{"ch":"g6c7","q":"لتكوين شبه موصل من النوع n، أي عنصر يجب أن نطعّم به السيليكون؟","opts":["عنصر ثلاثي التكافؤ (٣ إلكترونات تكافؤ) كالبورون","عنصر رباعي التكافؤ نفسه كالسيليكون تماماً","أي غاز خامل بلا إلكترونات تكافؤ إطلاقاً","عنصر خماسي التكافؤ (٥ إلكترونات تكافؤ) كالزرنيخ أو الفوسفور"],"a":3,"why":"الشائبة الخماسية التكافؤ تمنح إلكتروناً خامساً زائداً بعد تكوين ٤ روابط، فينتج فائض إلكترونات حرة — النوع n."},{"ch":"g6c7","q":"لماذا تُسمى ذرة الشائبة الثلاثية التكافؤ (كالبورون) «ذرة مستقبِلة»؟","opts":["لأنها جاهزة لاستقبال إلكترون من رابطة مجاورة يملأ فجوتها الناقصة","لأنها تمنح إلكتروناً إضافياً للبلورة","لأنها تستقبل فوتونات الضوء فقط دون أي دور كهربائي","لأنها تطرد كل الإلكترونات المجاورة لها"],"a":0,"why":"الشائبة الثلاثية التكافؤ تترك رابطة ناقصة إلكتروناً (فجوة)، جاهزة «لاستقبال» أي إلكترون مجاور يقفز إليها — لذا تُسمى مستقبِلة."},{"ch":"g6c7","q":"ما حاملات الشحنة الأغلبية في شبه موصل من النوع p؟","opts":["الإلكترونات الحرة فقط","البروتونات الحرة المتحركة","الفجوات (حاملات موجبة)","النيوترونات الحرة المتحركة"],"a":2,"why":"في النوع p، التطعيم بعنصر ثلاثي التكافؤ يولّد فائضاً كبيراً من الفجوات — فهي حاملات الشحنة الأغلبية."},{"ch":"g6c7","q":"قطعة سيليكون مطعّمة بالنوع n. أي عبارة صحيحة بخصوص شحنتها الكلية؟","opts":["سالبة الشحنة الصافية بمقدار كبير","متعادلة كهربائياً تماماً، رغم فائض الإلكترونات الحرة فيها","موجبة الشحنة الصافية بمقدار كبير","لا يمكن تحديد شحنتها الكلية إطلاقاً"],"a":1,"why":"التطعيم لا يضيف أي شحنة صافية؛ ذرة الشائبة متعادلة أصلاً، فيبقى صافي شحنة البلورة كلها صفراً، رغم تغيّر توزيع حاملات الشحنة الحرة."},{"ch":"g6c7","q":"ما الفرق الجوهري بين حاملات الشحنة الأقلية في النوع n وحاملات الشحنة الأغلبية فيه؟","opts":["لا فرق إطلاقاً بينهما بأي شيء","الأقلية أكبر عدداً من الأغلبية دوماً بالنوع n","الأغلبية فجوات، والأقلية إلكترونات بالنوع n","الأقلية (فجوات قليلة جداً) منشؤها حراري بحت، بينما الأغلبية (إلكترونات) منشؤها بالأساس التطعيم المتعمَّد"],"a":3,"why":"الإلكترونات الحرة (الأغلبية بالنوع n) مصدرها الأساسي التطعيم المتعمَّد بالشائبة المانحة، بينما الفجوات القليلة جداً (الأقلية) تنتج فقط من كسر حراري عرضي لروابط تساهمية، تماماً كما بالبلورة النقية."},{"ch":"g6c7","q":"أين يقع المستوى القابل (Acceptor Level) بالضبط داخل الفجوة الطاقية المحظورة، وماذا يحدث لمستوى فيرمي عند تولّده؟","opts":["تحت حزمة التوصيل مباشرة، ويرتفع فيرمي للأعلى","في منتصف الفجوة تماماً، ويبقى فيرمي ثابتاً","فوق حزمة التكافؤ مباشرة، وينخفض فيرمي نحو الأسفل","خارج الفجوة الطاقية كلياً، بلا أي أثر على فيرمي"],"a":2,"why":"المستوى القابل يتولّد عند التطعيم بشوائب ثلاثية التكافؤ (النوع p)، ويقع فوق حزمة التكافؤ مباشرة، فينخفض مستوى فيرمي نحو الأسفل ويقترب من حزمة التكافؤ."},{"ch":"g6c7","q":"ماذا يحدث للإلكترونات الحرة الكثيرة بجهة n عند تكوين وصلة pn؟","opts":["تبقى ثابتة تماماً بجهة n ولا تتحرك إطلاقاً","تنتشر عبر الوصلة إلى جهة p وتتحد مع فجوات هناك (إعادة اتحاد)","تنتقل جميعها فوراً إلى خارج البلورة كلياً","تتحول إلى فجوات مباشرة بلا أي انتقال"],"a":1,"why":"فرق التركيز يدفع الإلكترونات الحرة للانتشار من n (تركيز عالٍ) إلى p (تركيز منخفض)، حيث تتحد فوراً مع الفجوات هناك."},{"ch":"g6c7","q":"ما الذي يبقى فعلياً داخل منطقة الاستنزاف بعد اكتمال الانتشار وإعادة الاتحاد؟","opts":["فائض كبير من الإلكترونات الحرة المتحركة","فائض كبير من الفجوات المتحركة","لا يوجد أي شيء إطلاقاً؛ منطقة فارغة من المادة بالكامل","أيونات ثابتة فقط (موجبة بجهة n وسالبة بجهة p)، بلا حاملات شحنة حرة تقريباً"],"a":3,"why":"بعد إعادة الاتحاد، تبقى فقط ذرات الشوائب (الآن أيونات ثابتة ضمن الشبكة البلورية) — بلا أي حاملات شحنة حرة قادرة على الحركة."},{"ch":"g6c7","q":"ما القيمة التقريبية لجهد الحاجز عند التوازن في ثنائي مصنوع من السيليكون؟","opts":["≈0.7 V","≈0.3 V","≈5 V","≈صفر تماماً"],"a":0,"why":"جهد الحاجز النموذجي لثنائي السيليكون عند التوازن يساوي تقريباً 0.7V (مقابل ≈0.3V للجرمانيوم)."},{"ch":"g6c7","q":"لماذا يتوقف الانتشار عبر الوصلة pn تلقائياً عند الوصول إلى التوازن، بدل أن يستمر حتى تختفي كل حاملات الشحنة؟","opts":["لأن كل الإلكترونات والفجوات تفنى تماماً فور تكوّن الوصلة","لأن المجال الكهربائي الداخلي الناتج عن الأيونات الثابتة بمنطقة الاستنزاف يعاكس أي انتشار إضافي ويوقفه عند جهد الحاجز","لأن درجة حرارة الوصلة تنخفض لتمنع أي حركة إضافية","لأن حجم البلورة ينكمش فيسدّ الوصلة فيزيائياً"],"a":1,"why":"الأيونات الثابتة تنشئ مجالاً كهربائياً داخلياً (وجهد حاجز مقابلاً له) يعاكس اتجاه الانتشار، فيوقفه عند نقطة توازن ديناميكي بدل استمراره حتى الفناء الكامل."},{"ch":"g6c7","q":"في رمز الثنائي بالدارات الكهربائية، ماذا يمثّل اتجاه رأس السهم المثلث؟","opts":["اتجاه حركة الإلكترونات الحرة فقط، من n إلى p","لا يحمل الاتجاه أي دلالة فيزيائية، مجرد رمز عشوائي","اتجاه المجال المغناطيسي حول الثنائي","الاتجاه الذي يسمح فيه الثنائي بمرور التيار التقليدي بسهولة، من الأنود (p) إلى الكاثود (n)"],"a":3,"why":"رأس السهم بالرمز يشير من الأنود (جهة p) إلى الكاثود (جهة n)، وهو اتجاه مرور التيار التقليدي السهل عبر الثنائي."},{"ch":"g6c7","q":"بطعّم ثنائي pn بنسبة شوائب أعلى (تطعيم أكثف)، مع بقاء المادة ودرجة الحرارة ثابتتين. ماذا يحدث لمقدار جهد الحاجز عادة؟","opts":["يبقى ثابتاً تماماً مهما تغيّرت نسبة التطعيم","يتغيّر، لأن جهد الحاجز يعتمد على نسبة الشوائب مع نوع المادة ودرجة الحرارة معاً","ينعدم كلياً فوراً بأي زيادة بالتطعيم","يتغيّر فقط لو كانت المادة عازلاً لا شبه موصل"],"a":1,"why":"حاجز الجهد في الثنائي pn يعتمد على ثلاثة عوامل معاً: نوع مادة شبه الموصل، نسبة الشوائب المطعّمة بها، ودرجة حرارة المادة."},{"ch":"g6c7","q":"لتوصيل ثنائي pn توصيلاً أمامياً (Forward Bias)، كيف يجب ربط أقطاب البطارية؟","opts":["القطب الموجب لجهة n، والقطب السالب لجهة p","القطب الموجب لجهة p، والقطب السالب لجهة n","كلا القطبين لجهة p فقط","لا فرق إطلاقاً؛ أي توصيل يُعطي نفس النتيجة"],"a":1,"why":"الانحياز الأمامي يتطلب ربط الموجب بجهة p والسالب بجهة n، بحيث يعاكس المجال الخارجي المجال الداخلي بمنطقة الاستنزاف."},{"ch":"g6c7","q":"ماذا يحدث لعرض منطقة الاستنزاف عند الانحياز العكسي؟","opts":["تضيق (تصغر) تدريجياً حتى تختفي كلياً","تبقى ثابتة تماماً بلا أي تغيّر","تختفي فوراً بأي فولطية عكسية مهما صغرت","تتّسع (تكبر) تدريجياً مع زيادة الفولطية العكسية"],"a":3,"why":"الانحياز العكسي يسحب حاملات الشحنة الأغلبية بعيداً عن الوصلة، فتتّسع منطقة الاستنزاف تدريجياً مع زيادة الفولطية العكسية."},{"ch":"g6c7","q":"دائرة فيها بطارية 3V وثنائي سيليكون منحاز أمامياً (V₀=0.7V) ومقاومة R=100Ω على التوالي. جد التيار المار.","opts":["≈23 mA","≈30 mA","≈7 mA","≈100 mA"],"a":0,"why":"I=(EMF−V₀)/R=(3−0.7)/100=2.3/100=0.023A≈23mA."},{"ch":"g6c7","q":"لماذا يظل التيار في الانحياز العكسي ضئيلاً جداً (تيار تسرب فقط) بدل أن ينعدم تماماً؟","opts":["لأن البطارية نفسها معطوبة دوماً بهذا التوصيل","لأن حاملات الشحنة الأغلبية تعبر الوصلة بحرية تامة رغم الانحياز العكسي","بسبب حاملات الشحنة الأقلية (حرارية المنشأ) القادرة على عبور الوصلة رغم اتساع منطقة الاستنزاف","لأن منطقة الاستنزاف تختفي تماماً بالانحياز العكسي"],"a":2,"why":"حاملات الأقلية القليلة (نشأت حرارياً، لا بالتطعيم) هي وحدها القادرة على العبور مهما كان اتجاه الانحياز، فتنتج تيار تسرب عكسي صغيراً لكن غير معدوم تماماً."},{"ch":"g6c7","q":"بمنحني خواص الثنائي (I مقابل V)، ماذا يحدث بعد تجاوز الفولطية العكسية «جهد الانهيار»؟","opts":["يبقى التيار صفراً تماماً مهما زادت الفولطية العكسية","يتحول الثنائي تلقائياً لعازل تام دائم","يتوقف الثنائي عن التوصيل بأي اتجاه إلى الأبد","ينهار الثنائي ويتدفق فجأة تيار عكسي كبير جداً"],"a":3,"why":"عند فولطية عكسية كافية (جهد الانهيار)، ينهار الثنائي ويسمح بمرور تيار عكسي كبير فجأة — سلوك تستثمره ثنائيات زينر بالدرس القادم."},{"ch":"g6c7","q":"لماذا يبقى هبوط الجهد على الثنائي المنحاز أمامياً ثابتاً تقريباً (≈0.7V للسيليكون) مهما زاد التيار المار؟","opts":["لأن التيار في هذه الحالة يساوي صفراً دوماً","لأن جهد الحاجز خاصية شبه ثابتة للمادة نفسها بعد تجاوز العتبة، وأي زيادة بفولطية المصدر تهبط أساساً على بقية عناصر الدارة (كالمقاومة)","لأن الثنائي يتحول لعازل تام فور تجاوز 0.7V","لأن هذا سلوك عشوائي بلا أي تفسير فيزيائي"],"a":1,"why":"بعد تجاوز جهد الحاجز، يبقى هبوط الجهد على الثنائي قريباً من هذه القيمة المميِّزة للمادة، وتظهر أي زيادة إضافية بفولطية المصدر كهبوط جهد على بقية عناصر الدارة (كالمقاومة R في المثال المحلول)."},{"ch":"g6c7","q":"ما وظيفة الثنائي المقوّم (Rectifier) بأبسط تعريف؟","opts":["تكبير الإشارات الكهربائية الضعيفة","توليد الضوء من الكهرباء مباشرة","تحويل التيار المتردد (AC) إلى تيار مستمر (DC) بالسماح بمرور تيار باتجاه واحد فقط","تخزين الشحنة الكهربائية لفترة طويلة"],"a":2,"why":"خاصية الثنائي بالسماح بالمرور باتجاه واحد فقط تجعله أساس أي دائرة تقويم تحوّل AC إلى DC."},{"ch":"g6c7","q":"كيف يعمل ثنائي الخلية الشمسية (Solar Cell)؟","opts":["يُربَط بانحياز عكسي، ويحوّل الطاقة الضوئية الساقطة على الملتقى إلى طاقة كهربائية مباشرة (يولّد قوة دافعة كهربائية بنفسه)","يُربَط بانحياز أمامي، ويستهلك طاقة كهربائية لإصدار الضوء","لا علاقة له بالضوء إطلاقاً؛ يعمل بالحرارة فقط","يحوّل الصوت إلى كهرباء مباشرة"],"a":0,"why":"ثنائي الخلية الشمسية يُربَط بانحياز عكسي، ويحوّل طاقة الفوتونات الساقطة على منطقة الملتقى إلى طاقة كهربائية (قوة دافعة كهربائية) دون حاجة لمصدر جهد خارجي."},{"ch":"g6c7","q":"في الثنائي الباعث للضوء (LED)، ماذا يحدد لون الضوء المنبعث؟","opts":["شدة التيار المطبق فقط، بصرف النظر عن المادة","طول السلك الموصل للثنائي بالدارة","درجة حرارة الغرفة المحيطة فقط","الفجوة الطاقية Eg لمادة شبه الموصل المستعملة"],"a":3,"why":"طاقة الفوتون المنبعث تساوي تقريباً Eg للمادة (E=hc/λ)، وهي بالتالي ما يحدد الطول الموجي (اللون) بدقة."},{"ch":"g6c7","q":"ثنائي LED فجوته الطاقية Eg=2.2eV. جد الطول الموجي التقريبي للضوء المنبعث منه.","opts":["≈1130 nm (تحت أحمر)","≈565 nm (أخضر مائل للأصفر)","≈250 nm (فوق بنفسجي)","≈700 nm (أحمر غامق)"],"a":1,"why":"λ=hc/Eg=(6.63×10⁻³⁴×3×10⁸)/(2.2×1.6×10⁻¹⁹)≈5.65×10⁻⁷m=565nm — أخضر مائل للأصفر تقريباً."},{"ch":"g6c7","q":"بأي انحياز يُوصَّل الثنائي المتحسّس للضوء (Photodiode) عادة كحسّاس ضوء؟","opts":["انحياز أمامي فقط، مثل الـ LED تماماً","بلا أي انحياز إطلاقاً، ولا حتى تلامس مع دارة كهربائية","انحياز متردد فقط، لا مستمر بأي حال","انحياز عكسي، بحيث يزداد تيار التسرب العكسي طردياً مع شدة الضوء الساقط"],"a":3,"why":"الانحياز العكسي يجعل تيار التسرب العكسي الأساسي حساساً جداً لأي زوج إلكترون-فجوة إضافي يولّده الضوء الساقط، فيتناسب هذا التيار طردياً مع شدة الضوء."},{"ch":"g6c7","q":"ما القاسم المشترك الفيزيائي بين الثنائي الباعث للضوء LED والثنائي المتحسّس للضوء (Photodiode)؟","opts":["كلاهما يعملان فقط بانحياز عكسي بلا استثناء","لا علاقة بينهما إطلاقاً بأي شكل فيزيائي","كلاهما يربط بين طاقة الفوتون (E=hc/λ) وفجوة الطاقة Eg لمادة شبه الموصل، لكن باتجاهين معاكسين (بعث مقابل امتصاص)","كلاهما لا يحتاجان أي مصدر جهد خارجي مطلقاً للعمل"],"a":2,"why":"LED يحوّل طاقة إعادة الاتحاد (قريبة من Eg) إلى فوتون منبعث؛ الثنائي المتحسّس للضوء يمتص فوتوناً طاقته ≥Eg ليولّد زوج إلكترون-فجوة — نفس العلاقة E≈Eg، لكن بعملية معاكسة."},{"ch":"g6c7","q":"ما الأطراف الثلاثة للترانزستور ثنائي القطبية (BJT)؟","opts":["الأنود والكاثود والقاعدة","الباعث والقاعدة والمجمع","الموجب والسالب والمحايد","المصدر والبوابة والمصرف"],"a":1,"why":"أطراف الترانزستور الثلاثة هي: الباعث (Emitter)، القاعدة (Base)، والمجمع (Collector)."},{"ch":"g6c7","q":"لماذا يجب أن تكون منطقة القاعدة رقيقة جداً ومطعّمة تطعيماً خفيفاً؟","opts":["لأنها لا تحتاج أي تطعيم إطلاقاً، فهي منطقة نقية بحتة","لتعيد اتحاد كل حاملات الشحنة القادمة من الباعث بالكامل","لتمنع أي تيار من العبور خلالها نهائياً بأي ظرف","لتسمح لمعظم حاملات الشحنة القادمة من الباعث بعبورها إلى المجمع دون إعادة اتحاد تُذكر"],"a":3,"why":"رقّة القاعدة وتطعيمها الخفيف يقلّلان إعادة الاتحاد بداخلها، فتعبر أغلب حاملات الشحنة إلى المجمع، وهذا أساس عمل الترانزستور كمكبّر فعّال."},{"ch":"g6c7","q":"ما العلاقة الصحيحة بين تيارات الترانزستور الثلاثة؟","opts":["I_B = I_E + I_C","I_C = I_E + I_B","I_E = I_B + I_C","لا توجد أي علاقة ثابتة بينها"],"a":2,"why":"تيار الباعث يساوي مجموع تياري القاعدة والمجمع، بحكم حفظ الشحنة عند عقد الترانزستور."},{"ch":"g6c7","q":"في مضخّم قاعدة مشتركة: I_E=2mA وI_C=1.9mA وR_in=200Ω وR_out=100kΩ. جد ربح التيار α تقريباً.","opts":["≈0.95","≈1.05","≈2","≈500"],"a":0,"why":"α=I_C/I_E=1.9/2=0.95 — أقل من الواحد كما هو متوقّع بمضخّم القاعدة المشتركة."},{"ch":"g6c7","q":"بأي وضعية انحياز يعمل الترانزستور عادة عند استعماله كمكبّر (Amplifier)؟","opts":["كلتا الوصلتين منحازتان عكسياً معاً","كلتا الوصلتين منحازتان أمامياً معاً","بلا أي انحياز على الإطلاق بأي طرف","وصلة الباعث-القاعدة منحازة أمامياً، ووصلة القاعدة-المجمع منحازة عكسياً"],"a":3,"why":"هذا الترتيب (أمامي عند الباعث-القاعدة، عكسي عند القاعدة-المجمع) هو وضع التشغيل النشط الذي يحقن حاملات الشحنة من الباعث ويجمعها المجمع بفعالية، مولّداً التكبير."},{"ch":"g6c7","q":"ما الفرق بين فرق الطور في مضخّم القاعدة المشتركة ومضخّم الباعث المشترك؟","opts":["القاعدة المشتركة: فرق طور صفر (بنفس الطور). الباعث المشترك: فرق طور 180° (معاكس بالطور)","كلاهما بفرق طور صفر دائماً","كلاهما بفرق طور 180° دائماً","لا يوجد أي فرق طور في أي منهما بأي حال"],"a":0,"why":"بمضخّم القاعدة المشتركة تخرج الإشارة بنفس طور الدخول (0°)، بينما بمضخّم الباعث المشترك تخرج معاكسة الطور (180°)."},{"ch":"g6c7","q":"ما وجه الشبه الأساسي بين الترانزستور كـ«مفتاح إلكتروني» والبوابات المنطقية الرقمية (0 و1) بالمعالجات؟","opts":["الترانزستور لا يمكن أن يعمل كمفتاح إطلاقاً، بل كمكبّر فقط","البوابات المنطقية لا تستعمل ترانزستورات إطلاقاً بتصميمها","لا توجد أي علاقة بينهما؛ تشابه لفظي فقط","حالتا التشغيل التام (تشبّع) والإيقاف التام (قطع) بالترانزستور تقابلان مباشرة الحالتين الرقميتين 1 و0"],"a":3,"why":"بتيار قاعدة كافٍ يعمل الترانزستور بوضع التشبّع (تيار أقصى ≈ 1 رقمياً)، وبلا تيار قاعدة يعمل بوضع القطع (تيار معدوم ≈ 0 رقمياً) — أساس كل البوابات المنطقية الرقمية."},{"ch":"g6c7","q":"لماذا استُبدلت الصمامات المفرغة بالترانزستورات في تصنيع الأجهزة الإلكترونية الحديثة؟","opts":["لأن الصمام المفرغ لا يحتاج أي طاقة كهربائية إطلاقاً","لأن الترانزستور أكبر حجماً من الصمام المفرغ","لأن الترانزستور أصغر حجماً، أقل استهلاكاً للطاقة، وأطول عمراً وأكثر متانة","لأن الصمام المفرغ يحتاج فتيلاً كالترانزستور تماماً"],"a":2,"why":"الترانزستور (نبيطة الحالة الصلبة) أصغر، أقل استهلاكاً للطاقة، لا يحتاج فتيلاً ساخناً، وأطول عمراً من الصمام المفرغ."},{"ch":"g6c7","q":"طاقة الإلكترون بمستواه الأرضي في ذرة الهيدروجين تساوي −13.6eV. كم مقدار الطاقة اللازمة لتحريره تماماً من الذرة؟","opts":["−13.6 eV","+13.6 eV","0 eV","+27.2 eV"],"a":1,"why":"التحرر الكامل يعني الانتقال إلى المستوى الصفري E=0؛ الطاقة اللازمة = 0−(−13.6) = +13.6eV."},{"ch":"g6c7","q":"ما الذي يحدد ما إذا كانت المادة موصلاً أم عازلاً أم شبه موصل؟","opts":["عدد بروتونات نواة الذرة فقط","لون المادة الظاهري للعين المجردة","حجم الفجوة الطاقية المحرمة Eg بين حزمتي التكافؤ والتوصيل","درجة انصهار المادة فقط"],"a":2,"why":"حجم الفجوة الطاقية Eg هو الفيصل: صفر تقريباً (موصل)، صغيرة (شبه موصل)، كبيرة (عازل)."},{"ch":"g6c7","q":"(سؤال وزاري) ما الفرق بين حزمة التكافؤ وحزمة التوصيل في المواد الصلبة؟","opts":["حزمة التكافؤ عالية الطاقة وفارغة، وحزمة التوصيل واطئة وممتلئة","حزمة التكافؤ واطئة الطاقة وممتلئة كلياً أو جزئياً بإلكترونات مرتبطة بالنواة، وحزمة التوصيل أعلى منها وإلكتروناتها حرة الانتقال","لا فرق بينهما؛ اسمان لنفس الحزمة","حزمة التكافؤ توجد بالعوازل فقط، وحزمة التوصيل بالموصلات فقط"],"a":1,"why":"حزمة التكافؤ واطئة الطاقة (ممتلئة كلياً أو جزئياً، إلكتروناتها مرتبطة بالنواة)؛ حزمة التوصيل أعلى منها، وإلكتروناتها حرة تساهم بالتيار."},{"ch":"g6c7","q":"(سؤال وزاري) بماذا تتصف (تتميّز) حزم الطاقة في المواد العازلة؟","opts":["حزمة التكافؤ فارغة وحزمة التوصيل ممتلئة","حزمتا التكافؤ والتوصيل متراكبتان بلا أي فجوة","حزمة التكافؤ ممتلئة، حزمة التوصيل خالية، والفجوة بينهما واسعة (~5eV أو أكثر)","لا توجد أي حزم طاقة في المواد العازلة إطلاقاً"],"a":2,"why":"بالعوازل: حزمة التكافؤ مملوءة، حزمة التوصيل خالية تماماً، والفجوة المحرمة بينهما واسعة (~5eV فأكثر) فتمنع أي عبور."},{"ch":"g6c7","q":"فجوة طاقية Eg=1.5eV. جد أطول طول موجي لفوتون قادر على نقل إلكترون عبر هذه الفجوة تقريباً.","opts":["≈300 nm","≈1130 nm","≈829 nm","≈150 nm"],"a":2,"why":"λ_max=hc/Eg=(6.63×10⁻³⁴×3×10⁸)/(1.5×1.6×10⁻¹⁹)≈8.29×10⁻⁷m=829nm."},{"ch":"g6c7","q":"(سؤال وزاري) علّل: تقلّ قابلية التوصيل الكهربائي في المواد الموصلة (المعادن) بارتفاع درجة حرارتها.","opts":["لأن عدد الإلكترونات الحرة بالمعدن يقلّ فعلياً مع ارتفاع الحرارة","لأن ارتفاع الحرارة يزيد اهتزاز الشبيكة البلورية فيعيق حركة الإلكترونات الحرة وتزداد المقاومة","لأن المعدن يتحول لعازل تام عند أي ارتفاع بالحرارة","لأن حجم ذرات المعدن يتقلّص مع ارتفاع الحرارة"],"a":1,"why":"ارتفاع الحرارة يزيد الطاقة الاهتزازية لذرات المعدن، فتعيق اهتزازات الشبيكة حركة الإلكترونات الحرة وتزداد المقاومة، فتقلّ التوصيلية."},{"ch":"g6c7","q":"كم إلكترون تكافؤ تملكه ذرة السيليكون، وكم رابطة تساهمية تكوّنها مع جاراتها بالبلورة؟","opts":["إلكترون واحد، ورابطة واحدة","٤ إلكترونات تكافؤ، و٤ روابط تساهمية","٨ إلكترونات تكافؤ، و٨ روابط","٢ إلكترون، بلا روابط"],"a":1,"why":"السيليكون من المجموعة الرابعة، فله ٤ إلكترونات تكافؤ يكوّن بها ٤ روابط تساهمية مع ٤ ذرات مجاورة."},{"ch":"g6c7","q":"(سؤال وزاري) هل يمكن جعل شبه الموصل النقي (السيليكون) يمتلك قابلية توصيل كهربائي بوساطة التأثير الحراري؟","opts":["لا، لأن التأثير الحراري لا يؤثر على أشباه الموصلات إطلاقاً","نعم، لأن الحرارة تكسر أواصر تساهمية وتحرر إلكترونات لحزمة التوصيل، مولّدة أزواج إلكترون-فجوة","لا، لأن أشباه الموصلات تحتاج تطعيماً فقط لتوصيل التيار","نعم، لكن فقط عند درجة الصفر المطلق تحديداً"],"a":1,"why":"عند رفع الحرارة لدرجة الغرفة، تكتسب إلكترونات التكافؤ طاقة كافية لكسر أواصر تساهمية والانتقال لحزمة التوصيل، مولّدة أزواج (إلكترون-فجوة) تعمل حوامل شحنة."},{"ch":"g6c7","q":"(سؤال وزاري متكرر) علامَ يعتمد المعدّل الزمني لتوليد الأزواج (إلكترون–فجوة) في شبه الموصل النقي؟","opts":["على درجة حرارة شبه الموصل فقط ونوع مادته","على لون المادة الظاهري فقط","على شكل البلورة الهندسي الخارجي فقط","على مصدر الجهد الخارجي المطبق فقط"],"a":0,"why":"يعتمد على: درجة حرارة شبه الموصل (كلما ارتفعت، ازداد معدل التوليد)، ونوع مادته (سيليكون أم جرمانيوم، لاختلاف الفجوة الطاقية)."},{"ch":"g6c7","q":"(اختيار وزاري متكرر) تتولّد الأزواج (إلكترون–فجوة) في شبه الموصل النقي بوساطة:","opts":["إعادة الالتحام","التأيّن","التأثير الحراري","التطعيم"],"a":2,"why":"الطاقة الحرارية عند درجة حرارة الغرفة هي التي تكسر أواصر تساهمية وتحرر إلكترونات مولّدة الأزواج."},{"ch":"g6c7","q":"(اختيار وزاري متكرر) يزداد المعدّل الزمني لتوليد الأزواج (إلكترون–فجوة) في شبه الموصل بـ:","opts":["إدخال شوائب خماسية التكافؤ","إدخال شوائب ثلاثية التكافؤ","ولا واحدة مما سبق","ارتفاع درجة الحرارة"],"a":3,"why":"التطعيم يزيد حاملات الشحنة لكنه ليس توليداً لأزواج (إلكترون-فجوة)؛ ارتفاع الحرارة وحده هو ما يزيد معدل توليد الأزواج."},{"ch":"g6c7","q":"(سؤال وزاري متكرر) ما المقصود بمستوى فيرمي؟ وما موقعه في الموصلات وفي شبه الموصل النقي؟","opts":["أدنى مستوى طاقة يشغله الإلكترون؛ يقع دوماً بمنتصف حزمة التكافؤ","أعلى مستوى طاقة مسموح يشغله الإلكترون عند 0K؛ فوق حزمة التوصيل بالموصلات، ومنتصف الفجوة بشبه الموصل النقي","متوسط طاقة كل إلكترونات الذرة؛ لا علاقة له بنوع المادة","مستوى وهمي لا وجود فيزيائي حقيقي له"],"a":1,"why":"مستوى فيرمي: أعلى مستوى طاقة مسموح يشغله الإلكترون عند 0K. يقع فوق المنطقة المملوءة بالموصلات (ضمن حزمة التوصيل)، وفي منتصف الفجوة المحظورة بشبه الموصل النقي."},{"ch":"g6c7","q":"(صح أو خطأ وزاري) «في الموصلات وعند درجة 0K تكون مستويات الطاقة تحت مستوى فيرمي مشغولة بالإلكترونات» — العبارة:","opts":["صحيحة","خاطئة، الصحيح: خالية من الإلكترونات","صحيحة فقط بشبه الموصلات لا الموصلات","لا علاقة لمستوى فيرمي بإشغال الإلكترونات"],"a":0,"why":"مستوى فيرمي أعلى مستوى يشغله الإلكترون عند 0K، فكل ما تحته مشغول بالإلكترونات، وكل ما فوقه خالٍ."},{"ch":"g6c7","q":"لتكوين شبه موصل من النوع n، أي عنصر يجب تطعيم السيليكون به؟","opts":["عنصر ثلاثي التكافؤ كالبورون","عنصر خماسي التكافؤ كالزرنيخ أو الفوسفور","عنصر رباعي التكافؤ كالسيليكون نفسه","أي عنصر بلا شرط على تكافؤه"],"a":1,"why":"الشائبة الخماسية التكافؤ تمنح إلكتروناً خامساً زائداً بعد تكوين ٤ روابط، فينتج فائض إلكترونات حرة (النوع n)."},{"ch":"g6c7","q":"(سؤال وزاري) علّل: إذا كان التأثير الحراري يزيد توصيلية شبه الموصل النقي، فلماذا نلجأ لتطعيمه بشوائب؟","opts":["لأنه لا يمكن السيطرة على التوصيلية بالتأثير الحراري وحده، بينما التطعيم يتيح تحكماً دقيقاً ومضبوطاً بها","لأن التأثير الحراري لا يزيد التوصيلية إطلاقاً في الحقيقة","لأن التطعيم أرخص من تسخين البلورة","لا حاجة فعلية للتطعيم؛ يمكن الاستغناء عنه كلياً"],"a":0,"why":"التأثير الحراري يزيد التوصيلية لكن بلا تحكم دقيق أو منضبط؛ التطعيم يتيح ضبط نوع وكمية حاملات الشحنة بدقة."},{"ch":"g6c7","q":"(سؤال وزاري) علّل: الأيون الموجب المتولّد من الذرّة المانحة لا يُعدّ من حاملات الشحنة.","opts":["لأنه يرتبط بالهيكل البلوري ارتباطاً وثيقاً وثابتاً فلا يتحرك، فلا يسهم بالتوصيل","لأنه سالب الشحنة فعلياً لا موجب","لأنه أكبر حجماً من أن يتحرك خلال البلورة","لأنه يتحرك بعكس اتجاه الإلكترونات دوماً فلا يُحسَب"],"a":0,"why":"الأيون الموجب (الذرة المانحة بعد فقدان إلكترونها) ثابت ضمن الهيكل البلوري، فلا يسهم بالتوصيل رغم شحنته."},{"ch":"g6c7","q":"(سؤال وزاري) هل يمكن أن توجد فجوات في بلورة سيليكون نوع n؟ ولماذا؟","opts":["لا يمكن إطلاقاً بأي حال","نعم، لكنها قليلة جداً (أقلية) ومنشؤها حراري بحت، لا من التطعيم","نعم، وهي الحاملات الأغلبية فيه","نعم، لكنها ثابتة لا تتحرك أبداً"],"a":1,"why":"التطعيم بخماسية التكافؤ يزيد الإلكترونات فقط؛ الفجوات القليلة تتولد حرارياً كما بالبلورة النقية، وتُعد أقلية."},{"ch":"g6c7","q":"(سؤال وزاري — قارن) ما الفرق بين نوع N ونوع P من حيث نوع الشائبة وحاملات الشحنة؟","opts":["النوع N: شائبة ثلاثية وأغلبية فجوات. النوع P: شائبة خماسية وأغلبية إلكترونات","النوع N: شائبة خماسية (مانحة) وأغلبية إلكترونات. النوع P: شائبة ثلاثية (قابلة) وأغلبية فجوات","كلاهما بنفس نوع الشائبة وحاملات الشحنة تماماً","النوع N والنوع P لا يختلفان إلا باللون فقط"],"a":1,"why":"النوع N: شائبة خماسية التكافؤ (مانحة)، وحاملات الأغلبية إلكترونات. النوع P: شائبة ثلاثية التكافؤ (قابلة)، وحاملات الأغلبية فجوات."},{"ch":"g6c7","q":"أين يقع المستوى المانح (Donor Level) ضمن الفجوة الطاقية المحظورة، وماذا يحدث لمستوى فيرمي عند تولّده؟","opts":["تحت حزمة التوصيل مباشرة، ويرتفع فيرمي نحو الأعلى","فوق حزمة التكافؤ مباشرة، وينخفض فيرمي نحو الأسفل","في منتصف الفجوة تماماً، ويبقى فيرمي ثابتاً","خارج الفجوة الطاقية كلياً"],"a":0,"why":"المستوى المانح يتولّد بالتطعيم بشوائب خماسية (النوع n)، ويقع تحت حزمة التوصيل مباشرة، فيرتفع فيرمي نحو الأعلى."},{"ch":"g6c7","q":"(سؤال وزاري متكرر) علّل: سبب تولّد منطقة الاستنزاف في الثنائي البلوري pn.","opts":["لأن حوامل الأغلبية تنتشر عبر الملتقى وتلتحم قربه، تاركة أيونات ثابتة خالية من حاملات الشحنة الحرة","لأن البلورة تفقد نصف ذراتها عند تكوّن الوصلة","لأن درجة حرارة الوصلة تنخفض فجأة لحظة التلامس","لأن مجالاً مغناطيسياً خارجياً يطرد الشحنات من منطقة الوصلة"],"a":0,"why":"انتشار حوامل الأغلبية (إلكترونات من N وفجوات من P) عبر الملتقى والتحامها قربه يترك أيونات ثابتة خالية من حاملات الشحنة الحرة — هي منطقة الاستنزاف."},{"ch":"g6c7","q":"(سؤال وزاري متكرر) علامَ يعتمد مقدار حاجز الجهد الكهربائي في الثنائي البلوري pn؟","opts":["على شكل الثنائي الهندسي الخارجي فقط","على نوع مادة شبه الموصل، ونسبة الشوائب، ودرجة حرارة المادة","على لون الثنائي فقط","على اتجاه التيار المتردد المطبق فقط"],"a":1,"why":"حاجز الجهد يعتمد على ثلاثة عوامل: نوع مادة شبه الموصل (Si أم Ge)، نسبة التطعيم، ودرجة الحرارة."},{"ch":"g6c7","q":"ما القيمة التقريبية لجهد الحاجز عند التوازن في ثنائي مصنوع من الجرمانيوم؟","opts":["≈0.7 V","≈5 V","≈0.3 V","≈صفر تماماً"],"a":2,"why":"جهد الحاجز النموذجي لثنائي الجرمانيوم عند التوازن يساوي تقريباً 0.3V (مقابل ≈0.7V للسيليكون)."},{"ch":"g6c7","q":"لتوصيل ثنائي pn توصيلاً أمامياً (Forward Bias)، كيف يجب ربط أقطاب البطارية؟","opts":["الموجب لجهة n، والسالب لجهة p","الموجب لجهة p، والسالب لجهة n","كلا القطبين لجهة واحدة فقط","لا فرق؛ أي توصيل يعطي نفس النتيجة"],"a":1,"why":"الانحياز الأمامي يتطلب ربط الموجب بجهة p والسالب بجهة n، ليعاكس المجال الخارجي المجال الداخلي بمنطقة الاستنزاف."},{"ch":"g6c7","q":"(سؤال وزاري) علّل: ينساب تيار كبير في دائرة الثنائي pn عندما تزداد فولطية الانحياز بالاتجاه الأمامي.","opts":["لأن المجال الخارجي يعاكس مجال حاجز الجهد ويصبح أكبر منه، فتضيق منطقة الاستنزاف ويسهل عبور حوامل الأغلبية","لأن حاجز الجهد يزداد باستمرار مع الانحياز الأمامي","لأن منطقة الاستنزاف تتّسع باستمرار مع الانحياز الأمامي","لأن حوامل الأقلية فقط هي التي تعبر الملتقى بالانحياز الأمامي"],"a":0,"why":"المجال الخارجي بالانحياز الأمامي معاكس لمجال حاجز الجهد وأكبر منه، فتضيق منطقة الاستنزاف ويقلّ حاجز الجهد، فيسهل عبور حوامل الأغلبية."},{"ch":"g6c7","q":"(اختيار وزاري) عند زيادة حاجز الجهد في ثنائي pn منحاز أمامياً، فإن مقدار التيار الأمامي:","opts":["يزداد","يبقى ثابتاً","يقلّ","يزداد ثم ينقص"],"a":2,"why":"زيادة حاجز الجهد تعني زيادة إعاقة عبور حوامل الأغلبية، فيقلّ التيار الأمامي المنساب."},{"ch":"g6c7","q":"دائرة فيها بطارية 4.7V وثنائي سيليكون منحاز أمامياً (V₀=0.7V) ومقاومة R=200Ω على التوالي. جد التيار المار.","opts":["≈47 mA","≈23.5 mA","≈3.5 mA","≈20 mA"],"a":3,"why":"I=(EMF−V₀)/R=(4.7−0.7)/200=4/200=0.02A=20mA."},{"ch":"g6c7","q":"ما وظيفة الثنائي المقوّم (Rectifier) بأبسط تعريف؟","opts":["تكبير الإشارات الكهربائية الضعيفة","تحويل التيار المتردد (AC) إلى تيار مستمر (DC) بالسماح بالمرور باتجاه واحد فقط","توليد الضوء من الكهرباء مباشرة","تخزين الشحنة الكهربائية لفترة طويلة"],"a":1,"why":"خاصية السماح بالمرور باتجاه واحد فقط تجعل الثنائي أساس أي دائرة تقويم تحوّل AC إلى DC."},{"ch":"g6c7","q":"(سؤال وزاري متكرر — قارن) ما الفرق بين الثنائي الباعث للضوء (LED) والثنائي المتحسّس للضوء (Photodiode)؟","opts":["كلاهما يعملان بالانحياز الأمامي نفسه تماماً","LED بانحياز أمامي يحوّل كهرباء لضوء؛ Photodiode بانحياز عكسي يحوّل ضوءاً لكهرباء","LED بانحياز عكسي؛ Photodiode بانحياز أمامي (عكس الترتيب الشائع)","لا فرق بينهما؛ اسمان لنفس النبيطة"],"a":1,"why":"LED يُربَط بالانحياز الأمامي ويحوّل الكهرباء لضوء؛ Photodiode يُربَط بالانحياز العكسي ويحوّل الضوء لكهرباء (يزداد تياره مع شدة الضوء)."},{"ch":"g6c7","q":"كيف يعمل ثنائي الخلية الشمسية (Solar Cell)؟","opts":["يستهلك كهرباء لإصدار ضوء كـLED تماماً","يُربَط بانحياز عكسي ويحوّل الطاقة الضوئية الساقطة إلى طاقة كهربائية مباشرة","يعمل بالحرارة فقط بلا أي علاقة بالضوء","يحتاج مصدر تيار متردد خارجي ليعمل"],"a":1,"why":"ثنائي الخلية الشمسية يُربَط بانحياز عكسي ويحوّل طاقة الفوتونات الساقطة على الملتقى مباشرة إلى طاقة كهربائية (قوة دافعة كهربائية)."},{"ch":"g6c7","q":"ثنائي LED فجوته الطاقية Eg=2.0eV. جد الطول الموجي التقريبي للضوء المنبعث منه.","opts":["≈1130 nm (تحت أحمر)","≈300 nm (فوق بنفسجي)","≈622 nm (أحمر برتقالي)","≈900 nm (تحت أحمر)"],"a":2,"why":"λ=hc/Eg=(6.63×10⁻³⁴×3×10⁸)/(2×1.6×10⁻¹⁹)≈6.22×10⁻⁷m=622nm."},{"ch":"g6c7","q":"ما الأطراف الثلاثة للترانزستور ثنائي القطبية (BJT)؟","opts":["الأنود والكاثود والقاعدة","المصدر والبوابة والمصرف","الباعث والقاعدة والمجمع","الموجب والسالب والمحايد"],"a":2,"why":"أطراف الترانزستور الثلاثة: الباعث (Emitter)، القاعدة (Base)، والمجمع (Collector)."},{"ch":"g6c7","q":"(صح أو خطأ وزاري) «تيار الباعث IE يكون دائماً أكبر من تيار القاعدة وأكبر من تيار المجمع» — العبارة:","opts":["خاطئة؛ IE أصغرهما دائماً","صحيحة، لأن IE=IC+IB","صحيحة فقط بترانزستور PNP لا NPN","لا علاقة ثابتة بين التيارات الثلاثة"],"a":1,"why":"بما أن IE=IC+IB، فإن تيار الباعث هو الأكبر دائماً بين التيارات الثلاثة."},{"ch":"g6c7","q":"(سؤال وزاري — علّل) لماذا ممانعة ملتقى (المجمع-قاعدة) عالية بينما ممانعة ملتقى (الباعث-قاعدة) واطئة؟","opts":["لأن ملتقى الباعث-قاعدة محيّز عكسياً وملتقى المجمع-قاعدة محيّز أمامياً","لأن ملتقى الباعث-قاعدة محيّز أمامياً (استنزاف ضيق، مقاومة واطئة)، وملتقى المجمع-قاعدة محيّز عكسياً (استنزاف واسع، مقاومة عالية)","لأن كلا الملتقيين محيّزان أمامياً بنفس الدرجة","لأن المجمع مصنوع من مادة عازلة بخلاف الباعث"],"a":1,"why":"الباعث-قاعدة محيّز أمامياً فتضيق منطقة استنزافه (ممانعة واطئة)؛ المجمع-قاعدة محيّز عكسياً فتتّسع منطقة استنزافه (ممانعة عالية)."},{"ch":"g6c7","q":"(مسألة وزارية) في مضخّم قاعدة مشتركة: IE=3mA، Rin=500Ω، Rout=400kΩ، IC=2.94mA. جد ربح الفولطية Av تقريباً.","opts":["≈0.98","≈1.5","≈784","≈400"],"a":2,"why":"Vin=IE·Rin=3×10⁻³×500=1.5V. Vout=IC·Rout=2.94×10⁻³×400000=1176V. Av=Vout/Vin=1176/1.5=784."},{"ch":"g6c7","q":"(مسألة وزارية) مضخّم قاعدة مشتركة: ربح القدرة G=768، ربح الفولطية Av=784. جد ربح التيار α.","opts":["≈1.02","≈0.98","≈600×10³","≈16"],"a":1,"why":"G=α×Av ⟹ α=G/Av=768/784≈0.98."},{"ch":"g6c7","q":"(اختيار وزاري) ربح التيار α بمضخّم الباعث المشترك يساوي نسبة:","opts":["IE/IB","IC/IE","IC/IB","IE/IC"],"a":2,"why":"بمضخّم الباعث المشترك، ربح التيار = تيار الخروج (المجمع) على تيار الدخول (القاعدة) = IC/IB."},{"ch":"g6c7","q":"ما وجه الشبه الأساسي بين الترانزستور كـ«مفتاح إلكتروني» والبوابات المنطقية الرقمية (0 و1)؟","opts":["لا علاقة بينهما؛ تشابه لفظي فقط","البوابات المنطقية لا تستعمل ترانزستورات إطلاقاً","الترانزستور يعمل كمكبّر فقط، لا كمفتاح أبداً","وضعا التشبّع (تشغيل تام) والقطع (إيقاف تام) يقابلان مباشرة الحالتين الرقميتين 1 و0"],"a":3,"why":"بتيار قاعدة كافٍ يعمل الترانزستور بوضع التشبّع (≈1 رقمياً)، وبلا تيار قاعدة بوضع القطع (≈0 رقمياً) — أساس البوابات المنطقية."},{"ch":"g6c8","q":"أيّ عالِم اقترح أن الذرّة كرة مصمتة موزّعة الشحنة الموجبة تتوزّع بداخلها إلكترونات سالبة؟","opts":["رذرفورد","بور","طومسون","دالتون"],"a":2,"why":"طومسون هو صاحب أنموذج «الكعكة بالزبيب» — كرة موجبة الشحنة تتوزّع بداخلها إلكترونات سالبة."},{"ch":"g6c8","q":"ما السببان اللذان أدّيا إلى فشل أنموذج رذرفورد للذرّة؟","opts":["الذرّة يجب أن تنهار حلزونياً (إشعاع مستمر من إلكترون معجَّل)، والنموذج يتوقع طيفاً مستمراً بينما المُشاهَد طيف خطّي","لأن رذرفورد لم يفترض وجود نواة موجبة إطلاقاً","لأن الذرّة وفق رذرفورد تكون موجبة الشحنة الكلية دوماً","لا يوجد أي سبب فيزيائي حقيقي؛ النموذج صحيح تماماً"],"a":0,"why":"الإلكترون المعجَّل يجب أن يشعّ طاقة باستمرار فينهار حلزونياً نحو النواة (تنبؤ يخالف استقرار الذرّة)، كما يتنبأ بطيف مستمر بينما طيف الهيدروجين المُشاهَد خطّي."},{"ch":"g6c8","q":"وفق فرضيات بور، متى تنتقل الذرّة إلى حالة «متهيّجة» (Excited)؟","opts":["عندما تفقد الذرّة كل إلكتروناتها","عندما يكتسب الإلكترون كمّاً من الطاقة وينتقل من مستوى استقراره إلى مستوى أعلى","عندما تبرد الذرّة إلى الصفر المطلق","الذرّة متهيّجة دوماً بشكل دائم لا يتغيّر"],"a":1,"why":"الفرضية الرابعة: اكتساب الإلكترون طاقة مناسبة ينقله لمستوى أعلى (Ef)، فتصبح الذرّة متهيّجة، حتى يعود لاحقاً باعثاً فوتوناً."},{"ch":"g6c8","q":"ما الصيغة الصحيحة لشرط انبعاث أو امتصاص فوتون عند انتقال إلكتروني بين مستويين؟","opts":["hf = Ef + Eᵢ","h = f(Ef − Eᵢ)","f = h(Ef − Eᵢ)","hf = Ef − Eᵢ"],"a":3,"why":"طاقة الفوتون تساوي الفرق بين مستويي الطاقة النهائي والابتدائي: hf=Ef−Eᵢ."},{"ch":"g6c8","q":"وفق الفرضية السادسة لبور، ماذا يساوي الزخم الزاوي للإلكترون في مداره المحدد؟","opts":["قيمة مستمرة أي عدد حقيقي ممكن","أعداداً صحيحة من h/2π فقط (Lₙ=n·h/2π)","صفراً دائماً بكل المدارات","يساوي كتلة الإلكترون فقط"],"a":1,"why":"الزخم الزاوي مكمّم: Lₙ=n(h/2π)، حيث n عدد صحيح موجب (العدد الكمّي الرئيس) — هذا قيد إضافي فرضه بور لم يكن موجوداً بالفيزياء الكلاسيكية."},{"ch":"g6c8","q":"ماذا نسمي أوطأ مستوى طاقة لذرّة الهيدروجين E₁؟","opts":["المستوى المتهيّج","المستوى الأرضي","المستوى الحر","المستوى الصفري"],"a":1,"why":"أوطأ مستوى طاقة يُسمى المستوى الأرضي (Ground State)؛ المستويات الأعلى منه تُسمى مستويات متهيّجة."},{"ch":"g6c8","q":"إلى أي مستوى تنتهي الانتقالات الإلكترونية في سلسلة بالمر (Balmer)؟","opts":["n = 1","n = 3","n = 4","n = 2"],"a":3,"why":"سلسلة بالمر هي كل الانتقالات المنتهية عند n=2، وهي السلسلة الوحيدة الواقعة (جزئياً) بالمدى المرئي."},{"ch":"g6c8","q":"لماذا سلسلة لايمان (الانتقال إلى n=1) غير مرئية للعين البشرية؟","opts":["لأن فرق الطاقة بها كبير جداً فيقابل أطوالاً موجية فوق بنفسجية قصيرة","لأن فرق الطاقة بها صغير جداً فيقابل أطوالاً موجية تحت حمراء طويلة","لأنها لا تحدث إطلاقاً بذرّة الهيدروجين","لأن العين البشرية لا ترى أي طيف خطي مهما كان"],"a":0,"why":"الانتقال إلى n=1 (أوطأ مستوى) يقابل أكبر فرق طاقة بين السلاسل، فينتج فوتونات عالية الطاقة (فوق بنفسجية قصيرة الطول الموجي)، خارج المدى المرئي."},{"ch":"g6c8","q":"إلكترون انتقل من E₅=−0.54eV إلى E₂=−3.4eV. جد طاقة الفوتون المنبعث تقريباً بوحدة eV.","opts":["≈3.94 eV","≈0.54 eV","≈2.86 eV","≈13.6 eV"],"a":2,"why":"hf=E₅−E₂=(−0.54)−(−3.4)=2.86eV."},{"ch":"g6c8","q":"لماذا لا يمتلك إلكترون ذرّة الهيدروجين طاقة كافية للهروب من الذرّة تحت الظروف الطبيعية؟","opts":["لأن طاقات كل مستوياته صفر دائماً","لأن طاقات كل مستوياته موجبة دوماً وكبيرة جداً","لأن الإلكترون لا يملك أي طاقة إطلاقاً","لأن طاقات كل مستوياته سالبة (الإلكترون مرتبط بالنواة)"],"a":3,"why":"كل مستويات طاقة الإلكترون بالذرّة سالبة (مرتبط بجذب النواة)؛ الهروب الكلي يتطلب اكتساب طاقة كافية لرفع الطاقة إلى الصفر أو أكثر (التأيّن)."},{"ch":"g6c8","q":"من أين نحصل على الطيف المستمر؟","opts":["من غازات وأبخرة متوهّجة عند ضغط اعتيادي أو واطئ فقط","من الأجسام الصلبة والسائلة المتوهّجة، أو غازات متوهّجة بضغط عالٍ جداً","من مواد باردة تماماً بلا أي توهّج","من الفراغ الكامل بلا أي مصدر مادي"],"a":1,"why":"الطيف المستمر ينتج من الأجسام الصلبة والسائلة المتوهّجة، أو من غازات متوهّجة عند ضغط عالٍ جداً."},{"ch":"g6c8","q":"لماذا يُعدّ الطيف الخطي «بصمة» مميزة لكل عنصر؟","opts":["لأنه يتكرّر بنفس الشكل عند كل العناصر بلا استثناء","لأن الطيف الخطي لا علاقة له بنوع العنصر إطلاقاً","لأنه يظهر فقط بالعناصر المشعّة","لأن كل عنصر له مجموعة خطوط طيفية خاصة به لا تتكرّر عند أي عنصر آخر"],"a":3,"why":"لكل عنصر طيف خطي خاص به فريد تماماً — يُستعمل هذا في الكشف عن العناصر (كتحليل ضوء النجوم)."},{"ch":"g6c8","q":"ما سبب ظهور خطوط فراونهوفر السوداء ضمن الطيف المستمر للشمس؟","opts":["امتصاص الغازات المحيطة بالشمس لأطوال موجية محددة من طيفها المستمر","خلل بجهاز المطياف المستعمل في الرصد فقط","أن الشمس نفسها لا تُصدر أي طيف مستمر إطلاقاً","تراكم الغبار الكوني بين الأرض والشمس فقط"],"a":0,"why":"الغازات المحيطة بالشمس (الأبرد نسبياً) تمتصّ من طيفها المستمر تحديداً الأطوال الموجية التي كانت لتبعثها هي نفسها لو كانت متوهّجة."},{"ch":"g6c8","q":"طيف غاز ثنائي أوكسيد الكربون (CO₂) المتوهّج يظهر على هيئة:","opts":["طيف مستمر بلا أي فجوة","خطّين أصفرين فقط كالصوديوم","طيف حزمي (حزم عريضة، صفة المواد الجزيئية التركيب)","لا يُصدر أي طيف إطلاقاً"],"a":2,"why":"المواد ذات التركيب الجزيئي (كـCO₂) تُصدر طيفاً حزمياً (حزم عريضة)، بخلاف الذرّات المفردة التي تُصدر خطوطاً رفيعة."},{"ch":"g6c8","q":"طيف الامتصاص هو أساساً:","opts":["طيف خطي برّاق بلا أي خلفية","طيف مستمر تتخلّله خطوط أو حزم معتمة (سوداء)","طيف حزمي فقط لا غير","لا علاقة له بالطيف المستمر إطلاقاً"],"a":1,"why":"طيف الامتصاص = طيف مستمر ينقص منه بعض الأطوال الموجية المحددة (تظهر كخطوط أو حزم سوداء) نتيجة امتصاص بخار بارد لها."},{"ch":"g6c8","q":"علام يتوقف أعظم تردد لفوتون الأشعة السينية المتولّد؟","opts":["على لون الهدف المعدني فقط","على فرق الجهد V المسلّط على طرفي الأنبوبة (f_max=Ve/h)","على درجة حرارة الغرفة المحيطة فقط","على المجال المغناطيسي المحيط بالأنبوبة فقط"],"a":1,"why":"f_max=Ve/h — كلما زاد فرق الجهد V، زاد أعظم تردد ممكن للفوتون المتولّد."},{"ch":"g6c8","q":"لماذا يُصنع هدف أنبوبة الأشعة السينية من مادة عالية درجة الانصهار؟","opts":["لأن الحرارة الناتجة عن اصطدام الإلكترونات المعجَّلة بالهدف عالية جداً، فتنصهر مادة الهدف لو كانت منخفضة الانصهار","لأن هذا يزيد سرعة الإلكترونات المنبعثة من الكاثود فقط","لأن ذلك يمنع أي تسرب كهربائي من الأنبوبة","لا علاقة لدرجة الانصهار بالموضوع إطلاقاً"],"a":0,"why":"التصادم عالي السرعة يولّد حرارة كبيرة جداً بالهدف؛ مادة منخفضة الانصهار ستتلف بسرعة."},{"ch":"g6c8","q":"فرق جهد 50kV بأنبوبة أشعة سينية. جد أقصر طول موجي تقريباً (h=6.63×10⁻³⁴J.s، e=1.6×10⁻¹⁹C، c=3×10⁸m/s).","opts":["≈4.14×10⁻¹¹ m","≈8.28×10⁻¹¹ m","≈1×10⁻¹⁰ m","≈2.49×10⁻¹¹ m"],"a":3,"why":"λ_min=hc/(Ve)=(6.63×10⁻³⁴×3×10⁸)/(50000×1.6×10⁻¹⁹)≈2.49×10⁻¹¹m."},{"ch":"g6c8","q":"ما الفرق بين الأشعة السينية المميّزة (الخطّية) والأشعة السينية ذات الطيف المستمر؟","opts":["لا فرق بينهما؛ عمليتان متطابقتان تماماً","المميّزة تنتج فقط من مادة الكاثود، لا الأنود","المميّزة تنتج من انتزاع إلكترون داخلي وإعادة ملء الفراغ (صفة مادة الهدف)؛ المستمرة تنتج من تباطؤ الإلكترونات المعجَّلة تدريجياً","المستمرة وحدها تعتمد على فرق الجهد المطبق"],"a":2,"why":"الأشعة المميّزة صفة ذرّية لمادة الهدف (انتقالات إلكترونية داخلية)؛ الأشعة المستمرة تنتج من تباطؤ الإلكترونات بمجال نوى الهدف، بترددات متفاوتة."},{"ch":"g6c8","q":"لماذا لا تتأثر الأشعة السينية بالمجالات الكهربائية أو المغناطيسية؟","opts":["لأنها دقائق مشحونة سالبة الشحنة دوماً","لأن سرعتها أكبر من سرعة الضوء","لأن طولها الموجي طويل جداً يمنع أي تأثير","لأنها موجات كهرومغناطيسية غير مشحونة (ليست دقائق مشحونة)"],"a":3,"why":"الأشعة السينية موجة كهرومغناطيسية محايدة الشحنة، والمجالات الكهربائية والمغناطيسية تؤثر فقط في الدقائق المشحونة المتحركة."},{"ch":"g6c8","q":"في تجربة كومبتن، ماذا لاحظ بخصوص الطول الموجي للأشعة السينية المستطارة عن هدف الكرافيت؟","opts":["أقصر من الطول الموجي الساقط دائماً","يساوي الطول الموجي الساقط تماماً دون أي تغيّر","يعتمد فقط على شدة الحزمة الساقطة لا على أي شيء آخر","أطول بقليل من الطول الموجي الساقط، ويزداد الفرق مع زاوية الاستطارة"],"a":3,"why":"الطول الموجي المستطار λ′ أطول من الساقط λ، وفرقهما (λ′−λ) يزداد كلما كبرت زاوية الاستطارة θ."},{"ch":"g6c8","q":"بأي نوع من التصادم فسّر كومبتن تفاعل الفوتون مع الإلكترون الحر؟","opts":["تصادم غير مرن تفنى فيه الطاقة الحركية بالكامل","تصادم مرن، يخضع لحفظ الزخم وحفظ الطاقة معاً","لا يوجد أي تصادم؛ الفوتون يمرّ دون أي تأثير","تصادم كهرومغناطيسي بحت لا علاقة له بالميكانيك"],"a":1,"why":"افترض كومبتن تصادماً مرناً بين الفوتون والإلكترون الحر، خاضعاً لقانونَي حفظ الزخم وحفظ الطاقة — تماماً كتصادم جسيمين ميكانيكيين."},{"ch":"g6c8","q":"ما القيمة العددية لطول موجة كومبتن h/(mₑc)؟","opts":["6.63×10⁻³⁴ m","9.11×10⁻³¹ m","0.24×10⁻¹¹ m","3×10⁸ m"],"a":2,"why":"h/(mₑc) = (6.63×10⁻³⁴)/(9.11×10⁻³¹×3×10⁸) ≈ 0.24×10⁻¹¹ m — قيمة ثابتة تُستعمل مباشرة بعلاقة كومبتن."},{"ch":"g6c8","q":"فوتون استطار بزاوية 180° (ارتدّ للخلف تماماً) بتأثير كومبتن. ما مقدار الزيادة في طوله الموجي؟","opts":["صفر تماماً","0.24×10⁻¹¹ m","0.48×10⁻¹¹ m","لا نهاية"],"a":2,"why":"عند θ=180°: cos180°=−1، فإن Δλ=(h/mₑc)(1−(−1))=2×0.24×10⁻¹¹=0.48×10⁻¹¹m — أقصى زيادة ممكنة."},{"ch":"g6c8","q":"لماذا يُعدّ تأثير كومبتن دليلاً على أن الفوتون يحمل زخماً خطياً كالجسيمات المادية؟","opts":["لأن الفوتون عديم الكتلة فلا يمكن أن يملك أي زخم إطلاقاً","لأن تفسير الزيادة بالطول الموجي يتطلّب تطبيق قانون حفظ الزخم بين الفوتون والإلكترون، وهذا يستلزم أن يملك الفوتون زخماً محدداً قابلاً للتبادل","لأن تأثير كومبتن لا علاقة له بمفهوم الزخم أصلاً","لأن الإلكترون هو فقط من يملك زخماً بهذا التفاعل، لا الفوتون"],"a":1,"why":"تفسير كومبتن للظاهرة يعتمد أساساً على معادلة حفظ الزخم بين فوتون وإلكترون، وهذا يفترض ضمناً أن للفوتون زخماً محدداً (p=h/λ) يتبادله مع الإلكترون أثناء التصادم."},{"ch":"g6c8","q":"ماذا يعني الحرف الأول في اختصار LASER؟","opts":["Light (الضوء)","Laser (الليزر نفسه)","Line (الخط)","Level (المستوى)"],"a":0,"why":"LASER = Light Amplification by Stimulated Emission of Radiation."},{"ch":"g6c8","q":"من صمّم أول جهاز ليزر فعلياً عام 1960، وباستعمال أي مادة؟","opts":["أينشتاين، باستعمال الهيدروجين","تاونس، باستعمال الأمونيا","T.H. Maiman، باستعمال بلورة الياقوت","رونتجن، باستعمال الكرافيت"],"a":2,"why":"صمّم Maiman أول ليزر فعلي عام 1960 باستعمال بلورة الياقوت (Ruby Laser)؛ تاونس صمّم الميزر (لا الليزر) بالأمونيا عام 1954."},{"ch":"g6c8","q":"أي خاصية من خصائص الليزر الأربع تعني أن كل موجاته بنفس الطور والاتجاه والطاقة؟","opts":["أحادية الطول الموجي","السطوع","الاتجاهية","التشاكه"],"a":3,"why":"التشاكه (Coherency): كل الموجات بنفس الطور، فتتداخل تداخلاً بنّاءً."},{"ch":"g6c8","q":"ما الفرق الجوهري بين الانبعاث التلقائي والانبعاث المحفَّز؟","opts":["لا فرق بينهما؛ عمليتان متطابقتان تماماً","التلقائي يحتاج فوتوناً محفِّزاً خارجياً؛ المحفَّز لا يحتاج أي محفِّز","التلقائي عشوائي الطور والاتجاه؛ المحفَّز ينتج فوتوناً مطابقاً تماماً للفوتون المحفِّز الذي أثاره","التلقائي فقط هو أساس عمل الليزر، لا المحفَّز"],"a":2,"why":"الانبعاث التلقائي عشوائي بلا أي محفِّز خارجي؛ الانبعاث المحفَّز يحدث عندما يمرّ فوتون بذرّة متهيّجة فيحفّزها لبعث فوتون مطابق له تماماً — وهو أساس الليزر."},{"ch":"g6c8","q":"لماذا لا يبعث المصباح الكهربائي الاعتيادي ضوءاً متشاكهاً كالليزر؟","opts":["لأن المصباح لا يحتوي أي ذرّات مثارة إطلاقاً","لأنه يعتمد فقط على الانبعاث التلقائي العشوائي، بلا توزيع معكوس ولا انبعاث محفَّز","لأن المصباح يبعث الضوء بالانبعاث المحفَّز فقط دون التلقائي","لأن المصباح يستهلك طاقة أكبر من الليزر بكثير"],"a":1,"why":"المصباح الاعتيادي يعتمد على الانبعاث التلقائي العشوائي فقط، فلا ينتج حزمة متشاكهة كالليزر."},{"ch":"g6c8","q":"بالتوازن الحراري الطبيعي (بلا ضخّ خارجي)، أي العلاقتين صحيحة بين تركيز الذرّات بالمستويين؟","opts":["N₂ = N₁ دائماً","N₂ > N₁ دائماً","N₁ > N₂ دائماً","لا توجد أي علاقة ثابتة بينهما"],"a":2,"why":"بالتوازن الحراري، تفضّل الذرّات المستوى الأرضي الواطئ الطاقة، فيكون N₁ أكبر من N₂ دائماً وفق قانون بولتزمان."},{"ch":"g6c8","q":"ما المقصود بـ«التوزيع المعكوس» (Population Inversion)؟","opts":["أن يصبح عدد الذرّات بالمستوى الأعلى أكبر من عددها بالمستوى الأدنى (N₂>N₁)، عكس التوازن الحراري الطبيعي","أن تفقد كل الذرّات طاقتها كلياً وتصل للصفر المطلق","أن يتساوى عدد الذرّات بكل المستويات تماماً","أن تنعكس شحنة الذرّة من سالبة إلى موجبة"],"a":0,"why":"التوزيع المعكوس: N₂>N₁، أي فائض ذرّات متهيّجة عن الذرّات المستقرّة — أساس توليد الليزر."},{"ch":"g6c8","q":"ما اسم المستوى ذي العمر الزمني الأطول نسبياً الذي يسمح بتجمّع الذرّات فيه لتحقيق التوزيع المعكوس؟","opts":["المستوى الأرضي","المستوى شبه المستقر (Metastable State)","المستوى الصفري","المستوى الحر"],"a":1,"why":"المستوى شبه المستقر عمره الزمني أطول نسبياً (~10⁻⁶s)، فتتجمّع فيه الذرّات قبل أن تهبط، محقّقة التوزيع المعكوس."},{"ch":"g6c8","q":"ما مكونات جهاز الليزر الرئيسة الثلاثة؟","opts":["الكاثود، والأنود، والمرنان فقط","مرآتان عاكستان كلياً فقط بلا أي وسط","مصدر ليزر جاهز فقط بلا أي مكونات أخرى","الوسط الفعال، والمرنان (مرآتان)، وتقنية الضخّ"],"a":3,"why":"تشترك أجهزة الليزر كافة بثلاثة مكونات: الوسط الفعال، المرنان (مرآتان)، وتقنية الضخّ."},{"ch":"g6c8","q":"لماذا تُفضَّل منظومة الليزر رباعية المستوى على ثلاثية المستوى في أغلب التطبيقات العملية؟","opts":["لأنها أبسط تصميماً وتحتوي مستويين فقط لا أربعة","لأنها تتطلّب طاقة ضخّ أقل لتحقيق التوزيع المعكوس (المستوى الأدنى للانتقال اللازر شبه فارغ أصلاً)","لأنها لا تحتاج أي مرآة عاكسة جزئياً إطلاقاً","لأن طاقة ضخّها أعلى، فتُنتج ليزراً أقوى دوماً"],"a":1,"why":"المستوى الأدنى للانتقال الليزري (E₂) شبه فارغ أصلاً بالمنظومة الرباعية (هبوط سريع منه)، فتحقيق فائض بـE₃ يحتاج طاقة ضخّ أقل من المنظومة الثلاثية."},{"ch":"g6c8","q":"ما الفرق بين تقنية الضخّ الكهربائي والضخّ الكيميائي؟","opts":["لا فرق بينهما؛ نفس الآلية تماماً","الكيميائي وحده يُستعمل بالليزرات الغازية","الكهربائي وحده لا يحتاج أي مصدر طاقة خارجي","الكهربائي يعتمد على التفريغ الكهربائي للغاز؛ الكيميائي يعتمد على تفاعل كيميائي داخلي بلا حاجة مصدر قدرة خارجي"],"a":3,"why":"الضخّ الكهربائي يستعمل تفريغاً كهربائياً بالغاز (يحتاج مصدر جهد خارجي)؛ الضخّ الكيميائي يستمد الطاقة من تفاعل كيميائي بين مكونات الوسط الفعال نفسه، بلا حاجة مصدر خارجي."},{"ch":"g6c8","q":"ليزر الهيليوم-نيون (He-Ne) ينتمي لأي نوع من أنواع الليزر؟","opts":["ليزر الحالة الصلبة","ليزر أشباه الموصلات","الليزر الكيميائي","ليزر الحالة الغازية"],"a":3,"why":"الهيليوم والنيون غازان، فوسطه الفعال غازي — ليزر الحالة الغازية."},{"ch":"g6c8","q":"أول ليزر صُنع فعلياً بالتاريخ (Maiman، 1960) كان من أي نوع؟","opts":["ليزر غازي (هيليوم-نيون)","ليزر الحالة الصلبة (بلورة ياقوت)","ليزر أشباه الموصلات","ليزر كيميائي"],"a":1,"why":"أول ليزر فعلي كان ليزر الياقوت (Ruby Laser) — بلورة صلبة، مضخوخة ضوئياً."},{"ch":"g6c8","q":"أي تطبيق يستثمر خاصية «الاتجاهية» بشكل مباشر أكثر من غيره؟","opts":["قطع المعادن ولحامها فقط","قياس تلوث الهواء فقط","مسح وترصيف الأراضي والإنشاءات الهندسية بخطوط مستقيمة دقيقة","التصوير المجسّم فقط"],"a":2,"why":"بقاء شعاع الليزر متوازياً بانفراجية قليلة جداً (الاتجاهية) يجعله مثالياً لخطوط المسح والترصيف الهندسي المستقيمة الدقيقة."},{"ch":"g6c8","q":"ما مبدأ التصوير المجسّم (Holography) بوساطة الليزر؟","opts":["تسجيل سعة الموجات الضوئية المنعكسة من الجسم وطورها، لإظهاره بثلاثة أبعاد","تسخين الجسم المصوَّر إلى درجة الانصهار","قياس درجة حرارة الجسم عن بعد فقط","تسجيل الصوت المصاحب للجسم المصوَّر فقط"],"a":0,"why":"التصوير المجسّم يسجّل سعة وطور الموجات الضوئية المنعكسة معاً (لا السعة فقط كالتصوير العادي)، فيُنتج صورة ثلاثية الأبعاد واقعية."},{"ch":"g6c8","q":"ما مكونات منظومة الليزر الغازية النموذجية؟","opts":["بلورة صلبة فقط بلا أي مرنان","وسط فعال غازي، مرنان (مرآتان)، وضخّ كهربائي عادة","مرآة واحدة فقط عاكسة كلياً","أنبوبة مفرّغة تماماً بلا أي غاز بداخلها"],"a":1,"why":"منظومات الليزر الغازية تتضمّن: وسطاً فعالاً غازياً، مرناناً (مرآتان متقابلتان)، وميكانيكية ضخّ غالباً كهربائية (تفريغ كهربائي)."},{"ch":"g6c8","q":"لماذا فشل أنموذج رذرفورد للذرّة وفق الكهرومغناطيسية الكلاسيكية؟","opts":["لأن نواة الذرّة لا يمكن أن تكون موجبة الشحنة","لأنه افترض أن الذرّة متعادلة الشحنة كلياً","الإلكترون المعجَّل يجب أن يشعّ طاقة باستمرار فينهار حلزونياً نحو النواة، ويتنبّأ بطيف مستمر بينما المُشاهَد خطّي","لأن رذرفورد لم يقترح وجود إلكترونات إطلاقاً"],"a":2,"why":"الإلكترون المعجَّل يشعّ طاقة باستمرار وفق الكهرومغناطيسية الكلاسيكية فينهار حلزونياً، ويتنبأ النموذج بطيف مستمر يخالف الطيف الخطي المُشاهَد فعلياً."},{"ch":"g6c8","q":"(سؤال وزاري) عندما تُثار الذرّة بطاقة إشعاعية متصلة، فإنها:","opts":["تمتص الطاقة المناسبة لإثارة ذرّاتها فقط","تمتص الطاقة الإشعاعية كلها بلا استثناء","تمتص الطاقة بشكل مستمر غير مكمّم","لا تمتص أي طاقة إطلاقاً مهما كان مصدرها"],"a":0,"why":"وفق فرضية بور الرابعة، لا يمكن للذرّة امتصاص أي كمّ طاقة عشوائي، بل فقط المقدار المناسب تماماً لإثارتها بين مستويين محدَّدين."},{"ch":"g6c8","q":"ما الصيغة الرياضية لتكميم الزخم الزاوي وفق الفرضية السادسة لبور؟","opts":["L = mv²r","L = n(h/2π)","L = hf","L = m/r"],"a":3,"why":"الزخم الزاوي للإلكترون بمداره المحدد يساوي أعداداً صحيحة من h/2π: Lₙ=n(h/2π)."},{"ch":"g6c8","q":"أوطأ مستوى طاقة لذرّة الهيدروجين يُسمى:","opts":["المستوى المتهيّج","المستوى الأرضي","المستوى الحر","مستوى فيرمي"],"a":1,"why":"أوطأ مستوى طاقة للذرّة (E₁) يُسمى المستوى الأرضي؛ المستويات الأعلى تُسمى مستويات متهيّجة."},{"ch":"g6c8","q":"إلى أي مستوى تنتهي انتقالات سلسلة لايمان (Lyman)، وفي أي منطقة طيفية تقع؟","opts":["n=2، مرئية","n=3، تحت الحمراء","n=1، فوق البنفسجية","n=1، تحت الحمراء"],"a":2,"why":"سلسلة لايمان تنتهي عند n=1 (أوطأ مستوى)، وفرق الطاقة الكبير يقابل فوتونات فوق بنفسجية."},{"ch":"g6c8","q":"(سؤال وزاري) طيف ذرّة الهيدروجين هو طيف:","opts":["خطّي","مستمر","امتصاص خطي فقط","حزمي"],"a":0,"why":"الانتقالات بين مستويات منفصلة تُبعث فوتونات بترددات محددة، فتظهر كخطوط منفصلة — طيف خطّي."},{"ch":"g6c8","q":"إلكترون انتقل من E₃=−1.51eV إلى E₁=−13.6eV (انبعاث). جد طاقة الفوتون المنبعث تقريباً.","opts":["≈15.11 eV","≈1.51 eV","≈13.6 eV","≈12.09 eV"],"a":3,"why":"hf=|E₁−E₃|=|−13.6−(−1.51)|=12.09eV."},{"ch":"g6c8","q":"لماذا سلسلة بالمر (الانتقال إلى n=2) هي الوحيدة الواقعة (جزئياً) بالمدى المرئي؟","opts":["لأن فرق طاقتها أكبر فرق ممكن بين كل السلاسل","لأن فرق طاقتها يقابل بالضبط أطوالاً موجية بين ~400-700nm","لأنها السلسلة الوحيدة التي تحدث فعلياً بذرّة الهيدروجين","لأنها تنتهي عند المستوى الأرضي مباشرة"],"a":1,"why":"فرق الطاقة بين المستويات العليا والمستوى الثاني يقابل تحديداً أطوالاً موجية بالمدى المرئي؛ لايمان أكبر طاقة (UV) والباقي أصغر (IR)."},{"ch":"g6c8","q":"من أين نحصل على الطيف الخطي (لا المستمر)؟","opts":["من الأجسام الصلبة والسائلة المتوهّجة","من غازات متوهّجة بضغط عالٍ جداً فقط","من غازات وأبخرة متوهّجة عند ضغط اعتيادي أو واطئ","من مواد باردة بلا أي توهّج"],"a":2,"why":"الطيف الخطي ينتج من توهّج الغازات والأبخرة عند الضغط الاعتيادي أو الواطئ."},{"ch":"g6c8","q":"(سؤال وزاري) مم يتكوّن الطيف الخطي البرّاق لغاز الصوديوم؟","opts":["خطّان أصفران متقاربان جداً","أربعة خطوط ملوّنة","طيف مستمر كامل","خط واحد أحمر فقط"],"a":0,"why":"طيف الصوديوم الخطي البرّاق يتكوّن من خطّين أصفرين متقاربين جداً — بينما طيف الهيدروجين أربعة خطوط ملوّنة."},{"ch":"g6c8","q":"(سؤال وزاري) ما سبب ظهور خطوط فراونهوفر السوداء بطيف الشمس المستمر؟","opts":["خلل تقني بأجهزة الرصد الفلكي فقط","أن الشمس لا تُصدر أي ضوء بتلك الأطوال الموجية أصلاً","تراكم الغبار الكوني بين الأرض والشمس","امتصاص الغازات المحيطة بالشمس لأطوال موجية محددة من طيفها المستمر"],"a":3,"why":"الغازات الأبرد المحيطة بالشمس تمتصّ من طيفها المستمر تحديداً الأطوال الموجية التي كانت لتبعثها هي نفسها لو كانت متوهّجة."},{"ch":"g6c8","q":"طيف غاز مركّب جزيئياً (كـCO₂) متوهّج يظهر عادة على هيئة:","opts":["طيف مستمر تام","طيف حزمي (حزم عريضة)","خطّين فقط كالصوديوم","لا يُصدر أي طيف مهما سخُن"],"a":1,"why":"المواد ذات التركيب الجزيئي تُصدر طيفاً حزمياً (حزم عريضة)، بخلاف الذرّات المفردة (خطوط رفيعة)."},{"ch":"g6c8","q":"(سؤال وزاري متكرر جداً) علّل: يُصنع هدف أنبوبة الأشعة السينية من مادة انصهارها درجة حرارة عالية جداً.","opts":["لأن هذا يمنع أي تسرب كهربائي بالأنبوبة","لأن ذلك يزيد سرعة الإلكترونات الخارجة من الكاثود فقط","لأن الإلكترونات المعجَّلة تصطدم بالهدف بسرعات عالية منتجةً حرارة عالية جداً قد تُتلف مادة منخفضة الانصهار","لا علاقة حقيقية بين درجة الانصهار وعملية التوليد"],"a":2,"why":"التصادم عالي السرعة يولّد حرارة كبيرة جداً؛ مادة منخفضة الانصهار (كالتنكستن العالي الانصهار المُستعمَل فعلياً) ستتلف بسرعة."},{"ch":"g6c8","q":"(سؤال وزاري) لماذا لا تتأثر الأشعة السينية بالمجالات الكهربائية والمغناطيسية؟","opts":["لأنها موجات كهرومغناطيسية محايدة، ليست دقائق مشحونة","لأنها أسرع من الضوء فلا يلحقها أي مجال","لأنها دقائق موجبة الشحنة دوماً","لأن طولها الموجي طويل جداً يمنع أي تأثير"],"a":0,"why":"الأشعة السينية موجة كهرومغناطيسية محايدة، والمجالات تؤثر فقط بالدقائق المشحونة المتحركة."},{"ch":"g6c8","q":"فرق جهد 40kV بأنبوبة أشعة سينية. جد أقصر طول موجي تقريباً.","opts":["≈4.14×10⁻¹¹ m","≈1×10⁻¹⁰ m","≈6.2×10⁻¹¹ m","≈3.1×10⁻¹¹ m"],"a":3,"why":"λ_min=hc/(Ve)=(6.63×10⁻³⁴×3×10⁸)/(40000×1.6×10⁻¹⁹)≈3.11×10⁻¹¹m."},{"ch":"g6c8","q":"ما الفرق الجوهري بين الأشعة السينية المميّزة والأشعة السينية ذات الطيف المستمر؟","opts":["لا فرق بينهما إطلاقاً","المميّزة تنتج من انتقالات إلكترونية داخلية بذرّة الهدف (صفة مادته)؛ المستمرة تنتج من تباطؤ الإلكترونات المعجَّلة","المستمرة فقط تعتمد على فرق الجهد المطبَّق","المميّزة تحدث فقط بغياب أي فرق جهد"],"a":1,"why":"المميّزة صفة ذرّية لمادة الهدف (انتزاع إلكترون داخلي وإعادة ملء)؛ المستمرة تنتج من تباطؤ الإلكترونات بمجال نوى الهدف."},{"ch":"g6c8","q":"(سؤال وزاري متكرر) علّل: يُعدّ تأثير كومبتن دليلاً على السلوك الجسيمي للأشعة الكهرومغناطيسية.","opts":["لأن الفوتون يتحرك بسرعة أبطأ من الضوء بهذا التأثير","لأن الأشعة المستطارة تختفي كلياً بعد التصادم","لأن تفسير زيادة الطول الموجي المستطار يتطلّب افتراض تصادم مرن بين الفوتون والإلكترون خاضع لحفظ الزخم والطاقة — سلوك جسيمي بحت","لأن التأثير لا علاقة له بمفهوم الطاقة إطلاقاً"],"a":2,"why":"تفسير الزيادة بالطول الموجي يتطلّب معاملة الفوتون كجسيم له زخم محدد يتصادم تصادماً مرناً مع الإلكترون."},{"ch":"g6c8","q":"وفق علاقة كومبتن، على ماذا تعتمد الزيادة بالطول الموجي λ′−λ؟","opts":["على زاوية الاستطارة θ فقط","على شدة الحزمة الساقطة فقط","على درجة حرارة الهدف فقط","على المسافة بين المصدر والهدف فقط"],"a":0,"why":"Δλ=(h/mₑc)(1−cosθ) — تعتمد فقط على زاوية الاستطارة θ، لا على شدة الحزمة أو أي عامل آخر."},{"ch":"g6c8","q":"فوتون استطار بزاوية 90° بتأثير كومبتن. جد مقدار الزيادة بطوله الموجي (طول موجة كومبتن=0.24×10⁻¹¹m).","opts":["≈0.48×10⁻¹¹ m","صفر تماماً","≈0.12×10⁻¹¹ m","≈0.24×10⁻¹¹ m"],"a":3,"why":"عند θ=90°: cos90°=0، فإن Δλ=(0.24×10⁻¹¹)(1−0)=0.24×10⁻¹¹m."},{"ch":"g6c8","q":"(مسألة وزارية مركّبة) أقصر طول موجي أشعة سينية عند V=1.24×10⁴V يساوي 0.1nm. إذا استطارت بزاوية 90° بتأثير كومبتن، فما طولها الموجي المستطار؟","opts":["0.1 nm","0.1024 nm","0.0976 nm","0.2 nm"],"a":1,"why":"λ′=λ+Δλ=0.1nm+0.0024nm=0.1024nm (حيث Δλ=(0.24×10⁻¹¹)(1−cos90°)=0.24×10⁻¹¹m=0.0024nm)."},{"ch":"g6c8","q":"(سؤال وزاري) ماذا تعني كلمة الليزر (LASER)؟","opts":["تضخيم الموجات الدقيقة بوساطة الانبعاث التلقائي","تحويل الضوء إلى موجات صوتية","تضخيم الضوء بوساطة الانبعاث المحفَّز للإشعاع","امتصاص الضوء بوساطة الانبعاث التلقائي"],"a":2,"why":"LASER = Light Amplification by Stimulated Emission of Radiation = تضخيم الضوء بوساطة الانبعاث المحفَّز للإشعاع."},{"ch":"g6c8","q":"من صمّم أول جهاز ليزر فعلياً عام 1960؟","opts":["T.H. Maiman باستعمال بلورة الياقوت","ألبرت أينشتاين","تاونس","رونتجن"],"a":0,"why":"Maiman صمّم أول ليزر فعلي (ليزر الياقوت) عام 1960؛ أينشتاين وضع الأساس النظري فقط عام 1917، وتاونس صمّم الميزر لا الليزر."},{"ch":"g6c8","q":"أي خاصية من خصائص الليزر تفسّر أن بقعته على سطح القمر أصغر بكثير من بقعة ضوء عادي مرسَل لنفس المسافة؟","opts":["أحادية الطول الموجي","التشاكه","السطوع العالي","الاتجاهية (بقاء الحزمة متوازية بانفراجية قليلة)"],"a":3,"why":"الاتجاهية تجعل حزمة الليزر تبقى شبه متوازية لمسافات هائلة، بعكس الضوء العادي الذي ينتشر بكل الاتجاهات."},{"ch":"g6c8","q":"ما الفرق بين الانبعاث التلقائي والانبعاث المحفَّز؟","opts":["لا فرق بينهما إطلاقاً","التلقائي عشوائي الطور والاتجاه؛ المحفَّز ينتج فوتوناً مطابقاً تماماً للفوتون المحفِّز","المحفَّز فقط يحتاج طاقة؛ التلقائي مجاني كلياً","التلقائي وحده أساس عمل الليزر"],"a":1,"why":"الانبعاث التلقائي عشوائي بلا محفِّز خارجي؛ المحفَّز ينتج فوتوناً مطابقاً تماماً (طور، اتجاه، تردد) للفوتون الذي حفّزه — أساس الليزر."},{"ch":"g6c8","q":"بالتوازن الحراري الطبيعي (بلا ضخّ)، أي علاقة صحيحة بين N₁ وN₂؟","opts":["N₂ أكبر من N₁ دائماً","يتساويان دائماً بأي درجة حرارة","N₁ أكبر من N₂ دائماً وفق قانون بولتزمان","لا توجد علاقة ثابتة إطلاقاً"],"a":2,"why":"قانون بولتزمان N₂/N₁=exp[−(E₂−E₁)/kT] يعطي دائماً نسبة أقل من 1 (لأن الأس سالب)، أي N₁>N₂."},{"ch":"g6c8","q":"(سؤال وزاري) هل يتحقّق التوزيع المعكوس عندما تكون الطاقة الحرارية kT مساوية لطاقة الفوتون الساقط hf؟","opts":["لا، لأن التعويض يعطي N₂/N₁=exp(−1)=0.37<1","نعم دائماً بهذه الحالة تحديداً","يتحقق فقط بدرجات الحرارة المنخفضة جداً","التوزيع المعكوس لا علاقة له بدرجة الحرارة إطلاقاً"],"a":0,"why":"بوضع kT=hf=E₂−E₁ بقانون بولتزمان: N₂/N₁=exp(−1)=0.37<1، أي N₂<N₁ — لا يتحقق شرط التوزيع المعكوس (N₂>N₁)."},{"ch":"g6c8","q":"ما اسم مكونات جهاز الليزر الثلاثة؟","opts":["الكاثود والأنود والمصهر","مرآتان عاكستان كلياً فقط","بطارية ومقاومة ومكثّف فقط","الوسط الفعال، المرنان، وتقنية الضخّ"],"a":3,"why":"كل أجهزة الليزر تشترك بثلاثة مكونات: الوسط الفعال، المرنان (مرآتان)، وتقنية الضخّ."},{"ch":"g6c8","q":"(سؤال وزاري متكرر حرفياً) أيّهما أفضل لتوليد الليزر: منظومة المستويات الثلاثة أم الأربعة؟","opts":["الثلاثة أفضل، لأنها أبسط تصميماً فقط","الأربعة أفضل، لأنها تتطلّب طاقة ضخّ أقل لتحقيق التوزيع المعكوس","كلاهما متكافئتان تماماً بلا أي فرق","لا علاقة لعدد المستويات بكفاءة توليد الليزر"],"a":1,"why":"المنظومة الرباعية أفضل لأن مستواها الأدنى للانتقال الليزري شبه فارغ أصلاً (هبوط سريع منه)، فتحتاج طاقة ضخّ أقل من الثلاثية."},{"ch":"g6c8","q":"أي نوع ليزر وسطه الفعال بلورة صلبة (كالياقوت أو النيديميوم)؟","opts":["ليزر الحالة الغازية","ليزر أشباه الموصلات فقط","ليزر الحالة الصلبة","الليزر الكيميائي فقط"],"a":2,"why":"ليزر الحالة الصلبة وسطه الفعال بلورة صلبة كالياقوت (أول ليزر بالتاريخ) أو النيديميوم."},{"ch":"g6c8","q":"(سؤال وزاري) ما مكونات منظومات الليزرات الغازية الرئيسة؟","opts":["الوسط الفعال الغازي، المرنان، وميكانيكية الضخّ (غالباً كهربائي)","بلورة صلبة فقط بلا أي غاز","مرآة واحدة عاكسة جزئياً فقط","قطب كهربائي واحد بلا أي دائرة"],"a":0,"why":"الليزرات الغازية (كالهيليوم-نيون) تتضمّن وسطاً فعالاً غازياً، مرناناً (مرآتان)، وضخّاً كهربائياً غالباً (تفريغ كهربائي بالغاز)."},{"ch":"g6c8","q":"أي تطبيق للليزر يستثمر خاصيتي الاتجاهية والسطوع معاً بشكل مباشر لثقب المعادن وقطعها؟","opts":["قياس تلوث البيئة فقط","التصوير المجسّم فقط","مسح الأراضي الزراعية فقط","التطبيقات الصناعية (لحام وقطع المعادن بحرارة منحصرة بمساحة صغيرة جداً)"],"a":3,"why":"تركّز الطاقة العالية (السطوع) بحزمة ضيقة جداً (الاتجاهية) يسمح بقطع المعادن ولحامها بدقة، بلا تأثير بالمناطق المجاورة."},{"ch":"g6c8","q":"ما الفرق بين ليزر الإكسايمر وليزر الصبغة من حيث الوسط الفعال؟","opts":["كلاهما نفس الوسط الفعال تماماً","الإكسايمر: غازات نبيلة مع هالوجين (فوق بنفسجي)؛ الصبغة: محلول صبغة عضوية مذابة بمذيب","الإكسايمر وسطه صلب؛ الصبغة وسطها غازي","لا يوجد أي نوع اسمه ليزر الصبغة إطلاقاً"],"a":1,"why":"ليزر الإكسايمر يستعمل غازات نبيلة مع هالوجين (كـArF أو KrF)؛ ليزر الصبغة يستعمل محلول صبغة عضوية (كرودامين 6G) مذاباً بمذيب."},{"ch":"g6c9","q":"ماذا استنتج رذرفورد من تجربة استطارة جسيمات ألفا على رقاقة الذهب؟","opts":["أن الذرّة كتلة موحّدة الكثافة بلا أي تركيز للشحنة","أن الذرّة لا تحتوي أي شحنة موجبة إطلاقاً","أن معظم كتلة الذرّة وشحنتها الموجبة تتركّز في نواة صغيرة جداً وكثيفة بمركزها","أن الإلكترونات موجودة داخل النواة نفسها"],"a":2,"why":"ارتداد بعض جسيمات ألفا بزوايا كبيرة جداً دلّ على وجود حيّز صغير جداً وكثيف جداً يركّز معظم كتلة الذرّة وشحنتها الموجبة — النواة."},{"ch":"g6c9","q":"نواة عدد بروتوناتها Z=17 وعدد نيوتروناتها N=18. جد عددها الكتلي A وشحنتها q.","opts":["A=35، q=28.8×10⁻¹⁹C","A=35، q=27.2×10⁻¹⁹C","A=18، q=27.2×10⁻¹⁹C","A=35، q=17×10⁻¹⁹C"],"a":1,"why":"A=Z+N=17+18=35. q=Ze=17×1.6×10⁻¹⁹=27.2×10⁻¹⁹C."},{"ch":"g6c9","q":"نصف قطر النواة (R) يتغيّر:","opts":["عكسياً مع A^(1/3)","طردياً مع A³","عكسياً مع A³","طردياً مع A^(1/3)"],"a":3,"why":"R=r₀A^(1/3) — علاقة طردية مع الجذر التكعيبي للعدد الكتلي، أثبتتها تجارب استطارة ألفا."},{"ch":"g6c9","q":"جد نصف قطر نواة الحديد (A=56 تقريباً) بوحدة الفيرمي تقريباً (استعمل (56)^(1/3)≈3.83).","opts":["≈1.2 F","≈4.6 F","≈56 F","≈67.2 F"],"a":1,"why":"R=1.2×(56)^(1/3)≈1.2×3.83≈4.6 F."},{"ch":"g6c9","q":"ما خصائص القوة النووية القوية التي تربط نيوكليونات النواة؟","opts":["تعتمد على الشحنة فقط، وذات مدى بعيد جداً","أضعف من القوة الكهرومغناطيسية دائماً","لا تعتمد على الشحنة، ذات مدى قصير جداً، والأقوى في الطبيعة","تؤثر فقط بين البروتونات دون النيوترونات"],"a":2,"why":"القوة النووية القوية لا تعتمد على نوع الشحنة (تربط p-p وn-n وp-n)، مداها قصير جداً (ضمن أبعاد النواة)، وهي الأقوى بين القوى الأربع الأساسية."},{"ch":"g6c9","q":"لماذا لا تتفكك النواة رغم أن كل بروتوناتها موجبة الشحنة ومتنافرة كهربائياً؟","opts":["لأن النيوترونات تلغي شحنة البروتونات كلياً","لأن البروتونات تفقد شحنتها داخل النواة","لأن الجاذبية بين النيوكليونات تتغلب على التنافر الكهربائي","لأن القوة النووية القوية بين النيوكليونات أقوى بكثير من قوة التنافر الكهربائي الكولومي بين البروتونات"],"a":3,"why":"القوة النووية القوية أقوى من القوة الكهرومغناطيسية بمدى النواة القصير، فتتغلّب على تنافر كولوم بين البروتونات وتُبقي النواة متماسكة."},{"ch":"g6c9","q":"لماذا تكون كتلة النواة دائماً أقل من مجموع كتل بروتوناتها ونيوتروناتها منفصلة؟","opts":["لأن جزءاً من الكتلة يتحوّل إلى طاقة الربط النووية التي تماسك النواة (Eb=Δmc²)","لأن النواة تفقد بعض بروتوناتها عند تكوّنها","بسبب خطأ قياس دائم في كل الأجهزة المستعملة","لأن النيوترونات عديمة الكتلة أصلاً داخل النواة"],"a":0,"why":"النقص الكتلي Δm يكافئ طاقة الربط النووية المتحررة عند تكوّن النواة، وفق علاقة أينشتاين Eb=Δmc²."},{"ch":"g6c9","q":"ما المقصود بمعدل طاقة الربط النووية لكل نيوكليون Eb'؟","opts":["مجموع كتل كل النيوكليونات بالنواة","حاصل قسمة طاقة الربط الكلية Eb على العدد الكتلي A","حاصل ضرب Eb في العدد الذري Z","الفرق بين كتلة النواة وكتلة الذرّة"],"a":1,"why":"Eb'=Eb/A — يقيس متوسط طاقة الربط لكل نيوكليون واحد بالنواة، ويُستعمل لمقارنة استقرار النوى المختلفة."},{"ch":"g6c9","q":"أي نوى العناصر تمتلك أكبر قيمة لمعدل طاقة الربط النووية Eb'، وبالتالي الأكثر استقراراً؟","opts":["النوى الخفيفة جداً فقط","النوى الثقيلة جداً فقط","كل النوى بنفس القيمة تماماً بلا استثناء","النوى المتوسطة (كنواة الحديد ⁵⁶Fe)"],"a":3,"why":"منحنى Eb' مقابل A يبلغ ذروته عند النوى المتوسطة، وأشهرها نواة الحديد ⁵⁶Fe — لذا فهي الأكثر استقراراً."},{"ch":"g6c9","q":"نواة كتلتها الذرّية M، عدد بروتوناتها Z، عدد نيوتروناتها N. ما الصيغة الصحيحة للنقص الكتلي Δm (بكتل الذرّات)؟","opts":["Δm = M − Z·M_H − N·mₙ","Δm = Z·M_H + N·mₙ − M","Δm = Z·M_H − N·mₙ + M","Δm = Z + N − M"],"a":1,"why":"النقص الكتلي = مجموع كتل المكوّنات منفصلة (Z ذرّات هيدروجين + N نيوترونات) ناقص كتلة الذرّة الكاملة الفعلية M."},{"ch":"g6c9","q":"طاقة الربط النووية لنواة معيّنة Eb=120 MeV وعددها الكتلي A=20. جد معدل طاقة الربط لكل نيوكليون.","opts":["600 MeV/nucleon","6 MeV/nucleon","0.167 MeV/nucleon","2400 MeV/nucleon"],"a":1,"why":"Eb'=Eb/A=120/20=6 MeV/nucleon."},{"ch":"g6c9","q":"لماذا يمكن لكل من الانشطار (نوى ثقيلة) والاندماج (نوى خفيفة) أن يحرّرا طاقة هائلة، رغم أنهما عمليتان متعاكستان تماماً؟","opts":["لأن كلتيهما تنقلان النوى المتفاعلة نحو منطقة النوى المتوسطة الأعلى استقراراً (أعلى Eb')، فيتحرر فرق الطاقة أثناء ذلك","لأن الانشطار يزيد الكتلة والاندماج ينقصها بنفس المقدار دائماً","لأنهما في الحقيقة نفس العملية الفيزيائية بمسمّيين مختلفين فقط","لأن كلتيهما لا تغيّران نوع النوى المتفاعلة إطلاقاً"],"a":0,"why":"النوى الثقيلة جداً (منخفضة Eb') تنشطر لتقترب من منطقة الذروة، والنوى الخفيفة جداً (منخفضة Eb' أيضاً) تندمج لتقترب من نفس المنطقة — وكلتاهما تحرّران الفرق كطاقة."},{"ch":"g6c9","q":"ما جسيمة ألفا (α) في الحقيقة؟","opts":["إلكترون حر الحركة","فوتون عالي الطاقة","نواة ذرّة الهيليوم (بروتونان ونيوترونان)","نيوترون منفرد"],"a":2,"why":"جسيمة ألفا هي نواة ذرّة الهيليوم بالضبط (⁴₂He): بروتونان ونيوترونان، شحنتها +2e."},{"ch":"g6c9","q":"ماذا يحدث للعدد الكتلي A والعدد الذري Z عند انحلال ألفا؟","opts":["يزداد A بمقدار 4، ويزداد Z بمقدار 2","لا يتغيّر أي منهما إطلاقاً","ينقص A بمقدار 4، وينقص Z بمقدار 2","ينقص A بمقدار 2، وينقص Z بمقدار 4"],"a":2,"why":"انحلال ألفا يحمل معه دائماً بروتونين ونيوترونين، فينقص A بمقدار 4 وZ بمقدار 2."},{"ch":"g6c9","q":"في المعادلة: ²³⁸₉₂U → A₉₀Th + ⁴₂He، جد قيمة A.","opts":["236","238","230","234"],"a":3,"why":"بحفظ العدد الكتلي: 238 = A + 4 ⟹ A = 234."},{"ch":"g6c9","q":"ما الشرط اللازم لكي تنحلّ نواة تلقائياً بوساطة انحلال ألفا؟","opts":["أن تكون قيمة Qα موجبة (Qα&gt;0)","أن تكون قيمة Qα سالبة (Qα&lt;0)","أن تكون قيمة Qα تساوي صفراً بالضبط","لا يوجد أي شرط؛ يحدث دائماً بشكل عشوائي"],"a":0,"why":"الانحلال التلقائي يتطلّب تحرّر طاقة، أي Qα موجبة؛ لو كانت سالبة لاستحال حدوث الانحلال من تلقاء نفسه."},{"ch":"g6c9","q":"نواة أم كتلتها 210.048u، تنحلّ بألفا لنواة وليدة كتلتها 206.038u، وكتلة جسيمة ألفا 4.002603u. جد طاقة الانحلال Qα تقريباً بوحدة MeV، وهل يحدث الانحلال تلقائياً؟","opts":["Qα≈−1.6 MeV؛ لا يحدث تلقائياً","Qα≈7.4 MeV؛ يحدث تلقائياً","Qα≈6.9 MeV؛ يحدث تلقائياً","Qα≈0 MeV؛ حالة توازن فقط"],"a":2,"why":"Qα=[210.048−206.038−4.002603]×931=[0.007397]×931≈6.9 MeV؛ بما أنها موجبة فالانحلال يحدث تلقائياً."},{"ch":"g6c9","q":"لماذا يساعد انبعاث جسيمة ألفا نواة كبيرة الحجم والكتلة على الوصول لاستقرار أكبر؟","opts":["لأنه يزيد كتلة النواة وحجمها أكثر فأكثر","لأنه يقلّص كتلة النواة وحجمها، مقرِّباً إياها من منطقة النوى الأكثر استقراراً","لأنه يحوّل كل بروتونات النواة إلى نيوترونات","لأنه يجمّد حركة النواة تماماً"],"a":1,"why":"قذف جسيمة ألفا كاملة (4 نيوكليونات دفعة واحدة) يقلّص كتلة وحجم النواة الثقيلة، مقرِّباً معدل طاقة ربطها من ذروة الاستقرار عند النوى المتوسطة."},{"ch":"g6c9","q":"متى تُعاني نواة انحلال بيتا السالبة (β⁻)؟","opts":["عندما تكون نسبة النيوترونات إلى البروتونات أكبر من النسبة اللازمة للاستقرار","عندما تكون نسبة البروتونات إلى النيوترونات أكبر من اللازم","عندما يتساوى عدد البروتونات والنيوترونات تماماً دائماً","عندما تفقد النواة كل نيوتروناتها دفعة واحدة"],"a":0,"why":"زيادة نسبة النيوترونات عن الحد المستقر تدفع أحد النيوترونات للتحوّل إلى بروتون، باعثاً إلكتروناً (β⁻) ومضاد نيوترينو."},{"ch":"g6c9","q":"عندما تعاني نواة تلقائياً انحلال بيتا السالبة، فإن عددها الذري:","opts":["يقل بمقدار اثنين","لا يتغيّر إطلاقاً","يزداد بمقدار واحد","يقل بمقدار واحد"],"a":2,"why":"أحد نيوترونات النواة يتحوّل إلى بروتون، فيزداد العدد الذري (عدد البروتونات) بمقدار 1، بينما يبقى العدد الكتلي ثابتاً."},{"ch":"g6c9","q":"ما البوزترون (جسيمة بيتا الموجبة)؟","opts":["نواة ذرّة هيليوم كاملة","جسيم يمتلك كل صفات الإلكترون إلا أن شحنته موجبة — يُسمّى أيضاً مضاد الإلكترون","فوتون عالي الطاقة بلا أي شحنة","نيوترون تحوّل إلى فوتون"],"a":1,"why":"البوزترون نفس كتلة الإلكترون بالضبط، لكن شحنته +e بدل −e، ولهذا يُدعى «مضاد الإلكترون»."},{"ch":"g6c9","q":"ما الذي يبقى ثابتاً تماماً (بلا أي تغيّر) في انحلال كاما وحده، خلافاً لكل الانحلالات الأخرى؟","opts":["كتلة النواة السكونية فقط","طاقة النواة فقط","العدد الكتلي A والعدد الذري Z معاً","شحنة الفوتون المنبعث فقط"],"a":2,"why":"انحلال كاما يحرّر فائض طاقة فقط (فوتون)، بلا أي تغيّر بتركيب النواة نفسها — فيبقى A وZ ثابتين تماماً، خلافاً لألفا وبيتا."},{"ch":"g6c9","q":"نواة تنحلّ من ²¹⁴₈₂Pb إلى ²¹⁴₈₃Bi. ما نوع هذا الانحلال؟","opts":["كاما","ألفا","بيتا الموجبة","بيتا السالبة"],"a":3,"why":"ΔA=214−214=0 (ثابت)، ΔZ=83−82=+1 (يزداد بمقدار 1) — هذا بالضبط نمط انحلال بيتا السالبة."},{"ch":"g6c9","q":"لماذا تخترق أشعة كاما المواد بسهولة أكبر بكثير من جسيمات ألفا، رغم أن كليهما إشعاع مؤيّن؟","opts":["لأن كتلة كاما أكبر بكثير من كتلة ألفا","لأن كاما فوتونات متعادلة الشحنة عالية الطاقة، بينما ألفا جسيمات ثقيلة نسبياً وموجبة الشحنة تتفاعل بقوة مع ذرات المادة فتفقد طاقتها سريعاً","لأن كاما أبطأ من ألفا بكثير عند الانبعاث","لأن ألفا تحمل شحنة سالبة تجذبها المادة بقوة"],"a":1,"why":"جسيمات ألفا الثقيلة الموجبة الشحنة تتفاعل بشدة مع إلكترونات وذرات المادة (تأيّن قوي)، فتفقد طاقتها بسرعة كبيرة ومسافة اختراق قصيرة جداً؛ أما كاما (متعادلة، عالية الطاقة) فتتفاعل بشكل أضعف بكثير، فتخترق أعمق بكثير."},{"ch":"g6c9","q":"من أول عالِم برهن على حدوث تفاعل نووي محتث (اصطناعي)؟","opts":["فيرمي","ماري كوري","أينشتاين","رذرفورد"],"a":3,"why":"رذرفورد أول من حقّق تفاعلاً نووياً محتثاً، عبر تفاعل ⁴₂He+¹⁴₇N→¹⁷₈O+¹₁H."},{"ch":"g6c9","q":"لماذا يُعدّ النيوترون قذيفة أفضل من جسيمة ألفا أو البروتون لإحداث تفاعل نووي؟","opts":["لأن شحنته صفر فلا تصدّه قوة كولوم التنافرية عند اقترابه من النواة الموجبة","لأنه أثقل بكثير من البروتون وألفا معاً","لأنه يتحرك دائماً بسرعة الضوء","لأنه الجسيم الوحيد القادر على الانحلال تلقائياً"],"a":0,"why":"غياب الشحنة عن النيوترون يلغي قوة التنافر الكهربائي مع النواة الموجبة، فيدخلها بسهولة أكبر بكثير من الجسيمات المشحونة."},{"ch":"g6c9","q":"أي قوانين الحفظ التالية يجب أن تتحقق بأي تفاعل نووي؟","opts":["حفظ الشحنة الكهربائية فقط","لا يوجد أي قانون حفظ ملزم بالتفاعلات النووية","حفظ الطاقة-الكتلة فقط، دون أي قانون آخر","حفظ الطاقة-الكتلة، والزخم الخطي، والزخم الزاوي، والشحنة (Z)، وعدد النيوكليونات (A) معاً"],"a":3,"why":"التفاعل النووي يجب أن يحقق خمسة قوانين حفظ معاً: الطاقة-الكتلة، الزخم الخطي، الزخم الزاوي، الشحنة (العدد الذري)، وعدد النيوكليونات (العدد الكتلي)."},{"ch":"g6c9","q":"في تفاعل نووي، إذا كانت قيمة طاقة التفاعل Q سالبة، فماذا يعني ذلك؟","opts":["التفاعل محرِّر للطاقة ويحدث تلقائياً دوماً","التفاعل مستحيل الحدوث بأي ظرف كان","لا معنى فيزيائياً لإشارة Q السالبة","التفاعل ماص للطاقة، ويحتاج طاقة خارجية إضافية ليحدث"],"a":3,"why":"Q&lt;0 يعني أن كتلة النواتج أكبر من كتلة المتفاعلين، فيحتاج التفاعل طاقة خارجية (كطاقة حركية للجسيم الساقط) ليعوّض هذا الفرق ويحدث فعلياً."},{"ch":"g6c9","q":"في تفاعل: ¹₀n + ¹⁴₇N → ¹₁H + Y، ما العدد الذري والعدد الكتلي للنواة الناتجة Y؟","opts":["Z=7، A=14","Z=7، A=15","Z=6، A=14","Z=6، A=15"],"a":2,"why":"حفظ Z: 0+7=1+Z ⟹ Z=6. حفظ A: 1+14=1+A ⟹ A=14. إذن Y هي ¹⁴₆C (كربون)."},{"ch":"g6c9","q":"لماذا يجب أن تكون أي معادلة نووية «موزونة» (مجموع Z ومجموع A متساويين بطرفيها)؟","opts":["لأن هذا صحيح فقط بتفاعلات الانشطار دون غيرها","لأن العدد الذري والعدد الكتلي يتغيّران دائماً بالتفاعلات النووية","لأن قانونَي حفظ الشحنة الكهربائية وحفظ عدد النيوكليونات يجب أن يتحققا بأي تفاعل نووي حقيقي","لأن هذا مجرد اصطلاح كتابي بلا أي أساس فيزيائي"],"a":2,"why":"توازن المعادلة النووية هو الانعكاس المباشر لقانونَي حفظ الشحنة (Z) وحفظ عدد النيوكليونات (A) — لا يمكن لأي تفاعل حقيقي أن يخالفهما."},{"ch":"g6c9","q":"ما تعريف الانشطار النووي؟","opts":["اندماج نواتين خفيفتين لتكوين نواة أثقل","انقسام نواة ثقيلة إلى نواتين متوسطتي الكتلة، عادة بقصفها بنيوترون بطيء","انبعاث جسيمة ألفا من نواة ثقيلة","تحوّل بروتون داخل النواة إلى نيوترون"],"a":1,"why":"الانشطار النووي يقسّم نواة ثقيلة (كاليورانيوم) إلى نواتين متوسطتين، عادة بامتصاص نيوترون حراري بطيء."},{"ch":"g6c9","q":"لماذا يُستعمل نيوترون بطيء (حراري) تحديداً لإحداث انشطار اليورانيوم ²³⁵₉₂U؟","opts":["لأن النيوترون البطيء له شحنة كهربائية أكبر","لأن النيوترون البطيء وحده خالٍ من الكتلة","لأن سرعته العالية جداً تخترق النواة مباشرة دون امتصاص","لأن احتمالية امتصاصه بوساطة نواة اليورانيوم وتشكيل نواة مركّبة مثارة أكبر عند هذه الطاقة المنخفضة"],"a":3,"why":"نوى اليورانيوم-235 تمتص النيوترونات البطيئة (الحرارية، ~0.025eV) بكفاءة عالية، مكوّنة نواة مركّبة مثارة تنشطر فوراً تقريباً."},{"ch":"g6c9","q":"في انشطار نموذجي لليورانيوم، كم نيوتروناً جديداً يُنتَج تقريباً من كل انشطار؟","opts":["لا يُنتَج أي نيوترون جديد إطلاقاً","اثنان أو ثلاثة نيوترونات تقريباً","نيوترون واحد فقط دائماً بلا استثناء","عشرة نيوترونات أو أكثر دائماً"],"a":1,"why":"الانشطار النووي ينتج نموذجياً 2 أو 3 نيوترونات جديدة، وهي التي تُمكِّن من استمرار التفاعل المتسلسل."},{"ch":"g6c9","q":"ما الفرق الجوهري بين معامل تضاعف k=1 وk>1 بالتفاعل النووي المتسلسل؟","opts":["k>1 يعني توقف التفاعل نهائياً دون أي استمرار","لا فرق بينهما إطلاقاً بأي شكل","k=1 حالة حرجة مضبوطة (كمفاعل)، وk>1 تصاعد سريع غير محكوم (كقنبلة)","k=1 تفاعل خامد تماماً، وk>1 تفاعل ثابت متحكَّم به بمفاعل نووي"],"a":2,"why":"k=1 يعني كل انشطار ينتج بالضبط نيوتروناً فعّالاً واحداً يستمر به التفاعل بمعدل ثابت (مفاعل)؛ k>1 يعني تصاعداً هندسياً سريعاً غير محكوم (قنبلة)."},{"ch":"g6c9","q":"من حقّق أول تفاعل نووي انشطاري متسلسل مسيطر عليه من قِبل الإنسان، وأين؟","opts":["ماري كوري، بفرنسا","فيرمي وفريقه، بمدينة شيكاغو عام 1942","رذرفورد، ببريطانيا","أينشتاين، بألمانيا"],"a":1,"why":"حقّق العالِم إنريكو فيرمي وفريقه أول تفاعل نووي متسلسل مسيطر عليه بأول مفاعل نووي («الكومة») بجامعة شيكاغو عام 1942."},{"ch":"g6c9","q":"من أين تأتي الطاقة الهائلة المتحررة (~200 MeV) عند انشطار نواة يورانيوم واحدة؟","opts":["من احتراق كيميائي عادي لليورانيوم مثل أي وقود آخر","من طاقة حركية النيوترون البطيء الساقط وحدها فقط","من تفكك الإلكترونات المدارية حول النواة","من الفرق بين مجموع كتل المتفاعلين ومجموع كتل النواتج، المتحوّل إلى طاقة وفق E=mc²"],"a":3,"why":"مجموع كتل نواتج الانشطار (نواتان + نيوترونات) أقل من مجموع كتل المتفاعلين؛ هذا النقص الكتلي يتحوّل بالكامل إلى طاقة هائلة وفق علاقة أينشتاين."},{"ch":"g6c9","q":"ما تعريف الاندماج النووي؟","opts":["اندماج نواتين خفيفتين (صغيرتي الكتلة) لتكوين نواة أثقل، مع تحرر طاقة","انقسام نواة ثقيلة إلى نواتين متوسطتين","انبعاث جسيمة بيتا من نواة غير مستقرة","امتصاص نواة لنيوترون بطيء دون أي تغيّر بتركيبها"],"a":0,"why":"الاندماج النووي يدمج نواتين خفيفتين في نواة أثقل واحدة، وفرق الكتلة (الناتج أخف من مجموع الأصليين) يتحوّل إلى طاقة."},{"ch":"g6c9","q":"ما العملية الرئيسة المسؤولة عن إنتاج طاقة الشمس؟","opts":["احتراق كيميائي عادي للهيدروجين مع الأكسجين","انشطار نووي متسلسل لليورانيوم بباطن الشمس","دورة بروتون-بروتون: اندماج نوى الهيدروجين لتكوين الهيليوم","تفاعلات كيميائية بين طبقات الغلاف الجوي للشمس فقط"],"a":2,"why":"دورة بروتون-بروتون (اندماج أربعة بروتونات هيدروجين في نهاية المطاف لتكوين نواة هيليوم واحدة) هي المصدر الرئيس لطاقة الشمس."},{"ch":"g6c9","q":"ما العائق الرئيس أمام تحقيق اندماج نووي مفيد؟","opts":["نقص المواد الخام اللازمة لنظائر الهيدروجين","أن الاندماج لا يحرر أي طاقة إطلاقاً فيصبح بلا فائدة","عدم وجود أي قانون فيزيائي يسمح بحدوثه أصلاً","قوة كولوم الكهربائية التنافرية الكبيرة بين النوى الموجبة الشحنة عند المسافات القصيرة"],"a":3,"why":"تنافر كولوم بين النوى الموجبة يمنعها من الاقتراب كفاية لدخول نطاق القوة النووية القوية، ما لم تُمنح طاقة حركية هائلة (حرارة عالية جداً) للتغلّب عليه."},{"ch":"g6c9","q":"لماذا يتطلّب الاندماج النووي درجات حرارة هائلة (~10⁸K)؟","opts":["لتبريد النوى المتفاعلة إلى حالة سكون تامة","لأن البرودة الشديدة هي الشرط الوحيد لأي تفاعل نووي","لمنح النوى طاقة حركية كافية للتغلّب على قوة تنافر كولوم والاقتراب كفاية للاندماج","لتفكيك النوى إلى بروتونات ونيوترونات منفصلة قبل الاندماج"],"a":2,"why":"فقط عند حرارة هائلة جداً تمتلك النوى طاقة حركية كافية للتغلّب على حاجز تنافر كولوم والاقتراب لمسافة تسمح بتأثير القوة النووية القوية."},{"ch":"g6c9","q":"ما البلازما، ولماذا يحتاجها الاندماج النووي؟","opts":["مادة صلبة شديدة البرودة تحبس النوى بإحكام","الحالة الرابعة للمادة: نوى وإلكترونات منفصلة حرّة الحركة، تنشأ عند الحرارة الهائلة اللازمة للاندماج","نوع خاص من السوائل يُستعمل فقط لتبريد المفاعلات","غاز خامل يُستعمل لعزل التفاعل عن الهواء المحيط فقط"],"a":1,"why":"عند حرارة ~10⁸K تتفكك الذرات إلى نوى وإلكترونات حرّة منفصلة — هذه الحالة الرابعة للمادة (البلازما) هي الوسط الذي يحدث فيه الاندماج فعلياً."},{"ch":"g6c9","q":"ما الفرق الأساسي بين نفايات الانشطار والاندماج النوويين؟","opts":["نواتج الانشطار غالباً نوى مشعة خطرة لفترات طويلة، بينما نواتج الاندماج (كالهيليوم) غالباً غير مشعة وغير ضارة","كلاهما ينتج نفس النوع والكمية من النفايات المشعة تماماً","الاندماج ينتج نفايات مشعة أخطر بكثير من الانشطار دائماً","لا ينتج الانشطار أي نفايات مشعة إطلاقاً بأي حال"],"a":0,"why":"نواتج الانشطار عادة نوى جديدة غير مستقرة (مشعة) تبقى خطرة لفترات طويلة، بينما نواتج الاندماج (كالهيليوم) نظير مستقر غير مشعّ عادة — لهذا يُعدّ الاندماج أنظف نسبياً من ناحية النفايات."},{"ch":"g6c9","q":"اذكر مثالاً على مصدر إشعاع نووي طبيعي (خلفي).","opts":["الأشعة الكونية القادمة من الفضاء","إشعاعات المفاعلات النووية","المصادر الطبية للتشخيص والعلاج","النفايات النووية المشعة"],"a":0,"why":"الأشعة الكونية من مصادر الإشعاع الخلفي الطبيعي، إلى جانب الإشعاع من القشرة الأرضية والنشاط الإشعاعي داخل جسم الإنسان."},{"ch":"g6c9","q":"ما الفرق بين التأثيرات الجسدية والتأثيرات الوراثية للإشعاع النووي؟","opts":["الجسدية ضرر بالخلايا الاعتيادية (كالسرطان)، والوراثية ضرر بالخلايا التناسلية قد ينتقل للأجيال اللاحقة","الوراثية فقط تحدث من مصادر الإشعاع الطبيعي دون الاصطناعي","لا فرق بينهما إطلاقاً؛ مصطلحان لنفس التأثير","الجسدية فقط تحدث من الجرعات الصغيرة جداً"],"a":0,"why":"التأثيرات الجسدية تصيب خلايا الجسم الاعتيادية (مبكرة كالتهاب الجلد أو متأخرة كالسرطان)، بينما الوراثية تصيب الخلايا التناسلية وتنتقل للأجيال اللاحقة."},{"ch":"g6c9","q":"ما الإجراءات الاحترازية الثلاثة الأساسية لتقليل التعرّض للإشعاع النووي الاضطراري؟","opts":["زيادة زمن التعرّض للتعوّد عليه تدريجياً","الاقتراب من المصدر لفهم طبيعته بدقة أكبر","لا توجد أي إجراءات احترازية ممكنة إطلاقاً","تقليل زمن التعرّض، الابتعاد عن المصدر، واستعمال درع واقٍ ملائم"],"a":3,"why":"الإجراءات الثلاثة المعتمدة: تقليل زمن التعرّض إلى أقل ما يمكن، الابتعاد عن مصدر الإشعاع أكثر ما يمكن، واستعمال حواجز واقية ملائمة (كالرصاص)."},{"ch":"g6c9","q":"أي مادة شائعة تُستعمل غالباً كدرع واقٍ فعّال ضد أشعة كاما عالية الاختراق؟","opts":["الورق العادي الرقيق","الهواء وحده بلا أي مادة إضافية","الرصاص (أو الخرسانة السميكة)","قطعة قماش رقيقة"],"a":2,"why":"المواد الكثيفة كالرصاص أو الخرسانة السميكة قادرة على امتصاص جزء كبير من أشعة كاما عالية الاختراق، بعكس الورق الذي يوقف ألفا فقط."},{"ch":"g6c9","q":"أي استعمال من التالي يمثّل تطبيقاً طبياً سلمياً للإشعاع النووي؟","opts":["تسيير المركبات الفضائية بعيدة المدى","دراسة فسلجة النبات وتغذيته","تعقيم المستلزمات الطبية والقضاء على كائنات مسبِّبة للأمراض","حفظ المواد الغذائية لفترات أطول"],"a":2,"why":"تعقيم المستلزمات الطبية والقضاء على الفيروسات والكائنات المرضية من أبرز التطبيقات الطبية للإشعاع النووي؛ الخيارات الأخرى تطبيقات صناعية أو زراعية."},{"ch":"g6c9","q":"لماذا يمكن القول إن الفيزياء النووية «سلاح ذو حدّين»؟","opts":["لأنها لا تُستعمل إطلاقاً في أي مجال طبي أو صناعي مفيد","لأن الإشعاع النووي غير موجود أصلاً في الطبيعة إلا اصطناعياً","لأن كل استعمالاتها ضارة بالضرورة بلا أي استثناء مفيد","لأن نفس المبدأ الفيزيائي (تحوّل الكتلة إلى طاقة) يمكن استثماره في توليد الكهرباء والطب والزراعة سلمياً، أو في صناعة أسلحة مدمِّرة"],"a":3,"why":"المبدأ الفيزيائي نفسه (E=mc² وتحرّر الطاقة النووية) يُستثمر إما بتطبيقات سلمية نافعة جداً (طاقة، طب، زراعة، صناعة) أو بأسلحة مدمِّرة — الفارق في القصد والاستعمال البشري لا في الفيزياء ذاتها."},{"ch":"g6c9","q":"(سؤال وزاري متكرر) نصف قطر النواة (R) يتغيّر: <span class='wz'>تمهيدي 2017 · الدور الأول 2019 · تمهيدي 2022</span>","opts":["عكسياً مع A^(1/3)","طردياً مع A³","طردياً مع A^(1/3)","عكسياً مع A³"],"a":2,"why":"R=r₀A^(1/3) — علاقة طردية مع الجذر التكعيبي للعدد الكتلي."},{"ch":"g6c9","q":"جد شحنة نواة عنصر عدده الذري Z=26 (شحنة البروتون 1.6×10⁻¹⁹C).","opts":["26×10⁻¹⁹C","41.6×10⁻¹⁹C","16.25×10⁻¹⁹C","1.6×10⁻¹⁹C"],"a":1,"why":"q=Ze=26×1.6×10⁻¹⁹=41.6×10⁻¹⁹C."},{"ch":"g6c9","q":"(سؤال وزاري — علّل) لا تتنافر بروتونات النواة على الرغم من تشابهها بالشحنة. <span class='wz'>تمهيدي 2021 · الدور الأول 2019 و2022 و2023-2024</span>","opts":["لأن بروتونات النواة تفقد شحنتها فعلياً بمجرد دخولها النواة","لأن هناك قوة نووية قوية أقوى بكثير من التنافر الكهربائي الكولومي تربط وتمسك بنيوكليونات النواة","لأن النيوترونات تحيط بالبروتونات وتعزلها كهربائياً عن بعضها","لأن البروتونات بعيدة جداً عن بعضها داخل النواة"],"a":1,"why":"القوة النووية القوية أقوى بكثير من قوة التنافر الكهربائي الكولومي بين البروتونات، فتتغلّب عليها وتحافظ على تماسك النواة."},{"ch":"g6c9","q":"جد نصف قطر نواة الحديد (⁵⁶₂₆Fe) بوحدة الفيرمي تقريباً (استعمل (56)^(1/3)≈3.83).","opts":["≈3.83 F","≈56 F","≈1.2 F","≈4.6 F"],"a":3,"why":"R=1.2×(56)^(1/3)≈1.2×3.83≈4.6F."},{"ch":"g6c9","q":"(سؤال وزاري) ما المقصود بطاقة الربط النووية؟ <span class='wz'>تمهيدي 2020</span>","opts":["كتلة النواة بعد تفككها بالكامل","الطاقة المتحررة عند جمع البروتونات والنيوترونات لتشكيل نواة، أو الطاقة اللازمة لتفكيك النواة إلى مكوّناتها","الطاقة الحركية لبروتونات النواة فقط","طاقة الجاذبية بين نيوكليونات النواة فقط"],"a":1,"why":"طاقة الربط النووية: الطاقة المتحررة عند تكوّن النواة من مكوّناتها منفصلة، أو المطلوبة لتفكيكها إليها ثانية."},{"ch":"g6c9","q":"(سؤال وزاري — اختيار) تكون قيم معدل طاقة الربط النووية لكل نيوكليون أكبر لنوى: <span class='wz'>الدور الثالث 2018</span>","opts":["العناصر الخفيفة جداً فقط","العناصر الثقيلة جداً فقط","متساوية لكل العناصر بلا استثناء","العناصر المتوسطة (كالحديد ⁵⁶Fe)"],"a":3,"why":"معدل طاقة الربط Eb' يبلغ ذروته عند النوى المتوسطة، فتكون الأكثر استقراراً."},{"ch":"g6c9","q":"(سؤال وزاري — تطابق تام بنفس الأرقام) جد طاقة الربط النووية لنواة النيتروجين (¹⁴₇N)، علماً أن كتلة ذرّته 14.003074u، وكتلة الهيدروجين 1.007825u، وكتلة النيوترون 1.008665u. <span class='wz'>الدور الأول 2021-2022</span>","opts":["≈14 MeV","≈931 MeV","≈104.6 MeV","≈0.112 MeV"],"a":2,"why":"Eb=[7×1.007825+7×1.008665−14.003074]×931=0.112356×931≈104.6MeV."},{"ch":"g6c9","q":"نواة عددها الكتلي A=20 وطاقة ربطها الكلية Eb=140MeV. جد معدل طاقة الربط لكل نيوكليون Eb'.","opts":["2800 MeV/nucleon","0.143 MeV/nucleon","20 MeV/nucleon","7 MeV/nucleon"],"a":3,"why":"Eb'=Eb/A=140/20=7 MeV/nucleon."},{"ch":"g6c9","q":"ما جسيمة ألفا (α) في الحقيقة؟","opts":["فوتون عالي الطاقة","نواة ذرّة الهيليوم (⁴₂He): بروتونان ونيوترونان","إلكترون حر الحركة","نيوترون منفرد بلا أي بروتون"],"a":1,"why":"جسيمة ألفا هي نواة الهيليوم بالضبط، شحنتها +2e."},{"ch":"g6c9","q":"(سؤال وزاري) في المعادلة: ²²⁶₈₈Ra → A₈₆Rn + ⁴₂He، جد قيمة العدد A. <span class='wz'>تمهيدي 2017</span>","opts":["226","230","218","222"],"a":3,"why":"بحفظ العدد الكتلي: 226=A+4 ⟹ A=222."},{"ch":"g6c9","q":"(سؤال وزاري — برهان بنفس الأرقام حرفياً) نواة الراديوم (²²⁶₈₈Ra) تنحلّ إلى نواة الرادون (²²²₈₆Rn) بألفا. الكتل: He=4.002603u، Ra=226.025406u، Rn=222.017574u. جد طاقة الانحلال Qα، وهل يحدث تلقائياً؟ <span class='wz'>تمهيدي 2019</span>","opts":["Qα≈−4.868 MeV؛ لا يحدث تلقائياً","Qα≈931 MeV؛ يحدث تلقائياً","Qα≈0 MeV؛ حالة توازن","Qα≈4.868 MeV؛ يحدث تلقائياً (Qα>0)"],"a":3,"why":"Qα=[226.025406−222.017574−4.002603]×931≈4.868MeV، وبما أنها موجبة فالانحلال تلقائي."},{"ch":"g6c9","q":"(سؤال وزاري) تنحلّ نواة البولونيوم (²¹⁸₈₄Po) إلى نواة الرصاص (²¹⁴₈₂Pb). ما نوع هذا الانحلال؟ <span class='wz'>الدور الثالث 2019 · الدور الثاني 2019</span>","opts":["بيتا الموجبة","كاما","ألفا","بيتا السالبة"],"a":2,"why":"ΔA=218−214=4 وΔZ=84−82=2 — يطابق تماماً نمط انحلال ألفا."},{"ch":"g6c9","q":"(سؤال وزاري — اختيار) عندما تعاني نواة انحلال بيتا السالبة تلقائياً، فإن عددها الذري: <span class='wz'>الدور الأول 2017 · تمهيدي 2018</span>","opts":["يقل بمقدار اثنين","لا يتغيّر إطلاقاً","يزداد بمقدار واحد","يقل بمقدار واحد"],"a":2,"why":"أحد نيوترونات النواة يتحوّل إلى بروتون، فيزداد Z بمقدار 1، بينما A يبقى ثابتاً."},{"ch":"g6c9","q":"(سؤال وزاري) ما المقصود بالنيوترينو؟ <span class='wz'>الدور الثاني 2019</span>","opts":["نواة ذرّة الهيليوم","جسيم يرافق بيتا الموجبة، شحنته وكتلته السكونية صفر، وعدداه الذري والكتلي صفر","فوتون عالي الطاقة ينبعث بانحلال كاما","بروتون تحوّل حديثاً إلى نيوترون"],"a":1,"why":"النيوترينو جسيم متعادل عديم الكتلة السكونية تقريباً، يرافق انحلال بيتا الموجبة لضمان قوانين الحفظ."},{"ch":"g6c9","q":"ما الذي يبقى ثابتاً تماماً في انحلال كاما وحده، خلافاً لكل الانحلالات الأخرى؟","opts":["طاقة النواة فقط","كتلة النواة السكونية فقط","العدد الكتلي A والعدد الذري Z معاً","شحنة الفوتون المنبعث"],"a":2,"why":"انحلال كاما لا يغيّر تركيب النواة، بل يحرّر فائض طاقة فقط (فوتون) — فيبقى A وZ ثابتين."},{"ch":"g6c9","q":"(علل) لا تنحرف أشعة كاما بتأثير المجال الكهربائي أو المغناطيسي، بينما تنحرف جسيمات ألفا وبيتا.","opts":["لأن كاما أثقل بكثير من ألفا وبيتا معاً","لأن كاما فوتونات متعادلة الشحنة تماماً، والمجالات لا تؤثر إلا بالجسيمات المشحونة المتحركة","لأن ألفا وبيتا لا تتحركان أصلاً بعد الانبعاث","لأن كاما تتحرك أبطأ من الضوء بكثير"],"a":1,"why":"غياب أي شحنة عن فوتونات كاما يجعلها غير متأثرة بالمجالات الكهربائية والمغناطيسية، بعكس ألفا (+2e) وبيتا (±e)."},{"ch":"g6c9","q":"(سؤال وزاري — علّل) تُعدّ النيوترونات قذائف مهمة في التفاعلات النووية. <span class='wz'>2023-2024 الدور الأول</span>","opts":["لأن شحنة النيوترون صفر، فلا تصدّه قوة كولوم التنافرية عند اقترابه من النواة الموجبة","لأن النيوترون أثقل من البروتون وألفا معاً بكثير","لأن النيوترون يتحرك دائماً بسرعة الضوء بالضبط","لأن النيوترون وحده قادر على الانحلال تلقائياً خارج النواة"],"a":0,"why":"غياب الشحنة عن النيوترون يلغي التنافر الكهربائي مع النواة، فيدخلها بسهولة أكبر بكثير من الجسيمات المشحونة."},{"ch":"g6c9","q":"ما قوانين الحفظ الخمسة التي يجب أن تتحقق في أي تفاعل نووي؟","opts":["حفظ الطاقة-الكتلة، الزخم الخطي، الزخم الزاوي، الشحنة (Z)، وعدد النيوكليونات (A)","حفظ اللون والحجم والشكل والوزن والحرارة","حفظ الشحنة فقط دون أي قانون آخر","لا توجد أي قوانين حفظ ملزمة بالتفاعلات النووية"],"a":0,"why":"التفاعل النووي يجب أن يحقق معاً: حفظ الطاقة-الكتلة، الزخم الخطي، الزخم الزاوي، الشحنة الكهربائية، وعدد النيوكليونات."},{"ch":"g6c9","q":"(سؤال وزاري — بنفس الأرقام) في التفاعل: ⁴₂He + ¹⁴₇N → ¹⁷₈O + ¹₁H، جد طاقة التفاعل Q. الكتل: N=14.003074u، He=4.002603u، O=16.999132u، H=1.007825u. <span class='wz'>تمهيدي 2018</span>","opts":["Q≈+1.19 MeV؛ محرِّر للطاقة","Q≈−1.19 MeV؛ ماص للطاقة","Q≈0 MeV؛ متعادل","Q≈931 MeV؛ محرِّر للطاقة"],"a":1,"why":"Q=[4.002603+14.003074−16.999132−1.007825]×931≈−1.19MeV؛ القيمة سالبة فالتفاعل ماص للطاقة."},{"ch":"g6c9","q":"في تفاعل: ¹₀n + ²⁷₁₃Al → ²⁴₁₁Na + Y، ما الجسيم الناتج Y؟","opts":["نيوترون ¹₀n","بروتون ¹₁H","جسيمة ألفا ⁴₂He","فوتون كاما"],"a":2,"why":"حفظ A: 1+27=24+A_Y ⟹ A_Y=4. حفظ Z: 0+13=11+Z_Y ⟹ Z_Y=2. إذن Y=⁴₂He (جسيمة ألفا)."},{"ch":"g6c9","q":"ما تعريف الانشطار النووي؟","opts":["اندماج نواتين خفيفتين لتكوين نواة أثقل","انبعاث جسيمة ألفا من نواة ثقيلة تلقائياً","انقسام نواة ثقيلة إلى نواتين متوسطتي الكتلة، عادة بقصفها بنيوترون بطيء","تحوّل نيوترون داخل النواة إلى بروتون"],"a":2,"why":"الانشطار يقسّم نواة ثقيلة كاليورانيوم إلى نواتين متوسطتين، بامتصاص نيوترون حراري بطيء."},{"ch":"g6c9","q":"كم نيوتروناً جديداً يُنتَج تقريباً من كل انشطار نموذجي لليورانيوم؟","opts":["عشرة نيوترونات أو أكثر","لا يُنتَج أي نيوترون جديد","اثنان أو ثلاثة نيوترونات تقريباً","نيوترون واحد فقط دائماً"],"a":2,"why":"الانشطار ينتج نموذجياً 2 أو 3 نيوترونات جديدة، أساس استمرار التفاعل المتسلسل."},{"ch":"g6c9","q":"ماذا يعني أن معامل التضاعف k يساوي 1 بالضبط بتفاعل متسلسل؟","opts":["حالة حرجة مضبوطة، تفاعل ثابت متحكَّم به كما بالمفاعل النووي","تفاعل خامد تماماً يتوقف فوراً","تصاعد سريع غير محكوم كالقنبلة النووية","لا معنى فيزيائياً محدداً لهذه القيمة"],"a":0,"why":"k=1 يعني إنتاج نيوترون فعّال واحد بالمتوسط لكل انشطار، فيستمر التفاعل بمعدل ثابت — هذا مبدأ عمل المفاعل النووي."},{"ch":"g6c9","q":"من حقّق أول تفاعل نووي انشطاري متسلسل مسيطر عليه، وأين وفي أي عام؟","opts":["رذرفورد، ببريطانيا، 1911","أينشتاين، بألمانيا، 1905","ماري كوري، بفرنسا، 1898","فيرمي وفريقه، بشيكاغو، 1942"],"a":3,"why":"حقّق إنريكو فيرمي وفريقه أول تفاعل نووي متسلسل مسيطر عليه بأول مفاعل نووي بجامعة شيكاغو عام 1942."},{"ch":"g6c9","q":"ما العملية الرئيسة المسؤولة عن إنتاج طاقة الشمس؟","opts":["احتراق كيميائي عادي للهيدروجين","دورة بروتون-بروتون: اندماج نوى الهيدروجين لتكوين الهيليوم","انشطار نووي متسلسل لليورانيوم بباطنها","تفاعلات كيميائية بالغلاف الجوي للشمس"],"a":1,"why":"دورة بروتون-بروتون (اندماج نوى الهيدروجين لتكوين الهيليوم) هي مصدر طاقة الشمس الرئيس، عند حرارة باطنها ~1.5×10⁷K."},{"ch":"g6c9","q":"ما العائق الرئيس أمام تحقيق اندماج نووي مفيد؟","opts":["عدم وجود أي قانون فيزيائي يسمح بحدوثه","قوة تنافر كولوم الكهربائية الكبيرة بين النوى الموجبة عند المسافات القصيرة","نقص المواد الخام لنظائر الهيدروجين","أن الاندماج لا يحرر أي طاقة إطلاقاً"],"a":1,"why":"تنافر كولوم بين النوى الموجبة يمنعها من الاقتراب كفاية لدخول مدى القوة النووية القوية، إلا بطاقة حركية هائلة (حرارة عالية جداً)."},{"ch":"g6c9","q":"ما الفرق الأساسي بين نفايات الانشطار والاندماج النوويين؟","opts":["كلاهما ينتج نفس نوع وكمية النفايات المشعة تماماً","الاندماج ينتج نفايات أخطر بكثير من الانشطار دائماً","نواتج الانشطار غالباً مشعة وخطرة لفترات طويلة، ونواتج الاندماج (كالهيليوم) غالباً غير مشعة","لا ينتج الانشطار أي نفايات مشعة إطلاقاً"],"a":2,"why":"نواتج الانشطار عادة نوى مشعة تبقى خطرة طويلاً، بينما نواتج الاندماج (كالهيليوم) نظير مستقر غير مشعّ عادة."},{"ch":"g6c9","q":"(سؤال وزاري) ما الإجراء الاحترازي اللازم لتقليل التعرّض الاضطراري للإشعاع النووي الخارجي؟ <span class='wz'>الدور الثالث 2019</span>","opts":["الاقتراب من المصدر لدراسته عن قرب","زيادة زمن التعرّض تدريجياً للتعوّد عليه","تقليل زمن التعرّض، الابتعاد عن المصدر، واستعمال درع واقٍ ملائم","لا يوجد أي إجراء احترازي ممكن"],"a":2,"why":"الإجراءات الثلاثة: تقليل زمن التعرّض، الابتعاد عن المصدر، واستعمال حواجز واقية ملائمة (كالرصاص)."},{"ch":"g6c9","q":"ما الفرق بين التأثيرات الجسدية والوراثية للإشعاع النووي على جسم الإنسان؟","opts":["لا فرق بينهما؛ مصطلحان لنفس التأثير تماماً","الجسدية ضرر بالخلايا الاعتيادية (كالسرطان)، والوراثية ضرر بالخلايا التناسلية ينتقل للأجيال اللاحقة","الوراثية تصيب الخلايا الاعتيادية فقط","الجسدية فقط تنتج عن مصادر اصطناعية دون الطبيعية"],"a":1,"why":"الجسدية تصيب خلايا الجسم الاعتيادية (مبكرة أو متأخرة كالسرطان)؛ الوراثية تصيب الخلايا التناسلية وتنتقل للنسل."},{"ch":"g6c9","q":"أي مادة كثيفة تُستعمل غالباً كدرع واقٍ فعّال ضد أشعة كاما عالية الاختراق؟","opts":["ورقة رقيقة عادية","الرصاص أو الخرسانة السميكة","قطعة قماش خفيفة","الهواء العادي وحده"],"a":1,"why":"المواد الكثيفة كالرصاص أو الخرسانة السميكة قادرة على امتصاص جزء كبير من أشعة كاما، بعكس الورق الذي يوقف ألفا فقط."}];
